local config = {
  ui_story_5036_50360101_1_dialog_content = "¡Ahhh-!",
  ui_story_5036_50360101_2_dialog_content = "¡Ayuda!",
  ui_story_5036_50360101_3_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5036_50360101_4_dialog_content = "¡Puaj! *tos*",
  ui_story_5036_50360101_5_dialog_content = "¿Cómo te atreves a tocarme? ¿No sabes quién soy? ¡Soy dueño del Star Theatre!",
  ui_story_5036_50360101_6_dialog_content = "¿Te das cuenta de lo que estás haciendo?",
  ui_story_5036_50360101_7_dialog_content = "*Tose*",
  ui_story_5036_50360101_8_dialog_content = "Desafortunadamente, ya no la dejaré actuar en mi teatro, señorita Goldie.",
  ui_story_5036_50360101_9_dialog_content = "... Qué vergüenza.",
  ui_story_5036_50360101_10_dialog_content = "¡Buenos días!",
  ui_story_5036_50360101_11_dialog_content = "*bostezos* Buenos días.",
  ui_story_5036_50360101_12_dialog_content = "Estás aquí bastante temprano. ¿Ha surgido algo urgente?",
  ui_story_5036_50360101_13_dialog_content = "Vaya, ¿es este un mal momento?",
  ui_story_5036_50360101_14_dialog_content = "Lo siento, me emocioné tanto con la entrevista que ni siquiera me di cuenta de la hora.",
  ui_story_5036_50360101_15_dialog_content = "Uh, espera un segundo... ¿No te acuerdas de mí?",
  ui_story_5036_50360101_16_option_content = "te recordamos",
  ui_story_5036_50360101_17_dialog_content = "¿Te ves algo familiar...?",
  ui_story_5036_50360101_18_dialog_content = "Oh, espera, ¿no eras un extra en \"Tattletale\"?",
  ui_story_5036_50360101_19_option_content = "no te recuerdo",
  ui_story_5036_50360101_20_dialog_content = "Oh...",
  ui_story_5036_50360101_21_dialog_content = "¿Deberíamos conocerte?",
  ui_story_5036_50360101_22_dialog_content = "Eh, ejem...",
  ui_story_5036_50360101_23_dialog_content = "Estoy <color=#FFB400>Brandy</color>, reportero interno de The Daily Scoop!",
  ui_story_5036_50360101_24_dialog_content = "Nos conocimos brevemente frente a la Casa Embrujada de Andersen antes.",
  ui_story_5036_50360101_25_dialog_content = "Entonces no pude entrevistarlos a ustedes dos, y mi editor criticó el artículo que escribí...",
  ui_story_5036_50360101_26_dialog_content = "¡Pero eso está bien!",
  ui_story_5036_50360101_27_dialog_content = "¡Estoy muy agradecido por la entrevista exclusiva de hoy!",
  ui_story_5036_50360101_28_dialog_content = "¿Eh? ¿Cuándo acepté eso?",
  ui_story_5036_50360101_29_dialog_content = "Bueno, ¡no tenemos un momento que perder! ¿Por qué no comenzamos la entrevista entonces?",
  ui_story_5036_50360101_30_dialog_content = "¿Cuáles son sus pensamientos sobre el <color=#FFB400>Coloso errante</color>?",
  ui_story_5036_50360101_31_dialog_content = "¿Coloso errante?",
  ui_story_5036_50360101_32_dialog_content = "¿Es así como los jóvenes de Umbraton llaman a Soroz?",
  ui_story_5036_50360101_33_dialog_content = "¿Ah?",
  ui_story_5036_50360101_34_dialog_content = "¿No conoces el Coloso Errante?",
  ui_story_5036_50360101_35_dialog_content = "Casi todo el mundo lo sabe, desde Northland hasta Rediesel Desert, desde Lumopolis hasta Umbraton.",
  ui_story_5036_50360101_36_dialog_content = "¿Pero no has oído hablar de él, a pesar de ser Caelestita?",
  ui_story_5036_50360101_37_dialog_content = "¡Supongo que eso también cuenta como noticia!",
  ui_story_5036_50360101_38_dialog_content = "Hmmm, tiene potencial de noticias de titulares. ¡Debería anotar esto!",
  ui_story_5036_50360101_39_dialog_content = "Ejem. Estuve... demasiado ocupado con el trabajo y otras cosas últimamente para mantenerme al día con los asuntos actuales.",
  ui_story_5036_50360101_40_dialog_content = "¿No me digas que hay tabloides difundiendo rumores sobre mí otra vez?",
  ui_story_5036_50360101_41_dialog_content = "¡Para nada!",
  ui_story_5036_50360101_42_dialog_content = "Mira, aquí hay un poco de anoche.",
  ui_story_5036_50360101_43_dialog_content = "Extra:",
  ui_story_5036_50360101_44_dialog_content = "Pronóstico del rastro del coloso errante",
  ui_story_5036_50360101_45_dialog_content = "¡Dirigiéndose a Umbraton a lo largo del Río Dorado!",
  ui_story_5036_50360101_46_dialog_content = "¡Lo leeré para ustedes!",
  ui_story_5036_50360101_47_dialog_content = "\"Última actualización: el coloso errante se ha ido de Northland\".",
  ui_story_5036_50360101_48_dialog_content = "\"Los científicos lo están rastreando actualmente, y según sus cálculos...\"",
  ui_story_5036_50360101_49_dialog_content = "\"El Coloso continuará hacia el sur hacia Umbraton a lo largo del Río Dorado\".",
  ui_story_5036_50360101_50_dialog_content = "\"El Coloso apareció por primera vez abruptamente en los cielos justo sobre Northland y se pensó que provenía de la Zona Oscura\".",
  ui_story_5036_50360101_51_dialog_content = "\"Después de que un científico anónimo confirmara esta teoría, la noticia sacudió a todo el continente\".",
  ui_story_5036_50360101_52_dialog_content = "\"Algunos afirman que el Colossus no tiene navegante ni pasajeros, ni lleva armas destructivas\".",
  ui_story_5036_50360101_53_dialog_content = "\"Pero el exterior, especialmente el fondo, está equipado con pantallas gigantes y dispositivos estéreo que parecen ser de la antigüedad\".",
  ui_story_5036_50360101_54_dialog_content = "\"Actualmente, Illumina y Lumopolis están buscando formas de interceptar al Coloso Errante...\"",
  ui_story_5036_50360101_55_dialog_content = "\"... para decidir cómo procederán con la situación\".",
  ui_story_5036_50360101_56_dialog_content = "¿Un coloso... errante?",
  ui_story_5036_50360101_57_dialog_content = "Tengo tantas preguntas que no sé ni por dónde empezar.",
  ui_story_5036_50360101_58_dialog_content = "¿Un Colossus equipado con pantallas y sistemas estéreo?",
  ui_story_5036_50360101_59_dialog_content = "¡Creo que he leído sobre eso antes en alguna parte!",
  ui_story_5036_50360101_60_dialog_content = "¿En serio? ¿Qué más puedes decirme?",
  ui_story_5036_50360101_61_dialog_content = "Lo siento, no puedo recordar mucho al respecto.",
  ui_story_5036_50360101_62_dialog_content = "Pero no parezcas tan decepcionado. Iré a preguntarle al oficial Gronru ahora mismo.",
  ui_story_5036_50360101_63_dialog_content = "¡Estoy seguro de que puede contarnos más con su amplio conocimiento sobre Colosos!",
  ui_story_5036_50360101_64_dialog_content = "Eso no será necesario.",
  ui_story_5036_50360101_65_dialog_content = "¿Carleen...? ¡Estás de vuelta!",
  ui_story_5036_50360101_66_dialog_content = "Pensé que te ibas a quedar en Lumopolis para siempre.",
  ui_story_5036_50360101_67_dialog_content = "Leí sobre el Coloso Errante en las noticias hace unos días y encontré toda la situación bastante extraña, así que me sumergí en la investigación de la biblioteca.",
  ui_story_5036_50360101_68_dialog_content = "¡Debes haber encontrado algo!",
  ui_story_5036_50360101_69_dialog_content = "O no habrías venido aquí con tanta prisa...",
  ui_story_5036_50360101_70_dialog_content = "Sí, encontré algo de hace más de un siglo.",
  ui_story_5036_50360101_71_dialog_content = "¿Más de un siglo?",
  ui_story_5036_50360101_72_dialog_content = "Así es. Los caelestitas eran aislacionistas y no tenían mucho contacto con los aurorianos en ese entonces.",
  ui_story_5036_50360101_73_dialog_content = "Pero un día, de repente buscaron la ayuda de Lumopolis e Illumina.",
  ui_story_5036_50360101_74_dialog_content = "Su petición de ayuda implicaba que parecían haber perdido el contacto con un Coloso llamado <color=#FFB400>Eulogoz</color>.",
  ui_story_5036_50360101_75_dialog_content = "Eulogoz tiene una característica muy destacada:",
  ui_story_5036_50360101_76_dialog_content = "<color=#FFB400>Cuenta con pantallas gigantes externas</color>.",
  ui_story_5036_50360101_77_dialog_content = "¿Pantallas gigantes? Así describía el periódico al Coloso Errante.",
  ui_story_5036_50360101_78_dialog_content = "Lo que es notable es que Caelestites no pudo encontrar a Eulogoz hace cien años.",
  ui_story_5036_50360101_79_dialog_content = "¿Quieres decir... que el Coloso Errante es el Eulogoz perdido hace mucho tiempo?",
  ui_story_5036_50360101_80_dialog_content = "Eso es lo que supongo.",
  ui_story_5036_50360101_81_dialog_content = "¡¿Cómo es posible que desaparezca durante más de un siglo y permanezca sin descubrir hasta ahora?!",
  ui_story_5036_50360101_82_dialog_content = "Pensé que sabrías algo, siendo tú mismo un Caelestita.",
  ui_story_5036_50360101_83_dialog_content = "¿Tal vez pueda hacerse invisible?",
  ui_story_5036_50360101_84_dialog_content = "Nunca he oído hablar de un Caelestita capaz de ser invisible.",
  ui_story_5036_50360101_85_dialog_content = "Su nombre y orígenes apenas tienen importancia en este momento.",
  ui_story_5036_50360101_86_dialog_content = "¡Lo importante es que un Coloso apareció de la nada en el cielo!",
  ui_story_5036_50360101_87_dialog_content = "Todos sabemos que Colossi es exclusivo de Caelestites.",
  ui_story_5036_50360101_88_dialog_content = "Y aquí tenemos una Caelestita genuina y auténtica.",
  ui_story_5036_50360101_89_dialog_content = "Sin embargo, son Lumopolis e Illumina los que están decidiendo qué hacer con el Coloso.",
  ui_story_5036_50360101_90_dialog_content = "Cómo te sientes sobre eso, PlayerName?",
  ui_story_5036_50360101_91_dialog_content = "Confío en que los investigadores de Illumina notificarán PlayerName después de una investigación exhaustiva.",
  ui_story_5036_50360101_92_dialog_content = "Los caballeros fieles al Dios de la Luz nunca tomarían algo que no nos pertenece.",
  ui_story_5036_50360101_93_dialog_content = "*Ejem* Quería preguntarle la opinión de PlayerName sobre la situación ya que él es un Caelestita.",
  ui_story_5036_50360101_94_dialog_content = "...",
  ui_story_5036_50360101_95_dialog_content = "Lo siento.",
  ui_story_5036_50360101_96_dialog_content = "¿Ah?",
  ui_story_5036_50360101_97_dialog_content = "No puedo responder sin ver al Coloso en persona primero.",
  ui_story_5036_50360101_98_dialog_content = "Estás planeando...",
  ui_story_5036_50360101_99_dialog_content = "De todos modos, tengo derecho a investigar algo que pertenece a los Caelestites.",
  ui_story_5036_50360101_100_dialog_content = "¿Vendrán ustedes dos conmigo?",
  ui_story_5036_50360101_101_dialog_content = "Estaba planeando hacer exactamente eso.",
  ui_story_5036_50360101_102_dialog_content = "¿Tienes que preguntar?",
  ui_story_5036_50360101_103_dialog_content = "¡Está bien!",
  ui_story_5036_50360101_104_dialog_content = "Soroz...",
  ui_story_5036_50360101_105_option_content = "¡Máxima velocidad adelante!",
  ui_story_5036_50360101_106_dialog_content = "Oh, así que esto es genial PlayerName ¡La Caelestita se ve al mando de un Coloso!",
  ui_story_5036_50360101_107_dialog_content = "¡Necesito grabar esto!",
  ui_story_5036_50360101_108_dialog_content = "<color=#e8d9bb>¡Advertencia! ¡Advertencia! Comando inválido.</color>",
  ui_story_5036_50360101_109_dialog_content = "¿Ah?",
  ui_story_5036_50360101_110_dialog_content = "<color=#e8d9bb>Introduzca las coordenadas del objetivo.</color>",
  ui_story_5036_50360101_111_dialog_content = "Oh, eso...",
  ui_story_5036_50360101_112_dialog_content = "Dime, ¿alguien tiene las coordenadas del Coloso Errante?",
  ui_story_5036_50360101_113_dialog_content = "...",
  ui_story_5036_50360101_114_dialog_content = "Me preguntaba cuándo ibas a preguntar.",
  ui_story_5036_50360101_115_dialog_content = "Lo siento, pero no puedo alquilarte el teatro.",
  ui_story_5036_50360101_116_dialog_content = "¡Por favor, los ingresos no son un problema! ¡Mis conciertos son muy concurridos!",
  ui_story_5036_50360101_117_dialog_content = "¿No lo reconsiderarás?",
  ui_story_5036_50360101_118_dialog_content = "Te sugiero que pruebes suerte en otro lugar.",
  ui_story_5036_50360101_119_dialog_content = "Pero todos los demás teatros de Umbraton ya me rechazaron...",
  ui_story_5036_50360101_120_dialog_content = "extra, extra! ¡Se pronostica que Wandering Colossus se dirigirá a Umbraton a lo largo del Gold River!",
  ui_story_5036_50360101_121_dialog_content = "¿Coloso errante?",
  ui_story_5036_50360101_122_dialog_content = "¿Puedo tener una copia por favor?",
  ui_story_5036_50360101_123_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_5036_50360101_124_dialog_content = "¡Whoa!",
  ui_story_5036_50360101_125_dialog_content = "¡Realmente estamos despegando!",
  ui_story_5036_50360101_126_dialog_content = "¡Ese editor que me acosa día tras día nunca hubiera imaginado esto ni en un millón de años!",
  ui_story_5036_50360101_127_dialog_content = "Que de todos los periodistas que luchan por tener la oportunidad de seguir una de las historias de Caelestite en Umbraton, ¡soy el único que realmente vuela dentro del Coloso!",
  ui_story_5036_50360101_128_dialog_content = "¡Le mostraré quién es el reportero más increíble de la ciudad!",
  ui_story_5036_50360101_129_dialog_content = "¿Brandy...?",
  ui_story_5036_50360101_130_dialog_content = "¡Oh no, no debería haberme expuesto frente a mis entrevistados!",
  ui_story_5036_50360101_131_dialog_content = "Ejem. Tengan la seguridad de todos. Soy un profesional y procederé con mi trabajo con la máxima objetividad.",
  ui_story_5036_50360101_132_dialog_content = "Eso no es lo que quise decir.",
  ui_story_5036_50360101_133_dialog_content = "¿Querías volver a Umbraton? Puedo dejarte en el camino.",
  ui_story_5036_50360101_134_dialog_content = "¡Oh, para nada! Ni siquiera estoy cerca de terminar mi entrevista contigo todavía.",
  ui_story_5036_50360101_135_dialog_content = "También me gustaría que me dieras permiso para acompañarte en tu viaje al Coloso Errante.",
  ui_story_5036_50360101_136_dialog_content = "¡Te prometo que escribiré el artículo más épico y glorioso sobre ti!",
  ui_story_5036_50360101_137_dialog_content = "¡Aquellos en Lumopolis e Illumina ni siquiera pensarán en tocar la propiedad de Caelestite después de leerlo!",
  ui_story_5036_50360101_138_dialog_content = "Er, eso es... eso es un poco dramático, ja...",
  ui_story_5036_50360101_139_dialog_content = "¿Ey qué es eso?",
  ui_story_5036_50360101_140_dialog_content = "Un póster acaba de salirse de tu bolso, Brandy.",
  ui_story_5036_50360101_141_dialog_content = "Ahahaha, cierto! ¡Gracias! ¡Guardándolo de inmediato!",
  ui_story_5036_50360101_142_dialog_content = "Espera, ¿no conocemos a esa persona en el cartel?",
  ui_story_5036_50360101_143_dialog_content = "Sí, ¿no es esa Goldie?",
  ui_story_5036_50360101_144_dialog_content = "Después del estreno de \"Into the Haunted House\", la conocimos una vez en Andersen Haunted House.",
  ui_story_5036_50360101_145_dialog_content = "La película obtuvo excelentes críticas, pero decidió dejar de actuar.",
  ui_story_5036_50360101_146_dialog_content = "Me pregunto qué ha estado haciendo últimamente.",
  ui_story_5036_50360101_147_dialog_content = "Sin embargo, siento que últimamente se ha vuelto popular en Umbraton. Veo carteles de ella donde quiera que vaya.",
  ui_story_5036_50360101_148_dialog_content = "Este que tengo es diferente a los de la calle.",
  ui_story_5036_50360101_149_dialog_content = "¡Este es un coleccionable de edición limitada!",
  ui_story_5036_50360101_150_dialog_content = "¿Así que eres fan de ella?",
  ui_story_5036_50360101_151_dialog_content = "Realmente no me llamaría Ricitos de Oro...",
  ui_story_5036_50360101_152_dialog_content = "¿Un Ricito de Oro?",
  ui_story_5036_50360101_153_dialog_content = "Así se llaman los fans de Goldie. ¡Realmente no soy uno de ellos!",
  ui_story_5036_50360101_154_dialog_content = "Acabo de entrevistar a Goldie después del estreno de \"Into the Haunted House\".",
  ui_story_5036_50360101_155_dialog_content = "La encontré muy optimista y amable, como una brisa cálida que dispersa todos mis problemas.",
  ui_story_5036_50360101_156_dialog_content = "De lo contrario, probablemente no habría durado tanto tiempo como pasante en The Daily Scoop.",
  ui_story_5036_50360101_157_dialog_content = "Entonces, después de eso, seguí su trabajo de vez en cuando, eso es todo.",
  ui_story_5036_50360101_158_dialog_content = "¿Eso no te convierte básicamente en un fan?",
  ui_story_5036_50360101_159_dialog_content = "D-¿Lo hace? Pero escuché entre rumores que Goldie tiene tendencias violentas.",
  ui_story_5036_50360101_160_dialog_content = "Es cierto que muchas figuras públicas tienen un lado que nadie conoce.",
  ui_story_5036_50360101_161_dialog_content = "Pero no quiero idolatrar a alguien que es violento.",
  ui_story_5036_50360101_162_dialog_content = "Goldie, violento? ¡De ninguna manera!",
  ui_story_5036_50360101_163_dialog_content = "Ha habido muchos rumores absurdos últimamente, y ese es probablemente uno de ellos.",
  ui_story_5036_50360101_164_dialog_content = "Los periódicos de Umbraton probablemente representan PlayerName como un místico monstruo de tres cabezas por ahora.",
  ui_story_5036_50360101_165_dialog_content = "¡Verdadero! Lo odio.",
  ui_story_5036_50360101_166_dialog_content = "¡Será mejor que no me arrastres por el barro como ellos, Brandy!",
  ui_story_5036_50360101_167_dialog_content = "¡Relax!",
  ui_story_5036_50360101_168_dialog_content = "Solo informo la verdad como la veo con mis propios ojos.",
  ui_story_5036_50360101_169_dialog_content = "Ojalá hubiera más periodistas como tú en Umbraton.",
  ui_story_5036_50360101_170_dialog_content = "¿M-Yo? Oh, Dios, jejeje...",
  ui_story_5036_50360101_171_dialog_content = "<color=#e8d9bb>Advertencia: objeto volador no identificado detectado adelante.</color>",
  ui_story_5036_50360101_172_dialog_content = "<color=#e8d9bb>¡Por favor dé el comando para una acción evasiva!</color>",
  ui_story_5036_50360101_173_dialog_content = "¿Objeto volador no identificado?",
  ui_story_5036_50360101_174_dialog_content = "Su construcción es muy diferente a la de Soroz...",
  ui_story_5036_50360101_175_dialog_content = "¡pero el diseño y el brillo de su casco son obviamente los de un Colossus!",
  ui_story_5036_50360101_176_dialog_content = "La pantalla...",
  ui_story_5036_50360101_177_dialog_content = "¡Yo lo veo! ¿Ese enorme cuadrado es la pantalla?",
  ui_story_5036_50360101_178_dialog_content = "¡Eso definitivamente no es de nuestro tiempo!",
  ui_story_5036_50360101_179_dialog_content = "¡Debe ser eso! ¡Ese tiene que ser el Coloso Errante!",
  ui_story_5036_50360101_180_dialog_content = "Pero, ¿por qué Soroz no puede identificarlo por su nombre?",
  ui_story_5036_50360101_181_dialog_content = "¿Y por qué no puedo sentir su Navegador?",
  ui_story_5036_50360101_182_dialog_content = "¿Eres realmente el Eulogoz que desapareció hace un siglo?",
  ui_story_5036_50360101_183_dialog_content = "♪ La... La la la... ♪",
  ui_story_5036_50360101_184_dialog_content = "(¿Quién está cantando?)",
  ui_story_5036_50360101_185_dialog_content = "¿Escuchan eso?",
  ui_story_5036_50360101_186_dialog_content = "¿Escuchar qué?",
  ui_story_5036_50360101_187_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360101_188_dialog_content = "Cantando... ¡Alguien está cantando!",
  ui_story_5036_50360101_189_dialog_content = "¿Qué? no escucho nada",
  ui_story_5036_50360101_190_dialog_content = "♪ La la la la... ♪",
  ui_story_5036_50360101_191_dialog_content = "(¿Eres el navegante de Eulogoz?)",
  ui_story_5036_50360101_192_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360101_193_dialog_content = "(¿Por qué abandonaste tu Coloso?)",
  ui_story_5036_50360101_194_dialog_content = "♪ La... La la... ♪",
  ui_story_5036_50360101_195_dialog_content = "(Por qué...?)",
  ui_story_5036_50360101_196_dialog_content = "<color=#e8d9bb>Advertencia: objeto volador no identificado detectado adelante.</color>",
  ui_story_5036_50360101_197_dialog_content = "<color=#e8d9bb>Para evitar colisiones, el Colossus cambiará automáticamente la ruta de vuelo en tres segundos.</color>",
  ui_story_5036_50360101_198_dialog_content = "<color=#e8d9bb>Tres...</color>",
  ui_story_5036_50360101_199_dialog_content = "<color=#e8d9bb>Dos...</color>",
  ui_story_5036_50360101_200_dialog_content = "Detener el desvío de la ruta de vuelo.",
  ui_story_5036_50360101_201_dialog_content = "Haga coincidir la velocidad y la dirección del objeto volador no identificado.",
  ui_story_5036_50360101_202_dialog_content = "Ajuste el vuelo según sea necesario.",
  ui_story_5036_50360201_1_dialog_content = "<color=#e8d9bb>Atención, acercándose a un objeto volador no identificado.</color>",
  ui_story_5036_50360201_2_dialog_content = "¡El Coloso tiembla mucho! ¿Chocamos con el Coloso Errante?",
  ui_story_5036_50360201_3_dialog_content = "No te preocupes. Es solo Soroz reduciendo la velocidad.",
  ui_story_5036_50360201_4_dialog_content = "Eso es muy malo. Pensé que podría capturar una toma de dos colosos chocando entre sí.",
  ui_story_5036_50360201_5_dialog_content = "¡Una foto tan impresionante sería la portada de todos los periódicos!",
  ui_story_5036_50360201_6_dialog_content = "Si eso sucediera, dudo que tengas tiempo para tomar una foto.",
  ui_story_5036_50360201_7_dialog_content = "¡Sólo digo!",
  ui_story_5036_50360201_8_dialog_content = "Dicho esto, su cámara se ve bastante única.",
  ui_story_5036_50360201_9_dialog_content = "¡Tienes buen ojo, Vice!",
  ui_story_5036_50360201_10_dialog_content = "No todo el mundo tiene el privilegio de poseer un dispositivo avanzado como una cámara.",
  ui_story_5036_50360201_11_dialog_content = "Sin mencionar que siempre actualizo sus partes para poder obtener mejores tomas.",
  ui_story_5036_50360201_12_dialog_content = "Me contrataron como pasante gracias a esta cámara.",
  ui_story_5036_50360201_13_dialog_content = "¡Guau! Entonces, ¿puede tu cámara hacer que las personas se vean más bonitas en las fotos?",
  ui_story_5036_50360201_14_dialog_content = "¡Eso no lo puedo prometer, pero puedo garantizar que capturará la imagen más auténtica y real!",
  ui_story_5036_50360201_15_dialog_content = "<color=#e8d9bb>Ajuste realizado para mantener una velocidad y dirección constantes con el objeto no identificado.</color>",
  ui_story_5036_50360201_16_dialog_content = "Vamos.",
  ui_story_5036_50360201_17_dialog_content = "Espera, todavía estamos muy lejos del Coloso Errante.",
  ui_story_5036_50360201_18_dialog_content = "¿Cómo se supone que vamos a acercarnos?",
  ui_story_5036_50360201_19_dialog_content = "Volando, por supuesto.",
  ui_story_5036_50360201_20_dialog_content = "<anim type=Shake>¡¡¡Ahhhh!!!</anim>",
  ui_story_5036_50360201_21_dialog_content = "¡D-Realmente volamos sobre nosotros!",
  ui_story_5036_50360201_22_dialog_content = "Esa fue mi primera vez en un dirigible, ¡fue genial!",
  ui_story_5036_50360201_23_dialog_content = "¡Sin mencionar que no puedo creer que el Coloso Errante esté bajo mis pies ahora mismo!",
  ui_story_5036_50360201_24_dialog_content = "¡Dios mío, tantos reporteros morirían por una oportunidad como esta!",
  ui_story_5036_50360201_25_dialog_content = "Pero vaya, no importa cuán emocionado esté, un reportero profesional nunca debe descuidar el tema de su escritura.",
  ui_story_5036_50360201_26_dialog_content = "Déjame preguntar cómo PlayerName se siente en este momento!",
  ui_story_5036_50360201_27_dialog_content = "Perdóneme, PlayerName...?",
  ui_story_5036_50360201_28_dialog_content = "...",
  ui_story_5036_50360201_29_dialog_content = "Oye, te ves pálido... ¿Es esto alguna forma de protesta sin palabras contra las acciones de Illumina y Lumopolis?",
  ui_story_5036_50360201_30_dialog_content = "¡Es Darkflow! ¡Tanto Darkflow de repente!",
  ui_story_5036_50360201_31_dialog_content = "¿Qué? ¿Estamos en el lugar equivocado?",
  ui_story_5036_50360201_32_dialog_content = "Imposible, la jueza principal Irridon me dio las coordenadas ella misma. No pueden estar equivocados.",
  ui_story_5036_50360201_33_dialog_content = "Chicos, no hay tiempo para eso ahora, ¡tenemos un problema mayor!",
  ui_story_5036_50360201_34_dialog_content = "<size=45>Grah!!!</size>",
  ui_story_5036_50360202_1_dialog_content = "♪ La... La la la... ♪",
  ui_story_5036_50360202_2_dialog_content = "(Es el canto otra vez...)",
  ui_story_5036_50360202_3_dialog_content = "(¿Por qué suena extrañamente familiar cuando nunca lo había escuchado antes?)",
  ui_story_5036_50360202_4_dialog_content = "(Es como un ritmo que siempre ha estado latiendo en mis venas, solo burbujeando en la superficie de mi memoria en este momento).",
  ui_story_5036_50360202_5_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360202_6_dialog_content = "♪ La la la la... ♪",
  ui_story_5036_50360202_7_dialog_content = "E-Eres...",
  ui_story_5036_50360202_8_dialog_content = "¡Cómo se atreve un simple caelestita a olvidar el nombre del juez Matthieu!",
  ui_story_5036_50360202_9_dialog_content = "¡Ni siquiera un alma en Lumopolis se atreve a pasarme por alto así! ¡Me niego a sufrir tal indignidad!",
  ui_story_5036_50360202_10_dialog_content = "¿No estás de acuerdo, Loewe? ... ¿Qué estás haciendo, Loewe?",
  ui_story_5036_50360202_11_dialog_content = "¿Está bien, Su Alteza?",
  ui_story_5036_50360202_12_dialog_content = "Estoy bien. Fueron solo unos pocos eclipses.",
  ui_story_5036_50360202_13_dialog_content = "Pero gracias a su oportuna llegada, nos deshicimos de ellos lo suficientemente rápido.",
  ui_story_5036_50360202_14_dialog_content = "Hmph, nunca lo hubiera imaginado...",
  ui_story_5036_50360202_15_dialog_content = "¡Que algún día aprenderías a tomar el crédito y robar el protagonismo por ti mismo, Loewe!",
  ui_story_5036_50360202_16_dialog_content = "La investigación aún no ha terminado.",
  ui_story_5036_50360202_17_dialog_content = "Pero alguien quería irse a casa.",
  ui_story_5036_50360202_18_dialog_content = "¡Otra vez con eso!",
  ui_story_5036_50360202_19_dialog_content = "No tengo idea de dónde aprendió Loewe a ser un imbécil y traicionar a sus colegas.",
  ui_story_5036_50360202_20_dialog_content = "No se deje influir por sus tonterías, Lady Carleen.",
  ui_story_5036_50360202_21_dialog_content = "Durante los últimos días, he dirigido el trabajo de la unidad de investigación de Lumopolis en el Coloso Errante de la manera más adecuada y ordenada.",
  ui_story_5036_50360202_22_dialog_content = "Podrás leer mi informe detallado desde lo alto de tu lujoso cojín de terciopelo en Lumopolis a su debido tiempo.",
  ui_story_5036_50360202_23_dialog_content = "¿Ah, de verdad? Así que no has estado merodeando por Siobhan en un intento de plagiar su trabajo, ¿eh?",
  ui_story_5036_50360202_24_dialog_content = "Tenga la seguridad, oficial Gronru.",
  ui_story_5036_50360202_25_dialog_content = "Protegeré nuestros archivos con todo lo que tengo.",
  ui_story_5036_50360202_26_dialog_content = "Parece que te han pillado in fraganti.",
  ui_story_5036_50360202_27_dialog_content = "¡Callate! ¡Solo estaba confirmando nuestros propios hallazgos!",
  ui_story_5036_50360202_28_dialog_content = "¡Oficial Gronru, señorita Siobhan!",
  ui_story_5036_50360202_29_dialog_content = "¿Así que estás aquí por misión en el Coloso Errante?",
  ui_story_5036_50360202_30_dialog_content = "Vamos a echarte un vistazo... Vice, cariño, ¿has perdido peso otra vez?",
  ui_story_5036_50360202_31_dialog_content = "¿Tengo yo?",
  ui_story_5036_50360202_32_dialog_content = "Si sigues tratando así a Vice, PlayerName¡Te la voy a robar!",
  ui_story_5036_50360202_33_dialog_content = "Yo no he hecho nada...",
  ui_story_5036_50360202_34_dialog_content = "¿Es eso así? Jejeje...",
  ui_story_5036_50360202_35_dialog_content = "De todos modos, llegaste aquí mucho más tarde de lo que esperaba.",
  ui_story_5036_50360202_36_dialog_content = "casi pensé PlayerName había renunciado a la idea de inspeccionar este Coloso.",
  ui_story_5036_50360202_37_dialog_content = "Pero que yo sepa...",
  ui_story_5036_50360202_38_dialog_content = "Ni Lumopolis ni la Federación Illumina nunca notificaron oficialmente PlayerName sobre el Coloso Errante.",
  ui_story_5036_50360202_39_dialog_content = "¿Mmm? No creo que nos hayamos conocido.",
  ui_story_5036_50360202_40_dialog_content = "Hola, soy Brandy, reportera en prácticas de The Daily Scoop.",
  ui_story_5036_50360202_41_dialog_content = "Estoy haciendo una función en PlayerName. Por favor responde mi pregunta.",
  ui_story_5036_50360202_42_dialog_content = "¿Por qué ninguno de ustedes informó PlayerName sobre el coloso errante?",
  ui_story_5036_50360202_43_dialog_content = "¿Es cierto que Illumina y Lumopolis planearon dividir el Coloso a espaldas de Caelestite?",
  ui_story_5036_50360202_44_dialog_content = "Joven reportero, Illumina está obligada a informar PlayerName?",
  ui_story_5036_50360202_45_dialog_content = "¡Oficial Gronru!",
  ui_story_5036_50360202_46_dialog_content = "¡Vaya! ¿Los asusté a todos?",
  ui_story_5036_50360202_47_dialog_content = "Ehehe bien, responderé amablemente.",
  ui_story_5036_50360202_48_dialog_content = "Enviamos un gran equipo a investigar tan pronto como recibimos noticias sobre el Coloso Errante.",
  ui_story_5036_50360202_49_dialog_content = "Tenemos mucho apoyo en espera tanto en tierra como en el aire cercano.",
  ui_story_5036_50360202_50_dialog_content = "Contrariamente a sus suposiciones, nuestro objetivo principal no es tomar el Coloso para nosotros.",
  ui_story_5036_50360202_51_dialog_content = "Estamos aquí para evaluar qué nivel de amenaza podría suponer para Illumina un Coloso saliendo de la Zona Oscura.",
  ui_story_5036_50360202_52_dialog_content = "Después de todo, vino de la Zona Oscura, y nadie sabe qué tipo de <color=#FFB400>pasajeros</color> están a bordo.",
  ui_story_5036_50360202_53_dialog_content = "Lumopolis comparte esta opinión.",
  ui_story_5036_50360202_54_dialog_content = "No entiendo por qué siempre me eligen para tareas sucias y laboriosas como esta.",
  ui_story_5036_50360202_55_dialog_content = "Las noticias del Coloso Errante nunca fueron censuradas.",
  ui_story_5036_50360202_56_dialog_content = "Yo mismo tengo curiosidad por saber por qué PlayerName no era consciente de ello.",
  ui_story_5036_50360202_57_dialog_content = "B-Bueno, hay una razón...",
  ui_story_5036_50360202_58_dialog_content = "¿Oh?",
  ui_story_5036_50360202_59_dialog_content = "Olvida eso. No creo que hayamos llegado demasiado tarde.",
  ui_story_5036_50360202_60_dialog_content = "Pero estoy desconcertado al ver Eclipsites deambulando por los pasillos del Coloso Errante.",
  ui_story_5036_50360202_61_dialog_content = "Lamento mucho que haya tenido que pasar tanto susto al llegar, Lady Carleen.",
  ui_story_5036_50360202_62_dialog_content = "Si me permite, le recomiendo que deje este Coloso inmediatamente.",
  ui_story_5036_50360202_63_dialog_content = "No solo está lleno de telarañas, sino que también parece albergar innumerables eclipses sucios.",
  ui_story_5036_50360202_64_dialog_content = "Sin embargo, no necesita preocuparse por nuestra seguridad.",
  ui_story_5036_50360202_65_dialog_content = "Después de días de esfuerzo, hemos contenido la mayoría de los eclipses en un <color=#FFB400>área bloqueada</color> en la sección trasera.",
  ui_story_5036_50360202_66_dialog_content = "¡Así que ten la seguridad!",
  ui_story_5036_50360202_67_dialog_content = "Ya he enviado gente para intensificar la eliminación de Eclipsites, ¡lo prometo!",
  ui_story_5036_50360202_68_dialog_content = "Esa escoria asquerosa nunca más te molestará.",
  ui_story_5036_50360202_69_dialog_content = "Bien hecho, juez Matthieu.",
  ui_story_5036_50360202_70_dialog_content = "El honor es mío.",
  ui_story_5036_50360202_71_dialog_content = "Entonces, ¿es relativamente seguro en este Colossus por el momento?",
  ui_story_5036_50360202_72_dialog_content = "Mientras no pongas un pie en el <color=#FFB400>área bloqueada</color> donde la dificultad se marca hacia arriba, ¡deberías estar bien!",
  ui_story_5036_50360202_73_dialog_content = "Gronru, quiero saber más sobre este Coloso...",
  ui_story_5036_50360202_74_option_content = "Sistema de control",
  ui_story_5036_50360202_75_dialog_content = "Tal vez pueda intentar aterrizarlo.",
  ui_story_5036_50360202_76_dialog_content = "También pensé en eso, así que revisamos minuciosamente el puente.",
  ui_story_5036_50360202_77_dialog_content = "Pero encontramos los sistemas de control y navegación, incluso el Echo Template, todos dañados.",
  ui_story_5036_50360202_78_dialog_content = "Incluso usted probablemente no puede controlarlo ahora.",
  ui_story_5036_50360202_79_dialog_content = "¿Cómo podría ser esto? Entonces, ¿qué pasa con el—",
  ui_story_5036_50360202_80_option_content = "Núcleo de energía",
  ui_story_5036_50360202_81_dialog_content = "El Coloso todavía se mueve, por lo que el núcleo de energía debería estar intacto, ¿verdad?",
  ui_story_5036_50360202_82_dialog_content = "Podría decirse eso.",
  ui_story_5036_50360202_83_dialog_content = "Ya que todavía está suministrando energía para que el Coloso siga volando.",
  ui_story_5036_50360202_84_dialog_content = "Pero al mismo tiempo, tampoco está en la mejor forma...",
  ui_story_5036_50360202_85_dialog_content = "porque sufrió ataques de Eclipsite en algún momento en el pasado.",
  ui_story_5036_50360202_86_dialog_content = "No es lo suficientemente malo que la energía se pierda repentinamente, pero definitivamente afecta la producción de energía.",
  ui_story_5036_50360202_87_dialog_content = "Eso es reparable, ¿verdad?",
  ui_story_5036_50360202_88_dialog_content = "Restaurar el núcleo de energía no es tarea fácil.",
  ui_story_5036_50360202_89_dialog_content = "Como mínimo, primero debe apagar el Colossus y apagar el núcleo de alimentación.",
  ui_story_5036_50360202_90_dialog_content = "De lo contrario, no tenemos suficiente tiempo para diagnosticarlo y repararlo.",
  ui_story_5036_50360202_91_dialog_content = "Excepto que ahora mismo ni siquiera sabemos cómo evitar que vuele.",
  ui_story_5036_50360202_92_dialog_content = "¿Cómo podría ser esto? Entonces, ¿qué pasa con el—",
  ui_story_5036_50360202_93_option_content = "Pantalla y sistema de altavoces",
  ui_story_5036_50360202_94_dialog_content = "Noté que estaba equipado con lo que parecía ser una pantalla y parlantes en el exterior.",
  ui_story_5036_50360202_95_dialog_content = "¡Sí, esos son auténticos!",
  ui_story_5036_50360202_96_dialog_content = "La tecnología está mucho más allá de nuestra amplitud actual de conocimiento.",
  ui_story_5036_50360202_97_dialog_content = "Están sorprendentemente bien conservados a pesar de su edad.",
  ui_story_5036_50360202_98_dialog_content = "¡Gracias a la ayuda de Siobhan, descubrimos cómo activarlos!",
  ui_story_5036_50360202_99_dialog_content = "¡Sería espectacular reproducir películas en una pantalla tan gigante!",
  ui_story_5036_50360202_100_dialog_content = "Y...",
  ui_story_5036_50360202_100X1_dialog_content = "¿Hay algo más?",
  ui_story_5036_50360202_100X2_option_content = "Si",
  ui_story_5036_50360202_100X3_option_content = "Eso es todo",
  ui_story_5036_50360202_101_dialog_content = "Ah, y otra cosa...",
  ui_story_5036_50360202_102_dialog_content = "¿Descubriste alguna Caelestites o artículos relacionados?",
  ui_story_5036_50360202_103_dialog_content = "Mmm, todavía no.",
  ui_story_5036_50360202_104_dialog_content = "Pero hablando de eso...",
  ui_story_5036_50360202_105_dialog_content = "Mi querida asistente Siobhan nos ayudó a desenterrar registros históricos sobre este coloso errante.",
  ui_story_5036_50360202_106_dialog_content = "Por su apariencia y tamaño, es muy obvio que este Coloso fue el que los Caelestitas reportaron perdido hace más de cien años, llamado—",
  ui_story_5036_50360202_107_dialog_content = "<color=#FFB400>Eulogoz?</color>",
  ui_story_5036_50360202_108_dialog_content = "¿Qué, ya lo sabías?",
  ui_story_5036_50360202_109_dialog_content = "Desafortunadamente, saber su nombre no importa.",
  ui_story_5036_50360202_110_dialog_content = "Este Coloso está repleto de tecnología malvada e inevitablemente debe ser destruido.",
  ui_story_5036_50360202_111_dialog_content = "Lo siento, ¿qué? ¿Quién está destruyendo a Eulogoz?",
  ui_story_5036_50360202_112_dialog_content = "No malinterpretes. No fue mi única decisión.",
  ui_story_5036_50360202_113_dialog_content = "Fue la solución que la mayoría de nosotros acordamos.",
  ui_story_5036_50360202_114_dialog_content = "Wow, ¿puedes actuar más villano?",
  ui_story_5036_50360202_115_dialog_content = "Es demasiado pronto para decir eso. Todavía no lo he firmado.",
  ui_story_5036_50360202_116_dialog_content = "Bueno, tal vez no sea tu elección al final.",
  ui_story_5036_50360202_117_dialog_content = "¿Qué está pasando, juez Matthieu? Por favor elabora.",
  ui_story_5036_50360202_118_dialog_content = "Ya me escuchó, Lady Carleen.",
  ui_story_5036_50360202_119_dialog_content = "Este coloso no tiene ningún valor y está repleto de eclipses incontrolables.",
  ui_story_5036_50360202_120_dialog_content = "Dejarlo a la deriva representará una gran amenaza para la supervivencia de todos en Astra.",
  ui_story_5036_50360202_121_dialog_content = "Además...",
  ui_story_5036_50360202_122_dialog_content = "¿Qué pasa si se estrella en Lumopolis?",
  ui_story_5036_50360202_123_dialog_content = "Destruir esta máquina abandonada mantiene a salvo a nuestra ciudad natal.",
  ui_story_5036_50360202_124_dialog_content = "Estoy seguro de que eres tan consciente como yo de que el Señor de la Ciudad haría la misma llamada si estuviera presente.",
  ui_story_5036_50360202_125_dialog_content = "Nuestros equipos de expedición han estado buscando incansablemente los restos de Colossi en el desierto.",
  ui_story_5036_50360202_126_dialog_content = "Ahora que finalmente encontramos uno que realmente funciona, ¿vamos a destruirlo?",
  ui_story_5036_50360202_127_dialog_content = "No escuches sus tonterías malvadas, Vice.",
  ui_story_5036_50360202_128_dialog_content = "Ya determinamos que su ruta de vuelo no cruzará a Lumopolis.",
  ui_story_5036_50360202_129_dialog_content = "Y si seguimos haciendo lo que estamos haciendo aquí, nos desharemos de todos los eclipses.",
  ui_story_5036_50360202_130_dialog_content = "Además, Eulogoz no es \"completamente inútil\" como afirma ese bufón.",
  ui_story_5036_50360202_131_dialog_content = "Cada una de sus partes es valiosa para la investigación.",
  ui_story_5036_50360202_132_dialog_content = "Aunque mucho está dañado y es muy difícil de arreglar...",
  ui_story_5036_50360202_133_dialog_content = "Sigo pensando que vale la pena el precio de arreglarlo.",
  ui_story_5036_50360202_134_dialog_content = "Pero también debes darte cuenta...",
  ui_story_5036_50360202_135_dialog_content = "que es mucho más eficiente desde el punto de vista financiero para usted salvar las partes que desea estudiar y explotar el resto.",
  ui_story_5036_50360202_136_dialog_content = "¿Por qué dejar esta cosa incontrolable volando por todo el cielo?",
  ui_story_5036_50360202_137_dialog_content = "¡Es mucho más valioso estudiar una muestra completa!",
  ui_story_5036_50360202_138_dialog_content = "¿Puede proporcionar evidencia del potencial de reparación del Colossus?",
  ui_story_5036_50360202_139_dialog_content = "¡Yo... necesito más tiempo!",
  ui_story_5036_50360202_140_dialog_content = "El tiempo no espera a nadie.",
  ui_story_5036_50360202_141_dialog_content = "Cuanto más espere, más costoso será este esfuerzo.",
  ui_story_5036_50360202_142_dialog_content = "Derribamos el Coloso, completamos la misión y nos separamos. ¿No es eso mejor?",
  ui_story_5036_50360202_143_dialog_content = "¿Así que solo quieres irte a casa?",
  ui_story_5036_50360202_144_dialog_content = "No me malinterprete, simplemente estoy empleando tácticas de negociación, Lady Carleen.",
  ui_story_5036_50360202_145_dialog_content = "Eulogoz pertenece a los caelestitas. ¡No dejaré que nadie lo derribe!",
  ui_story_5036_50360202_146_dialog_content = "¡Puedo ayudar a limpiar los eclipses!",
  ui_story_5036_50360202_147_dialog_content = "¡También te demostraré su verdadero valor!",
  ui_story_5036_50360202_148_dialog_content = "Por cierto. Yo también ayudaré.",
  ui_story_5036_50360202_149_dialog_content = "¿Qué está haciendo, señora Carleen?",
  ui_story_5036_50360202_150_dialog_content = "¡Ajá, parece que la Princesa de Lumopolis también se resiste a ver derribado a Eulogoz!",
  ui_story_5036_50360202_151_dialog_content = "Cariño, no hay tiempo para la desgana en este mundo.",
  ui_story_5036_50360202_152_dialog_content = "Si lo hay, solo significa que no se ha ofrecido suficiente dinero.",
  ui_story_5036_50360202_153_dialog_content = "¿Ah?",
  ui_story_5036_50360202_154_dialog_content = "Aunque no me importa que las chicas me adulen, esto todavía me pone la piel de gallina.",
  ui_story_5036_50360202_155_dialog_content = "¿Señorita Sheol?",
  ui_story_5036_50360202_156_dialog_content = "Ah, PlayerName, mi VIP!",
  ui_story_5036_50360202_157_dialog_content = "No has ido al Cloudrover Guild para verme en mucho tiempo.",
  ui_story_5036_50360202_158_dialog_content = "Pero esa no es razón para que vengas tan lejos a venderme cosas...",
  ui_story_5036_50360202_159_dialog_content = "Jajaja, nuestro adorable PlayerName ha desarrollado un sentido del humor.",
  ui_story_5036_50360202_160_dialog_content = "Pero en cierto sentido, tienes razón.",
  ui_story_5036_50360202_161_dialog_content = "Esta vez, sin embargo, tengo una propuesta un poco diferente.",
  ui_story_5036_50360202_162_dialog_content = "¡Ven aquí, cariño!",
  ui_story_5036_50360202_163_dialog_content = "¿Estás hablando conmigo?",
  ui_story_5036_50360202_164_dialog_content = "No temas al daño ni al fracaso.",
  ui_story_5036_50360202_165_dialog_content = "La persistencia será recompensada con buena fortuna.",
  ui_story_5036_50360202_166_dialog_content = "No te desanimes ni te desanimes.",
  ui_story_5036_50360202_167_dialog_content = "¡Solo mira el camino de Goldie!",
  ui_story_5036_50360202_168_dialog_content = "¡Visitantes del Coloso, encantados de conoceros a todos!",
  ui_story_5036_50360202_169_dialog_content = "¿G-Goldie?",
  ui_story_5036_50360202_170_dialog_content = "Hola, PlayerName! ¿Como has estado?",
  ui_story_5036_50360202_171_dialog_content = "¿Qué?",
  ui_story_5036_50360202_172_dialog_content = "¿Qué hace Goldie aquí?",
  ui_story_5036_50360202_173_dialog_content = "Como parece que todos se conocen, puedo comenzar la conversación de negocios.",
  ui_story_5036_50360202_174_dialog_content = "Creo que me sobreestimas, Lady Sheol.",
  ui_story_5036_50360202_175_dialog_content = "Nunca podría permitirme contratar a una celebridad para que hiciera un espectáculo para mí.",
  ui_story_5036_50360202_176_dialog_content = "Cariño, la razón por la que viajé en un costoso dirigible de alquiler y vine hasta aquí con la estrella más caliente a cuestas...",
  ui_story_5036_50360202_177_dialog_content = "ciertamente no fue solo para presentarle una empresa comercial solo a usted.",
  ui_story_5036_50360202_178_dialog_content = "Esto podría ser demasiado repentino y podría sonar impactante, jeje.",
  ui_story_5036_50360202_179_dialog_content = "¡Pero ya ves, queremos ofrecer un concierto especial y único en este Colossus que envía ondas de choque en todo Astra!",
  ui_story_5036_50360202_180_dialog_content = "Cuando llegue a Umbraton...",
  ui_story_5036_50360202_181_dialog_content = "¡Me pararé sobre él y cantaré mis bendiciones para que todos lo escuchen!",
  ui_story_5036_50360202_182_dialog_content = "¡Todo Umbraton y Lumopolis podrán ver el espectáculo en la pantalla gigante!",
  ui_story_5036_50360202_183_dialog_content = "Hmph, los plebeyos nunca cambian... Siempre soñando demasiado para tus pantalones.",
  ui_story_5036_50360202_184_dialog_content = "Realmente no crees que puedes cantar solo porque tienes boca, ¿verdad? Y por cierto, parece que llevas adornos de pastel.",
  ui_story_5036_50360202_185_dialog_content = "¿Qué tipo de término vulgar es \"ídolo\", de todos modos?",
  ui_story_5036_50360202_186_dialog_content = "Wow, esta es la razón por la cual la gente no debería recluirse en pequeñas islas flotantes como lo hacen ustedes en Lumopolis.",
  ui_story_5036_50360202_187_dialog_content = "No deberías hablar cuando ni siquiera sabes lo que es un ídolo.",
  ui_story_5036_50360202_188_dialog_content = "¿Me estás llamando ignorante?",
  ui_story_5036_50360202_189_dialog_content = "La verdad siempre duele.",
  ui_story_5036_50360202_190_dialog_content = "Siobhan, eduquemos a nuestro juez aquí sobre el concepto de un ídolo, ¿de acuerdo?",
  ui_story_5036_50360202_191_dialog_content = "Sí, oficial Gronru.",
  ui_story_5036_50360202_192_dialog_content = "Los ídolos son una ocupación recién surgida en Umbraton y el desierto de Rediesel.",
  ui_story_5036_50360202_193_dialog_content = "Se dedican principalmente a actividades relacionadas con el entretenimiento, como cantar, bailar y ser anfitriones.",
  ui_story_5036_50360202_194_dialog_content = "En comparación con los cantantes, bailarines y actores tradicionales, están mucho más dispuestos a estar más cerca de sus fans.",
  ui_story_5036_50360202_195_dialog_content = "Obtienen apoyo con su encanto individual y, a cambio, transmiten positividad a sus fans.",
  ui_story_5036_50360202_196_dialog_content = "Sí, esa es la esencia de esto.",
  ui_story_5036_50360202_197_dialog_content = "My Goldie tiene múltiples talentos, aunque nuestro enfoque actual está en su carrera como cantante.",
  ui_story_5036_50360202_198_dialog_content = "Entiendo...",
  ui_story_5036_50360202_199_dialog_content = "Uh, quiero decir, ¡no estoy interesado en los asuntos de los plebeyos!",
  ui_story_5036_50360202_200_dialog_content = "Llegué a donde estoy hoy todo gracias a mis fans, los Ricitos de Oro.",
  ui_story_5036_50360202_201_dialog_content = "¡Quiero que me vean actuando para ellos en el escenario más grande posible!",
  ui_story_5036_50360202_202_dialog_content = "Je, no me importan los conciertos...",
  ui_story_5036_50360202_203_dialog_content = "¿Pero no es demasiado albergar uno en el Coloso Errante?",
  ui_story_5036_50360202_204_dialog_content = "Cariño, ¿no dijiste tú misma que la pantalla y los sistemas estéreo funcionaban perfectamente?",
  ui_story_5036_50360202_205_dialog_content = "Seguramente a alguien tan apasionado por Colossi como usted le encantaría presenciar el funcionamiento de estos sistemas en persona, ¿no es así?",
  ui_story_5036_50360202_206_dialog_content = "Bueno...",
  ui_story_5036_50360202_207_dialog_content = "Imagínese, una multitud masiva reunida en la orilla del río Gold. Solo tienen que mirar hacia arriba...",
  ui_story_5036_50360202_208_dialog_content = "para ver el concierto en una pantalla gigante.",
  ui_story_5036_50360202_209_dialog_content = "Las personas que viajan en aeronaves pueden incluso ver el espectáculo sobre el escenario del concierto.",
  ui_story_5036_50360202_210_dialog_content = "Parece que sería un gran festival para todo el continente...",
  ui_story_5036_50360202_211_dialog_content = "¡Sí, un gran festival para Astra! me gusta como lo pones PlayerName!",
  ui_story_5036_50360202_212_dialog_content = "Me sorprendió oírte llamar a esto Colossus Eulogoz.",
  ui_story_5036_50360202_213_dialog_content = "Tal vez fue construido para transmitir canciones.",
  ui_story_5036_50360202_214_dialog_content = "Si realmente debe ser destruido...",
  ui_story_5036_50360202_215_dialog_content = "¡Me encantaría que entregara una canción final antes de eso!",
  ui_story_5036_50360202_216_dialog_content = "!",
  ui_story_5036_50360202_217_dialog_content = "Qué pena.",
  ui_story_5036_50360202_218_dialog_content = "El Colossus volará a través de una región deshabitada mañana, que es el mejor lugar para derribarlo.",
  ui_story_5036_50360202_219_dialog_content = "Eso no te dejará tiempo para un concierto.",
  ui_story_5036_50360202_220_dialog_content = "No apresuremos las cosas, gente.",
  ui_story_5036_50360202_221_dialog_content = "Después de volar sobre Umbraton, si continúa a lo largo del Río Dorado...",
  ui_story_5036_50360202_222_dialog_content = "llegará a una región deshabitada aún más grande.",
  ui_story_5036_50360202_223_dialog_content = "¿Quieres decir... el mar?",
  ui_story_5036_50360202_224_dialog_content = "¿Derribar el Coloso sobre el mar?",
  ui_story_5036_50360202_225_dialog_content = "Creo que es una buena idea, oficial Gronru.",
  ui_story_5036_50360202_226_dialog_content = "Un concierto exitoso demostraría su valor y lo salvaría de la destrucción.",
  ui_story_5036_50360202_227_dialog_content = "Eso también nos dará más tiempo para tratar de arreglar el Colossus.",
  ui_story_5036_50360202_228_dialog_content = "Si el concierto resulta ser un fracaso, aún podemos derribarlo una vez que esté sobre el océano.",
  ui_story_5036_50360202_229_dialog_content = "Es la forma más segura de hacerlo, ya que no dañaría a nadie en tierra.",
  ui_story_5036_50360202_230_dialog_content = "¡Ay, te lo ruego!",
  ui_story_5036_50360202_231_dialog_content = "Por favor pospongan la destrucción de este Coloso...",
  ui_story_5036_50360202_232_dialog_content = "¡Permítanos construir un escenario y organizar un concierto sin precedentes!",
  ui_story_5036_50360301_1_dialog_content = "<color=#e8d9bb>Seis días para el concierto</color>",
  ui_story_5036_50360301_2_dialog_content = "El lado izquierdo está apagado. Muévelo un poco hacia arriba.",
  ui_story_5036_50360301_3_dialog_content = "¿Así?",
  ui_story_5036_50360301_4_dialog_content = "Ahora el lado derecho está apagado.",
  ui_story_5036_50360301_5_dialog_content = "Mm, creo que el cartel se ve bien torcido.",
  ui_story_5036_50360301_6_dialog_content = "¿Qué opinas, nombre del jugador?",
  ui_story_5036_50360301_7_dialog_content = "No soy un experto, ¿por qué no le preguntamos a Goldie?",
  ui_story_5036_50360301_8_dialog_content = "¡Wau!",
  ui_story_5036_50360301_9_dialog_content = "¡Ah! ¡Que hermosura! ¡Quiero acariciar a Marshmallow cada vez que lo veo!",
  ui_story_5036_50360301_10_dialog_content = "¡A Marshmallow también le encanta ser mascota!",
  ui_story_5036_50360301_11_dialog_content = "¡Guau guau!",
  ui_story_5036_50360301_12_dialog_content = "Muy bien, Marshmallow, luego jugaré contigo.",
  ui_story_5036_50360301_13_dialog_content = "Así que danos algo de tiempo para hablar, ¿de acuerdo?",
  ui_story_5036_50360301_14_dialog_content = "¡Wau!",
  ui_story_5036_50360301_15_dialog_content = "¿Qué querían preguntarme con tanta urgencia?",
  ui_story_5036_50360301_16_dialog_content = "Estamos ocupados colocando carteles, pero no estamos seguros de cuál es la mejor manera de hacerlo...",
  ui_story_5036_50360301_17_dialog_content = "¿Qué? Ustedes no tienen que hacer todo esto.",
  ui_story_5036_50360301_18_dialog_content = "Sí.",
  ui_story_5036_50360301_19_dialog_content = "Si no fuera por tu idea del concierto, Eulogoz probablemente ya estaría destruido.",
  ui_story_5036_50360301_20_dialog_content = "No podemos lidiar con ninguno de los equipos, así que los carteles son todo lo que podemos hacer.",
  ui_story_5036_50360301_21_dialog_content = "Oh, ustedes ya me ayudaron más de lo que saben.",
  ui_story_5036_50360301_22_dialog_content = "Sin ti, no creo que Illumina y Lumopolis hubieran estado de acuerdo con esto.",
  ui_story_5036_50360301_23_dialog_content = "El Gran Mariscal me autorizó a tomar decisiones con respecto al Coloso Errante...",
  ui_story_5036_50360301_24_dialog_content = "pero todavía necesito unos días más para investigar antes de poder darte una respuesta.",
  ui_story_5036_50360301_25_dialog_content = "¿Qué más hay que investigar? ¡Esto es una farsa!",
  ui_story_5036_50360301_26_dialog_content = "¿Por qué los nobles de Lumopolis se preocuparían por los ídolos de los plebeyos?",
  ui_story_5036_50360301_27_dialog_content = "Sé que solo yo no es suficiente, así que este no será mi propio concierto en solitario.",
  ui_story_5036_50360301_28_dialog_content = "¡Planeo invitar a estrellas de todas partes a unirse a mí en este concierto en el cielo!",
  ui_story_5036_50360301_29_dialog_content = "Tal vez en Lumopolis e Illumina, tienes una idea diferente de lo que son los ídolos,",
  ui_story_5036_50360301_30_dialog_content = "pero eso está bien. ¡Puedes enviar a tus ídolos a participar también, sean quienes sean!",
  ui_story_5036_50360301_31_dialog_content = "¡Yo apoyo esto!",
  ui_story_5036_50360301_32_dialog_content = "¿Ah?",
  ui_story_5036_50360301_33_dialog_content = "¡Apoyo a Goldie organizando un concierto en el Colossus!",
  ui_story_5036_50360301_34_dialog_content = "Ella está en lo correcto. El propósito de Eulogoz puede haber sido transmitir música.",
  ui_story_5036_50360301_35_dialog_content = "Como Caelestite, quiero verlo cumplir su propósito.",
  ui_story_5036_50360301_36_dialog_content = "¡Y quiero ver a personas de diferentes lugares dejar de lado sus prejuicios y disfrutar de la música juntos!",
  ui_story_5036_50360301_37_dialog_content = "Quizás Eulogoz volvió para ayudarnos a entender",
  ui_story_5036_50360301_38_dialog_content = "que somos capaces de lograr algo juntos, sin importar de dónde venimos o quiénes somos.",
  ui_story_5036_50360301_39_dialog_content = "Por favor, dele a Goldie y Eugoloz el tiempo que necesitan.",
  ui_story_5036_50360301_40_dialog_content = "Y yo también. Quizás...",
  ui_story_5036_50360301_41_dialog_content = "¡Tal vez pueda encontrar una forma de salvar a Eulogoz!",
  ui_story_5036_50360301_42_dialog_content = "Ahora que lo pienso, tu discurso fue tan épico, PlayerName!",
  ui_story_5036_50360301_43_dialog_content = "Me emocionó tanto que casi lloré.",
  ui_story_5036_50360301_44_dialog_content = "No es de extrañar que Sheol siempre diga que los Lovegators superan en número a los Goldilocks.",
  ui_story_5036_50360301_45_dialog_content = "Nah, no soy todo eso... Supongo que soy fácilmente excitable y tengo tendencia a empezar a divagar sin pensar.",
  ui_story_5036_50360301_46_dialog_content = "Personalmente, pensé que Lady Sheol era la más genial.",
  ui_story_5036_50360301_47_dialog_content = "¡Prácticamente brillaba cuando sonrió y dijo que pagaría la factura de todos los que trabajaran en el proyecto!",
  ui_story_5036_50360301_48_dialog_content = "Los empresarios no hacen tratos perdedores.",
  ui_story_5036_50360301_49_dialog_content = "Estaba segura de que el concierto sería rentable cuando decidió invertir en él.",
  ui_story_5036_50360301_50_dialog_content = "Pero, ¿cómo va a ganar dinero cuando todo el mundo tiene que pararse junto al Gold River y escucharlo gratis?",
  ui_story_5036_50360301_51_dialog_content = "Lástima que ya está de vuelta en Umbraton para promocionar el concierto.",
  ui_story_5036_50360301_52_dialog_content = "¡Tengo que preguntarle cómo se está beneficiando!",
  ui_story_5036_50360301_53_dialog_content = "Vice, a veces pienso que deberías haber nacido en Umbraton.",
  ui_story_5036_50360301_54_dialog_content = "Hablas de Nightium mucho más en serio que durante tus años como estudiante de intercambio en Lumopolis.",
  ui_story_5036_50360301_55_dialog_content = "¿Soy? Bueno, culpar a alguien por eso.",
  ui_story_5036_50360301_56_dialog_content = "Oigan, ¿por qué están todos mirándome?",
  ui_story_5036_50360301_57_dialog_content = "Je, no podemos esperar entender las maniobras comerciales de Sheol.",
  ui_story_5036_50360301_58_dialog_content = "¡Todo lo que tenemos que hacer es hacer nuestro propio trabajo!",
  ui_story_5036_50360301_59_dialog_content = "¡Y ahora mismo, mi trabajo es prepararme para el concierto!",
  ui_story_5036_50360301_60_dialog_content = "...",
  ui_story_5036_50360301_61_dialog_content = "Algo en tu mente, PlayerName?",
  ui_story_5036_50360301_62_dialog_content = "Oh, estaba pensando, aunque la pantalla y los parlantes de Eulogoz están bien...",
  ui_story_5036_50360301_63_dialog_content = "¿Son realmente suficientes para que todos en tierra escuchen la música?",
  ui_story_5036_50360301_64_dialog_content = "¿Tienes tan poca fe en la tecnología Caelestite?",
  ui_story_5036_50360301_65_dialog_content = "¡Tengo fe en ello, por supuesto! Es solo que...",
  ui_story_5036_50360301_66_dialog_content = "Mira, sé lo que preocupa a todo el mundo. Confía en mí, quiero que el concierto transcurra sin problemas más que nadie.",
  ui_story_5036_50360301_67_dialog_content = "Le pregunté a Siobhan sobre los problemas del equipo y aprendí a controlar el volumen.",
  ui_story_5036_50360301_68_dialog_content = "¡Definitivamente podrán escuchar mi voz en el suelo a través del equipo!",
  ui_story_5036_50360301_69_dialog_content = "¿Ya te ocupaste de eso? No debería haber esperado menos de un ídolo profesional.",
  ui_story_5036_50360301_70_dialog_content = "Por cierto, ¿no estás buscando una forma de salvar a Eulogoz?",
  ui_story_5036_50360301_71_dialog_content = "¿Alguna novedad en ese frente?",
  ui_story_5036_50360301_72_dialog_content = "Nada en absoluto.",
  ui_story_5036_50360301_73_dialog_content = "Realmente no tenía idea de en lo que me estaba metiendo.",
  ui_story_5036_50360301_74_dialog_content = "¿Por qué pensé que podría pensar en algo cuando ni siquiera el oficial técnico de Illumina pudo?",
  ui_story_5036_50360301_75_dialog_content = "No seas tan negativo, PlayerName!",
  ui_story_5036_50360301_76_dialog_content = "Quieres que consulte mi <color=#FFB400>bala de la suerte</color> ¿para ti?",
  ui_story_5036_50360301_77_dialog_content = "¿Tu que?",
  ui_story_5036_50360301_78_dialog_content = "Bala de la suerte, voluntad PlayerName encontrar una manera de salvar a Eulogoz?",
  ui_story_5036_50360301_79_dialog_content = "Si es así, ¡aterriza de cabeza primero!",
  ui_story_5036_50360301_80_dialog_content = "PlayerName, ven a tirar la bala al aire!",
  ui_story_5036_50360301_81_dialog_content = "¿Echarlo? ¿Como esto?",
  ui_story_5036_50360301_82_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_5036_50360301_83_dialog_content = "Allí va...",
  ui_story_5036_50360301_84_dialog_content = "<color=#e8d9bb>¡Tintinar!</color>",
  ui_story_5036_50360301_85_dialog_content = "¡Perfecto! ¡Mira, aterrizó de cabeza!",
  ui_story_5036_50360301_86_dialog_content = "¡Mi bala de la suerte está segura de que encontrarás la manera!",
  ui_story_5036_50360301_87_dialog_content = "¿En serio?",
  ui_story_5036_50360301_88_dialog_content = "Cuando tengo problemas, la bala siempre tiene una respuesta para mí.",
  ui_story_5036_50360301_89_dialog_content = "¡Creo que también te traerá buena suerte!",
  ui_story_5036_50360301_90_dialog_content = "... Está bien. ¡No me rendiré!",
  ui_story_5036_50360301_91_dialog_content = "Siempre me llenas de motivación, Goldie.",
  ui_story_5036_50360301_92_dialog_content = "¡Creo que voy a ser un Goldilock yo mismo!",
  ui_story_5036_50360301_93_dialog_content = "¡Jaja, deberías!",
  ui_story_5036_50360301_94_dialog_content = "Ya he sido un Lovegator acérrimo durante mucho tiempo, solo para que lo sepas.",
  ui_story_5036_50360301_95_dialog_content = "¿Qué?",
  ui_story_5036_50360301_96_dialog_content = "<color=#e8d9bb>¡Hacer clic!</color>",
  ui_story_5036_50360301_97_dialog_content = "¿Ah?",
  ui_story_5036_50360301_98_dialog_content = "¡P-Perdóname!",
  ui_story_5036_50360301_99_dialog_content = "Me conmovió su nueva camaradería y no pude evitar tomar una foto grupal por el bien de la memoria...",
  ui_story_5036_50360301_100_dialog_content = "Wow, gracias Brandy!",
  ui_story_5036_50360301_101_dialog_content = "(Goldie... dijo mi nombre...?)",
  ui_story_5036_50360301_102_dialog_content = "La prensa en Umbraton seguro sabe lo que están haciendo si pudieron enviarte para cubrir el concierto tan rápido.",
  ui_story_5036_50360301_103_dialog_content = "En realidad, vine con PlayerName.",
  ui_story_5036_50360301_104_dialog_content = "Sí, Brandy está haciendo un reportaje sobre mí.",
  ui_story_5036_50360301_105_dialog_content = "Ah, ¿así que estabas aquí por él?",
  ui_story_5036_50360301_106_dialog_content = "Creo que estoy un poco celoso.",
  ui_story_5036_50360301_107_dialog_content = "eh...",
  ui_story_5036_50360301_108_dialog_content = "¡Es una broma!",
  ui_story_5036_50360301_109_dialog_content = "No pensé que me recordarías.",
  ui_story_5036_50360301_110_dialog_content = "Por supuesto que sí. ¡Guardé un recorte de ese artículo que hiciste sobre mí!",
  ui_story_5036_50360301_111_dialog_content = "Pero estaba tan mal escrito que el editor incluso me regañó por ello.",
  ui_story_5036_50360301_112_dialog_content = "No quiero oírte decir eso de ti, Brandy.",
  ui_story_5036_50360301_113_dialog_content = "¡Eres más diligente que nadie cuando se trata de entrevistas!",
  ui_story_5036_50360301_114_dialog_content = "Tienes que creer en ti mismo y en tu juicio, sin importar lo que digan los demás.",
  ui_story_5036_50360301_115_dialog_content = "Cree en mi...",
  ui_story_5036_50360301_116_dialog_content = "Siempre transmites tanta positividad que gano la energía para seguir trabajando.",
  ui_story_5036_50360301_117_dialog_content = "Pero escuché a los reporteros senior decir que has estado planeando tu show en el Star Theatre durante mucho tiempo.",
  ui_story_5036_50360301_118_dialog_content = "¿No se cancelará si estás dando un concierto en el Coloso Errante?",
  ui_story_5036_50360301_119_dialog_content = "Sobre eso...",
  ui_story_5036_50360301_120_dialog_content = "Simplemente no puedo perderme un lugar tan grandioso como Eulogoz.",
  ui_story_5036_50360301_121_dialog_content = "Habrá muchas más oportunidades para mí en los escenarios de Umbraton en el futuro.",
  ui_story_5036_50360301_122_dialog_content = "Comprendo.",
  ui_story_5036_50360301_123_dialog_content = "¡Ja ja! ¡Todo salió a la perfección!",
  ui_story_5036_50360301_124_dialog_content = "¡La bala de la suerte estaba en lo cierto acerca de que yo conseguiría un gran reportero!",
  ui_story_5036_50360301_125_dialog_content = "¿Qué?",
  ui_story_5036_50360301_126_dialog_content = "Sheol me pidió que consiguiera un reportero para cubrir el concierto, pero no tenía idea de dónde encontrar uno.",
  ui_story_5036_50360301_127_dialog_content = "Si es posible, me encantaría que cubrieras este proyecto hasta el final, Brandy.",
  ui_story_5036_50360301_128_dialog_content = "Es decir, si no es mucho pedir...",
  ui_story_5036_50360301_129_dialog_content = "Puedes pensarlo antes de darme una respuesta.",
  ui_story_5036_50360301_130_dialog_content = "(¡Esa es la amable y considerada Goldie que conozco!)",
  ui_story_5036_50360301_131_dialog_content = "(Esa noticia de que ella tiene una mala racha probablemente fue inventada).",
  ui_story_5036_50360301_132_dialog_content = "No nos quedemos parados.",
  ui_story_5036_50360301_133_dialog_content = "¡Aún tenemos carteles para colocar!",
  ui_story_5036_50360301_134_dialog_content = "Seguro que se mueven rápido.",
  ui_story_5036_50360301_135_dialog_content = "El corredor aquí también está cubierto con coloridos carteles.",
  ui_story_5036_50360301_136_dialog_content = "Simplemente no entiendo el trato con los ídolos.",
  ui_story_5036_50360301_137_dialog_content = "Suben al escenario, sonríen, actúan lindos y reciben vítores y aplausos.",
  ui_story_5036_50360301_138_dialog_content = "Mientras tanto, aquí trabajamos duro y no recibimos ningún elogio.",
  ui_story_5036_50360301_139_dialog_content = "¿Derecha? Nunca antes había oído hablar de ídolos con disfraces tan llamativos y extraños.",
  ui_story_5036_50360301_140_dialog_content = "¡Cantar y bailar solo pueden entretener, no salvar a la gente!",
  ui_story_5036_50360301_141_dialog_content = "Nunca pensé que habría un día en el que me encontraría cara a cara con alguien de Lumopolis.",
  ui_story_5036_50360301_142_dialog_content = "Bueno, nosotros somos los desafortunados.",
  ui_story_5036_50360301_143_dialog_content = "¡Llegan a dar un concierto y nos dejan para asegurar el perímetro y limpiar Eclipsites!",
  ui_story_5036_50360301_144_dialog_content = "No sé por qué, pero en los últimos días me he sentido cada vez más fatigado.",
  ui_story_5036_50360301_145_dialog_content = "Cuéntame.",
  ui_story_5036_50360301_146_dialog_content = "Ejem...",
  ui_story_5036_50360301_147_dialog_content = "!",
  ui_story_5036_50360301_148_dialog_content = "¡Saludos, Teniente Vice!",
  ui_story_5036_50360301_149_dialog_content = "¡Buenos días, Lady Carleen!",
  ui_story_5036_50360301_150_dialog_content = "A gusto. Estás haciendo un gran trabajo.",
  ui_story_5036_50360301_151_dialog_content = "Uh, probablemente dijimos muchas cosas estúpidas, ¡así que por favor perdónanos!",
  ui_story_5036_50360301_152_dialog_content = "¡Perdónenos, Teniente Vice!",
  ui_story_5036_50360301_153_dialog_content = "Burlarnos de los civiles no es lo que hacemos como caballeros.",
  ui_story_5036_50360301_154_dialog_content = "Deberías saber lo que debes hacer ahora.",
  ui_story_5036_50360301_155_dialog_content = "¡Mis disculpas, señorita Goldie!",
  ui_story_5036_50360301_156_dialog_content = "Y usted también.",
  ui_story_5036_50360301_157_dialog_content = "¡Lo siento, señorita Goldie!",
  ui_story_5036_50360301_158_dialog_content = "No fui caballeroso en mi discurso. ¡Por favor castígame con esta espada!",
  ui_story_5036_50360301_159_dialog_content = "Está bien. Los castigaré a los dos...",
  ui_story_5036_50360301_160_dialog_content = "enviándote a la cama temprano. ¡Que tengas un dulce sueño!",
  ui_story_5036_50360301_161_dialog_content = "¿Ah?",
  ui_story_5036_50360301_162_dialog_content = "Vamos, ¿quién no se queja cuando está en el trabajo?",
  ui_story_5036_50360301_163_dialog_content = "Y verdaderamente, soy la razón del aumento de la carga de trabajo de todos.",
  ui_story_5036_50360301_164_dialog_content = "¡Debería ser yo quien se disculpara!",
  ui_story_5036_50360301_165_dialog_content = "Le pedí a Sheol que contratara mercenarios de Umbraton para ayudar a llevar la carga.",
  ui_story_5036_50360301_166_dialog_content = "¡Tendrán más tiempo de inactividad para ustedes!",
  ui_story_5036_50360301_167_dialog_content = "Bueno.",
  ui_story_5036_50360301_168_dialog_content = "Hay bebidas energéticas al final del pasillo. Me imagino que ustedes dos no han tenido la oportunidad de tomar algo.",
  ui_story_5036_50360301_169_dialog_content = "¡Ve a probarlo!",
  ui_story_5036_50360301_170_dialog_content = "¡Te garantizo que te sentirás revitalizado después de tomar un poco!",
  ui_story_5036_50360301_171_dialog_content = "...",
  ui_story_5036_50360301_172_dialog_content = "Por qué sigues aquí? La escuchaste.",
  ui_story_5036_50360301_173_dialog_content = "Su Alteza...?",
  ui_story_5036_50360301_174_dialog_content = "La señorita Goldie ha repartido su castigo, así que puedes irte.",
  ui_story_5036_50360301_175_dialog_content = "¡Gracias, Su Alteza! ¡Gracias, señorita Goldie!",
  ui_story_5036_50360301_176_dialog_content = "¡Gracias, Teniente Vice! ¡Gracias, señorita Goldie!",
  ui_story_5036_50360301_177_dialog_content = "De hecho, hay mucho que considerar cuando se organiza un concierto.",
  ui_story_5036_50360301_178_dialog_content = "No puedo creer que me olvidé de tener en cuenta a los soldados...",
  ui_story_5036_50360301_179_dialog_content = "Si crees que es necesario, Goldie, puedo pedir más Lumo Knights.",
  ui_story_5036_50360301_180_dialog_content = "Está bien, ¡no debería molestarte más de lo que lo he hecho!",
  ui_story_5036_50360301_181_dialog_content = "Ya le pedí a los Mercenarios de la Llama Blanca que me ayudaran a entregar suministros y construir el escenario.",
  ui_story_5036_50360301_182_dialog_content = "¡Lo agregaré a su agenda cuando lleguen aquí!",
  ui_story_5036_50360301_183_dialog_content = "No es barato contratar a los White Flames para cosas como esta.",
  ui_story_5036_50360301_184_dialog_content = "¿Será Sheol responsable de los gastos?",
  ui_story_5036_50360301_185_dialog_content = "...",
  ui_story_5036_50360301_186_dialog_content = "¿Goldie?",
  ui_story_5036_50360301_187_dialog_content = "¿Ah?",
  ui_story_5036_50360301_188_dialog_content = "Oh, uh... sí, Sheol es muy ingenioso. No debería ser un problema.",
  ui_story_5036_50360301_189_dialog_content = "¿Estabas preocupada por algo, Goldie?",
  ui_story_5036_50360301_190_dialog_content = "Realmente no...",
  ui_story_5036_50360301_191_dialog_content = "Es solo que las Llamas Blancas ya deberían estar aquí, pero no lo están...",
  ui_story_5036_50360301_192_dialog_content = "<color=#e8d9bb>*Pasos caóticos*</color>",
  ui_story_5036_50360301_193_dialog_content = "Escucho pasos... Suena como un grupo de personas viniendo hacia aquí.",
  ui_story_5036_50360301_194_dialog_content = "Hablando del diablo... Deben ser ellos.",
  ui_story_5036_50360301_195_dialog_content = "¡Qué casualidad!",
  ui_story_5036_50360301_196_dialog_content = "¡Graaaaaagh!",
  ui_story_5036_50360301_197_dialog_content = "¿Qué? ¡Oh, no!",
  ui_story_5036_50360301_198_dialog_content = "¡Estos no son mercenarios!",
  ui_story_5036_50360301_199_dialog_content = "¡Yo no contraté a Eclipsites!",
  ui_story_5036_50360302_1_dialog_content = "¡Cuidado detrás de ti, Goldie!",
  ui_story_5036_50360302_2_dialog_content = "¿Qué...?",
  ui_story_5036_50360302_3_dialog_content = "Grah!",
  ui_story_5036_50360302_4_dialog_content = "¡Fuera!",
  ui_story_5036_50360302_5_dialog_content = "¡Los Mercenarios de la Llama Blanca están aquí!",
  ui_story_5036_50360302_6_dialog_content = "¿Está bien, señorita Goldie?",
  ui_story_5036_50360302_7_dialog_content = "Estoy bien, gracias a tu sincronización perfecta.",
  ui_story_5036_50360302_8_dialog_content = "Yo no lo llamaría perfecto...",
  ui_story_5036_50360302_9_dialog_content = "Conseguir los suministros para el escenario costó más tiempo del esperado, así que lamento que acabemos de llegar.",
  ui_story_5036_50360302_10_dialog_content = "Aunque tampoco pensé que habría Eclipsitos en el Coloso Errante.",
  ui_story_5036_50360302_11_dialog_content = "Bueno, lo descubrí después de subirme.",
  ui_story_5036_50360302_12_dialog_content = "Pero los soldados de Illumina y Lumopolis confinaron a la mayoría de los Eclipsites a un área segura en la parte trasera.",
  ui_story_5036_50360302_13_dialog_content = "Todavía hay algunos rezagados dando vueltas, pero como viste...",
  ui_story_5036_50360302_14_dialog_content = "No son formidables.",
  ui_story_5036_50360302_15_dialog_content = "Los soldados han intensificado sus esfuerzos de limpieza.",
  ui_story_5036_50360302_16_dialog_content = "Ahora con tu ayuda...",
  ui_story_5036_50360302_17_dialog_content = "Estoy seguro de que estos rezagados y los de la retaguardia también serán tratados.",
  ui_story_5036_50360302_18_dialog_content = "Haremos todo lo posible para completar las tareas de Lady Sheol.",
  ui_story_5036_50360302_19_dialog_content = "¡Puedes contar con nosotros!",
  ui_story_5036_50360302_20_dialog_content = "¡Gracias a todos!",
  ui_story_5036_50360302_21_dialog_content = "Sin sudar. Oh, escuchamos en Umbraton que",
  ui_story_5036_50360302_22_dialog_content = "¡un montón de gente ya se ha apuntado al concierto!",
  ui_story_5036_50360302_23_dialog_content = "¡Las noticias viajan rápido!",
  ui_story_5036_50360302_24_dialog_content = "Wow, la gente está mucho más emocionada de lo que imaginaba.",
  ui_story_5036_50360302_25_dialog_content = "Antes de que comience oficialmente el espectáculo, también estamos organizando un <color=#FFB400>audición de ídolos</color>.",
  ui_story_5036_50360302_26_dialog_content = "Vamos a elegir ídolos con fuerte presencia en el escenario.",
  ui_story_5036_50360302_27_dialog_content = "¿Una audición de ídolos? ¡Eso suena como un evento emocionante!",
  ui_story_5036_50360302_28_dialog_content = "La primera ronda es mañana, así que necesitaremos a varios de ustedes para el control de multitudes.",
  ui_story_5036_50360302_29_dialog_content = "¡No hay problema!",
  ui_story_5036_50360302_30_dialog_content = "¡Vamos a ponernos a trabajar, chicos!",
  ui_story_5036_50360302_31_dialog_content = "¡Entendido!",
  ui_story_5036_50360302_32_dialog_content = "Eres un gran motivador.",
  ui_story_5036_50360302_33_dialog_content = "Sin embargo, una audición de ídolo parece mucho trabajo.",
  ui_story_5036_50360302_34_dialog_content = "Es algo que siempre he querido hacer. No todos los días tengo la oportunidad de cumplir uno de mis sueños.",
  ui_story_5036_50360302_35_dialog_content = "¡No se siente como un trabajo para mí en absoluto!",
  ui_story_5036_50360302_36_dialog_content = "¿Siempre has querido hacer una audición?",
  ui_story_5036_50360302_37_dialog_content = "Así es. Me encanta tanto el escenario como el público debajo de él.",
  ui_story_5036_50360302_38_dialog_content = "¡Quiero contagiar mi pasión a los demás!",
  ui_story_5036_50360302_39_dialog_content = "Quiero que haya más ídolos para mover e inspirar a la audiencia.",
  ui_story_5036_50360302_40_dialog_content = "Tengo que apoyar a todos aquellos que aspiran a ser ídolos mientras tenga la capacidad de hacerlo.",
  ui_story_5036_50360302_41_dialog_content = "Realmente amas tu carrera.",
  ui_story_5036_50360302_42_dialog_content = "Hablando de que...",
  ui_story_5036_50360302_43_dialog_content = "¿Estarías interesado en <color=#FFB400>unirse al comité de selección</color>?",
  ui_story_5036_50360302_44_dialog_content = "¿Quién, yo?",
  ui_story_5036_50360302_45_dialog_content = "¡Sí! Estar en el comité es bastante fácil.",
  ui_story_5036_50360302_46_dialog_content = "Solo tienes que ver las actuaciones de los concursantes y decidir quién debería subir al escenario según tus preferencias.",
  ui_story_5036_50360302_47_dialog_content = "Estaba reservando el puesto para Sheol, pero parece muy ocupada haciendo todas las cosas de promoción.",
  ui_story_5036_50360302_48_dialog_content = "Después de reflexionar, decidí que eres el más adecuado para la tarea.",
  ui_story_5036_50360302_49_dialog_content = "Pero no estoy seguro de poder manejarlo.",
  ui_story_5036_50360302_50_dialog_content = "¡Oye! Carleen, Vice... ¿A ustedes dos no les gusta cantar también?",
  ui_story_5036_50360302_51_dialog_content = "¿Interesado en formar parte del comité?",
  ui_story_5036_50360302_52_dialog_content = "Oh...",
  ui_story_5036_50360302_53_dialog_content = "Bueno...",
  ui_story_5036_50360302_54_dialog_content = "Ah, ¿no lo sabías?",
  ui_story_5036_50360302_55_dialog_content = "¡Vice y Carleen se inscribieron para la audición!",
  ui_story_5036_50360302_56_dialog_content = "Ellos que?!",
  ui_story_5036_50360302_57_dialog_content = "¿Por qué no estaba al tanto de esto?",
  ui_story_5036_50360302_58_dialog_content = "No puedes culparnos por eso. Te lo dijimos.",
  ui_story_5036_50360302_59_dialog_content = "Pero estabas escuchando algo en ese momento y no nos prestaste atención.",
  ui_story_5036_50360302_60_dialog_content = "Vice y yo lo discutimos. Si el concierto es un éxito, eso debería ser suficiente para demostrar el valor de Eulogoz.",
  ui_story_5036_50360302_61_dialog_content = "Entonces, podemos persuadir a los altos mandos de Illumina y a mi padre para que no lo destruyan.",
  ui_story_5036_50360302_62_dialog_content = "Incluso si no podemos encontrar una manera de mantener el Coloso bajo control...",
  ui_story_5036_50360302_63_dialog_content = "Al menos aún se le podría permitir a Eulogoz continuar deambulando como lo hace ahora.",
  ui_story_5036_50360302_64_dialog_content = "¡Tal vez en cien años, regrese a los cielos de Astra!",
  ui_story_5036_50360302_65_dialog_content = "Ustedes dos realmente pensaron en el futuro.",
  ui_story_5036_50360302_66_dialog_content = "De hecho, casi te inscribimos a ti también, pero luego pensamos...",
  ui_story_5036_50360302_67_dialog_content = "No, no deberíamos.",
  ui_story_5036_50360302_68_dialog_content = "Definitivamente no tengo confianza en mis habilidades de interpretación, ¡pero no tienes que ser tan directo al respecto!",
  ui_story_5036_50360302_69_dialog_content = "No tienes que ser bueno en las artes escénicas para estar en el comité de selección.",
  ui_story_5036_50360302_70_dialog_content = "¡Todo lo que necesita es un ojo para el talento para calificar!",
  ui_story_5036_50360302_71_dialog_content = "Mmm...",
  ui_story_5036_50360302_72_dialog_content = "Suspiro, supongo que esta es la única opción.",
  ui_story_5036_50360302_73_dialog_content = "Es difícil de creer...",
  ui_story_5036_50360302_74_dialog_content = "que estaría haciendo algo así a mi edad.",
  ui_story_5036_50360302_75_dialog_content = "¡Rugido!",
  ui_story_5036_50360302_76_dialog_content = "¡Cállate!",
  ui_story_5036_50360302_77_dialog_content = "<size=35>¿Rugido?</size>",
  ui_story_5036_50360302_78_dialog_content = "Es tarde, pequeño Drako.",
  ui_story_5036_50360302_79_dialog_content = "Asustarás a la gente al ser tan ruidoso.",
  ui_story_5036_50360302_80_dialog_content = "No quiero sobresalir como un pulgar dolorido de inmediato.",
  ui_story_5036_50360302_81_dialog_content = "*lloriqueo*",
  ui_story_5036_50360302_82_dialog_content = "Está bien, date prisa en volver con Fia ahora.",
  ui_story_5036_50360302_83_dialog_content = "Pero recuerda...",
  ui_story_5036_50360302_84_dialog_content = "No le reveles mi paradero.",
  ui_story_5036_50360401_1_dialog_content = "¡Soy yo, editor jefe!",
  ui_story_5036_50360401_2_dialog_content = "¿Cómo sé quién eres si no me dices tu nombre?",
  ui_story_5036_50360401_3_dialog_content = "... Es Brandy.",
  ui_story_5036_50360401_4_dialog_content = "Oh, ahora recuerdo.",
  ui_story_5036_50360401_5_dialog_content = "El becario que solo escribe artículos aburridos.",
  ui_story_5036_50360401_6_dialog_content = "Pensé que ya lo habías dejado.",
  ui_story_5036_50360401_7_dialog_content = "Dijiste que me darías una última oportunidad.",
  ui_story_5036_50360401_8_dialog_content = "Ah, me parece recordar algo así... Entonces, ¿tienes buenas noticias para mí?",
  ui_story_5036_50360401_9_dialog_content = "¡Sí! ¿Adivina qué?",
  ui_story_5036_50360401_10_dialog_content = "Ahora mismo estoy en Eulogoz, ¡el coloso errante del que todo el mundo habla!",
  ui_story_5036_50360401_11_dialog_content = "¿Y?",
  ui_story_5036_50360401_12_dialog_content = "Cuando vuele sobre Umbraton, ¡habrá un gran concierto a bordo!",
  ui_story_5036_50360401_13_dialog_content = "Tengo una agenda apretada, así que dime algo que no sepa.",
  ui_story_5036_50360401_14_dialog_content = "Oh y...",
  ui_story_5036_50360401_15_dialog_content = "¡Fui elegido para ser el reportero oficial del concierto y también seré el anfitrión de las audiciones de ídolos!",
  ui_story_5036_50360401_16_dialog_content = "¿Está orgulloso de informar comunicados de prensa oficiales?",
  ui_story_5036_50360401_17_dialog_content = "Parece que todavía no lo entiendes.",
  ui_story_5036_50360401_18_dialog_content = "¡Lo que quiero es una primicia interna que sea lo suficientemente atractiva como para atraer vistas!",
  ui_story_5036_50360401_19_dialog_content = "¿Qué?",
  ui_story_5036_50360401_20_dialog_content = "... ¿Interior primicia?",
  ui_story_5036_50360401_21_dialog_content = "<color=#e8d9bb>Cinco días para el concierto</color>",
  ui_story_5036_50360401_22_dialog_content = "¡Lamento haberlos hecho esperar, queridos concursantes!",
  ui_story_5036_50360401_23_dialog_content = "Bienvenidos a la audición para el <color=#FFB400>Concierto en el cielo 'El momento en que las estrellas brillan más'</color>.",
  ui_story_5036_50360401_24_dialog_content = "¿Cómo te sentiste abordando el Colossus en aeronaves exclusivas?",
  ui_story_5036_50360401_25_dialog_content = "¿Entusiasmado? ¿Exaltado? ¿Nervioso? ¿Encantado?",
  ui_story_5036_50360401_26_dialog_content = "Pero hay más emoción y emociones por venir.",
  ui_story_5036_50360401_27_dialog_content = "¡Por la presente anuncio el comienzo de la primera ronda de audiciones!",
  ui_story_5036_50360401_28_dialog_content = "¡Oh! ¡Aquí vamos!",
  ui_story_5036_50360401_29_dialog_content = "Por favor, guarden silencio por un momento mientras les explico las reglas.",
  ui_story_5036_50360401_30_dialog_content = "Como puede ver, tenemos un panel de seis jueces.",
  ui_story_5036_50360401_31_dialog_content = "¡Puedes hablar conmigo sobre tus juegos de simulación favoritos!",
  ui_story_5036_50360401_32_dialog_content = "Estaré juzgando tu canto, baile, visuales, figura, EQ y IQ.",
  ui_story_5036_50360401_33_dialog_content = "Debe sobresalir en solo uno de los seis para obtener mi voto.",
  ui_story_5036_50360401_34_dialog_content = "Estoy buscando actuaciones perfectamente altruistas, sanas, puras y apropiadas dignas de nobles...",
  ui_story_5036_50360401_35_dialog_content = "¿Eres capaz?",
  ui_story_5036_50360401_36_dialog_content = "Vayan todos.",
  ui_story_5036_50360401_37_dialog_content = "¡Espero iluminar los cielos contigo!",
  ui_story_5036_50360401_38_dialog_content = "Hola todos. ¡Prestaré mucha atención a tus actuaciones!",
  ui_story_5036_50360401_39_dialog_content = "Las reglas son simples, todo lo que necesitas son cuatro votos de los jueces...",
  ui_story_5036_50360401_40_dialog_content = "y pasarás a la siguiente ronda para tener la oportunidad de actuar en el escenario del concierto.",
  ui_story_5036_50360401_41_dialog_content = "¡Aquellos que reciben votos unánimes automáticamente pueden actuar en el concierto!",
  ui_story_5036_50360401_42_dialog_content = "Si no avanzas, no te preocupes, porque todos tienen tres oportunidades.",
  ui_story_5036_50360401_43_dialog_content = "Siéntase libre de utilizar las salas de Eulogoz para ensayar.",
  ui_story_5036_50360401_44_dialog_content = "Ahora bien, ¡comencemos el espectáculo!",
  ui_story_5036_50360401_45_dialog_content = "¡Venga y actúe cuando llamen su número!",
  ui_story_5036_50360401_46_dialog_content = "¡Número 1, el Coro Illumina!",
  ui_story_5036_50360401_47_dialog_content = "Las audiciones han comenzado. ¿No quieres comprobarlo?",
  ui_story_5036_50360401_48_dialog_content = "No, ahora no.",
  ui_story_5036_50360401_49_dialog_content = "Todavía no he decidido lo que voy a hacer.",
  ui_story_5036_50360401_50_dialog_content = "Si miro ahora, solo me pondrá aún más nervioso.",
  ui_story_5036_50360401_51_dialog_content = "Yo tampoco he decidido qué hacer.",
  ui_story_5036_50360401_52_dialog_content = "Nos inscribimos principalmente porque nos preocupaba que no hubiera suficientes participantes.",
  ui_story_5036_50360401_53_dialog_content = "Pero viendo cuánta gente hay aquí, en realidad estoy pensando...",
  ui_story_5036_50360401_54_dialog_content = "Tal vez no soy necesario.",
  ui_story_5036_50360401_55_dialog_content = "¿Qué? Escuché que tanto Illumina como Lumopolis obtuvieron espacios reservados.",
  ui_story_5036_50360401_56_dialog_content = "Illumina eligió el Coro, y pensé que obtendrías el puesto de Lumopolis.",
  ui_story_5036_50360401_57_dialog_content = "Esa fue nuestra actuación. ¡Gracias!",
  ui_story_5036_50360401_58_dialog_content = "¡Tus movimientos estuvieron bien sincronizados y enérgicos, y cantaste canciones inspiradoras que realmente ejemplifican a los soldados de Illumina!",
  ui_story_5036_50360401_59_dialog_content = "Sé que su grupo siempre hace giras por Illumina, y su familiaridad con el escenario era evidente.",
  ui_story_5036_50360401_60_dialog_content = "Me encantó tu canto! ¡La mejor de las suertes!",
  ui_story_5036_50360401_61_dialog_content = "Gracias.",
  ui_story_5036_50360401_62_dialog_content = "Ahora bien, el Coro Illumina se pone...",
  ui_story_5036_50360401_63_dialog_content = "¡Los 6 votos!",
  ui_story_5036_50360401_64_dialog_content = "¡Soportaron la presión de la audición primero y se ganaron la oportunidad de actuar en el concierto! ¡Felicidades!",
  ui_story_5036_50360401_65_dialog_content = "¡Gracias! ¡No defraudaremos a la audiencia!",
  ui_story_5036_50360401_66_dialog_content = "Bien, a continuación, ¡tenemos el Coro de Lumopolis, Keating!",
  ui_story_5036_50360401_67_dialog_content = "Así es como funciona esto.",
  ui_story_5036_50360401_68_dialog_content = "Sería una pena dejar pasar una oportunidad tan rara.",
  ui_story_5036_50360401_69_dialog_content = "Es exactamente por eso que debe reservarse para aquellos que lo merecen.",
  ui_story_5036_50360401_70_dialog_content = "¿Que demonios?",
  ui_story_5036_50360401_71_dialog_content = "¿Mmm?",
  ui_story_5036_50360401_72_dialog_content = "¿Así que soy el único que está audicionando ahora?",
  ui_story_5036_50360401_73_dialog_content = "¡Oh, espera, lo sé!",
  ui_story_5036_50360401_74_dialog_content = "Van a ver el concierto en Lumopolis también...",
  ui_story_5036_50360401_75_dialog_content = "¿Eres demasiado tímida para actuar para tu público local, Carleen?",
  ui_story_5036_50360401_76_dialog_content = "¡Para nada!",
  ui_story_5036_50360401_77_dialog_content = "Entonces, pruébalo.",
  ui_story_5036_50360401_78_dialog_content = "Muéstrales a todos de lo que eres capaz.",
  ui_story_5036_50360401_79_dialog_content = "esto es ♪",
  ui_story_5036_50360401_80_dialog_content = "Nuestro desempeño ♪",
  ui_story_5036_50360401_81_dialog_content = "Ahora por favor comience ♪",
  ui_story_5036_50360401_82_dialog_content = "Tu actuación ♪",
  ui_story_5036_50360401_83_dialog_content = "¡Increíble gracia!",
  ui_story_5036_50360401_84_dialog_content = "¡No es de extrañar que el mismísimo Lord Schwartz te haya elegido!",
  ui_story_5036_50360401_85_dialog_content = "Sus voces son simplemente divinas y me han limpiado por dentro y por fuera.",
  ui_story_5036_50360401_86_dialog_content = "Los plebeyos deberían apreciar esto.",
  ui_story_5036_50360401_87_dialog_content = "Fuiste bendecido por el Dios de la Luz para poder escuchar un himno tan sagrado.",
  ui_story_5036_50360401_88_dialog_content = "Tu acto ♪",
  ui_story_5036_50360401_89_dialog_content = "es tonto ♪",
  ui_story_5036_50360401_90_dialog_content = "Tus palabras ♪",
  ui_story_5036_50360401_91_dialog_content = "Son halagos vacíos ♪",
  ui_story_5036_50360401_92_dialog_content = "¿Escucha eso? ¡Son melodiosos incluso cuando hablan!",
  ui_story_5036_50360401_93_dialog_content = "No se puede distinguir la adulación de la burla.",
  ui_story_5036_50360401_94_dialog_content = "Qué es esto...?",
  ui_story_5036_50360401_95_dialog_content = "¡Keating también obtiene 6 votos y se dirige directamente al concierto! ¡Felicidades!",
  ui_story_5036_50360401_96_dialog_content = "¿Ambos concursantes? Esto no está amañado, ¿verdad?",
  ui_story_5036_50360401_97_dialog_content = "¿Eres el concursante no. 3, Bárbara?",
  ui_story_5036_50360401_98_dialog_content = "¡Soy yo, Bárbara!",
  ui_story_5036_50360401_99_dialog_content = "Ignora a esa mujer ruidosa. ¡Yo, Bárbara, nací verdaderamente para ser un ídolo!",
  ui_story_5036_50360401_100_dialog_content = "¡Ja, tal vez deberías asegurarte de que puedes tocar tus notas antes de subir al escenario!",
  ui_story_5036_50360401_101_dialog_content = "¿Por qué no pasas menos tiempo criticándome y más tiempo aprendiendo a cantar?",
  ui_story_5036_50360401_102_dialog_content = "Es hora de que ustedes dos actúen.",
  ui_story_5036_50360401_103_dialog_content = "No puedo creer esto.",
  ui_story_5036_50360401_104_dialog_content = "¿Cómo fue que Rediesel Wrench terminó con alguien con tan mal gusto musical como tú?",
  ui_story_5036_50360401_105_dialog_content = "Vaya, mira quién habla...",
  ui_story_5036_50360401_106_dialog_content = "¿De verdad crees que a alguien en Rediesel Wrench le gusta tu voz de mierda?",
  ui_story_5036_50360401_107_dialog_content = "¿Qué? ¡Repitelo!",
  ui_story_5036_50360401_108_dialog_content = "¡Yo Te reto!",
  ui_story_5036_50360401_109_dialog_content = "Oye, ¿por qué hay alguien más en el escenario?",
  ui_story_5036_50360401_110_dialog_content = "¡Soy el número 3!",
  ui_story_5036_50360401_111_dialog_content = "Lo sentimos Barbara, y la entrada no. 4, Reina...",
  ui_story_5036_50360401_112_dialog_content = "Los jueces te descalificaron por alteración del orden público.",
  ui_story_5036_50360401_113_dialog_content = "Regístrese nuevamente para la próxima ronda.",
  ui_story_5036_50360401_114_dialog_content = "¡¿Qué?!",
  ui_story_5036_50360401_115_dialog_content = "Ya veo.",
  ui_story_5036_50360401_116_dialog_content = "¿Q-Qué ves?",
  ui_story_5036_50360401_117_dialog_content = "¿Te sientes solo porque vas a actuar solo?",
  ui_story_5036_50360401_118_dialog_content = "No tan alto...",
  ui_story_5036_50360401_119_dialog_content = "Bien, lo admito.",
  ui_story_5036_50360401_120_dialog_content = "Después de todo, siempre hacemos todo juntos como grupo.",
  ui_story_5036_50360401_121_dialog_content = "Se siente un poco raro ir solo de repente.",
  ui_story_5036_50360401_122_dialog_content = "Bien entonces.",
  ui_story_5036_50360401_123_dialog_content = "Supongo que puedo ayudar a una paloma solitaria.",
  ui_story_5036_50360401_124_dialog_content = "¡No soy una paloma solitaria!",
  ui_story_5036_50360401_125_dialog_content = "Jajaja...",
  ui_story_5036_50360401_126_dialog_content = "Sin embargo, en comparación con estar allí solo...",
  ui_story_5036_50360401_127_dialog_content = "Extraño cómo se siente estar en el escenario contigo.",
  ui_story_5036_50360401_128_dialog_content = "¿Ah?",
  ui_story_5036_50360401_129_dialog_content = "¿Qué pasa con la nostalgia repentina?",
  ui_story_5036_50360401_130_dialog_content = "Bueno, de todos modos, creo que la persona que era en ese entonces habría tenido muchas más ganas de actuar.",
  ui_story_5036_50360401_131_dialog_content = "En realidad, yo también...",
  ui_story_5036_50360401_132_dialog_content = "Qué pena.",
  ui_story_5036_50360401_133_dialog_content = "Ningún concursante hasta ahora ha podido llegar al concierto aparte de los dos primeros.",
  ui_story_5036_50360401_134_dialog_content = "Ahora, demos la bienvenida al último participante por hoy.",
  ui_story_5036_50360401_135_dialog_content = "¿Qué actuación nos tiene reservada?",
  ui_story_5036_50360401_136_dialog_content = "Hola a todos.",
  ui_story_5036_50360401_137_dialog_content = "soy vic Soy un entrenador de bestias maravillosas.",
  ui_story_5036_50360401_138_dialog_content = "Vic?!",
  ui_story_5036_50360401_139_dialog_content = "¿PlayerName?",
  ui_story_5036_50360401_140_dialog_content = "No esperaba ver una cara familiar en el comité de selección.",
  ui_story_5036_50360401_141_dialog_content = "Debo aclarar que en verdad no sabía PlayerName iba a ser juez.",
  ui_story_5036_50360401_142_dialog_content = "¡Realmente eres tú!",
  ui_story_5036_50360401_143_dialog_content = "Pensé que estaba equivocado... ¿Por qué te inscribiste en esto?",
  ui_story_5036_50360401_144_dialog_content = "Porque quiero ser un ídolo y actuar en este escenario único.",
  ui_story_5036_50360401_145_dialog_content = "Nunca supe que querías ser un ídolo.",
  ui_story_5036_50360401_146_dialog_content = "Por lo que sé, ya te has hecho un nombre en el mundo del entrenamiento de bestias maravillosas.",
  ui_story_5036_50360401_147_dialog_content = "¿Quién dice que los extrozoólogos no pueden ser ídolos?",
  ui_story_5036_50360401_148_dialog_content = "¡Solo yo puedo decidir eso!",
  ui_story_5036_50360401_149_dialog_content = "Hoy en día, cualquiera puede ser un ídolo...",
  ui_story_5036_50360401_150_dialog_content = "y disfruta de sus 15 minutos de fama en el centro de atención.",
  ui_story_5036_50360401_151_dialog_content = "\"Hoy en día, cualquiera puede ser un ídolo\", dices.",
  ui_story_5036_50360401_152_dialog_content = "¡Muy bien puesto!",
  ui_story_5036_50360401_153_dialog_content = "Agradezco su actitud y comprensión acerca de este negocio. ¡Espero tu actuación!",
  ui_story_5036_50360401_154_dialog_content = "¡Guau, este es el primer concursante hasta ahora en captar la atención de la propia Miss Goldie!",
  ui_story_5036_50360401_155_dialog_content = "Entonces, ¿qué actuación emocionante nos traerá?",
  ui_story_5036_50360401_156_dialog_content = "¡Empieza Vic, por favor!",
  ui_story_5036_50360401_157_dialog_content = "Voy a recitar algo para todos ustedes. Ejem...",
  ui_story_5036_50360401_158_dialog_content = "¡Ay! ¡La primavera ha llegado aquí, y la tierra cobra vida una vez más!",
  ui_story_5036_50360401_159_dialog_content = "Es una vez más la temporada durante la cual las maravillosas bestias muestran su vigor.",
  ui_story_5036_50360401_160_dialog_content = "(Ni siquiera estoy seguro de que esto califique como una actuación...)",
  ui_story_5036_50360401_161_dialog_content = "(¡¿Pero parece que Vic está recitando su Enciclopedia Exótica?!)",
  ui_story_5036_50360401_162_dialog_content = "¡Pobre de mí! ¡La gloria de la vida llena cada centímetro de la tierra, ya sea en los bosques o en las llanuras!",
  ui_story_5036_50360401_163_dialog_content = "Pero en medio de esta cacofonía, hay una criatura que es la excepción.",
  ui_story_5036_50360401_164_dialog_content = "los <color=#FFB400>Ouroboros</color> es uno de <color=#FFB400> más longevo </color> bestias maravillosas en Astra.",
  ui_story_5036_50360401_165_dialog_content = "Cuando alcanzan la madurez—",
  ui_story_5036_50360401_166_dialog_content = "¡Perdón, déjame interrumpirte un segundo!",
  ui_story_5036_50360401_167_dialog_content = "Los jueces se preguntan si tienes algo más que mostrarnos.",
  ui_story_5036_50360401_168_dialog_content = "Bueno, no... Solo preparé esta narración dramática para hoy.",
  ui_story_5036_50360401_169_dialog_content = "Ya veo... Qué lástima.",
  ui_story_5036_50360401_170_dialog_content = "Lo hiciste bien en tu recitación, pero no es exactamente lo que estamos buscando.",
  ui_story_5036_50360401_171_dialog_content = "¡Pero no te desanimes!",
  ui_story_5036_50360401_172_dialog_content = "Tienes una muy buena voz y muy buenas imágenes también.",
  ui_story_5036_50360401_173_dialog_content = "Estoy seguro de que harás bien en cambiar a cantar o bailar.",
  ui_story_5036_50360401_174_dialog_content = "No me sorprendería si algún día superas incluso a algunos de los artistas experimentados.",
  ui_story_5036_50360401_175_dialog_content = "Espero ver a alguien diferente a ti en una ronda posterior.",
  ui_story_5036_50360401_176_dialog_content = "Creo que tienes un gran potencial, ¡así que sigue esforzándote!",
  ui_story_5036_50360401_177_dialog_content = "Ah, supongo que lo intentaré de nuevo.",
  ui_story_5036_50360401_178_dialog_content = "(Goldie mira a Vic como si acabara de descubrir una joya escondida...)",
  ui_story_5036_50360401_179_dialog_content = "(¿Vic realmente tiene lo que se necesita para ser un ídolo?)",
  ui_story_5036_50360401_180_dialog_content = "¡Gracias a todos nuestros candidatos y jueces! Las audiciones de hoy han llegado a su fin.",
  ui_story_5036_50360401_181_dialog_content = "¡Asegúrate de sintonizar futuras rondas de audiciones!",
  ui_story_5036_50360401_182_dialog_content = "¡Nos veremos mañana!",
  ui_story_5036_50360401_183_dialog_content = "PlayerName, Goldie, ¿se acabó?",
  ui_story_5036_50360401_184_dialog_content = "Sí. Pensé que sería relajante ver las actuaciones, pero en realidad me costó mucho.",
  ui_story_5036_50360401_185_dialog_content = "Por cierto, ¿cómo es que no aparecisteis?",
  ui_story_5036_50360401_186_dialog_content = "Queríamos ensayar un poco más antes de unirnos.",
  ui_story_5036_50360401_187_dialog_content = "¿Estáis ensayando juntos?",
  ui_story_5036_50360401_188_dialog_content = "Sí. Pensamos que sería más divertido participar como dúo.",
  ui_story_5036_50360401_189_dialog_content = "No parezcas tan sorprendido. Escuchaste eso correctamente.",
  ui_story_5036_50360401_190_dialog_content = "Vice y yo vamos a actuar como dúo.",
  ui_story_5036_50360401_191_dialog_content = "¡Es una gran idea!",
  ui_story_5036_50360401_192_dialog_content = "¿Ya tienes idea de lo que vas a hacer?",
  ui_story_5036_50360401_193_dialog_content = "Estaremos cantando. Ya hemos seleccionado algunas canciones.",
  ui_story_5036_50360401_194_dialog_content = "Pero tenemos que ensayar antes de decidir con cuál ir.",
  ui_story_5036_50360401_195_dialog_content = "Sinceramente, no sé si podremos hacerlo...",
  ui_story_5036_50360401_196_dialog_content = "No te preocupes. Dejame decirte un secreto.",
  ui_story_5036_50360401_197_dialog_content = "De hecho, aún no he decidido qué canciones cantar.",
  ui_story_5036_50360401_198_dialog_content = "Debes tener una gran selección de tus propias canciones para elegir, ¿verdad?",
  ui_story_5036_50360401_199_dialog_content = "Sí, pero no siento que haya uno adecuado para un escenario en Eulogoz.",
  ui_story_5036_50360401_200_dialog_content = "Está bien, sin embargo. Tal vez lo averigüe en los próximos días.",
  ui_story_5036_50360401_201_dialog_content = "¿Quieres decir que estás escribiendo una nueva canción solo para Eulogoz?",
  ui_story_5036_50360401_202_dialog_content = "¡Shh, no tan fuerte! Pero sí, esa es la idea.",
  ui_story_5036_50360401_203_dialog_content = "No estoy seguro de poder hacerlo, así que mantenlo en secreto.",
  ui_story_5036_50360401_204_dialog_content = "¿Escribes todas tus canciones?",
  ui_story_5036_50360401_205_dialog_content = "¡Eso es impresionante!",
  ui_story_5036_50360401_206_dialog_content = "No todos, no.",
  ui_story_5036_50360401_207_dialog_content = "Es solo que una melodía o ritmo aparece en mi mente de vez en cuando.",
  ui_story_5036_50360401_208_dialog_content = "Luego trato de escribirlo y convertirlo en una canción.",
  ui_story_5036_50360401_209_dialog_content = "Pero no todo el tiempo obtengo la melodía que quiero.",
  ui_story_5036_50360401_210_dialog_content = "¿Una melodía que se te viene a la mente...?",
  ui_story_5036_50360401_211_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360401_212_dialog_content = "♪ La la la la... ♪",
  ui_story_5036_50360401_213_dialog_content = "Entonces, desde que me acerqué mucho a Eulogoz, he estado escuchando melodías en mi cabeza.",
  ui_story_5036_50360401_214_dialog_content = "Incluso diría que no es tanto una melodía como alguien que realmente tararea.",
  ui_story_5036_50360401_215_dialog_content = "¿En serio?",
  ui_story_5036_50360401_216_dialog_content = "Escuché que Caelestites era una raza amante de la música.",
  ui_story_5036_50360401_217_dialog_content = "¡Tal vez tengas una afinidad natural por hacer música!",
  ui_story_5036_50360401_218_dialog_content = "¿T-Tú crees?",
  ui_story_5036_50360401_219_dialog_content = "¿Podría Eugoloz estar enviándome inspiración?",
  ui_story_5036_50360401_220_dialog_content = "¡Eso es posible!",
  ui_story_5036_50360401_221_dialog_content = "Que tiene sentido.",
  ui_story_5036_50360401_222_dialog_content = "Eulogoz pertenecía a los caelestitas.",
  ui_story_5036_50360401_223_dialog_content = "Si pudiera cantar una canción compuesta por Caelestite en Eulogoz, ¡sería muy significativo!",
  ui_story_5036_50360401_224_dialog_content = "¡PlayerName!",
  ui_story_5036_50360401_225_dialog_content = "Si no te importa, ¿puedes compartir la melodía que ha estado apareciendo en tu cabeza?",
  ui_story_5036_50360401_226_dialog_content = "Por supuesto que no me importa.",
  ui_story_5036_50360401_227_dialog_content = "Detener-!",
  ui_story_5036_50360401_228_dialog_content = "¿Qué está pasando?",
  ui_story_5036_50360401_229_dialog_content = "Grah!",
  ui_story_5036_50360401_230_dialog_content = "Parece que tendremos que esperar en eso, PlayerName!",
  ui_story_5036_50360402_1_dialog_content = "¡Lamento molestarte!",
  ui_story_5036_50360402_2_dialog_content = "Un guardia colapsó en el área de bloqueo mientras limpiaba los Eclipsites, lo que los dejó salir.",
  ui_story_5036_50360402_3_dialog_content = "Afortunadamente, los soldados de Illumina y Lumopolis nos ayudaron.",
  ui_story_5036_50360402_4_dialog_content = "¿Qué pasa con el guardia? ¿Está herido?",
  ui_story_5036_50360402_5_dialog_content = "Está consciente y debería estar bien.",
  ui_story_5036_50360402_6_dialog_content = "¿Fue porque tratar con los Eclipsites en el área de bloqueo era demasiado exigente?",
  ui_story_5036_50360402_7_dialog_content = "Seguimos tu consejo y les dimos mucho descanso a todos, así que las cosas no están tan mal.",
  ui_story_5036_50360402_8_dialog_content = "Dijo que se desmayó porque no tenía nada para comer.",
  ui_story_5036_50360402_9_dialog_content = "¿No proporcionamos suficientes comidas?",
  ui_story_5036_50360402_10_dialog_content = "Bueno, alguien robó su porción y no tuvo tiempo de conseguir un reemplazo.",
  ui_story_5036_50360402_11_dialog_content = "¿Alguien le robó la comida?",
  ui_story_5036_50360402_12_dialog_content = "¡De ninguna manera, no me digas que también me atraparon!",
  ui_story_5036_50360402_13_dialog_content = "¿Estás herido, soldado?",
  ui_story_5036_50360402_14_dialog_content = "¡Estoy bien, teniente Vice!",
  ui_story_5036_50360402_15_dialog_content = "Es solo que las raciones que tenía conmigo parecen estar desaparecidas.",
  ui_story_5036_50360402_16_dialog_content = "¿Tú también?",
  ui_story_5036_50360402_17_dialog_content = "Sí. A todos los chicos que me rodeaban les pasaba lo mismo.",
  ui_story_5036_50360402_18_dialog_content = "Nuestras raciones siguen desapareciendo misteriosamente.",
  ui_story_5036_50360402_19_dialog_content = "Pensé que llevar mis raciones conmigo sería seguro, pero...",
  ui_story_5036_50360402_20_dialog_content = "¿Quizás los perdieron mientras luchaban contra los Eclipsites?",
  ui_story_5036_50360402_21_dialog_content = "Eso es lo que pensamos también, así que no lo informamos.",
  ui_story_5036_50360402_22_dialog_content = "los <color=#FFB400>ladrón fantasma</color>... ¡Debe ser el ladrón fantasma!",
  ui_story_5036_50360402_23_dialog_content = "ladrón fantasma?",
  ui_story_5036_50360402_24_dialog_content = "¡Hay un ladrón fantasma en el Coloso, Lady Carleen!",
  ui_story_5036_50360402_25_dialog_content = "El ladrón te deja inconsciente cuando menos te lo esperas.",
  ui_story_5036_50360402_26_dialog_content = "¡Entonces se lleva todos tus objetos de valor sin ser visto!",
  ui_story_5036_50360402_27_dialog_content = "Así es como perdí mi reloj de bolsillo de piedras preciosas.",
  ui_story_5036_50360402_28_dialog_content = "¿Robar comida y joyas?",
  ui_story_5036_50360402_29_dialog_content = "Eso no suena como algo que harían los Eclipsites.",
  ui_story_5036_50360402_30_dialog_content = "Así que tenemos un ladrón en nuestras manos...",
  ui_story_5036_50360402_31_dialog_content = "Sabes, de alguna manera, esto suena familiar.",
  ui_story_5036_50360402_32_dialog_content = "¿Dónde he visto una situación similar antes...",
  ui_story_5036_50360402_33_dialog_content = "¿Podría un carterista profesional subirse a bordo del Coloso Errante?",
  ui_story_5036_50360402_34_dialog_content = "Los mercenarios también han notado este problema, señorita Goldie.",
  ui_story_5036_50360402_35_dialog_content = "No solo nosotros, sino incluso aquellos que se inscribieron para la audición se quejaron de perder dulces y bebidas.",
  ui_story_5036_50360402_36_dialog_content = "Maldiciones, ¡¿por qué los criminales tienen que aparecer en el cielo?!",
  ui_story_5036_50360402_37_dialog_content = "Me preocupa que el ladrón moleste a los candidatos a la audición, Goldie.",
  ui_story_5036_50360402_38_dialog_content = "Carleen tiene razón. El problema más apremiante es asegurarse de que el ladrón no les haga perder la fe en los anfitriones del concierto.",
  ui_story_5036_50360402_39_dialog_content = "¿Te importaría enviar a alguien a comprar otro cargamento de comida y bebida de Umbraton?",
  ui_story_5036_50360402_40_dialog_content = "Tenemos que asegurarnos de que todos los concursantes y soldados de Eulogoz estén alimentados.",
  ui_story_5036_50360402_41_dialog_content = "Teniendo en cuenta el volumen involucrado, tendré que enviar más personas.",
  ui_story_5036_50360402_42_dialog_content = "Por favor, hágalo e incluya el costo en la factura.",
  ui_story_5036_50360402_43_dialog_content = "¡Entendido!",
  ui_story_5036_50360402_44_dialog_content = "...",
  ui_story_5036_50360402_45_dialog_content = "¿Estás bien, Goldie?",
  ui_story_5036_50360402_46_dialog_content = "...",
  ui_story_5036_50360402_47_dialog_content = "¿Goldie?",
  ui_story_5036_50360402_48_dialog_content = "¿Hmm? Eh... Sí, estoy bien, ¡no te preocupes por mí!",
  ui_story_5036_50360402_49_dialog_content = "Concéntrate en tu ensayo y no te preocupes por esto, Carleen, Vice.",
  ui_story_5036_50360402_50_dialog_content = "Absolutamente...",
  ui_story_5036_50360402_51_dialog_content = "¡Absolutamente no dejaré que nadie impida que el concierto suceda!",
  ui_story_5036_50360501_1_dialog_content = "Mercenarios...",
  ui_story_5036_50360501_2_dialog_content = "¡¿Qué hiciste?!",
  ui_story_5036_50360501_3_dialog_content = "¡Qué maravilloso escenario has construido!",
  ui_story_5036_50360501_4_dialog_content = "¡Limpiaste completamente la pantalla de Eugoloz y la equipaste con iluminación multicolor!",
  ui_story_5036_50360501_5_dialog_content = "Créeme cuando digo esto...",
  ui_story_5036_50360501_6_dialog_content = "¡Esta etapa es más impresionante que cualquier otra que haya visto en Umbraton!",
  ui_story_5036_50360501_7_dialog_content = "Gracias por el cumplido, señorita Goldie.",
  ui_story_5036_50360501_8_dialog_content = "Simplemente seguimos las instrucciones de la Sra. Sheol.",
  ui_story_5036_50360501_9_dialog_content = "No, ustedes son diferentes.",
  ui_story_5036_50360501_10_dialog_content = "Lady Sheol dice que la mayoría de los mercenarios hacen un trabajo descuidado y de mala calidad.",
  ui_story_5036_50360501_11_dialog_content = "Solo se puede confiar en las Llamas Blancas para que sean siempre meticulosas y confiables.",
  ui_story_5036_50360501_12_dialog_content = "Aunque es una pena...",
  ui_story_5036_50360501_13_dialog_content = "que un lugar tan impresionante solo se realizará a la vez.",
  ui_story_5036_50360501_14_dialog_content = "Si lo desea, señorita Goldie...",
  ui_story_5036_50360501_15_dialog_content = "Podemos construir el mismo escenario para ti más tarde en Umbraton.",
  ui_story_5036_50360501_16_dialog_content = "Mas tarde?",
  ui_story_5036_50360501_17_dialog_content = "Suponiendo que todavía sea un ídolo para entonces...",
  ui_story_5036_50360501_18_dialog_content = "¿Ah?",
  ui_story_5036_50360501_19_dialog_content = "No importa. ¿Alguna noticia del ladrón?",
  ui_story_5036_50360501_20_dialog_content = "Ninguno hasta ahora.",
  ui_story_5036_50360501_21_dialog_content = "El culpable es bastante astuto. Todavía no tenemos pistas sólidas.",
  ui_story_5036_50360501_22_dialog_content = "Todo lo que sabemos es que la mayoría de las cosas fueron robadas durante la noche.",
  ui_story_5036_50360501_23_dialog_content = "Eso es un comienzo.",
  ui_story_5036_50360501_24_dialog_content = "Estaré patrullando contigo por la noche.",
  ui_story_5036_50360501_25_dialog_content = "¿Patrullarás con nosotros?",
  ui_story_5036_50360501_26_dialog_content = "Jaja, eres la primera persona en rechazar la compañía de un ídolo famoso.",
  ui_story_5036_50360501_27_dialog_content = "¡No me atrevería! Solo me preocupa que le quite tiempo a su composición.",
  ui_story_5036_50360501_28_dialog_content = "¡Oh, nunca subestimes lo que puede hacer un ídolo!",
  ui_story_5036_50360501_29_dialog_content = "Tengo muchas canciones que puedo cantar en el escenario.",
  ui_story_5036_50360501_30_dialog_content = "Me encantaría escribir una nueva canción con la melodía de Caelestite...",
  ui_story_5036_50360501_31_dialog_content = "pero PlayerName sólo me dio algunas notas. No se donde puedo llevar eso.",
  ui_story_5036_50360501_32_dialog_content = "¿Solo algunas notas?",
  ui_story_5036_50360501_33_dialog_content = "¿Eres curioso?",
  ui_story_5036_50360501_34_dialog_content = "U-Uh, no me atrevería a entrometerme...",
  ui_story_5036_50360501_35_dialog_content = "¿No? Pero tengo ganas de cantarla en este nuevo escenario.",
  ui_story_5036_50360501_36_dialog_content = "♪ La... ♪",
  ui_story_5036_50360501_37_dialog_content = "♪ La... La la la... ♪",
  ui_story_5036_50360501_38_dialog_content = "Grahhhhhh!",
  ui_story_5036_50360501_39_dialog_content = "Los Eclipsites escapados... ¡Se esconden debajo del escenario!",
  ui_story_5036_50360501_40_dialog_content = "Salieron tan pronto como Miss Goldie empezó a cantar...",
  ui_story_5036_50360501_41_dialog_content = "¡¿No me digas que también son Ricitos de Oro?!",
  ui_story_5036_50360502_1_dialog_content = "Escuché que el escenario se completará esta noche.",
  ui_story_5036_50360502_2_dialog_content = "¡Necesito vencer a todos los que están allí para obtener las tomas desde todos los ángulos!",
  ui_story_5036_50360502_3_dialog_content = "¡Lo que quiero es una primicia interna que sea lo suficientemente atractiva como para atraer vistas!",
  ui_story_5036_50360502_4_dialog_content = "En serio, ¿podría el editor haber hecho una demanda más difícil?",
  ui_story_5036_50360502_5_dialog_content = "¿Dónde se supone que debo entrar en primicia?",
  ui_story_5036_50360502_6_dialog_content = "Lo único que puedo hacer es ser el primero en informar cualquier noticia sobre Eulogoz.",
  ui_story_5036_50360502_7_dialog_content = "Oye, hay alguien en el escenario...",
  ui_story_5036_50360502_8_dialog_content = "Si tan solo los Eclipsites pudieran convertirse en Goldilocks...",
  ui_story_5036_50360502_9_dialog_content = "¿Te gustan los eclipses?",
  ui_story_5036_50360502_10_dialog_content = "¡¿Me estás tomando el pelo?!",
  ui_story_5036_50360502_11_dialog_content = "¡Lo siento!",
  ui_story_5036_50360502_12_dialog_content = "Bueno, fue mi culpa por no aclarar.",
  ui_story_5036_50360502_13_dialog_content = "Estaba pensando, sería genial si los Eclipsites pudieran entender mis canciones.",
  ui_story_5036_50360502_14_dialog_content = "Si pudieran escuchar el amor y la paz en ellos, tal vez eso los influiría.",
  ui_story_5036_50360502_15_dialog_content = "para detener su comportamiento salvaje y asesino.",
  ui_story_5036_50360502_16_dialog_content = "Je... ¿Eso salió pomposo o qué?",
  ui_story_5036_50360502_17_dialog_content = "Influencia, salvaje,... ¿asesino?",
  ui_story_5036_50360502_18_dialog_content = "¿Qué está diciendo Goldie? Es difícil decirlo desde tan lejos.",
  ui_story_5036_50360502_19_dialog_content = "Supongo que tengo que acercarme un poco...",
  ui_story_5036_50360502_20_dialog_content = "<color=#e8d9bb> ¡Bonk! </color>",
  ui_story_5036_50360502_21_dialog_content = "¡Oh vamos! ¿Cómo pude ser tan desafortunado?",
  ui_story_5036_50360502_22_dialog_content = "¡Por supuesto que tuve que toparme con una caja de madera justo en este momento!",
  ui_story_5036_50360502_23_dialog_content = "¿Me escucharon?",
  ui_story_5036_50360502_24_dialog_content = "Uf, supongo que no lo hicieron.",
  ui_story_5036_50360502_25_dialog_content = "¿Quién está ahí?",
  ui_story_5036_50360502_26_dialog_content = "¿Ah?",
  ui_story_5036_50360502_27_dialog_content = "¡Uy, estoy atrapado!",
  ui_story_5036_50360502_28_dialog_content = "Está bien. Solo explicaré que estaba de paso. La señorita Goldie seguramente...",
  ui_story_5036_50360502_29_dialog_content = "créeme, ¿verdad?",
  ui_story_5036_50360502_30_dialog_content = "<color=#e8d9bb>*Choque*</color>",
  ui_story_5036_50360502_31_dialog_content = "¡Alto ahí!",
  ui_story_5036_50360502_32_dialog_content = "¿Qué? Que...?",
  ui_story_5036_50360502_33_dialog_content = "¿Goldie parece estar gritando en otra dirección?",
  ui_story_5036_50360502_34_dialog_content = "¿Hay alguien más aparte de mí escondido aquí?",
  ui_story_5036_50360502_35_dialog_content = "¡Eres incluso más perspicaz que nuestra exploradora, señorita Goldie!",
  ui_story_5036_50360502_36_dialog_content = "No pensé que alguien estaría escondido debajo del piso.",
  ui_story_5036_50360502_37_dialog_content = "Lástima que el delincuente se escapó antes de que pudiera levantarlo.",
  ui_story_5036_50360502_38_dialog_content = "Mira, raciones a medio comer.",
  ui_story_5036_50360502_39_dialog_content = "Es el empaque de Illumina.",
  ui_story_5036_50360502_40_dialog_content = "¿Raciones de Illumina?",
  ui_story_5036_50360502_41_dialog_content = "Pero ninguno de los soldados de Illumina fue asignado para trabajar cerca del escenario.",
  ui_story_5036_50360502_42_dialog_content = "Sí. A todos los chicos que me rodeaban les pasaba lo mismo.",
  ui_story_5036_50360502_43_dialog_content = "Nuestras raciones siguen desapareciendo misteriosamente.",
  ui_story_5036_50360502_44_dialog_content = "Podría ser...",
  ui_story_5036_50360502_45_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5036_50360502_46_dialog_content = "¿Era una rata?",
  ui_story_5036_50360502_47_dialog_content = "¡No! No una rata.",
  ui_story_5036_50360502_48_dialog_content = "¿Ves esa cosa huyendo, Marshmallow?",
  ui_story_5036_50360502_49_dialog_content = "¡Ve tras él!",
  ui_story_5036_50360502_50_dialog_content = "¡Guau guau!",
  ui_story_5036_50360502_51_dialog_content = "¿Hola?",
  ui_story_5036_50360502_52_dialog_content = "¡Hiya!",
  ui_story_5036_50360502_53_dialog_content = "No lo captures, Marshmallow. Solo síguelo de cerca por ahora.",
  ui_story_5036_50360502_54_dialog_content = "Tal vez nos lleve a <color=#FFB400>pez más grande</color>.",
  ui_story_5036_50360502_55_dialog_content = "¡Hola!",
  ui_story_5036_50360502_56_dialog_content = "¿Eh? Suspiro...",
  ui_story_5036_50360502_57_dialog_content = "Me ignoraste por completo hace un minuto, Bica...",
  ui_story_5036_50360502_58_dialog_content = "¿Ahora quieres acurrucarte?",
  ui_story_5036_50360502_59_dialog_content = "¡Wau!",
  ui_story_5036_50360502_60_dialog_content = "Ejem. Oye, ¿no deberías ponerle correa a ese perro gordito que tienes?",
  ui_story_5036_50360502_61_dialog_content = "Mi Bica es muy sensible y se pone nerviosa con facilidad, lo que luego le revuelve el estómago—",
  ui_story_5036_50360502_62_dialog_content = "¿Eres el ladrón fantasma?",
  ui_story_5036_50360502_63_dialog_content = "¿Fantasma? De ninguna manera.",
  ui_story_5036_50360502_64_dialog_content = "¿No me crees? Me morderé para demostrarlo. ¡Ay!",
  ui_story_5036_50360502_65_dialog_content = "Hombre, ¡eso realmente dolió!",
  ui_story_5036_50360502_66_dialog_content = "Mira, soy como vivir puede ser. Siento dolor. Los fantasmas no.",
  ui_story_5036_50360502_67_dialog_content = "(Es una tarea hablar con este tipo.)",
  ui_story_5036_50360502_68_dialog_content = "(¿Pero por qué suena familiar?)",
  ui_story_5036_50360502_69_dialog_content = "No me importa si eres el fantasma o no, ¡pero no toleraré que nadie intente arruinar mi concierto!",
  ui_story_5036_50360502_70_dialog_content = "¡Será mejor que empieces a explicarte!",
  ui_story_5036_50360502_71_dialog_content = "<color=#828282>¡Ding!</color>",
  ui_story_5036_50360502_72_dialog_content = "¡Esta cosa en mi mano no es solo ornamental!",
  ui_story_5036_50360502_73_dialog_content = "Bien bien...",
  ui_story_5036_50360502_74_dialog_content = "¡Tómalo con calma! Casi me tropiezo por tus amenazas.",
  ui_story_5036_50360502_75_dialog_content = "Tu atuendo se ve abultado. ¿Qué escondes debajo?",
  ui_story_5036_50360502_76_dialog_content = "Solo un bebé precioso que acabo de domesticar. Está descansando ahora mismo.",
  ui_story_5036_50360502_77_dialog_content = "¿Por qué no creo eso ni un poco?",
  ui_story_5036_50360502_78_dialog_content = "Suspiro. Solo puedo decir que te falta comprensión entonces.",
  ui_story_5036_50360502_79_dialog_content = "Lee más libros, hojea más periódicos, haz más obras de caridad... Eso es todo el consejo que puedo darte.",
  ui_story_5036_50360502_80_dialog_content = "Si no hay nada más, me despediré ahora.",
  ui_story_5036_50360502_81_dialog_content = "¡Quítate la ropa!",
  ui_story_5036_50360502_82_dialog_content = "¡¿Eh?! Puede que esté oscuro y no puedas ver nada...",
  ui_story_5036_50360502_83_dialog_content = "¡pero todavía tengo que proteger mi modestia!",
  ui_story_5036_50360502_84_dialog_content = "¡Atrápalo, Marshmallow!",
  ui_story_5036_50360502_85_dialog_content = "¡Wau!",
  ui_story_5036_50360502_86_dialog_content = "Míralo...!",
  ui_story_5036_50360502_87_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5036_50360502_88_dialog_content = "Me caí de todos modos...",
  ui_story_5036_50360502_89_dialog_content = "Oye, ¿no era uno de los artistas de la audición?",
  ui_story_5036_50360502_90_dialog_content = "Así que ese es el pretexto que usaste para colarte a bordo.",
  ui_story_5036_50360502_91_dialog_content = "Ay, ay, ay...",
  ui_story_5036_50360502_92_dialog_content = "¡¿Él?!",
  ui_story_5036_50360502_93_dialog_content = "¡Cau cau!",
  ui_story_5036_50360502_94_dialog_content = "Que...? ¿Se le cayó un búho de los brazos?",
  ui_story_5036_50360502_95_dialog_content = "¿No eran bienes robados? ¿Estaba siendo demasiado paranoico?",
  ui_story_5036_50360502_96_dialog_content = "Te dije que era inocente.",
  ui_story_5036_50360502_97_dialog_content = "<color=#e8d9bb>*Chapoteo* Clang, clang...</color>",
  ui_story_5036_50360502_98_dialog_content = "Muchas joyas se cayeron de las plumas de la lechuza.",
  ui_story_5036_50360502_99_dialog_content = "Mira, te dije que no era un ladrón.",
  ui_story_5036_50360502_100_dialog_content = "¡Oh, Lutumi, podrías haber sido cualquier cosa! ¿Por qué serías un ladrón?",
  ui_story_5036_50360502_101_dialog_content = "Ugh...",
  ui_story_5036_50360502_102_dialog_content = "¿Cómo sigues negándolo? ¡La evidencia está literalmente esparcida a nuestro alrededor!",
  ui_story_5036_50360502_103_dialog_content = "¡Relax!",
  ui_story_5036_50360502_104_dialog_content = "¡No tendré piedad contigo!",
  ui_story_5036_50360502_105_dialog_content = "Oh...",
  ui_story_5036_50360502_106_dialog_content = "¡¿Señorita Goldie?!",
  ui_story_5036_50360502_107_dialog_content = "No te preocupes, solo está temporalmente noqueado.",
  ui_story_5036_50360502_108_dialog_content = "Tiene una lengua plateada, y ninguno de nosotros tiene el tiempo ni la energía para lidiar con eso ahora.",
  ui_story_5036_50360502_109_dialog_content = "Por favor, llévelo bajo custodia e interróguelo cuando haya terminado con la tarea que tiene entre manos.",
  ui_story_5036_50360502_110_dialog_content = "<color=#e8d9bb>¡Hacer clic!</color>",
  ui_story_5036_50360502_111_dialog_content = "Así que...",
  ui_story_5036_50360502_112_dialog_content = "¿El rumor sobre la mala racha de Goldie era cierto?",
  ui_story_5036_50360502_113_dialog_content = "Con esta imagen podré...",
  ui_story_5036_50360601_1_dialog_content = "¿Ahora que?",
  ui_story_5036_50360601_2_dialog_content = "¡Lo tengo! ¡Excelente interior que garantizará las vistas!",
  ui_story_5036_50360601_3_dialog_content = "Será mejor que no me hagas perder el tiempo.",
  ui_story_5036_50360601_4_dialog_content = "¡Te prometo que estarás feliz con lo que tengo!",
  ui_story_5036_50360601_5_dialog_content = "¿Recuerdas cuando recibiste un aviso sobre que Goldie tenía una mala racha?",
  ui_story_5036_50360601_6_dialog_content = "(¿Dónde estoy?)",
  ui_story_5036_50360601_7_dialog_content = "(¿Cuándo regresé a Eraveil? Lo último que recuerdo es que estaba...)",
  ui_story_5036_50360601_8_dialog_content = "(¿Dónde estaba yo otra vez?)",
  ui_story_5036_50360601_9_dialog_content = "♪ La... La la la... ♪",
  ui_story_5036_50360601_10_dialog_content = "(¡Conozco esa melodía!)",
  ui_story_5036_50360601_11_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360601_12_dialog_content = "(¿Quién está tarareando?)",
  ui_story_5036_50360601_13_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_5036_50360601_14_dialog_content = "(¿Qué acaba de pasar volando, un coloso?)",
  ui_story_5036_50360601_15_dialog_content = "(Debería averiguarlo.)",
  ui_story_5036_50360601_16_dialog_content = "♪ La la la la... ♪",
  ui_story_5036_50360601_17_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360601_18_dialog_content = "♪ La... La la... ♪",
  ui_story_5036_50360601_19_dialog_content = "(La chica de ahí, ella es la que ha estado cantando.)",
  ui_story_5036_50360601_20_dialog_content = "Ahí tienes.",
  ui_story_5036_50360601_21_dialog_content = "(¿Me está hablando a mí?)",
  ui_story_5036_50360601_22_dialog_content = "¡Kree, kree!",
  ui_story_5036_50360601_23_dialog_content = "(Oh, ella está hablando con una criatura que se parece a un coloso).",
  ui_story_5036_50360601_24_dialog_content = "¿Aquí para escucharme cantar? ¡Eres un fan tan leal!",
  ui_story_5036_50360601_25_dialog_content = "Pero creo que es hora de poner palabras en la música.",
  ui_story_5036_50360601_26_dialog_content = "(La forma en que se viste y actúa... Definitivamente es una Caelestita).",
  ui_story_5036_50360601_27_dialog_content = "(¡Sabía que encontraría otros Caelestites!)",
  ui_story_5036_50360601_28_dialog_content = "Hmm, tengo un poco de sed.",
  ui_story_5036_50360601_29_dialog_content = "¡Vamos a recoger algunas frutas silvestres!",
  ui_story_5036_50360601_30_dialog_content = "¡Kree, kree!",
  ui_story_5036_50360601_31_dialog_content = "¡Hola pequeña!",
  ui_story_5036_50360601_32_dialog_content = "¡Espera!",
  ui_story_5036_50360601_33_dialog_content = "¿Ah?",
  ui_story_5036_50360601_34_dialog_content = "<color=#e8d9bb>¡Toc, toc!</color>",
  ui_story_5036_50360601_35_dialog_content = "¡Niñita!",
  ui_story_5036_50360601_36_dialog_content = "¿Ah?",
  ui_story_5036_50360601_37_dialog_content = "Ay, solo fue un sueño...",
  ui_story_5036_50360601_38_dialog_content = "<color=#e8d9bb>Cuatro días para el concierto</color>",
  ui_story_5036_50360601_39_dialog_content = "<color=#e8d9bb>¡Pila, libra, libra!</color>",
  ui_story_5036_50360601_40_dialog_content = "¿Estás bien ahí? PlayerName?",
  ui_story_5036_50360601_41_dialog_content = "¡Ya voy!",
  ui_story_5036_50360601_42_dialog_content = "¡Estabas muerto de sueño!",
  ui_story_5036_50360601_43_dialog_content = "¿No nos escuchaste golpeando la puerta?",
  ui_story_5036_50360601_44_dialog_content = "Empezamos a pensar que los eclipses se habían colado en tu habitación...",
  ui_story_5036_50360601_45_dialog_content = "Vice y yo estuvimos así de cerca de derribar la puerta.",
  ui_story_5036_50360601_46_dialog_content = "Lo siento, acabo de tener este sueño. Se sentía como si todavía estuviera en él.",
  ui_story_5036_50360601_47_dialog_content = "Ah, otro sueño.",
  ui_story_5036_50360601_48_dialog_content = "¿Otro?",
  ui_story_5036_50360601_49_dialog_content = "Sí. ¿Te olvidaste, Carleen?",
  ui_story_5036_50360601_50_dialog_content = "PlayerName tiene sueños extraños muy a menudo.",
  ui_story_5036_50360601_51_dialog_content = "De repente recordé que también tuve un sueño extraño esta mañana.",
  ui_story_5036_50360601_52_dialog_content = "Creo que soñé con Eraveil.",
  ui_story_5036_50360601_53_dialog_content = "Excepto que la persona que vivía allí no estaba PlayerName, pero una niña que nunca había visto antes.",
  ui_story_5036_50360601_54_dialog_content = "¡Yo también! yo tuve el mismo sueño!",
  ui_story_5036_50360601_55_dialog_content = "Wow, realmente tenemos una gran química en estos días.",
  ui_story_5036_50360601_56_dialog_content = "¡Deben ser todos esos ensayos!",
  ui_story_5036_50360601_57_dialog_content = "Pero soñé lo mismo.",
  ui_story_5036_50360601_58_dialog_content = "¿Qué?",
  ui_story_5036_50360601_59_dialog_content = "Vi a una niña cantando en Eraveil.",
  ui_story_5036_50360601_60_dialog_content = "¡Su canción era la melodía que se me quedó grabada en la cabeza!",
  ui_story_5036_50360601_61_dialog_content = "La chica de mi sueño no cantaba. Ella solo estaba ordenando su casa.",
  ui_story_5036_50360601_62_dialog_content = "La chica con la que soñé estaba leyendo en una habitación.",
  ui_story_5036_50360601_63_dialog_content = "Así que nuestros sueños eran ligeramente diferentes.",
  ui_story_5036_50360601_64_dialog_content = "Escuché que cuando varias personas experimentan lo mismo, existe la posibilidad de que terminen teniendo sueños similares.",
  ui_story_5036_50360601_65_dialog_content = "Debido a su experiencia compartida, su subconsciente gravita hacia los mismos pensamientos, lo que resulta en sueños similares.",
  ui_story_5036_50360601_66_dialog_content = "Uno sueña de noche lo que medita de día, como dice el refrán.",
  ui_story_5036_50360601_67_dialog_content = "Pero nuestras diferentes personalidades se reflejan en los detalles de un sueño idéntico.",
  ui_story_5036_50360601_68_dialog_content = "Eso es todo? Me emocioné por nada.",
  ui_story_5036_50360601_69_dialog_content = "De paso, PlayerName, ¿estás seguro de que quieres seguir chateando con nosotros?",
  ui_story_5036_50360601_70_dialog_content = "Tienes que estar presente en la segunda ronda de audiciones hoy, ¿no?",
  ui_story_5036_50360601_71_dialog_content = "¡¡Ups!! ¡Lo olvidé totalmente!",
  ui_story_5036_50360601_72_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360601_73_dialog_content = "♪ La... La la... ♪",
  ui_story_5036_50360601_74_dialog_content = "Esa es la totalidad de la melodía en mi cabeza. ¡Se siente bien sacarlo todo!",
  ui_story_5036_50360601_75_dialog_content = "*Bostezos*",
  ui_story_5036_50360601_76_dialog_content = "¿E-Estaba totalmente fuera de tono o algo así?",
  ui_story_5036_50360601_77_dialog_content = "No. No dormí bien anoche, así que disculpe, PlayerName.",
  ui_story_5036_50360601_78_dialog_content = "¿Es porque tuviste demasiados sueños?",
  ui_story_5036_50360601_79_dialog_content = "Tienes bastante imaginación, PlayerName.",
  ui_story_5036_50360601_80_dialog_content = "Revisé el escenario anoche.",
  ui_story_5036_50360601_81_dialog_content = "Y fue al área de encierro para cuidar de Eclipsites hasta altas horas de la madrugada.",
  ui_story_5036_50360601_82_dialog_content = "¿No están a cargo de eso los Mercenarios de la Llama Blanca?",
  ui_story_5036_50360601_83_dialog_content = "Sí, pero no podía soportar estar encerrado en mi habitación.",
  ui_story_5036_50360601_84_dialog_content = "Pensé que en lugar de preocuparme por eso, también podría ayudar.",
  ui_story_5036_50360601_85_dialog_content = "No es de extrañar que seas el ídolo más popular de Umbraton. Trabajas demasiado duro.",
  ui_story_5036_50360601_86_dialog_content = "¡Te involucras en todo!",
  ui_story_5036_50360601_87_dialog_content = "Cualquier pequeña cosa puede hacer o deshacer el concierto.",
  ui_story_5036_50360601_88_dialog_content = "El espectáculo es de suma importancia para mí. No puedo dejar que nada lo descarrile.",
  ui_story_5036_50360601_89_dialog_content = "Pareces ser del tipo que trata cada actuación como si fuera la última.",
  ui_story_5036_50360601_90_dialog_content = "R-¿En serio? Ajaja...",
  ui_story_5036_50360601_91_dialog_content = "Pero nos desviamos. ¿Cómo debo describir la melodía que acabas de compartir conmigo?",
  ui_story_5036_50360601_92_dialog_content = "¡Suave, relajante, terapéutico, únicamente Caelestite y fácil de cantar!",
  ui_story_5036_50360601_93_dialog_content = "¡Es exactamente el tipo de música que estoy buscando en todos los aspectos!",
  ui_story_5036_50360601_94_dialog_content = "¿Estás seguro de que no te importa que lo interprete en el escenario?",
  ui_story_5036_50360601_95_dialog_content = "Nunca pensé que sería compositor, ¡así que déjate llevar!",
  ui_story_5036_50360601_96_dialog_content = "Tener un ídolo tan famoso interpretando mi canción sería un honor.",
  ui_story_5036_50360601_97_dialog_content = "¡Déjame saber si tienes alguna idea para la letra!",
  ui_story_5036_50360601_98_dialog_content = "Ahora, hay algo más de lo que quería hablar contigo.",
  ui_story_5036_50360601_99_dialog_content = "¿Recuerdas al participante final en las audiciones de ayer?",
  ui_story_5036_50360601_100_dialog_content = "¿Te refieres a Vic?",
  ui_story_5036_50360601_101_dialog_content = "¿Es un amigo tuyo?",
  ui_story_5036_50360601_102_dialog_content = "Soy cercano a su aprendiz, así que supongo que podrías decir eso.",
  ui_story_5036_50360601_103_dialog_content = "Pero no sabía que se inscribió, y tampoco voté por él.",
  ui_story_5036_50360601_104_dialog_content = "¡No tienes que preocuparte por mi favoritismo!",
  ui_story_5036_50360601_105_dialog_content = "¿Tiene tendencias cleptómanas?",
  ui_story_5036_50360601_106_dialog_content = "¿Qué? ¿Por qué lo preguntas?",
  ui_story_5036_50360601_107_dialog_content = "Bueno, anoche tarde...",
  ui_story_5036_50360601_108_dialog_content = "¡Ayuda!",
  ui_story_5036_50360601_109_dialog_content = "Grahhhhhh!",
  ui_story_5036_50360601_110_dialog_content = "¡Deja de correr!",
  ui_story_5036_50360601_111_dialog_content = "¿Eclipsitas persiguiendo a Vic, mercenarios persiguiendo a los Eclipsitas? ¡¿Que está pasando aqui?!",
  ui_story_5036_50360602_1_dialog_content = "Los otros jueces están en sus asientos, la señorita Goldie y PlayerName.",
  ui_story_5036_50360602_2_dialog_content = "Si no te importa...",
  ui_story_5036_50360602_3_dialog_content = "¡Ayuda!",
  ui_story_5036_50360602_4_dialog_content = "Deberías unirte a nosotros para la segunda ronda de audiciones.",
  ui_story_5036_50360602_5_dialog_content = "Graagh!!!!",
  ui_story_5036_50360602_6_dialog_content = "¡Toma esto!",
  ui_story_5036_50360602_7_dialog_content = "Todo el mundo parece un poco preocupado en este momento...",
  ui_story_5036_50360602_8_dialog_content = "¡Ayuda!",
  ui_story_5036_50360602_9_dialog_content = "Ya puedes dejar de gritar. Los eclipses están caídos.",
  ui_story_5036_50360602_10_dialog_content = "*jadeo pesado*",
  ui_story_5036_50360602_11_dialog_content = "¡Estaba gritando para que no me encerraran con ellos otra vez!",
  ui_story_5036_50360602_12_dialog_content = "Por suerte para mí, las garras de Little Furball eran lo suficientemente largas como para abrir la cerradura.",
  ui_story_5036_50360602_13_dialog_content = "De lo contrario, ¡ni siquiera habría tenido la oportunidad de pedir ayuda!",
  ui_story_5036_50360602_14_dialog_content = "Lo sentimos, no teníamos ninguna intención de ponerte en peligro en absoluto.",
  ui_story_5036_50360602_15_dialog_content = "Pero cuando te encerramos en esa habitación, no había eclipses allí.",
  ui_story_5036_50360602_16_dialog_content = "...",
  ui_story_5036_50360602_17_dialog_content = "Se arrastraron por las rejillas de ventilación, señorita Goldie.",
  ui_story_5036_50360602_18_dialog_content = "El respiradero de esa habitación parece estar conectado al área de encierro.",
  ui_story_5036_50360602_19_dialog_content = "¿Pero la salida de aire no está asegurada con una cubierta?",
  ui_story_5036_50360602_20_dialog_content = "Ya veo.",
  ui_story_5036_50360602_21_dialog_content = "¡Estabas tratando de escapar a través del respiradero, lo que atrajo a los Eclipsites allí!",
  ui_story_5036_50360602_22_dialog_content = "Uh... Je, je.",
  ui_story_5036_50360602_23_dialog_content = "Hacía mucho calor en la habitación. Realmente necesitaba un poco de aire.",
  ui_story_5036_50360602_24_dialog_content = "¿Que esta pasando? ¿Por qué encerraste a Vic?",
  ui_story_5036_50360602_25_dialog_content = "Lo siento, PlayerName.",
  ui_story_5036_50360602_26_dialog_content = "Pero tu amigo Vic es el ladrón fantasma que ha estado robando durante los últimos días.",
  ui_story_5036_50360602_27_dialog_content = "¿Vic es el ladrón?",
  ui_story_5036_50360602_28_option_content = "Bueno, es posible.",
  ui_story_5036_50360602_29_dialog_content = "Es un extrozoólogo publicado, pero eso fue hace muchos años.",
  ui_story_5036_50360602_30_dialog_content = "Podía imaginarlo recurriendo al hurto sin ningún libro nuevo en su haber ni ingresos fiables.",
  ui_story_5036_50360602_31_dialog_content = "Pero no importa cuán pobre seas, aún debes ganar dinero con tus propias manos.",
  ui_story_5036_50360602_32_dialog_content = "¡No deberías poner tus manos en los bolsillos de otros y tomar sus cosas!",
  ui_story_5036_50360602_33_option_content = "¡Imposible!",
  ui_story_5036_50360602_34_dialog_content = "Es un extrozoólogo publicado con muchos estudiantes.",
  ui_story_5036_50360602_35_dialog_content = "No importa lo pobre que sea, ¡no recurriría a pequeños robos!",
  ui_story_5036_50360602_36_dialog_content = "Sé que te cuesta aceptarlo.",
  ui_story_5036_50360602_37_dialog_content = "No puedo creerlo yo mismo. Vi mucho potencial en él.",
  ui_story_5036_50360602_38_dialog_content = "Pero ayer descubrimos comida y joyas robadas en sus bolsillos. La prueba estaba ahí.",
  ui_story_5036_50360602_39_dialog_content = "Escúchame explicar...",
  ui_story_5036_50360602_40_dialog_content = "Ayer escuché suficientes excusas enrevesadas.",
  ui_story_5036_50360602_41_dialog_content = "¿Sigues tratando de negarlo con la cantidad de evidencia disponible?",
  ui_story_5036_50360602_42_dialog_content = "Está bien, está bien, confieso todo el robo reciente.",
  ui_story_5036_50360602_43_dialog_content = "¡¿Así que realmente eres el ladrón fantasma?!",
  ui_story_5036_50360602_44_dialog_content = "¡Aunque soy responsable, hay un descargo de responsabilidad!",
  ui_story_5036_50360602_45_dialog_content = "Yo, Vic, soy un extrozoólogo famoso, pero nunca he sido un ladrón.",
  ui_story_5036_50360602_46_dialog_content = "El ladrón del que todos hablan es en realidad una bestia maravillosa que traje conmigo.",
  ui_story_5036_50360602_47_dialog_content = "Hola...",
  ui_story_5036_50360602_48_dialog_content = "Ugh...",
  ui_story_5036_50360602_49_dialog_content = "¡Chirp, chirp!",
  ui_story_5036_50360602_50_dialog_content = "El pequeño peludo en tu hombro parece estar agitado.",
  ui_story_5036_50360602_51_dialog_content = "Little Furball está diciendo: \"¡Fueron esos dos, no yo!\"",
  ui_story_5036_50360602_52_dialog_content = "¡Chirrido!",
  ui_story_5036_50360602_53_dialog_content = "Por lo general, cambio sus comidas todos los días.",
  ui_story_5036_50360602_54_dialog_content = "Pero estaba demasiado ocupado empacando para mí y solo traje un tipo de comida.",
  ui_story_5036_50360602_55_dialog_content = "Estos dos se fueron solos, probablemente porque estaban cansados de comer lo mismo.",
  ui_story_5036_50360602_56_dialog_content = "Cuando me enteré del robo en el Coloso, pensé que podrían haber sido ellos.",
  ui_story_5036_50360602_57_dialog_content = "Me tomó una eternidad finalmente atraparlos a ambos anoche.",
  ui_story_5036_50360602_58_dialog_content = "¿Justo antes de que te atrapáramos?",
  ui_story_5036_50360602_59_dialog_content = "Sí. Que casualidad, eh?",
  ui_story_5036_50360602_60_dialog_content = "Entiendo que los animales quieran comer, pero ¿por qué robar joyas?",
  ui_story_5036_50360602_61_dialog_content = "¿Fue el búho Lutumi?",
  ui_story_5036_50360602_62_dialog_content = "Así es. El Lutumi Owl puede emitir un gas anestésico. Lo traje conmigo para fines de defensa personal.",
  ui_story_5036_50360602_63_dialog_content = "Pero le encanta coleccionar objetos brillantes, así que si le pierdes la pista...",
  ui_story_5036_50360602_64_dialog_content = "Termina convirtiéndose exactamente en el tipo de ladrón del que todo el mundo ha estado hablando.",
  ui_story_5036_50360602_65_dialog_content = "Sin embargo, solo actúan por instinto. No albergan malicia hacia nosotros.",
  ui_story_5036_50360602_66_dialog_content = "Yo tengo la culpa de no mantenerlos a raya.",
  ui_story_5036_50360602_67_dialog_content = "¡Prometo devolver todas las joyas y monedas a sus dueños!",
  ui_story_5036_50360602_68_dialog_content = "Si es necesario, incluso pagaré por los problemas que les causé a todos.",
  ui_story_5036_50360602_69_dialog_content = "¡Solo por favor no castigues a las criaturas! No lo dijeron en serio.",
  ui_story_5036_50360602_70_dialog_content = "Hai, hai, hai.",
  ui_story_5036_50360602_71_dialog_content = "...",
  ui_story_5036_50360602_72_dialog_content = "Está bien, pero debes hacer lo que prometiste.",
  ui_story_5036_50360602_73_dialog_content = "Devuélvelo todo con una disculpa y una compensación.",
  ui_story_5036_50360602_74_dialog_content = "Entonces, ¿qué tal si no nos encierran más en una pequeña habitación oscura?",
  ui_story_5036_50360602_75_dialog_content = "Está muy cargado allí...",
  ui_story_5036_50360602_76_dialog_content = "Yo puedo hacer eso.",
  ui_story_5036_50360602_77_dialog_content = "Pero debes prometerme que te irás de Eulogoz después de que te ocupes de todo.",
  ui_story_5036_50360602_78_dialog_content = "¿Qué? No, no puedo irme. ¡Todavía no he logrado mi sueño de ser un ídolo!",
  ui_story_5036_50360602_79_dialog_content = "¿No me animó a seguir audicionándose, señorita Goldie?",
  ui_story_5036_50360602_80_dialog_content = "Tienes talento además de una lengua simplista...",
  ui_story_5036_50360602_81_dialog_content = "Pero de alguna manera tengo la sensación de que no viniste aquí para una audición de ídolo.",
  ui_story_5036_50360602_82_dialog_content = "!",
  ui_story_5036_50360602_83_dialog_content = "... Está bien, supongo que seré sincero.",
  ui_story_5036_50360602_84_dialog_content = "De hecho, estoy aquí buscando una bestia maravillosa llamada Ouroboros.",
  ui_story_5036_50360602_85_dialog_content = "Cuando la criatura crece hasta cierto punto, se convierte en un huevo.",
  ui_story_5036_50360602_86_dialog_content = "Luego estalla después de la incubación y el ciclo se repite, lo que le permite alcanzar la inmortalidad.",
  ui_story_5036_50360602_87_dialog_content = "¡¿Hay criaturas inmortales en el mundo?!",
  ui_story_5036_50360602_88_dialog_content = "He sabido desde que era muy joven que mi padre y mi madre no eran mis padres biológicos.",
  ui_story_5036_50360602_89_dialog_content = "Recientemente descubrí que mi línea de sangre parece estar conectada con los Ouroboros. ¡Por lo tanto, debo encontrarlo!",
  ui_story_5036_50360602_89X1_dialog_content = "Si encuentro un Ouroboros, puedo averiguar más sobre mis orígenes, y tal vez incluso pueda encontrar a mis padres biológicos.",
  ui_story_5036_50360602_90_dialog_content = "Los registros sobre la especie son escasos. Lo único cierto sobre ellos es que les gusta andar por Colosos.",
  ui_story_5036_50360602_91_dialog_content = "¡Estás en un estupor de borracho otra vez, maestro! ¡Animarse!",
  ui_story_5036_50360602_92_dialog_content = "Ya busqué información sobre todos los Colossi en Astra, incluido Soroz de PlayerName.",
  ui_story_5036_50360602_93_dialog_content = "Nunca se encontraron signos de ningún Ouroboros cerca de ninguno de ellos.",
  ui_story_5036_50360602_94_dialog_content = "¿Existen realmente los Ouroboros?",
  ui_story_5036_50360602_96_dialog_content = "¡¿No volverás a jugar conmigo, verdad?!",
  ui_story_5036_50360602_97_dialog_content = "¡Hmph! ¡No me hagas buscar un estúpido Ouroboros para ti nunca más!",
  ui_story_5036_50360602_98_dialog_content = "Revisé todos los Colosos en Astra pero no pude encontrar ningún rastro de un Ouroboros.",
  ui_story_5036_50360602_99_dialog_content = "El único lugar en el que no he buscado todavía es este coloso volador en el que estamos.",
  ui_story_5036_50360602_100_dialog_content = "Entonces, ¿has encontrado rastros de un Ouroboros en Eulogoz?",
  ui_story_5036_50360602_101_dialog_content = "No, pero tengo una corazonada, una corazonada muy fuerte.",
  ui_story_5036_50360602_102_dialog_content = "¡Definitivamente hay un Ouroboros en Eulogoz!",
  ui_story_5036_50360602_103_dialog_content = "¡Permítanme quedarme y buscarlo!",
  ui_story_5036_50360602_104_dialog_content = "¡Dale a alguien que nunca antes ha experimentado el cálido hogar de un hogar lleno de amor, la oportunidad de encontrar a su familia!",
  ui_story_5036_50360602_105_dialog_content = "... ¿Ya terminaste?",
  ui_story_5036_50360602_106_dialog_content = "Sí, he terminado.",
  ui_story_5036_50360602_107_dialog_content = "Esa historia tuya es más increíble de lo que podría ofrecer cualquier película de bajo presupuesto de Umbraton.",
  ui_story_5036_50360602_108_dialog_content = "Debo agradecerte por ampliar mis horizontes.",
  ui_story_5036_50360602_109_dialog_content = "Jejeje, no hay problema. Gracias por entender.",
  ui_story_5036_50360602_110_dialog_content = "Debería habérselo dejado claro a todo el mundo desde el principio.",
  ui_story_5036_50360602_111_dialog_content = "Muy bien, la hora del cuento ha terminado.",
  ui_story_5036_50360602_112_dialog_content = "Ahora, ¿podrías por favor salir de Eulogoz?",
  ui_story_5036_50360602_113_dialog_content = "¿Qué?",
  ui_story_5036_50360602_114_dialog_content = "Por aqui por favor. Te escoltaré.",
  ui_story_5036_50360602_115_dialog_content = "¡Espera un minuto! ¡No he terminado aún!",
  ui_story_5036_50360602_116_dialog_content = "¡Es una broma! Solo estaba bromeando, jajaja.",
  ui_story_5036_50360602_116X1_dialog_content = "Adaptarse e improvisar para cualquier situación, animar el ambiente y apelar a las emociones de los fanáticos: todo eso es parte de las responsabilidades de un ídolo.",
  ui_story_5036_50360602_116X2_dialog_content = "¡Quería mostrarles de lo que soy capaz para que sepan cuán sinceramente deseo participar en las audiciones!",
  ui_story_5036_50360602_117_dialog_content = "¿Te refieres a comedia de improvisación?",
  ui_story_5036_50360602_118_dialog_content = "¿No te hizo reír mi historia espontánea?",
  ui_story_5036_50360602_119_dialog_content = "Bueno...",
  ui_story_5036_50360602_120_dialog_content = "(De hecho, Vic cautivó toda mi atención desde el principio).",
  ui_story_5036_50360602_121_dialog_content = "(Lady Sheol dijo que me faltaba algo... ¿Podría ser el cautivador sentido del humor que posee Vic?)",
  ui_story_5036_50360602_124_dialog_content = "Realmente quiero ser un ídolo... Por favor, déjame quedarme y competir.",
  ui_story_5036_50360602_125_dialog_content = "Puede que no me creas, pero no creas PlayerName?",
  ui_story_5036_50360602_126_dialog_content = "Es nuestro VIP, por supuesto que le creo de todo corazón.",
  ui_story_5036_50360602_127_dialog_content = "Ahí lo tienes entonces.",
  ui_story_5036_50360602_128_dialog_content = "Fia te ayudó muchas veces antes, cierto, PlayerName?",
  ui_story_5036_50360602_129_dialog_content = "Er... sí, podrías decir eso.",
  ui_story_5036_50360602_130_dialog_content = "Y por asociación, ¿eso no significa que técnicamente soy tu benefactor?",
  ui_story_5036_50360602_131_dialog_content = "B-Benefactor?",
  ui_story_5036_50360602_132_dialog_content = "Entonces, como juez, responderá por mí, ¿verdad?",
  ui_story_5036_50360602_133_dialog_content = "...",
  ui_story_5036_50360602_134_dialog_content = "PlayerName responde por mí, señorita Goldie.",
  ui_story_5036_50360602_135_dialog_content = "Por favor, no me eches en su nombre...",
  ui_story_5036_50360602_136_dialog_content = "¿Respondes por él, PlayerName?",
  ui_story_5036_50360602_137_dialog_content = "Eh, bueno.",
  ui_story_5036_50360602_138_dialog_content = "Acercate, PlayerName. Escuchar...",
  ui_story_5036_50360602_139_dialog_content = "¡No me digas que no notaste la poderosa presencia de Lumina en el área de bloqueo de Eulogoz!",
  ui_story_5036_50360602_140_dialog_content = "¡¿Qué?!",
  ui_story_5036_50360602_141_dialog_content = "Así que Goldie estaba tratando de atrapar a un ladrón anoche...",
  ui_story_5036_50360602_142_dialog_content = "Eso significa que mi foto era engañosa...",
  ui_story_5036_50360602_143_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_5036_50360602_144_dialog_content = "¿Cuándo me envías la foto que mencionas, Brandy?",
  ui_story_5036_50360602_145_dialog_content = "¡Necesito profundizar más en la situación!",
  ui_story_5036_50360602_146_dialog_content = "¿Qué más excavaciones tienes que hacer?",
  ui_story_5036_50360602_147_dialog_content = "La verdad no importa, ¡solo las noticias cautivadoras son buenas noticias!",
  ui_story_5036_50360602_148_dialog_content = "Pero...",
  ui_story_5036_50360602_149_dialog_content = "¡No te molestes en volver si no envías la foto!",
  ui_story_5036_50360602_150_dialog_content = "¡Editor! ¡Editor!",
  ui_story_5036_50360701_1_dialog_content = "Tus comentarios son cada vez más profesionales, PlayerName!",
  ui_story_5036_50360701_2_dialog_content = "¡Algún día podrías convertirte en un verdadero productor de ídolos!",
  ui_story_5036_50360701_3_dialog_content = "Aunque...",
  ui_story_5036_50360701_4_dialog_content = "¿Sigues preocupado por Vic?",
  ui_story_5036_50360701_5_dialog_content = "¡Sí, lo siento!",
  ui_story_5036_50360701_6_dialog_content = "A pesar de que respondiste por él, todavía estoy ansioso.",
  ui_story_5036_50360701_7_dialog_content = "Lo puse en una sala de ensayo cercana, pero no sé si está practicando en serio.",
  ui_story_5036_50360701_8_dialog_content = "Me pregunto si está siendo perjudicial para los demás.",
  ui_story_5036_50360701_9_dialog_content = "Sabes qué, tengo que ir a ver cómo está.",
  ui_story_5036_50360701_10_dialog_content = "Te ayudare.",
  ui_story_5036_50360701_11_dialog_content = "Cumple mi palabra, así que debería supervisarlo.",
  ui_story_5036_50360701_12_dialog_content = "Y apenas has descansado desde ayer. Deberías tomar un descanso.",
  ui_story_5036_50360701_13_dialog_content = "Verdadero. También tengo una canción para escribir... ¡No puedo desperdiciar la melodía que compartiste conmigo!",
  ui_story_5036_50360701_14_dialog_content = "¡Te dejaré a Vic!",
  ui_story_5036_50360701_15_dialog_content = "*Bostezo* ¿Qué dijiste?",
  ui_story_5036_50360701_16_dialog_content = "¿Cómo te va hoy?",
  ui_story_5036_50360701_17_dialog_content = "No está mal.",
  ui_story_5036_50360701_18_dialog_content = "¡Dormí genial anoche!",
  ui_story_5036_50360701_19_dialog_content = "Estaba preguntando por tu ensayo.",
  ui_story_5036_50360701_20_dialog_content = "¿No me digas que dormiste todo el día y nunca pensaste en eso?",
  ui_story_5036_50360701_21_dialog_content = "¿No me aclaré ya? Está bien, una vez más.",
  ui_story_5036_50360701_22_dialog_content = "Inscribirse en la competencia fue una excusa, la historia de Ouroboros no es falsa.",
  ui_story_5036_50360701_23_dialog_content = "Quería aprovechar esta oportunidad para entrar en Eulogoz y encontrar a la criatura.",
  ui_story_5036_50360701_24_dialog_content = "Lo sé, pero no siento ninguna Lumina poderosa proveniente del área de bloqueo.",
  ui_story_5036_50360701_25_dialog_content = "Solo hay un montón de Eclipsites durmiendo allí.",
  ui_story_5036_50360701_26_dialog_content = "Un Ouroboros en incubación no libera una cantidad significativa de Lumina.",
  ui_story_5036_50360701_27_dialog_content = "¡Eso significa que la criatura todavía está en un huevo!",
  ui_story_5036_50360701_28_dialog_content = "¿Cómo estás tan seguro de que hay una de esas cosas en Eugoloz?",
  ui_story_5036_50360701_29_dialog_content = "Llámalo intuición. La intuición de un extrozoólogo.",
  ui_story_5036_50360701_30_dialog_content = "Así que básicamente no tienes evidencia alguna.",
  ui_story_5036_50360701_31_dialog_content = "Puedo entender un poco por qué Fia siempre está de mal humor contigo ahora.",
  ui_story_5036_50360701_32_dialog_content = "¿Todavía no puedes convencerlos de que me dejen entrar en el área de encierro?",
  ui_story_5036_50360701_33_dialog_content = "¿Cómo esperas que aborde el tema?",
  ui_story_5036_50360701_34_dialog_content = "Goldie ordenó a los mercenarios que protegieran el área, por lo que claramente no quiere que nadie entre y cause problemas.",
  ui_story_5036_50360701_35_dialog_content = "Incluso si hay un Ouroboros en Eulogoz, al menos puedes esperar hasta que termine el concierto antes de buscarlo.",
  ui_story_5036_50360701_36_dialog_content = "¿Quieres decir que puedo quedarme en Eulogoz hasta que termine el programa?",
  ui_story_5036_50360701_37_dialog_content = "Eso depende de si superas las audiciones.",
  ui_story_5036_50360701_38_dialog_content = "Los concursantes que no obtengan suficientes votos deben irse de inmediato. Está claramente establecido en las reglas.",
  ui_story_5036_50360701_39_dialog_content = "¿Oh eso? Eso es pan comido.",
  ui_story_5036_50360701_40_dialog_content = "¿Vaya? ¿Tenías un espectáculo en mente?",
  ui_story_5036_50360701_41_dialog_content = "¿Qué piensas acerca de hacer que Little Furball haga volteretas hacia atrás?",
  ui_story_5036_50360701_42_dialog_content = "¿Un espectáculo de animales? Sería mejor que hicieras una audición para un circo.",
  ui_story_5036_50360701_43_dialog_content = "¿No es esto una competencia de canto de ídolos?",
  ui_story_5036_50360701_44_dialog_content = "¿Te tropezaste con el lugar equivocado?",
  ui_story_5036_50360701_45_dialog_content = "Ooh, ¿se está gestando un drama aquí?",
  ui_story_5036_50360701_46_dialog_content = "Donde hay drama, hay noticias. ¡Será mejor que tome buenas notas!",
  ui_story_5036_50360701_47_dialog_content = "¡Oye, deja de mirar a los demás! ¡Si, tú!",
  ui_story_5036_50360701_48_dialog_content = "¿Me conoces?",
  ui_story_5036_50360701_49_dialog_content = "te conozco",
  ui_story_5036_50360701_50_dialog_content = "¡Vaya, no esperaba encontrarme con alguien que leyera mi trabajo aquí!",
  ui_story_5036_50360701_51_dialog_content = "Eres ese ladrón fantasma que fue atrapado recientemente.",
  ui_story_5036_50360701_52_dialog_content = "¿No se supone que los ladrones deben ser arrestados? ¿Qué está haciendo todavía en la audición?",
  ui_story_5036_50360701_53_dialog_content = "¡Sin mencionar que está ocupando un puesto!",
  ui_story_5036_50360701_54_dialog_content = "Escucha, ladrón. No sé a quién le engrasaste las palmas...",
  ui_story_5036_50360701_55_dialog_content = "¡Pero ninguno de nosotros le permitirá profanar el escenario o nuestros sueños!",
  ui_story_5036_50360701_56_dialog_content = "Si no planeas hacer una audición de verdad, ¡entonces vete!",
  ui_story_5036_50360701_57_dialog_content = "Tómenlo con calma, todos...",
  ui_story_5036_50360701_58_dialog_content = "Todo fue un malentendido. Realmente quiero competir.",
  ui_story_5036_50360701_59_dialog_content = "No solo eso, he decidido llegar hasta la etapa final.",
  ui_story_5036_50360701_60_dialog_content = "¿Con tu número de circo?",
  ui_story_5036_50360701_61_dialog_content = "¡Estaba bromeando!",
  ui_story_5036_50360701_62_dialog_content = "¿Por qué me inscribiría si no tenía una actuación preparada?",
  ui_story_5036_50360701_63_dialog_content = "Entonces muéstranos lo que tienes.",
  ui_story_5036_50360701_64_dialog_content = "¡Sí!",
  ui_story_5036_50360701_65_dialog_content = "¡Veamos qué tipo de espectáculo estás montando!",
  ui_story_5036_50360701_66_dialog_content = "Sobre eso...",
  ui_story_5036_50360701_67_dialog_content = "Bueno, ¿qué estás esperando?",
  ui_story_5036_50360701_68_dialog_content = "¡Vamos! ¡Muéstranos!",
  ui_story_5036_50360701_69_dialog_content = "¡Vale, cálmate! ¡Lo haré!",
  ui_story_5036_50360701_70_dialog_content = "Ejem, damas y caballeros: la danza Drakolion.",
  ui_story_5036_50360701_71_dialog_content = "Este baile es una imitación de un Drakolion en vuelo, buscando pareja. ¡Échale un buen vistazo!",
  ui_story_5036_50360701_72_dialog_content = "¡Oye!",
  ui_story_5036_50360701_73_dialog_content = "¡Ja!",
  ui_story_5036_50360701_74_dialog_content = "¿Es... que se supone que es un baile?",
  ui_story_5036_50360701_75_dialog_content = "Se parece más a alguien que vuelve a aprender a caminar después de romperse una pierna.",
  ui_story_5036_50360701_76_dialog_content = "¡Mira esto, una voltereta hacia atrás en el aire!",
  ui_story_5036_50360701_77_dialog_content = "Yo-ho! Aquí tienes.",
  ui_story_5036_50360701_78_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5036_50360701_79_dialog_content = "Oh Dios... ¡Ay, ay, ay, ay, ay!",
  ui_story_5036_50360701_80_dialog_content = "¡Jajaja!",
  ui_story_5036_50360701_81_dialog_content = "¿Te lastimaste la espalda en su lugar?",
  ui_story_5036_50360701_82_dialog_content = "¡Se necesita un talento especial para bailar así!",
  ui_story_5036_50360701_83_dialog_content = "Extrozoólogo convertido en ídolo intimidado en Eulogoz...",
  ui_story_5036_50360701_84_dialog_content = "¿Le gustará al editor este tipo de historia?",
  ui_story_5036_50360701_85_dialog_content = "¿Estás bien, Vic?",
  ui_story_5036_50360701_86_dialog_content = "solo veo PlayerName se preocupa por los ancianos!",
  ui_story_5036_50360701_87_dialog_content = "Mi trasero está atascado en algo. ¿Puedes levantarme?",
  ui_story_5036_50360701_88_dialog_content = "Seguro...",
  ui_story_5036_50360701_89_dialog_content = "Oye, ¿eso es... una salida de aire detrás de ti?",
  ui_story_5036_50360701_90_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5036_50360701_91_dialog_content = "¿Qué fue eso?",
  ui_story_5036_50360701_92_dialog_content = "Wow, volví a romper el respiradero, ¡jajaja!",
  ui_story_5036_50360701_93_dialog_content = "¡Graagh!",
  ui_story_5036_50360701_94_dialog_content = "¿Por qué también hay eclipses en este respiradero?",
  ui_story_5036_50360701_95_dialog_content = "Correr-!",
  ui_story_5036_50360702_1_dialog_content = "¡Graagh!",
  ui_story_5036_50360702_2_dialog_content = "¡Florecer!",
  ui_story_5036_50360702_3_dialog_content = "La forma en que Goldie lidió con esos eclipses... Necesito darme prisa y encontrar una forma de investigar ese dato sobre ella.",
  ui_story_5036_50360702_4_dialog_content = "¡Oh, no! Olvidé tomar fotos...",
  ui_story_5036_50360702_5_dialog_content = "Hay alguien herido?",
  ui_story_5036_50360702_6_dialog_content = "Todo el mundo está bien, sólo un poco asustado.",
  ui_story_5036_50360702_7_dialog_content = "Gracias por salvarnos, señorita Goldie.",
  ui_story_5036_50360702_8_dialog_content = "Eres tan bonita como en los carteles... ¡No, eres mucho más bonita!",
  ui_story_5036_50360702_9_dialog_content = "¡¿Señorita Goldie?!",
  ui_story_5036_50360702_10_dialog_content = "¡He sido un Goldilock desde que debutaste!",
  ui_story_5036_50360702_11_dialog_content = "¿Quiere autografiar aquí, señorita Goldie?",
  ui_story_5036_50360702_12_dialog_content = "Goldie! Goldie! Goldie!",
  ui_story_5036_50360702_13_dialog_content = "Perdón por esto. Enviaré a alguien para sellar el respiradero y proporcionar comida a todos.",
  ui_story_5036_50360702_14_dialog_content = "Todo es culpa de ese ladrón. Nada de esto hubiera pasado si su trasero no hubiera roto la pantalla.",
  ui_story_5036_50360702_15_dialog_content = "¡Y seguro que es un pésimo bailarín!",
  ui_story_5036_50360702_16_dialog_content = "¡Échalo afuera! ¡Échalo afuera! ¡Échalo afuera!",
  ui_story_5036_50360702_17_dialog_content = "Pero...",
  ui_story_5036_50360702_18_dialog_content = "Tengo muchas ganas de pasar la audición.",
  ui_story_5036_50360702_19_dialog_content = "¿Oh sí?",
  ui_story_5036_50360702_20_dialog_content = "¿Tienes la perseverancia para llegar hasta el final?",
  ui_story_5036_50360702_21_dialog_content = "Para Uróboros...",
  ui_story_5036_50360702_22_dialog_content = "¡Yo debo!",
  ui_story_5036_50360702_23_dialog_content = "¡Debo llegar hasta el final!",
  ui_story_5036_50360702_24_dialog_content = "(Tal optimismo y determinación ciegos me hacen sentir nostalgia.)",
  ui_story_5036_50360702_25_dialog_content = "(Antes de pasar por cualquier entrenamiento, también prometí que algún día estaría en un escenario más grande).",
  ui_story_5036_50360702_26_dialog_content = "(¿Estoy viendo cosas?)",
  ui_story_5036_50360702_27_dialog_content = "(¿Por qué veo a mi yo más joven en Vic?)",
  ui_story_5036_50360702_28_dialog_content = "(¿Es porque ambos creemos en el poder de la fe?)",
  ui_story_5036_50360702_29_dialog_content = "¡Debo perseverar hasta el final!",
  ui_story_5036_50360702_30_dialog_content = "...",
  ui_story_5036_50360702_31_dialog_content = "Está bien, te creeré una última vez.",
  ui_story_5036_50360702_32_dialog_content = "¡Échalo afuera! ¡Échalo afuera! ¡Échalo afuera!",
  ui_story_5036_50360702_33_dialog_content = "Escúchame...",
  ui_story_5036_50360702_34_dialog_content = "Debido a una serie de malentendidos, tomamos por error a Vic como el ladrón fantasma.",
  ui_story_5036_50360702_35_dialog_content = "Pero todo se aclaró. Vic ya devolvió todo a sus respectivos dueños e hizo las enmiendas correspondientes.",
  ui_story_5036_50360702_36_dialog_content = "Entonces, acordamos dejarlo continuar audicionando.",
  ui_story_5036_50360702_37_dialog_content = "Sin embargo, sus acciones interrumpieron los procedimientos.",
  ui_story_5036_50360702_38_dialog_content = "Por lo tanto, le estamos dando solo una última oportunidad.",
  ui_story_5036_50360702_39_dialog_content = "Si todavía no puede venir, haremos que se vaya.",
  ui_story_5036_50360702_40_dialog_content = "Sólo quedan uno o dos días. No mejorará por mucho que practique.",
  ui_story_5036_50360702_41_dialog_content = "Pero, ya que la Srta. Goldie ha hablado...",
  ui_story_5036_50360702_42_dialog_content = "¡Apoyo su decisión!",
  ui_story_5036_50360702_43_dialog_content = "Si pasa con un baile así...",
  ui_story_5036_50360702_44_dialog_content = "No puedo evitar dudar de la señorita Goldie y de la integridad del evento.",
  ui_story_5036_50360702_45_dialog_content = "¡Por favor, créanme cuando digo que seré justo!",
  ui_story_5036_50360702_46_dialog_content = "Goldie! Goldie! Goldie!",
  ui_story_5036_50360702_47_dialog_content = "Ejem, gracias, señorita Goldie.",
  ui_story_5036_50360702_48_dialog_content = "¿Qué haces todavía aquí?",
  ui_story_5036_50360702_49_dialog_content = "¿Ah?",
  ui_story_5036_50360702_50_dialog_content = "Encuentra una habitación y empieza a practicar.",
  ui_story_5036_50360702_51_dialog_content = "Pero ya es muy tarde...",
  ui_story_5036_50360702_52_dialog_content = "Te dije que tenías muy buena voz y excelentes visuales.",
  ui_story_5036_50360702_53_dialog_content = "Ya estás muy por delante de la curva que la mayoría de la gente.",
  ui_story_5036_50360702_54_dialog_content = "Pero si realmente quieres llegar hasta el final...",
  ui_story_5036_50360702_55_dialog_content = "Debes hacer lo que digo.",
  ui_story_5036_50360801_1_dialog_content = "<color=#e8d9bb>Tres días para el concierto</color>",
  ui_story_5036_50360801_2_dialog_content = "♪ Ah... Ah...",
  ui_story_5036_50360801_3_dialog_content = "¡Alto!",
  ui_story_5036_50360801_4_dialog_content = "¿Esa es la canción que planeas cantar?",
  ui_story_5036_50360801_5_dialog_content = "¡Les dije que tenía algo preparado, pero ninguno de ustedes me creyó!",
  ui_story_5036_50360801_6_dialog_content = "¿Funcionará esta canción?",
  ui_story_5036_50360801_7_dialog_content = "Salí a un bosque remoto en Northland y observé raras auroragales cantando en busca de inspiración para la melodía.",
  ui_story_5036_50360801_8_dialog_content = "Junto con letras salvajes y naturistas escritas por un extrozoólogo como yo...",
  ui_story_5036_50360801_9_dialog_content = "¡No hay forma de que no salga bien!",
  ui_story_5036_50360801_10_dialog_content = "Ejem...",
  ui_story_5036_50360801_11_dialog_content = "La canción no es el problema. Tu canto todavía tiene mucho margen de mejora.",
  ui_story_5036_50360801_12_dialog_content = "Creo que lo estás expresando demasiado bien.",
  ui_story_5036_50360801_13_dialog_content = "De hecho, MUY bien.",
  ui_story_5036_50360801_14_dialog_content = "PlayerName es una cosa, pero ¿por qué se burlaría de mí también, señorita reportera?",
  ui_story_5036_50360801_15_dialog_content = "Sólo estoy diciendo la verdad.",
  ui_story_5036_50360801_16_dialog_content = "Brandy es una reportera amable, objetiva y profesional.",
  ui_story_5036_50360801_17_dialog_content = "Si tu canto no la impresionó, debes averiguar cuál es el problema.",
  ui_story_5036_50360801_18_dialog_content = "¿Quizás sus orejas sufrieron heridas en el pasado? ¿Es por eso que no pudo distinguir lo hermosa que es mi voz, señorita reportera?",
  ui_story_5036_50360801_19_dialog_content = "¡No, no es a eso a lo que voy con esto!",
  ui_story_5036_50360801_20_dialog_content = "Um, así que, de todos modos...",
  ui_story_5036_50360801_21_dialog_content = "Para cantar bien una canción, primero hay que aprender a respirar correctamente.",
  ui_story_5036_50360801_22_dialog_content = "¿Necesito aprender a respirar?",
  ui_story_5036_50360801_23_dialog_content = "Si quieres ser seleccionado, sigue mis instrucciones.",
  ui_story_5036_50360801_24_dialog_content = "¡Entendido, Maestro Goldie!",
  ui_story_5036_50360801_25_dialog_content = "Inhala y llena tu barriga de aire como un globo. Contrae tu vientre cuando exhalas.",
  ui_story_5036_50360801_26_dialog_content = "Esta es la técnica de respiración abdominal.",
  ui_story_5036_50360801_27_dialog_content = "Practícalo durante unos diez minutos.",
  ui_story_5036_50360801_28_dialog_content = "Eso suena como cuando Little Furball se acurruca y se va a dormir.",
  ui_story_5036_50360801_29_dialog_content = "Inhala exhala...",
  ui_story_5036_50360801_30_dialog_content = "Nada mal. Dibújalo más tiempo.",
  ui_story_5036_50360801_31_dialog_content = "Inhaaaaale... Exhaaaaale...",
  ui_story_5036_50360801_32_dialog_content = "Muy bueno. Seguid así.",
  ui_story_5036_50360801_33_dialog_content = "Inhala exhala...",
  ui_story_5036_50360801_34_dialog_content = "Inhala exhala...",
  ui_story_5036_50360801_35_dialog_content = "¿Vic se durmió?",
  ui_story_5036_50360801_36_dialog_content = "Zzz...",
  ui_story_5036_50360801_37_dialog_content = "Vic!",
  ui_story_5036_50360801_38_dialog_content = "¡No te enojes, Fía! Qué...?",
  ui_story_5036_50360801_39_dialog_content = "Oh, es Goldie. Espera, es broma, es el Maestro Goldie.",
  ui_story_5036_50360801_40_dialog_content = "Se supone que debes practicar la respiración, no quedarte dormido.",
  ui_story_5036_50360801_41_dialog_content = "<color=#e8d9bb>Algún tiempo después</color>",
  ui_story_5036_50360801_42_dialog_content = "Una vez que aprendas a respirar, podrás trabajar tu técnica vocal.",
  ui_story_5036_50360801_43_dialog_content = "Tienes una buena voz, Vic, ¡pero recuerda esto!",
  ui_story_5036_50360801_44_dialog_content = "Cantar sin las técnicas vocales adecuadas hará un daño irreversible a tus cuerdas vocales.",
  ui_story_5036_50360801_45_dialog_content = "Pero, ¿cómo desarrollo una técnica vocal adecuada, maestro Goldie?",
  ui_story_5036_50360801_46_dialog_content = "Buena pregunta.",
  ui_story_5036_50360801_47_dialog_content = "Te enseño mi método súper especial... ¡Trinos de labios!",
  ui_story_5036_50360801_48_dialog_content = "¡Mira cuidadosamente! Presiona tus labios juntos, luego...",
  ui_story_5036_50360801_49_dialog_content = "Brrrrrrrrrrr...",
  ui_story_5036_50360801_50_dialog_content = "Brrrrrrrrrrr...",
  ui_story_5036_50360801_51_dialog_content = "Guau, eso es muy bueno. ¡Aprendes rápido!",
  ui_story_5036_50360801_52_dialog_content = "¡Esto no es difícil para mí de hacer en absoluto!",
  ui_story_5036_50360801_53_dialog_content = "A veces, hago este sonido en el campo para atraer a los rinocerontes de barro en celo.",
  ui_story_5036_50360801_54_dialog_content = "Brrrrrrrrrrr...",
  ui_story_5036_50360801_55_dialog_content = "¡En un buen día, puedo atraer a más de una docena a la vez!",
  ui_story_5036_50360801_56_dialog_content = "Yo... ya veo...",
  ui_story_5036_50360801_57_dialog_content = "Afortunadamente, estamos en el cielo ahora mismo.",
  ui_story_5036_50360801_58_dialog_content = "De todos modos, practicar esto no solo agregará profundidad a tu voz, sino que también resolverá problemas respiratorios.",
  ui_story_5036_50360801_59_dialog_content = "Tienes menos de dos días hasta la última ronda de audiciones.",
  ui_story_5036_50360801_60_dialog_content = "Si te tomas en serio la práctica, un día es más que suficiente para que entrenes la memoria muscular y mejores tu canto.",
  ui_story_5036_50360801_61_dialog_content = "¿Imitar gruñidos de rinoceronte de barro con mis labios mejorará mi canto?",
  ui_story_5036_50360801_62_dialog_content = "¡Debería ampliar eso e imitar a otras bestias maravillosas también!",
  ui_story_5036_50360801_63_dialog_content = "¡Ja, ja, ja!",
  ui_story_5036_50360801_64_dialog_content = "¿Hola?",
  ui_story_5036_50360801_65_dialog_content = "¡Uu! ¡Uu! ¡Uu! ¡Uu!",
  ui_story_5036_50360801_66_dialog_content = "¿Gruñido?",
  ui_story_5036_50360801_67_dialog_content = "¡Chirrido! ¡Chirrido, chirrido!",
  ui_story_5036_50360801_68_dialog_content = "¿Chirrido?",
  ui_story_5036_50360801_69_dialog_content = "A-Está bien, está bien.",
  ui_story_5036_50360801_70_dialog_content = "Solo los rinocerontes de barro servirán.",
  ui_story_5036_50360801_71_dialog_content = "¿En serio? Supongo que fui un poco demasiado lejos.",
  ui_story_5036_50360801_72_dialog_content = "En lo que realmente también necesitas trabajar es en tu baile.",
  ui_story_5036_50360801_73_dialog_content = "Cantar es solo una parte. El baile completará tu actuación.",
  ui_story_5036_50360801_74_dialog_content = "Todavía tenemos que coreografiar una rutina para tu canción.",
  ui_story_5036_50360801_75_dialog_content = "Antes de hacer eso, necesito ver qué tan coordinado eres.",
  ui_story_5036_50360801_76_dialog_content = "Haré algunos pasos básicos de baile. Haga su mejor esfuerzo para mantenerse al día.",
  ui_story_5036_50360801_77_dialog_content = "¿Puedes manejar la música? PlayerName?",
  ui_story_5036_50360801_78_dialog_content = "¡Sí, tocaré el acompañamiento!",
  ui_story_5036_50360801_79_dialog_content = "¡Vale, Vic, sigue el ritmo!",
  ui_story_5036_50360801_80_dialog_content = "¡A-uno, a-dos, mueve los pies!",
  ui_story_5036_50360801_81_dialog_content = "¡Una vez a la izquierda, una vez a la derecha!",
  ui_story_5036_50360801_82_dialog_content = "Uh, izquierda... derecha... ¡¿Por alguna razón de repente no puedo distinguir la izquierda de la derecha?!",
  ui_story_5036_50360801_83_dialog_content = "¡Ahora, levanta los brazos! ¡Haz círculos en el aire!",
  ui_story_5036_50360801_84_dialog_content = "¡Mano izquierda afuera, tira hacia atrás!",
  ui_story_5036_50360801_85_dialog_content = "¡Mano derecha afuera, tira hacia atrás!",
  ui_story_5036_50360801_86_dialog_content = "Pie izquierdo... Uh, ¡¿ya estás en tu mano derecha?!",
  ui_story_5036_50360801_87_dialog_content = "¡No dejes de mover los pies!",
  ui_story_5036_50360801_88_dialog_content = "No estoy viendo cosas, ¿verdad?",
  ui_story_5036_50360801_89_dialog_content = "Señorita Goldie...",
  ui_story_5036_50360801_90_dialog_content = "¡¿La ídolo más popular de Umbraton, la señorita Goldie, realmente está bailando frente a mí en este momento?!",
  ui_story_5036_50360801_91_dialog_content = "¡Ni siquiera el más acérrimo Ricitos de Oro ha llegado a disfrutar de tal beneficio!",
  ui_story_5036_50360801_X91_dialog_content = "Mantén la calma, debes mantener la calma... Ni siquiera he encontrado lo que vine a buscar todavía...",
  ui_story_5036_50360801_92_dialog_content = "¡Se ve aún más elegante al lado de Vic!",
  ui_story_5036_50360801_93_dialog_content = "¡Tengo que conseguir esto en la película!",
  ui_story_5036_50360801_94_dialog_content = "Extiende los brazos como si estuvieras alcanzando tus sueños... ¡y luego llévalos a tu pecho!",
  ui_story_5036_50360801_95_dialog_content = "¡A-uno, a-dos, mueve los pies!",
  ui_story_5036_50360801_96_dialog_content = "¡Agite la mano izquierda, agite la mano derecha!",
  ui_story_5036_50360801_97_dialog_content = "*Jadeando* ¿Ya terminó?",
  ui_story_5036_50360801_98_dialog_content = "¡Por último, levantamos ambas manos!",
  ui_story_5036_50360801_99_dialog_content = "¡Gira una vez alrededor!",
  ui_story_5036_50360801_100_dialog_content = "¡Gira... gira!",
  ui_story_5036_50360801_101_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5036_50360801_102_dialog_content = "Ay, ay... Eso dolió.",
  ui_story_5036_50360801_103_dialog_content = "¿Cuántas veces te has caído ya hoy?",
  ui_story_5036_50360801_104_dialog_content = "¡Está bien, estoy acostumbrado!",
  ui_story_5036_50360801_105_dialog_content = "Difícil de creer que eres aún más torpe que un niño pequeño que aprende a caminar.",
  ui_story_5036_50360801_106_dialog_content = "Y respiras con tanta dificultad después de unas simples maniobras... ¿No haces ejercicio con regularidad?",
  ui_story_5036_50360801_107_dialog_content = "¿El sueño cuenta como ejercicio?",
  ui_story_5036_50360801_108_dialog_content = "Esto va a ser un problema. La coordinación toma tiempo para desarrollarse.",
  ui_story_5036_50360801_109_dialog_content = "<color=#e8d9bb>Algo más de tiempo después...</color>",
  ui_story_5036_50360801_110_dialog_content = "¿Puedes recordar los pasos?",
  ui_story_5036_50360801_111_dialog_content = "¡Sí, es solo caminar mientras agitas las manos!",
  ui_story_5036_50360801_112_dialog_content = "Aunque estos son los pasos más básicos y sencillos...",
  ui_story_5036_50360801_113_dialog_content = "Todavía necesito que pongas tus sentimientos en ello.",
  ui_story_5036_50360801_114_dialog_content = "¿Bailar con sentimientos? No entiendo muy bien eso.",
  ui_story_5036_50360801_115_dialog_content = "Vic, ¿cuál crees que es el mayor activo de un ídolo?",
  ui_story_5036_50360801_116_dialog_content = "¿La capacidad de cantar y bailar?",
  ui_story_5036_50360801_117_dialog_content = "Correcto e incorrecto.",
  ui_story_5036_50360801_118_dialog_content = "Ser capaz de cantar y bailar es bastante necesario, sin duda.",
  ui_story_5036_50360801_119_dialog_content = "Pero son solo un medio para transmitir sus emociones a su audiencia.",
  ui_story_5036_50360801_120_dialog_content = "Las cosas más importantes para un ídolo son su determinación y pasión inquebrantables.",
  ui_story_5036_50360801_121_dialog_content = "Transmites esto a la audiencia a través del canto y el baile.",
  ui_story_5036_50360801_122_dialog_content = "Ah...",
  ui_story_5036_50360801_123_dialog_content = "<size=35>Quizá ya lo tenga...</size>",
  ui_story_5036_50360801_124_dialog_content = "¿Dijiste algo, Maestro?",
  ui_story_5036_50360801_125_dialog_content = "*Ejem* Primero debes impresionarte a ti mismo antes de poder mover a otros.",
  ui_story_5036_50360801_126_dialog_content = "He dicho todo lo que puedo decir. El resto depende de usted.",
  ui_story_5036_50360801_127_dialog_content = "No mostraré ningún favoritismo durante la audición.",
  ui_story_5036_50360801_128_dialog_content = "Solo te queda un día y medio.",
  ui_story_5036_50360801_129_dialog_content = "¡Otro día y medio y podré seguir buscando a los Ouroboros!",
  ui_story_5036_50360801_130_dialog_content = "*Tose* ¡Goldie!",
  ui_story_5036_50360801_131_dialog_content = "Muchas gracias por llegar hasta el final.",
  ui_story_5036_50360801_132_dialog_content = "No hay problema. Es mi trabajo ofrecer consejos a los concursantes, de todos modos.",
  ui_story_5036_50360801_133_dialog_content = "Para ser honesto, pensé que no lo ayudarías después de todos los problemas que causó.",
  ui_story_5036_50360801_134_dialog_content = "Definitivamente es un alborotador.",
  ui_story_5036_50360801_135_dialog_content = "Pero, su potencial también es innegable.",
  ui_story_5036_50360801_136_dialog_content = "Si realmente puede emprender el camino para convertirse en un ídolo, también me servirá como una especie de motivación.",
  ui_story_5036_50360801_137_dialog_content = "Oigan, ¿ustedes dos están diciendo cosas buenas sobre mí?",
  ui_story_5036_50360801_138_dialog_content = "¿Puedo escuchar?",
  ui_story_5036_50360801_139_dialog_content = "Oh, casi se me olvida lo más importante.",
  ui_story_5036_50360801_140_dialog_content = "Para los ídolos, la aptitud física es la base de todo lo que haces.",
  ui_story_5036_50360801_141_dialog_content = "Resulta que tengo el secreto de eso. ¿Quieres saber lo que es?",
  ui_story_5036_50360801_142_dialog_content = "Oye, ¿dónde conseguiste una jaula llena de eclipses?",
  ui_story_5036_50360801_143_dialog_content = "¡Los capturé, por supuesto!",
  ui_story_5036_50360801_144_dialog_content = "Grah!",
  ui_story_5036_50360801_145_dialog_content = "Su secreto no sería luchar contra Eclipsites, ¿verdad?",
  ui_story_5036_50360801_146_dialog_content = "Deja a un lado a tus maravillosos amigos.",
  ui_story_5036_50360801_147_dialog_content = "Estás solo esta vez.",
  ui_story_5036_50360801_148_dialog_content = "¿Qué?",
  ui_story_5036_50360801_149_dialog_content = "¡Graagh!",
  ui_story_5036_50360801_150_dialog_content = "¡Mantente lejos de mí!",
  ui_story_5036_50360801_151_dialog_content = "¡Sabía que podías luchar contra los Eclipsites por tu cuenta!",
  ui_story_5036_50360801_152_dialog_content = "¡Pero es demasiado agotador!",
  ui_story_5036_50360801_153_dialog_content = "¡No te detengas ahora!",
  ui_story_5036_50360801_154_dialog_content = "¡Sigue cantando y bailando mientras luchas!",
  ui_story_5036_50360801_155_dialog_content = "¡¿Qué?!",
  ui_story_5036_50360801_156_dialog_content = "¡Eres el verdadero diablo!",
  ui_story_5036_50360801_157_dialog_content = "Grahhhhhh!",
  ui_story_5036_50360802_1_dialog_content = "<color=#e8d9bb>Dos días para el concierto</color>",
  ui_story_5036_50360802_2_dialog_content = "¡Manos arriba, todos! Vamos...",
  ui_story_5036_50360802_3_dialog_content = "¡Hazlo otra vez!",
  ui_story_5036_50360802_4_dialog_content = "¿E-Es realmente el ladrón que vimos hace unos días?",
  ui_story_5036_50360802_5_dialog_content = "Puede que sea él, pero ¿quizás no?",
  ui_story_5036_50360802_6_dialog_content = "♪ ¡Ah, la primavera ha llegado aquí y todo ha vuelto a la vida! ♪",
  ui_story_5036_50360802_7_dialog_content = "♪ Los animales salen de sus madrigueras y guaridas ♪",
  ui_story_5036_50360802_8_dialog_content = "♪ En los bosques y en las praderas ♪",
  ui_story_5036_50360802_9_dialog_content = "♪ La dulzura de la vida abunda ♪",
  ui_story_5036_50360802_10_dialog_content = "No tengo ni idea de lo que está cantando...",
  ui_story_5036_50360802_11_dialog_content = "pero la melodía es de alguna manera realmente pegadiza?",
  ui_story_5036_50360802_12_dialog_content = "♪ Mira, ¿qué es eso? ♪",
  ui_story_5036_50360802_13_dialog_content = "♪ Una Bica peluda a la que le encanta decir \"¡Hai!\" ♪",
  ui_story_5036_50360802_14_dialog_content = "¡Ja, ja, ja!",
  ui_story_5036_50360802_15_dialog_content = "¡Ja, ja, ja!",
  ui_story_5036_50360802_16_dialog_content = "♪ Mira, ¿qué es eso? ♪",
  ui_story_5036_50360802_17_dialog_content = "♪ Un búho Lutumi está a la vuelta de la esquina. ¡Cuidado con los bolsillos! ♪",
  ui_story_5036_50360802_18_dialog_content = "¡Cau cau!",
  ui_story_5036_50360802_19_dialog_content = "¡¡Cau cau cau!!",
  ui_story_5036_50360802_20_dialog_content = "Goldie, ¿encontraste a alguien que se hiciera pasar por Vic?",
  ui_story_5036_50360802_21_dialog_content = "¿Qué quieres decir?",
  ui_story_5036_50360802_22_dialog_content = "Quiero decir, ¡ha mejorado a pasos agigantados en solo un día y medio!",
  ui_story_5036_50360802_23_dialog_content = "Ni siquiera reconozco a esta persona ante mis ojos.",
  ui_story_5036_50360802_24_dialog_content = "¡Es como una persona completamente diferente!",
  ui_story_5036_50360802_25_dialog_content = "Te dije que Vic tenía un gran potencial de ídolo.",
  ui_story_5036_50360802_26_dialog_content = "Era un diamante en bruto que necesitaba un poco de pulido para brillar.",
  ui_story_5036_50360802_27_dialog_content = "¡La alegría del crecimiento!",
  ui_story_5036_50360802_28_dialog_content = "¿Quién aquí entiende la alegría del crecimiento?",
  ui_story_5036_50360802_29_dialog_content = "Casi perfecto en canto, baile, apariencia, figura, EQ y IQ.",
  ui_story_5036_50360802_30_dialog_content = "¡Por fin, un concursante completo!",
  ui_story_5036_50360802_31_dialog_content = "No puedo creer que estaba hipnotizado por esa actuación...",
  ui_story_5036_50360802_32_dialog_content = "¡Perdóname, Dios de la Luz!",
  ui_story_5036_50360802_33_dialog_content = "Sí, gran mejora.",
  ui_story_5036_50360802_34_dialog_content = "♪ Brrrrrrrrr... ♪",
  ui_story_5036_50360802_35_dialog_content = "♪ Cualquiera ha visto el escurridizo huevo de Ouroboros♪",
  ui_story_5036_50360802_36_dialog_content = "♪ Brrrrrrrrrr... ♪",
  ui_story_5036_50360802_37_dialog_content = "♪ No me detendré hasta encontrarte ♪",
  ui_story_5036_50360802_38_dialog_content = "Y ese es el final. ¡Gracias a todos!",
  ui_story_5036_50360802_39_dialog_content = "Vic! Vic! Vic! Vic!",
  ui_story_5036_50360802_40_dialog_content = "Como podemos ver, ¡todo el lugar se quedó prendado de esa actuación!",
  ui_story_5036_50360802_41_dialog_content = "¡Gracias, Vic, por tan gran espectáculo!",
  ui_story_5036_50360802_42_dialog_content = "Veamos qué tienen que decir nuestros jueces.",
  ui_story_5036_50360802_43_dialog_content = "¡Señorita Goldie, es todo suyo!",
  ui_story_5036_50360802_44_dialog_content = "No tengo nada que decir.",
  ui_story_5036_50360802_45_dialog_content = "¿Qué? ¡Pero me quedé despierto para practicar durante dos noches seguidas! ¿Todavía no puedo hacerlo?",
  ui_story_5036_50360802_46_dialog_content = "Me hubiera quedado en la cama si hubiera sabido eso.",
  ui_story_5036_50360802_47_dialog_content = "Lo que quiero decir es que tu actuación fue demasiado buena para mí como para encontrar fallas.",
  ui_story_5036_50360802_48_dialog_content = "Creo que nuestros votos hablarán por sí mismos.",
  ui_story_5036_50360802_49_dialog_content = "¡Bien! Los resultados están aquí.",
  ui_story_5036_50360802_50_dialog_content = "¡Veamos si Vic puede llegar al escenario del concierto!",
  ui_story_5036_50360802_51_dialog_content = "El recibio...",
  ui_story_5036_50360802_52_dialog_content = "Recibí...?",
  ui_story_5036_50360802_53_dialog_content = "<size=45>¡Un voto unánime!</size>",
  ui_story_5036_50360802_54_dialog_content = "¿En serio? Incluso el novato lo logró. La presión está puesta para cierta persona.",
  ui_story_5036_50360802_55_dialog_content = "¿Debería cantar una canción positiva para animarla?",
  ui_story_5036_50360802_56_dialog_content = "Llévate tu monótona música pop empalagosa a otro lugar.",
  ui_story_5036_50360802_57_dialog_content = "Oh, pero estaría tan triste y solo si no lo lograras.",
  ui_story_5036_50360802_58_dialog_content = "Solo lo hiciste antes que yo porque actuaste antes que yo.",
  ui_story_5036_50360802_59_dialog_content = "Sólo espera y veras. ¡Los jueces se arrepentirán de elegirlos como payasos después de ver mi actuación!",
  ui_story_5036_50360802_60_dialog_content = "¿Cómo te sientes Vic?",
  ui_story_5036_50360802_61_dialog_content = "Por fin puedo dormir un poco...",
  ui_story_5036_50360802_62_dialog_content = "Cuando me despierto, yo...",
  ui_story_5036_50360802_63_dialog_content = "puede ir a buscar... Ourobo...",
  ui_story_5036_50360802_64_dialog_content = "Vic?",
  ui_story_5036_50360802_65_dialog_content = "¿Estás bien, Vic?",
  ui_story_5036_50360802_66_dialog_content = "Zzz...",
  ui_story_5036_50360802_67_dialog_content = "Eh, Vic...",
  ui_story_5036_50360802_68_dialog_content = "¡Por favor, no te duermas durante la audición!",
  ui_story_5036_50360802_69_dialog_content = "Vic realmente cayó en un sueño notablemente profundo, al parecer.",
  ui_story_5036_50360802_70_dialog_content = "¡No puedo creer que durmió todo el día, con todo ese ruido!",
  ui_story_5036_50360802_71_dialog_content = "Sí, ni siquiera se despertó cuando los mercenarios lo arrastraron de regreso a su habitación.",
  ui_story_5036_50360802_72_dialog_content = "Todos fuimos testigos de su mejoría.",
  ui_story_5036_50360802_73_dialog_content = "Debe haber estado exhausto por practicar tan duro durante los últimos dos días.",
  ui_story_5036_50360802_74_dialog_content = "Creo que ustedes dos también practicaron mucho.",
  ui_story_5036_50360802_75_dialog_content = "O no hubieras obtenido también un voto unánime.",
  ui_story_5036_50360802_76_dialog_content = "¡Oh, lo esperábamos totalmente!",
  ui_story_5036_50360802_77_dialog_content = "Pero sí, estoy cansado.",
  ui_story_5036_50360802_78_dialog_content = "Deberíamos acostarnos temprano hoy.",
  ui_story_5036_50360802_79_dialog_content = "Mañana habrá un día entero de ensayos.",
  ui_story_5036_50360802_80_dialog_content = "Espero no tener otro sueño esta noche.",
  ui_story_5036_50360802_81_dialog_content = "Sí. Buenas noches.",
  ui_story_5036_50360802_82_dialog_content = "¿Vicio? ¿Carleen?",
  ui_story_5036_50360802_83_dialog_content = "Se fueron tan rápido...",
  ui_story_5036_50360802_84_dialog_content = "Bien entonces...",
  ui_story_5036_50360802_85_dialog_content = "Yo también debería entregarme.",
  ui_story_5036_50360901_1_dialog_content = "Dónde estoy...?",
  ui_story_5036_50360901_2_dialog_content = "En un Coloso, creo... ¿Es esa Caelestite que estaba en mi sueño antes?",
  ui_story_5036_50360901_3_dialog_content = "¿Estoy soñando otra vez?",
  ui_story_5036_50360901_4_dialog_content = "Eres Eulogoz, ¿verdad?",
  ui_story_5036_50360901_5_dialog_content = "Sí. Eres mi nuevo navegante, ¿supongo?",
  ui_story_5036_50360901_6_dialog_content = "¡Así es! Mi nombre es Chaminade. Encantada de conocerte.",
  ui_story_5036_50360901_7_dialog_content = "(La ubicación ha cambiado... ¿Este parece ser el puente?)",
  ui_story_5036_50360901_8_dialog_content = "¿Por qué tienes tantas pantallas y sistemas de sonido extraños, Eulogoz?",
  ui_story_5036_50360901_9_dialog_content = "Le pregunté a mis amigos y nunca antes habían visto algo así en otros Colossi.",
  ui_story_5036_50360901_10_dialog_content = "Incluso yo no sé la respuesta a esa pregunta.",
  ui_story_5036_50360901_11_dialog_content = "Hace mucho tiempo los recuerdos se me escapan como cantando en el viento.",
  ui_story_5036_50360901_12_dialog_content = "Qué lástima...",
  ui_story_5036_50360901_13_dialog_content = "¡Pero todos te aman!",
  ui_story_5036_50360901_14_dialog_content = "Solo tú puedes hacer que la música resuene en Eraveil.",
  ui_story_5036_50360901_15_dialog_content = "Gracias. Estoy muy feliz de escuchar eso.",
  ui_story_5036_50360901_16_dialog_content = "¡Vámonos de viaje, Eulogoz!",
  ui_story_5036_50360901_17_dialog_content = "¿Mmm? ¿Por qué tan repentino?",
  ui_story_5036_50360901_18_dialog_content = "Mis maestros dicen que muchos en Astra todavía sufren de guerra y Eclipses.",
  ui_story_5036_50360901_19_dialog_content = "Sus vidas son desesperadas y difíciles, ¡así que quiero cantar para ellos!",
  ui_story_5036_50360901_20_dialog_content = "Sé que mi canto no puede derrotar a los Eclipsites ni proporcionarles nada útil...",
  ui_story_5036_50360901_21_dialog_content = "pero al menos, puedo darles algo para escuchar además de disparos.",
  ui_story_5036_50360901_22_dialog_content = "Lugares así son demasiado peligrosos para ti.",
  ui_story_5036_50360901_23_dialog_content = "Lo sé, pero si mi canto puede brindarles un poco de consuelo y esperanza, cualquier peligro vale la pena.",
  ui_story_5036_50360901_24_dialog_content = "Entendido.",
  ui_story_5036_50360901_25_dialog_content = "Vamos ahora.",
  ui_story_5036_50360901_26_dialog_content = "¿Otro sueño? Pero se siente diferente... más como un recuerdo.",
  ui_story_5036_50360901_27_dialog_content = "Así que el nombre de la niña Caelestite es Chaminade.",
  ui_story_5036_50360901_28_dialog_content = "A menos que ese sueño fuera yo sintiendo los rastros persistentes de su presencia en este Coloso.",
  ui_story_5036_50360901_29_dialog_content = "Una Caelestite cantante montando un Colossus, de gira por Astra... Se parece mucho a Goldie.",
  ui_story_5036_50360901_30_dialog_content = "*Bostezo* Seguro que soñé mucho por solo una hora de sueño.",
  ui_story_5036_50360901_31_dialog_content = "No podré volver a dormirme por un tiempo... tal vez debería comer algo.",
  ui_story_5036_50360901_32_dialog_content = "<color=#e8d9bb>¡Toc, toc!</color>",
  ui_story_5036_50360901_33_dialog_content = "(¿Quién llama a esta hora de la noche?)",
  ui_story_5036_50360901_34_dialog_content = "¡Ya voy!",
  ui_story_5036_50360901_35_dialog_content = "Lo siento, PlayerName, ¿Te desperte?",
  ui_story_5036_50360901_36_dialog_content = "No, estaba despierto... ¿Qué haces aquí, Goldie?",
  ui_story_5036_50360901_37_dialog_content = "Necesito tu ayuda. ¡El futuro de todo el concierto depende de ello!",
  ui_story_5036_50360901_38_dialog_content = "¿Tan serio? ¿Se está estrellando el Eulogoz?",
  ui_story_5036_50360901_39_dialog_content = "No, no es tan malo... ¿Has tenido un sueño extraño últimamente?",
  ui_story_5036_50360901_40_dialog_content = "Un sueño de un vasto valle, y el sonido de una niña cantando.",
  ui_story_5036_50360901_41_dialog_content = "Sí, yo tengo. Por alguna razón, he tenido ese sueño todas las noches.",
  ui_story_5036_50360901_42_dialog_content = "El valle es Eraveil, y la chica es Caelestita.",
  ui_story_5036_50360901_43_dialog_content = "¡¿Así que ella es una Caelestita?!",
  ui_story_5036_50360901_44_dialog_content = "¿No lo delataba la forma en que estaba vestida?",
  ui_story_5036_50360901_45_dialog_content = "El sueño es raro, pero no le he prestado mucha atención ya que no es una pesadilla.",
  ui_story_5036_50360901_46_dialog_content = "Espera, ¿no hablamos de esto antes y lo atribuimos a una coincidencia?",
  ui_story_5036_50360901_47_dialog_content = "Eso es lo que yo también pensé, pero ahora, ¡todos en el Coloso han tenido el mismo sueño!",
  ui_story_5036_50360901_48_dialog_content = "¡¿Todo el mundo?!",
  ui_story_5036_50360901_49_dialog_content = "Sí. Es una coincidencia cuando son dos o tres personas, ¡pero no cuando son todos!",
  ui_story_5036_50360901_50_dialog_content = "Ha puesto a todos ansiosos.",
  ui_story_5036_50360901_51_dialog_content = "Los concursantes han venido a mí quejándose de que el sueño les está interrumpiendo el sueño.",
  ui_story_5036_50360901_52_dialog_content = "No pueden funcionar correctamente sin un descanso adecuado.",
  ui_story_5036_50360901_53_dialog_content = "Entonces, ¿quieres llegar a la raíz del problema para garantizar un descanso adecuado para todos?",
  ui_story_5036_50360901_54_dialog_content = "Sí. Traté de investigarlo yo mismo, pero fue en vano, ya que no tengo tus habilidades psíquicas.",
  ui_story_5036_50360901_55_dialog_content = "Me puedes ayudar, PlayerName?",
  ui_story_5036_50360901_56_dialog_content = "¡Por el bien del concierto, definitivamente!",
  ui_story_5036_50360901_57_dialog_content = "¡Gracias!",
  ui_story_5036_50360901_58_dialog_content = "Pero dado el tamaño de Eulogoz, no puedo cubrir toda la estructura ni siquiera con mi telepatía.",
  ui_story_5036_50360901_59_dialog_content = "¿Por dónde deberíamos empezar?",
  ui_story_5036_50360901_60_dialog_content = "No lo sé...",
  ui_story_5036_50360901_61_dialog_content = "¡Sugiero comenzar desde la sección trasera!",
  ui_story_5036_50360901_62_dialog_content = "Vic! ¿De donde vienes?",
  ui_story_5036_50360901_63_dialog_content = "¡El concierto es en dos días! ¿No deberías estar practicando?",
  ui_story_5036_50360901_64_dialog_content = "Vamos, ¿no estabas estresado por el extraño sueño?",
  ui_story_5036_50360901_65_dialog_content = "Primero necesitas dormir bien para tener la energía para practicar.",
  ui_story_5036_50360901_66_dialog_content = "Eso es cierto, pero escuchar eso de tu boca es sospechoso.",
  ui_story_5036_50360901_67_dialog_content = "¡Jajaja! Solo estás siendo paranoico.",
  ui_story_5036_50360901_68_dialog_content = "Es sospechoso verte siendo tan proactivo.",
  ui_story_5036_50360901_69_dialog_content = "¡Ahora recuerdo! Has querido buscar el Ouroboros por allí. ¡Definitivamente tienes un motivo oculto!",
  ui_story_5036_50360901_70_dialog_content = "¿Como pudiste decir eso? Cuanto más, mejor. No tienes nada que perder dejándome acompañarte.",
  ui_story_5036_50360901_71_dialog_content = "Está bien, pero te estaré observando en la práctica de mañana, así que no intentes holgazanear.",
  ui_story_5036_50360901_72_dialog_content = "Los extrozoólogos no mienten.",
  ui_story_5036_50360901_73_dialog_content = "Pero por ahora, concentrémonos en lidiar con el extraño sueño.",
  ui_story_5036_50360901_74_dialog_content = "(Es sospechoso que Vic esté tan interesada en esto).",
  ui_story_5036_50360901_75_dialog_content = "(¿Que esta haciendo?)",
  ui_story_5036_50360901_76_dialog_content = "La sección trasera... ¿No es ahí donde están contenidos los Eclipsites?",
  ui_story_5036_50360901_77_dialog_content = "¿Hay alguna evidencia que sugiera que deberíamos comenzar con un lugar tan peligroso?",
  ui_story_5036_50360901_78_dialog_content = "¡Ninguno en absoluto!",
  ui_story_5036_50360901_79_option_content = "vamos a ignorarlo",
  ui_story_5036_50360901_80_dialog_content = "Oh vamos, PlayerName, hemos trabajado juntos antes. ¡No seas tan cruel!",
  ui_story_5036_50360901_81_option_content = "...",
  ui_story_5036_50360901_82_dialog_content = "...",
  ui_story_5036_50360901_83_dialog_content = "Los jóvenes se desconciertan fácilmente porque hay muchas cosas que no han visto.",
  ui_story_5036_50360901_84_dialog_content = "No tengo pruebas concretas, pero mi sugerencia no era infundada.",
  ui_story_5036_50360901_85_dialog_content = "Las secciones superiores están libres de eclipses, por lo que todos pueden moverse libremente.",
  ui_story_5036_50360901_86_dialog_content = "Naturalmente, eso significa que esas áreas prácticamente no necesitan ser investigadas.",
  ui_story_5036_50360901_87_dialog_content = "Verdadero. Alguien ya se habría dado cuenta de que algo andaba mal.",
  ui_story_5036_50360901_88_dialog_content = "Entonces eso deja solo la sección trasera.",
  ui_story_5036_50360901_89_dialog_content = "Pero hay muchos eclipses allí. Es demasiado arriesgado con solo nosotros tres.",
  ui_story_5036_50360901_90_dialog_content = "pensé en eso también. Solo necesitamos que Lutumi Owl nos ayude.",
  ui_story_5036_50360901_91_dialog_content = "Deja que ponga a dormir a los Eclipsites antes de que entremos a escondidas. Eso debería minimizar la necesidad de pelear.",
  ui_story_5036_50360901_92_dialog_content = "¿Es así como robaste todas esas cosas antes?",
  ui_story_5036_50360901_93_dialog_content = "¡Por supuesto que no!",
  ui_story_5036_50360901_94_dialog_content = "De todos modos, la lechuza fue la que causó todo ese malentendido.",
  ui_story_5036_50360901_95_dialog_content = "Ahora, dejaremos que compense el problema. ¿Cómo es eso?",
  ui_story_5036_50360901_96_dialog_content = "Discutamos este asunto después del concierto.",
  ui_story_5036_50360901_97_dialog_content = "Sin embargo, Vic tiene razón. Comencemos con la parte trasera del Colossus.",
  ui_story_5036_50360901_98_dialog_content = "De acuerdo, vamos.",
  ui_story_5036_50360901_99_dialog_content = "Iba a acercarme a Goldie acerca de su racha malvada rumoreada...",
  ui_story_5036_50360901_100_dialog_content = "¡pero ahora los tres están haciendo algo secreto!",
  ui_story_5036_50360901_101_dialog_content = "Por suerte, estaba demasiado lejos para PlayerName sentirme con su habilidad!",
  ui_story_5036_50360901_102_dialog_content = "Sin embargo, estaban demasiado lejos para que yo los escuchara con claridad...",
  ui_story_5036_50360901_103_dialog_content = "¿No es ahí... donde está la parte trasera?",
  ui_story_5036_50360901_104_dialog_content = "¡Están actuando demasiado sospechosos para que yo no los siga!",
  ui_story_5036_50360901_105_dialog_content = "Está tan oscuro aquí... Da la sensación de que los eclipses aparecerán en cualquier momento.",
  ui_story_5036_50360901_106_dialog_content = "Relájate y déjalo todo a Lutumi Owl. Mirar.",
  ui_story_5036_50360901_107_dialog_content = "¡Cau cau!",
  ui_story_5036_50360901_108_dialog_content = "(Eclipsian) ¿L-Lady Forsakin?",
  ui_story_5036_50360901_109_dialog_content = "¡¡Cau cau cau!!",
  ui_story_5036_50360901_110_dialog_content = "(Eclipsian) Gracias por los elogios. ¡Trabajaré más duro!",
  ui_story_5036_50360901_111_dialog_content = "(Eclipsian) No puedo creer que me hayan felicitado... Tan extraño... tan somnoliento...",
  ui_story_5036_50360901_112_dialog_content = "(Eclipsian) Bostezo...",
  ui_story_5036_50360901_113_dialog_content = "¿Ver? Pan comido.",
  ui_story_5036_50360901_114_dialog_content = "¿Estás seguro de que esto no cuenta como explotar al animal por su poder?",
  ui_story_5036_50360901_115_dialog_content = "Lutumi Owl es mi amigo. Me está ayudando de buena gana. Estoy seguro de eso.",
  ui_story_5036_50360901_116_dialog_content = "Está muy oscuro aquí...",
  ui_story_5036_50360901_117_dialog_content = "*gemido* ¡No! ¡Tengo que seguir!",
  ui_story_5036_50360901_118_dialog_content = "¿Estás bien, Goldie?",
  ui_story_5036_50360901_119_dialog_content = "¿Eh? ¡Estoy totalmente bien!",
  ui_story_5036_50360901_120_dialog_content = "¿Por qué un ídolo no estaría bien? Estoy un poco cansada y necesito un descanso.",
  ui_story_5036_50360901_121_dialog_content = "Déjame abrazarte, Marshmallow.",
  ui_story_5036_50360901_122_dialog_content = "Guau...",
  ui_story_5036_50360901_123_dialog_content = "Tan suave y borroso... Bien, ¡ya estoy listo!",
  ui_story_5036_50360901_124_dialog_content = "¡Continuemos!",
  ui_story_5036_50360901_125_dialog_content = "(Goldie está actuando de manera extraña. ¿Le tiene miedo a la oscuridad?)",
  ui_story_5036_50360901_126_dialog_content = "Llevamos tanto tiempo caminando... Ya deberíamos estar cerca de la cola del Coloso.",
  ui_story_5036_50360901_X126_dialog_content = "¿Puedes sentir algo cerca, PlayerName?",
  ui_story_5036_50360901_127_dialog_content = "Déjame ver.",
  ui_story_5036_50360901_128_option_content = "¡Potencia de fuerza!",
  ui_story_5036_50360901_129_dialog_content = "(No hay nada más que Eclipsites durmientes alrededor).",
  ui_story_5036_50360901_130_dialog_content = "(Excepto que algo se siente mal... ¿estoy siendo paranoico?)",
  ui_story_5036_50360901_131_dialog_content = "(Espera, esto se siente...)",
  ui_story_5036_50360901_132_dialog_content = "(¡Se siente muy similar a cuando sentí las emociones persistentes de Caelestites cuando regresé a Eraveil por primera vez!)",
  ui_story_5036_50360901_133_dialog_content = "(Déjame tratar de profundizar más).",
  ui_story_5036_50360901_134_dialog_content = "¡Guau! ¿Qué es esto, Eulogoz?",
  ui_story_5036_50360901_135_dialog_content = "No entres en pánico, Chaminade, no es un Eclipsite.",
  ui_story_5036_50360901_136_dialog_content = "Según mis datos, es un animal llamado Ouroboros. Es muy amigable con los Aurorianos y Caelestites.",
  ui_story_5036_50360901_137_dialog_content = "Gracias a Dios que no es un Eclipsite.",
  ui_story_5036_50360901_138_dialog_content = "¡Kree, kree!",
  ui_story_5036_50360901_139_dialog_content = "Hee, ¡deja de lamerme la cara!",
  ui_story_5036_50360901_140_dialog_content = "¿Puedes sentir algo, PlayerName?",
  ui_story_5036_50360901_141_dialog_content = "Su nombre es Chaminade después de todo...",
  ui_story_5036_50360901_142_dialog_content = "Chaminade? ¿Estás hablando de esa chica Caelestite?",
  ui_story_5036_50360901_143_dialog_content = "Sí. Sentí rastros persistentes de ella, y...",
  ui_story_5036_50360901_144_dialog_content = "los Ouroboros también!",
  ui_story_5036_50360901_145_dialog_content = "¡¿Qué?!",
  ui_story_5036_50360901_146_dialog_content = "¿Sentiste el Ouroboros? ¡Rápido, cuéntame más!",
  ui_story_5036_50360901_147_dialog_content = "¡Deja de sacudirme y suéltame antes de que vomite!",
  ui_story_5036_50360901_148_dialog_content = "Habla primero, luego te dejo ir.",
  ui_story_5036_50360901_149_dialog_content = "¡Lo que sentí no fue un Ouroboros del presente sino uno del pasado!",
  ui_story_5036_50360901_150_dialog_content = "¿El pasado?",
  ui_story_5036_50360901_151_dialog_content = "La antigua propietaria de este Colossus y la chica Caelestite con la que todos habían estado soñando, su nombre era Chaminade.",
  ui_story_5036_50360901_152_dialog_content = "Érase una vez, conoció a un Ouroboros y lo dejó a bordo.",
  ui_story_5036_50360901_153_dialog_content = "Pero supongo que eso sucedió hace al menos cien años.",
  ui_story_5036_50360901_154_dialog_content = "El Ouroboros que estás buscando probablemente ya se haya ido.",
  ui_story_5036_50360901_155_dialog_content = "Oh...",
  ui_story_5036_50360901_156_dialog_content = "Dime, ¿qué tal si me dejas ir?",
  ui_story_5036_50360901_157_dialog_content = "Bueno, no obtuviste una ubicación, pero sigue siendo información valiosa.",
  ui_story_5036_50360901_158_dialog_content = "¡Ayúdame, joven Caelestite, sigue usando esos sentidos tuyos!",
  ui_story_5036_50360901_159_dialog_content = "¡Considera esto pagarme por todo el peligro que mi querida alumna Fia sufrió por ti!",
  ui_story_5036_50360901_160_dialog_content = "¿Pagándote a TI?",
  ui_story_5036_50360901_161_dialog_content = "¡Deténgase! ¿No se supone que deberíamos estar resolviendo el problema de los sueños ahora mismo?",
  ui_story_5036_50360901_162_dialog_content = "¿Cuándo se convirtió nuestro objetivo en encontrar los Ouroboros?",
  ui_story_5036_50360901_163_dialog_content = "¡Oh, sí, casi me desvío!",
  ui_story_5036_50360901_164_dialog_content = "Jóvenes, están viendo esto de manera equivocada.",
  ui_story_5036_50360901_165_dialog_content = "¿No dijiste que Caelestite con Ouroboros era la chica de nuestros sueños?",
  ui_story_5036_50360901_166_dialog_content = "Sí... Y deberíamos centrar nuestra investigación en torno a ella, independientemente.",
  ui_story_5036_50360901_167_dialog_content = "Bueno, solo te pido que estés atento a las pistas sobre los Ouroboros mientras tanto.",
  ui_story_5036_50360901_168_dialog_content = "¿Por qué siento que te estoy dando mano de obra gratis?",
  ui_story_5036_50360901_169_dialog_content = "No es mano de obra gratis. Mostrar respeto por tus mayores es una buena virtud.",
  ui_story_5036_50360901_170_dialog_content = "Realmente piensas en cualquier cosa, ¿verdad?",
  ui_story_5036_50360901_171_dialog_content = "Por que gracias.",
  ui_story_5036_50360901_172_dialog_content = "Nosotros necesitamos PlayerName para investigar el sueño.",
  ui_story_5036_50360901_173_dialog_content = "¿Te importaría volver a sentir en otro lugar para ver si puedes encontrar más rastros persistentes?",
  ui_story_5036_50360901_174_dialog_content = "Tal vez podamos clasificarlos y descubrir la fuente de los sueños.",
  ui_story_5036_50360901_175_dialog_content = "¡Claro, le daré una oportunidad!",
  ui_story_5036_50360901_176_dialog_content = "Nunca he estado aquí antes.",
  ui_story_5036_50360901_177_dialog_content = "Estamos más cerca de la sección trasera que antes, por lo que deberíamos poder encontrar algo nuevo.",
  ui_story_5036_50360901_178_dialog_content = "Goldie, Vic, ¿ustedes sienten algo mal acerca de este lugar?",
  ui_story_5036_50360901_179_dialog_content = "Hace un poco de frío. ¿Quizás por Darkflow?",
  ui_story_5036_50360901_180_dialog_content = "No, no estoy sintiendo demasiado Darkflow. Me siento ansioso por alguna razón.",
  ui_story_5036_50360901_181_dialog_content = "No le tienes miedo a la oscuridad, ¿verdad?",
  ui_story_5036_50360901_182_dialog_content = "¡Por supuesto que no!",
  ui_story_5036_50360901_183_dialog_content = "No es nada de qué avergonzarse.",
  ui_story_5036_50360901_184_dialog_content = "Shira le tenía miedo a la oscuridad cuando era joven. ¡El viento la asustaría hasta las lágrimas por la noche!",
  ui_story_5036_50360901_185_dialog_content = "Además de cazar pájaros, un Drakolion también puede... ¡Achoo!",
  ui_story_5036_50360901_186_dialog_content = "... También puede estornudar?",
  ui_story_5036_50360901_187_dialog_content = "No, no... ¡Achu!",
  ui_story_5036_50360901_188_dialog_content = "Solo necesitaba estornudar de repente.",
  ui_story_5036_50360901_189_dialog_content = "¿Te resfriaste?",
  ui_story_5036_50360901_190_dialog_content = "No. Supongo que Vic me está hablando basura en alguna parte.",
  ui_story_5036_50360901_191_dialog_content = "Voy a interrogarlo sobre eso cuando regrese.",
  ui_story_5036_50360901_192_dialog_content = "¿Estás mintiendo otra vez?",
  ui_story_5036_50360901_193_dialog_content = "De ninguna manera. Pregúntale a Shira si no lo crees.",
  ui_story_5036_50360901_194_dialog_content = "No importa, tengo mejores cosas que hacer.",
  ui_story_5036_50360901_X194_dialog_content = "Parece que todavía hay algunas emociones persistentes por aquí. Trataré de sentirlos.",
  ui_story_5036_50360901_195_option_content = "Enlace mental!",
  ui_story_5036_50360901_196_dialog_content = "♪ Gotas de rocío, capturando el amanecer dorado ♪",
  ui_story_5036_50360901_197_dialog_content = "♪ Brilla muy tímidamente ♪",
  ui_story_5036_50360901_198_dialog_content = "(¡Es la melodía para iniciar el Coloso!)",
  ui_story_5036_50360901_199_dialog_content = "¡Kree, kree... kree!",
  ui_story_5036_50360901_200_dialog_content = "¿Uróboros? ¿No estabas durmiendo? ¿Qué estás haciendo aquí?",
  ui_story_5036_50360901_201_dialog_content = "Kree—♪ Kree—♪",
  ui_story_5036_50360901_202_dialog_content = "¡¿Estas cantando?! ¡¿La canción que estaba cantando?!",
  ui_story_5036_50360901_203_dialog_content = "¿Entiendes mi música?",
  ui_story_5036_50360901_204_dialog_content = "Kree— ♪ Kree, kree, kree ♪",
  ui_story_5036_50360901_205_dialog_content = "¿Es eso una afirmación?",
  ui_story_5036_50360901_206_dialog_content = "Qué asombroso, la criatura podía comunicarse usando la melodía que Caelestites usa para controlar a los Colosos.",
  ui_story_5036_50360901_207_dialog_content = "Siento algo más...",
  ui_story_5036_50360901_208_dialog_content = "Estos recuerdos solo me llegan en partes y fragmentos.",
  ui_story_5036_50360901_209_dialog_content = "¿Qué es? ¡Dime!",
  ui_story_5036_50360901_210_dialog_content = "¿Mencionan algo sobre los sueños extraños?",
  ui_story_5036_50360901_211_dialog_content = "No.",
  ui_story_5036_50360901_212_dialog_content = "Siento la grata sorpresa de Chaminade al descubrir por casualidad el secreto de los Ouroboros.",
  ui_story_5036_50360901_213_dialog_content = "Estas criaturas parecen ser capaces de transmitir emociones y comunicarse con las personas usando las melodías para controlar a los Colosos.",
  ui_story_5036_50360901_214_dialog_content = "¡Esa es información completamente nueva relacionada con los Ouroboros!",
  ui_story_5036_50360901_215_dialog_content = "¡Excelente! Aunque no tengo nada con lo que recompensarte.",
  ui_story_5036_50360901_216_dialog_content = "...",
  ui_story_5036_50360901_217_dialog_content = "Sabes, los libros antiguos mencionan una conexión misteriosa entre esta especie y los Colosos.",
  ui_story_5036_50360901_218_dialog_content = "No podemos descartar la posibilidad de que tal vez también poseían ciertas habilidades psíquicas.",
  ui_story_5036_50360901_219_dialog_content = "Por ejemplo... hacer soñar a la gente.",
  ui_story_5036_50360901_220_dialog_content = "¿Crees que sí?",
  ui_story_5036_50360901_221_dialog_content = "¡Realmente voy a castigarte esta vez si estás mintiendo!",
  ui_story_5036_50360901_222_dialog_content = "¡No me atrevería!",
  ui_story_5036_50360901_223_dialog_content = "Es solo una teoría. No puedo garantizar que tenga razón.",
  ui_story_5036_50360901_224_dialog_content = "Que dudoso...",
  ui_story_5036_50360901_225_dialog_content = "¿Qué opinas, nombre del jugador?",
  ui_story_5036_50360901_226_option_content = "Cree Vic",
  ui_story_5036_50360901_227_dialog_content = "Si bien Vic suele mentir mucho y no es muy confiable...",
  ui_story_5036_50360901_228_dialog_content = "él realmente es una autoridad absoluta en todo lo relacionado con las bestias maravillosas.",
  ui_story_5036_50360901_229_dialog_content = "No debería ser un problema confiar en él en esa área.",
  ui_story_5036_50360901_230_dialog_content = "De hecho, siempre debes escuchar a tus mayores.",
  ui_story_5036_50360901_231_dialog_content = "Está bien, confío en el juicio de PlayerName.",
  ui_story_5036_50360901_232_option_content = "no creas vic",
  ui_story_5036_50360901_233_dialog_content = "Mi consejo es que no le hagáis caso, porque casi nunca dice la verdad.",
  ui_story_5036_50360901_234_dialog_content = "Oh, mi pobre viejo corazón... *Sollozo*",
  ui_story_5036_50360901_235_dialog_content = "Solo así, ¿ves? Llora que es un anciano un segundo, luego te dice que tiene 18 años para siempre al siguiente.",
  ui_story_5036_50360901_236_dialog_content = "Ustedes, mequetrefes, no lo entienden. Se llama ser joven de corazón.",
  ui_story_5036_50360901_237_dialog_content = "Definitivamente no es de fiar.",
  ui_story_5036_50360901_238_dialog_content = "¡Suspiro!",
  ui_story_5036_50360901_239_dialog_content = "Sin embargo, no tenemos más remedio que seguir esta única pista que tenemos.",
  ui_story_5036_50360901_240_dialog_content = "¿Así que solo podemos seguir adelante? Suspiro, pero aun así, supongo que no podemos rendirnos tan fácilmente.",
  ui_story_5036_50360901_241_dialog_content = "Vamos a ver qué más podemos encontrar.",
  ui_story_5036_50360901_242_dialog_content = "Siguen parando, ¿qué están haciendo?",
  ui_story_5036_50360901_243_dialog_content = "Ahora que me doy cuenta, esta es el área de bloqueo, ¿no? Tan oscuro y aterrador...",
  ui_story_5036_50360901_244_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_5036_50360901_245_dialog_content = "¿Eh? ¿E-Ese fue el viento? Probablemente debería regresar y preguntarle a Goldie otro día...",
  ui_story_5036_50360901_246_dialog_content = "No, Brandy, eres un reportero que busca la verdad. ¡No puedes renunciar ahora!",
  ui_story_5036_50360901_247_dialog_content = "¡Tengo que estar al día con ellos!",
  ui_story_5036_50360901_248_dialog_content = "¿Cuánto tiempo hemos estado caminando? ¿Veinte minutos?",
  ui_story_5036_50360901_249_dialog_content = "Los pasillos aquí son laberínticos. Solo estamos dando vueltas y vueltas.",
  ui_story_5036_50360901_250_dialog_content = "¿No deberías liderar, PlayerName, ya que has vivido en un Coloso durante tanto tiempo?",
  ui_story_5036_50360901_251_dialog_content = "Solo conozco a Soroz, no a este de aquí.",
  ui_story_5036_50360901_252_dialog_content = "Verdadero. ¿Qué tal probar tus habilidades psíquicas?",
  ui_story_5036_50360901_253_dialog_content = "Si los rastros de esa Caelestite todavía están por ahí, eso podría guiarnos.",
  ui_story_5036_50360901_254_dialog_content = "Esa es una idea. Déjame intentarlo.",
  ui_story_5036_50360901_255_option_content = "Enlace mental!",
  ui_story_5036_50360901_256_dialog_content = "¡Oh no, Eulogoz!",
  ui_story_5036_50360901_257_dialog_content = "¡Mira lo que pasó con los Ouroboros!",
  ui_story_5036_50360901_258_dialog_content = "*Sollozo* ¿Qué le pasó? ¿Se ha ido para siempre?",
  ui_story_5036_50360901_259_dialog_content = "Sin él, no hubiéramos podido evadir todos esos ataques de Eclipsite...",
  ui_story_5036_50360901_260_dialog_content = "No entres en pánico, Chaminade.",
  ui_story_5036_50360901_261_dialog_content = "Los Ouroboros son criaturas de longevidad. Se convierten en huevos cuando envejecen, se vuelven a incubar y luego renacen.",
  ui_story_5036_50360901_262_dialog_content = "Confía en ti para protegerlo cuando está en su momento más débil. Es por eso que eligió convertirse en un huevo aquí.",
  ui_story_5036_50360901_263_dialog_content = "Solo espera un momento y podrá viajar contigo nuevamente.",
  ui_story_5036_50360901_264_dialog_content = "¿En serio?",
  ui_story_5036_50360901_265_dialog_content = "¡Esto es genial! Entonces los Ouroboros no murieron, y todavía podemos estar juntos.",
  ui_story_5036_50360901_266_dialog_content = "lo protegeré. ¿Qué tal esto? ¡Pongamos el huevo en la habitación más segura!",
  ui_story_5036_50360901_267_dialog_content = "¡Ningún eclipse puede acercarse entonces!",
  ui_story_5036_50360901_268_dialog_content = "¡Yo lo veo! ¡Excepcionalmente claro esta vez!",
  ui_story_5036_50360901_269_dialog_content = "Chaminade dijo que puso el huevo en la habitación más fortificada del Coloso.",
  ui_story_5036_50360901_X269_dialog_content = "Ella corrió en esa dirección.",
  ui_story_5036_50360901_270_dialog_content = "¡Vamos! Podríamos encontrar algo nuevo.",
  ui_story_5036_50360901_271_dialog_content = "Sin embargo, han pasado años. Cualquier pista ya se habría enfriado.",
  ui_story_5036_50360901_272_dialog_content = "No importa, solo vámonos.",
  ui_story_5036_50361001_1_dialog_content = "Hemos estado caminando por un tiempo. ¿Cómo es que no hemos llegado a esa habitación todavía?",
  ui_story_5036_50361001_2_dialog_content = "Eulogoz es enorme, pero ya deberíamos estar allí.",
  ui_story_5036_50361001_3_dialog_content = "¿A menos que hayamos estado dando vueltas en círculos todo este tiempo?",
  ui_story_5036_50361001_4_dialog_content = "Ni idea, pero esto se está volviendo cada vez más insoportable.",
  ui_story_5036_50361001_5_dialog_content = "Este lugar es espeluznante y me pone la piel de gallina.",
  ui_story_5036_50361001_6_dialog_content = "A menudo me pierdo y doy vueltas en la naturaleza.",
  ui_story_5036_50361001_7_dialog_content = "¡Lo que hay que hacer es dejar un rastro!",
  ui_story_5036_50361001_8_dialog_content = "Buena idea. ¿Alguien tiene algo para escribir?",
  ui_story_5036_50361001_9_dialog_content = "¡No!",
  ui_story_5036_50361001_10_dialog_content = "Yo tampoco, pero traje esto.",
  ui_story_5036_50361001_11_dialog_content = "¿Carteles para el concierto? ¿Trajiste esto contigo?",
  ui_story_5036_50361001_12_dialog_content = "Muchos fans se acercan y piden autógrafos, pero no siempre tienen algo en la mano para que les firme.",
  ui_story_5036_50361001_13_dialog_content = "Traigo carteles para firmar por ellos para que no se decepcionen.",
  ui_story_5036_50361001_14_dialog_content = "¡Muy considerado de tu parte!",
  ui_story_5036_50361001_15_dialog_content = "¡Ser considerado con los fans es uno de los trabajos más básicos de un ídolo!",
  ui_story_5036_50361001_16_dialog_content = "carteles, ¿eh? Definitivamente un rastreador muy notable.",
  ui_story_5036_50361001_17_dialog_content = "De todos modos, pondré uno aquí. ¡Vamonos!",
  ui_story_5036_50361001_18_dialog_content = "<color=#e8d9bb>Algún tiempo después</color>",
  ui_story_5036_50361001_19_dialog_content = "Ha pasado un tiempo, pero nada a nuestro alrededor parece haber cambiado.",
  ui_story_5036_50361001_20_dialog_content = "Oye, ¿no es ese el cartel que puso Goldie?",
  ui_story_5036_50361001_21_dialog_content = "¡Está! ¡Realmente estamos dando vueltas en círculos!",
  ui_story_5036_50361001_22_dialog_content = "Espera, algo anda mal con este cartel...",
  ui_story_5036_50361001_23_dialog_content = "¿Cómo es que el cabello de Goldie es oscuro en este póster? Y su expresión no parece natural...",
  ui_story_5036_50361001_24_dialog_content = "¿Cómo pudo pasar esto? ¿Alguien está haciendo una broma?",
  ui_story_5036_50361001_25_dialog_content = "Esta es un área inexplorada en la sección trasera. Nadie más debería estar aquí aparte de nosotros tres.",
  ui_story_5036_50361001_26_dialog_content = "No me digas...",
  ui_story_5036_50361001_27_option_content = "¡¿Nos están siguiendo?!",
  ui_story_5036_50361001_28_dialog_content = "¿Un fan demasiado entusiasta, tal vez? ¿O un sinvergüenza empeñado en sabotear el concierto?",
  ui_story_5036_50361001_29_dialog_content = "De todos modos, esto es bastante espeluznante...",
  ui_story_5036_50361001_30_dialog_content = "Deberíamos salir de aquí.",
  ui_story_5036_50361001_31_option_content = "¿Eclipsitos?",
  ui_story_5036_50361001_32_dialog_content = "¿Pero no los puso a dormir Lutumi Owl?",
  ui_story_5036_50361001_33_dialog_content = "Todavía deberían estar fuera.",
  ui_story_5036_50361001_34_dialog_content = "Este lugar simplemente no se siente bien. Démonos prisa y salgamos de aquí.",
  ui_story_5036_50361001_35_dialog_content = "¿Pero de qué manera?",
  ui_story_5036_50361001_36_dialog_content = "¡Solo elige una dirección y sigue recto!",
  ui_story_5036_50361001_37_dialog_content = "¡Vamos por este camino!",
  ui_story_5036_50361001_38_dialog_content = "¡Oye, baja la velocidad para este viejo!",
  ui_story_5036_50361001_39_dialog_content = "¡Desacelerar!",
  ui_story_5036_50361001_40_dialog_content = "S-Algo es raro en este cartel.",
  ui_story_5036_50361001_41_dialog_content = "¡Oye, espérame!",
  ui_story_5036_50361001_42_dialog_content = "*Jadeando* Hmm, esto es diferente de los pasillos en los que estábamos.",
  ui_story_5036_50361001_43_dialog_content = "¿Será esta la habitación de la que habló Chaminade?",
  ui_story_5036_50361001_44_dialog_content = "Parece muy sólido, aunque el muro todavía está hecho jirones por años de abandono.",
  ui_story_5036_50361001_45_dialog_content = "También se siente aún más espeluznante aquí. Realmente no quiero quedarme...",
  ui_story_5036_50361001_46_dialog_content = "Sigo sintiendo que los eclipses van a aparecer en cualquier momento.",
  ui_story_5036_50361001_47_dialog_content = "*Sonidos de crujidos*",
  ui_story_5036_50361001_48_dialog_content = "¡¿Quién está ahí?!",
  ui_story_5036_50361001_49_dialog_content = "¡Muéstrate!",
  ui_story_5036_50361001_50_dialog_content = "¡Soy yo! ¡No me golpees!",
  ui_story_5036_50361001_51_dialog_content = "¡No estoy hablando de ti!",
  ui_story_5036_50361001_52_dialog_content = "¿Ah?",
  ui_story_5036_50361001_53_dialog_content = "¿Brandy? ¿Qué estás haciendo aquí? ¡Espera, cuidado!",
  ui_story_5036_50361001_54_dialog_content = "Graaaaah!",
  ui_story_5036_50361001_55_dialog_content = "¡Pato!",
  ui_story_5036_50361001_56_dialog_content = "¡¿Goldie?!",
  ui_story_5036_50361001_57_dialog_content = "(¡Goldie acaba de salvarme la vida!)",
  ui_story_5036_50361001_58_dialog_content = "¡No dejaré que dañes a nadie en mi presencia!",
  ui_story_5036_50361001_59_dialog_content = "¡Prepárate para lo que viene para ti!",
  ui_story_5036_50361001_60_dialog_content = "¡Wau!",
  ui_story_5036_50361002_1_dialog_content = "¡Vaya, eso estuvo cerca!",
  ui_story_5036_50361002_2_dialog_content = "Ahora está bien. Maté al último Eclipsite.",
  ui_story_5036_50361002_3_dialog_content = "¿Estás bien? No estás herido, ¿verdad?",
  ui_story_5036_50361002_4_dialog_content = "Estoy bien aparte de que mis piernas se sienten como gelatina...",
  ui_story_5036_50361002_5_dialog_content = "Con razón sentí que alguien estaba mirando todo este tiempo... Nos has estado siguiendo.",
  ui_story_5036_50361002_6_dialog_content = "¿Qué estás haciendo acá?",
  ui_story_5036_50361002_7_dialog_content = "¿No sabes que acechar es ilegal, Brandy? ¡Te castigan por eso!",
  ui_story_5036_50361002_8_dialog_content = "¡Yo... yo no estaba acechando!",
  ui_story_5036_50361002_9_dialog_content = "¡Estoy aquí para descubrir la verdad!",
  ui_story_5036_50361002_10_dialog_content = "¿La verdad? ¿También estás investigando los sueños extraños?",
  ui_story_5036_50361002_11_dialog_content = "No, eso no. Era algo más. Quería investigar en secreto, pero ahora que lo sabes, solo te preguntaré directamente.",
  ui_story_5036_50361002_12_dialog_content = "Goldie, ¿recuerdas al dueño de Star Theatre?",
  ui_story_5036_50361002_13_dialog_content = "Déjame pensar... Eso me suena.",
  ui_story_5036_50361002_14_dialog_content = "¿Goldie también lo golpeó?",
  ui_story_5036_50361002_15_dialog_content = "Deja de interrumpir, Vic.",
  ui_story_5036_50361002_16_dialog_content = "Trabajamos juntos brevemente, pero las cosas terminaron con una nota amarga.",
  ui_story_5036_50361002_17_dialog_content = "¿Entonces te fuiste en malos términos? ¿Por qué no buscó otro lugar en lugar de tomarse la molestia de abordar el Coloso Errante solo para dar un concierto?",
  ui_story_5036_50361002_18_dialog_content = "Desde entonces, otros propietarios de teatros han rechazado mis ofertas para alquilar sus locales.",
  ui_story_5036_50361002_19_dialog_content = "¿Sabes por qué?",
  ui_story_5036_50361002_20_dialog_content = "Es una larga historia.",
  ui_story_5036_50361002_21_dialog_content = "El dueño de ese cine una vez envió un aviso al editor de The Daily Scoop, alegando que lo agrediste.",
  ui_story_5036_50361002_X21_dialog_content = "¿Qué significa eso? ¿Eres propenso a los arrebatos violentos?",
  ui_story_5036_50361002_22_dialog_content = "Incluso le mostró al editor las heridas en su rostro. Tenía la cara y la nariz tan hinchadas y magulladas... Parecía realmente doloroso.",
  ui_story_5036_50361002_23_dialog_content = "¡No lo lastimé en lo más mínimo! ¡Por el contrario, él era el que lastimaba a los niños inocentes!",
  ui_story_5036_50361002_24_dialog_content = "Todavía no quiero creer que lo hiciste, pero... Soy reportero, así que debo confiar en la evidencia.",
  ui_story_5036_50361002_25_dialog_content = "¿Tiene algo que demuestre su inocencia o que demuestre alguna irregularidad de su parte?",
  ui_story_5036_50361002_26_dialog_content = "¡Yo estoy diciendo la verdad! Aquí, la historia completa debería aclarar las cosas.",
  ui_story_5036_50361002_27_dialog_content = "Todo empezó hace unos diez días. En ese momento, estaba buscando un lugar para celebrar mi próximo concierto.",
  ui_story_5036_50361002_28_dialog_content = "Después de pensarlo mucho, decidí que Star Theatre era la mejor opción, así que me acerqué al propietario al respecto.",
  ui_story_5036_50361002_29_dialog_content = "Programé un ensayo antes de mi show para acostumbrarme al lugar.",
  ui_story_5036_50361002_30_dialog_content = "♪ La—la la la ♪",
  ui_story_5036_50361002_31_dialog_content = "<color=#e8d9bb>Bofetada-!</color>",
  ui_story_5036_50361002_32_dialog_content = "¡Ahhhhh!",
  ui_story_5036_50361002_33_dialog_content = "¡Ayuda!",
  ui_story_5036_50361002_34_dialog_content = "¿Eh? ¿Qué fue eso de ahora?",
  ui_story_5036_50361002_35_dialog_content = "¿Parece que ustedes los punks pertenecen aquí, eh? ¡Largarse! ¡Supérenlo, todos ustedes!",
  ui_story_5036_50361002_36_dialog_content = "¡Malditas ratas sucias, no entren en mi teatro!",
  ui_story_5036_50361002_37_dialog_content = "¡Ah!",
  ui_story_5036_50361002_38_dialog_content = "¡No le pegues a mi hermano!",
  ui_story_5036_50361002_39_dialog_content = "¿Qué está pasando acá?",
  ui_story_5036_50361002_40_dialog_content = "Bueno, ¡si no es la propia Goldie! No hay nada que ver aquí, no hay motivo para su preocupación.",
  ui_story_5036_50361002_41_dialog_content = "Eran solo un par de mocosos sin un centavo tratando de ver un espectáculo gratis. Los tiraré en un segundo.",
  ui_story_5036_50361002_42_dialog_content = "Esto no es un concierto oficial, es solo un ensayo. ¿Qué tiene de malo que vengamos aquí a escuchar cantar a Goldie?",
  ui_story_5036_50361002_43_dialog_content = "Escuchar no es gratis, punk. Paga o piérdete.",
  ui_story_5036_50361002_44_dialog_content = "Pero si todavía te sientes engreído, ¡déjame volver a ponerte en tu lugar!",
  ui_story_5036_50361002_45_dialog_content = "¡Agh!",
  ui_story_5036_50361002_X45_dialog_content = "¡Ayuda!",
  ui_story_5036_50361002_46_dialog_content = "¡Alto!",
  ui_story_5036_50361002_47_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5036_50361002_48_dialog_content = "¡Puaj! *tos*",
  ui_story_5036_50361002_49_dialog_content = "¿Cómo te atreves a tocarme? ¿No sabes quién soy? ¡Soy dueño del Star Theatre!",
  ui_story_5036_50361002_50_dialog_content = "¡No me importa si eres el dueño! ¡No dejaré que lastimes a un par de niños inocentes!",
  ui_story_5036_50361002_51_dialog_content = "¿Te das cuenta de lo que estás haciendo?",
  ui_story_5036_50361002_52_dialog_content = "*Tose*",
  ui_story_5036_50361002_53_dialog_content = "Desafortunadamente, ya no la dejaré actuar en mi teatro, señorita Goldie.",
  ui_story_5036_50361002_54_dialog_content = "... Qué vergüenza.",
  ui_story_5036_50361002_55_dialog_content = "¿Así que saltaste para defender a esos niños y accidentalmente lo tiraste al suelo?",
  ui_story_5036_50361002_56_dialog_content = "¡Eso es totalmente diferente de lo que todo el mundo está diciendo!",
  ui_story_5036_50361002_57_dialog_content = "¡Todos esos son solo rumores sin fundamento!",
  ui_story_5036_50361002_58_dialog_content = "¡Y otra cosa! Cuando cayó al suelo, aterrizó sobre su trasero, ¡no sobre su cara!",
  ui_story_5036_50361002_59_dialog_content = "¡Si no me crees, pregúntale a esos dos niños! Te contarán todo lo que pasó ese día.",
  ui_story_5036_50361002_60_dialog_content = "(Goldie siempre ha sido una persona buena y justa. No creo que actúe violentamente sin una buena razón).",
  ui_story_5036_50361002_61_dialog_content = "¿Por qué no les dijiste a todos todo esto en primer lugar?",
  ui_story_5036_50361002_62_dialog_content = "Soy un ídolo, no puedo darme el lujo de exponer mis vulnerabilidades.",
  ui_story_5036_50361002_63_dialog_content = "Para arruinar mi reputación, varios dueños de teatros se han confabulado entre sí para evitar que alquile un lugar para mi concierto.",
  ui_story_5036_50361002_64_dialog_content = "Saben que les prometí a mis fans un concierto aquí en Umbraton y están tratando de hacerme faltar a mi palabra.",
  ui_story_5036_50361002_65_dialog_content = "Mis fans estarán muy decepcionados si no soy capaz de cumplir la promesa que les hice...",
  ui_story_5036_50361002_X65_dialog_content = "¡También podría despedirme de mi carrera como ídolo si hago eso!",
  ui_story_5036_50361002_X66_dialog_content = "Por eso, pase lo que pase, tengo que celebrar ese concierto según lo programado.",
  ui_story_5036_50361002_X67_dialog_content = "¡Tengo que demostrarles a mis fans que nunca traicionaría todo el amor y el apoyo que me han dado!",
  ui_story_5036_50361002_66_dialog_content = "¡¿Cómo pudieron esas personas hacerte eso?!",
  ui_story_5036_50361002_67_dialog_content = "Lo único que puedo hacer ahora es realizar un concierto único para que todos puedan experimentar mi verdadero yo por sí mismos.",
  ui_story_5036_50361002_68_dialog_content = "A medida que me vuelva más popular, ¡más y más personas estarán dispuestas a escucharme y creerme!",
  ui_story_5036_50361002_69_dialog_content = "Entonces, cuando ocurrió ese incidente, elegí pasar desapercibido y guardarme las cosas para mí. No quería que nadie me viera en una posición vulnerable.",
  ui_story_5036_50361002_70_dialog_content = "(Así que eso es lo que Goldie estuvo pensando todo el tiempo...)",
  ui_story_5036_50361002_71_dialog_content = "(La mirada en sus ojos me dice que no está mintiendo. Además, incluso me salvó de los eclipses).",
  ui_story_5036_50361002_72_dialog_content = "Uf... casi creí los rumores y te tomé por una especie de mala persona...",
  ui_story_5036_50361002_73_dialog_content = "Aclararé este asunto con los dos niños más tarde.",
  ui_story_5036_50361002_X73_dialog_content = "Si dices la verdad, escribiré un artículo al respecto de inmediato. Limpiaremos tu buen nombre y nos desharemos de todos los rumores.",
  ui_story_5036_50361002_74_dialog_content = "¡No podría pedir nada más!",
  ui_story_5036_50361002_75_dialog_content = "Dejemos la pelusa sentimental para después de que terminemos aquí. Todavía tenemos otros asuntos que atender.",
  ui_story_5036_50361002_76_dialog_content = "¡Así es! ¿Adónde vamos a seguir? PlayerName?",
  ui_story_5036_50361002_77_dialog_content = "Puedo sentir que nos estamos acercando al lugar donde Chaminade escondió el huevo.",
  ui_story_5036_50361002_78_dialog_content = "Déjame intentarlo una vez más.",
  ui_story_5036_50361002_79_option_content = "¡Enlace mental!",
  ui_story_5036_50361002_80_dialog_content = "Graah-!",
  ui_story_5036_50361002_81_dialog_content = "<color=#e8d9bb>Ruido sordo-!</color>",
  ui_story_5036_50361002_82_dialog_content = "¡Ah—!",
  ui_story_5036_50361002_83_dialog_content = "Están intentando entrar... ¿Qué debo hacer?",
  ui_story_5036_50361002_84_dialog_content = "¿Incluso la habitación más fuerte del Coloso no puede contener a todos estos eclipses?",
  ui_story_5036_50361002_85_dialog_content = "Eulogoz? Eulogoz!",
  ui_story_5036_50361002_86_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361002_87_dialog_content = "No... ¿Eulogoz ya podría ser...?",
  ui_story_5036_50361002_88_dialog_content = "¡No! ¡No puedo rendirme! ¡Todavía tengo que proteger a los Ouroboros!",
  ui_story_5036_50361002_89_dialog_content = "¡Necesito esconderlo en algún lugar seguro primero!",
  ui_story_5036_50361002_90_dialog_content = "Nadie debería poder encontrarlo dentro de este compartimento secreto de pared.",
  ui_story_5036_50361002_91_dialog_content = "Quédate aquí y no muevas ni un músculo, ¿de acuerdo?",
  ui_story_5036_50361002_92_dialog_content = "¡Te protegeré pase lo que pase!",
  ui_story_5036_50361002_93_dialog_content = "<color=#e8d9bb>¡¡¡zas!!!</color>",
  ui_story_5036_50361002_94_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5036_50361002_95_dialog_content = "Graaah...",
  ui_story_5036_50361002_96_dialog_content = "Eclipsites...",
  ui_story_5036_50361002_97_dialog_content = "Venid a mí... ¡Venid a mí, todos vosotros!",
  ui_story_5036_50361002_98_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361002_99_dialog_content = "Duele...",
  ui_story_5036_50361002_100_dialog_content = "Mi cuerpo... se siente tan frío...",
  ui_story_5036_50361002_101_dialog_content = "Eulogoz... Ouroboros... ¿Siguen ahí ustedes dos?",
  ui_story_5036_50361002_102_dialog_content = "Yo... solo quiero irme a casa...",
  ui_story_5036_50361002_103_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361002_104_dialog_content = "Kree—!",
  ui_story_5036_50361101_1_dialog_content = "...",
  ui_story_5036_50361101_2_dialog_content = "¿PlayerName?",
  ui_story_5036_50361101_3_dialog_content = "...",
  ui_story_5036_50361101_4_dialog_content = "PlayerName! ¿Estás bien? ¿Qué viste?",
  ui_story_5036_50361101_5_dialog_content = "Yo... yo vi el último recuerdo de Chaminade.",
  ui_story_5036_50361101_6_dialog_content = "Después de que Ouroboros se convirtiera en un huevo, ella y Eulogoz fueron atacados por Eclipsites.",
  ui_story_5036_50361101_7_dialog_content = "Para proteger el huevo de Ouroboros, lo escondió en un compartimento secreto en la pared.",
  ui_story_5036_50361101_8_dialog_content = "Después de eso, Chaminade alejó sola a los Eclipsites de la habitación... Y luego...",
  ui_story_5036_50361101_9_dialog_content = "... Eso es suficiente. Entendemos.",
  ui_story_5036_50361101_10_dialog_content = "Esa pobre niña luchó hasta el amargo final para proteger el huevo de Ouroboros.",
  ui_story_5036_50361101_11_dialog_content = "Lo hizo bien, aunque parezca un poco demasiado.",
  ui_story_5036_50361101_12_dialog_content = "Ahora no es el momento de hablar así, Vic.",
  ui_story_5036_50361101_13_dialog_content = "¿Qué quieres decir? Mira dentro de la grieta en esta pared, si no me crees.",
  ui_story_5036_50361101_14_dialog_content = "¿Hay algo ahí?",
  ui_story_5036_50361101_15_dialog_content = "¡Ahhh!",
  ui_story_5036_50361101_16_dialog_content = "¿Que ves?",
  ui_story_5036_50361101_17_dialog_content = "¿Qué es esto? No se parece en nada al patrón de la pared.",
  ui_story_5036_50361101_18_dialog_content = "No está hecho de metal o Colossus Patches. Se parece más a... una cáscara de huevo.",
  ui_story_5036_50361101_19_dialog_content = "¿Podría pertenecer a los Ouroboros?",
  ui_story_5036_50361101_20_dialog_content = "Así que todavía está aquí, después de todo. Pero, ¿cómo se hizo tan grande? ¡Incluso abrió la pared!",
  ui_story_5036_50361101_21_dialog_content = "¿No debería ser un poco más grande que una sandía? Incluso esa niña podría llevarlo.",
  ui_story_5036_50361101_22_dialog_content = "¡¿Un \"huevo de Ouroboros\"?! ¡Pensé que Vic solo estaba bromeando sobre eso! ¿Cómo está sucediendo esto realmente?",
  ui_story_5036_50361101_23_dialog_content = "¿Qué está pasando aquí exactamente, Vic?",
  ui_story_5036_50361101_24_dialog_content = "Ni idea...",
  ui_story_5036_50361101_25_dialog_content = "¿Qué? ¿No se supone que eres el principal extrozoólogo del mundo?",
  ui_story_5036_50361101_26_dialog_content = "Es precisamente porque soy un extrozoólogo que me niego a hacer suposiciones precipitadas.",
  ui_story_5036_50361101_27_dialog_content = "Lo único que puedo asegurar por ahora es que este huevo ya pasó su período de incubación, pero aún no ha salido del cascarón.",
  ui_story_5036_50361101_28_dialog_content = "No solo eso, el Ouroboros dentro del huevo todavía está muy vivo. Sigue creciendo, y el huevo crece con él.",
  ui_story_5036_50361101_29_dialog_content = "En cuanto a todo lo demás, ¡no tengo ni idea!",
  ui_story_5036_50361101_30_dialog_content = "Ouroboros es una especie extremadamente rara, por lo que la información sobre ella es escasa en el mejor de los casos.",
  ui_story_5036_50361101_31_dialog_content = "Es un misterio total, para decirlo simplemente.",
  ui_story_5036_50361101_32_dialog_content = "Todo este tiempo, pensé que Vic solo estaba inventando cosas. No tenía idea de que estaba hablando en serio.",
  ui_story_5036_50361101_33_dialog_content = "¿Crees que este huevo es la fuente de los extraños sueños de todos?",
  ui_story_5036_50361101_34_dialog_content = "¡Es posible!",
  ui_story_5036_50361101_35_dialog_content = "¿De verdad lo crees?",
  ui_story_5036_50361101_36_dialog_content = "No tengo ninguna prueba, así que es solo una suposición.",
  ui_story_5036_50361101_37_dialog_content = "Siempre he tenido curiosidad por saber cómo sobrevive el Ouroboros a su período de incubación como huevo.",
  ui_story_5036_50361101_38_dialog_content = "¿Cómo se supone que un huevo lucha contra los depredadores o huye de ellos?",
  ui_story_5036_50361101_39_dialog_content = "¡Pero ahora, se me ha ocurrido una nueva hipótesis! Creo que los Ouroboros pueden poseer una habilidad psíquica única mientras están en su estado de huevo.",
  ui_story_5036_50361101_40_dialog_content = "¡Uno que puede hacer que otras criaturas experimenten extraños sueños o alucinaciones! Al hacerles sentir el peligro, los Ouroboros pueden mantenerlos a una distancia segura.",
  ui_story_5036_50361101_41_dialog_content = "Se protege a sí mismo de esta manera para protegerse de los peligros.",
  ui_story_5036_50361101_42_dialog_content = "Así que estás diciendo los extraños sueños que hemos estado teniendo, y esa extraña sensación de incomodidad...",
  ui_story_5036_50361101_43_dialog_content = "O incluso ese póster extraño de antes. ¡¿Todo eso fue obra de los Ouroboros?!",
  ui_story_5036_50361101_44_dialog_content = "Por cierto. O más bien, ¡esa es la explicación más razonable que se me ocurre!",
  ui_story_5036_50361101_45_dialog_content = "Así que nuestro próximo movimiento es obvio, ¿verdad? ¡Necesitamos encontrar una manera de mover este huevo a algún lugar lejano!",
  ui_story_5036_50361101_46_option_content = "este huevo?",
  ui_story_5036_50361101_47_option_content = "¿Muévelo?",
  ui_story_5036_50361101_48_dialog_content = "¡Sip!",
  ui_story_5036_50361101_49_dialog_content = "Si no sacamos este huevo de aquí, el poder de los Ouroboros seguirá afectando a todos.",
  ui_story_5036_50361101_50_dialog_content = "¡Y a este ritmo, definitivamente impactará mi concierto!",
  ui_story_5036_50361101_51_dialog_content = "No estoy de acuerdo.",
  ui_story_5036_50361101_52_dialog_content = "¡¿Qué?!",
  ui_story_5036_50361101_53_dialog_content = "El huevo es colosal y está atascado en la pared.",
  ui_story_5036_50361101_54_dialog_content = "Incluso si logras sacarlo, ¿cómo piensas transportarlo a otro lugar de manera segura?",
  ui_story_5036_50361101_55_dialog_content = "¡Contrataré a los Mercenarios de la Llama Blanca para que lo desentierren y se lo lleven en una aeronave!",
  ui_story_5036_50361101_56_dialog_content = "Estas paredes no están hechas exactamente de palos y piedras, ¿sabes? Para cuando termines de desenterrarlo, el concierto habrá terminado hace mucho tiempo.",
  ui_story_5036_50361101_57_dialog_content = "Yo...",
  ui_story_5036_50361101_58_dialog_content = "Sin mencionar que este puede ser el único huevo de Ouroboros que queda en todo el mundo, dado lo raros que son los exóticos.",
  ui_story_5036_50361101_59_dialog_content = "Si algo le sucediera durante la extracción, la vida de los Ouroboros podría correr peligro.",
  ui_story_5036_50361101_60_dialog_content = "Si eso sucede, ¿estarás listo para cargar con la culpa de causar la extinción de toda una especie de bestias maravillosas?",
  ui_story_5036_50361101_61_dialog_content = "Yo...",
  ui_story_5036_50361101_62_dialog_content = "¿Por qué no sigues mi consejo y cancelas este concierto?",
  ui_story_5036_50361101_63_dialog_content = "Puede realizar un concierto en cualquier otro lugar en cualquier momento. Solo sería esta vez, así que esperemos a que nazcan los Ouroboros y...",
  ui_story_5036_50361101_64_dialog_content = "¡De ninguna manera!",
  ui_story_5036_50361101_65_dialog_content = "este concierto es <color=#FFB400>especialmente importante</color> ¡a mi! ¡No puedo rendirme así como así!",
  ui_story_5036_50361101_66_dialog_content = "Puedo comprometerme en cualquier otra situación, ¡pero no en esta!",
  ui_story_5036_50361101_67_dialog_content = "Es verdad, este concierto es algo que Goldie prometió a sus fans...",
  ui_story_5036_50361101_68_dialog_content = "(\"¿Especialmente importante\"? Goldie se ve realmente angustiada en este momento. ¿Qué está pasando?)",
  ui_story_5036_50361101_69_dialog_content = "Ah, entonces parece que tenemos un pequeño dilema en nuestras manos.",
  ui_story_5036_50361101_70_dialog_content = "...",
  ui_story_5036_50361101_71_dialog_content = "(Ninguno de los dos está dispuesto a dar marcha atrás. Tengo que hacer algo al respecto).",
  ui_story_5036_50361101_72_dialog_content = "¿Realmente no hay otra manera?",
  ui_story_5036_50361101_73_dialog_content = "¿Quizás podamos deshacernos de la influencia psíquica del huevo sin moverlo?",
  ui_story_5036_50361101_74_dialog_content = "¡Así es! Eres el extrozoólogo experto, Vic. ¿No se te ocurre una forma mejor?",
  ui_story_5036_50361101_75_dialog_content = "Suspiro. Como de costumbre, a ustedes, mocosos, les encanta hacer sufrir a un anciano. Simplemente empeoran generación tras generación...",
  ui_story_5036_50361101_76_dialog_content = "Ah, bueno, supongo que no se puede evitar. Mis aprendices siempre me ruegan que salve sus tristes traseros. Esto no es diferente, supongo.",
  ui_story_5036_50361101_77_dialog_content = "Interesante elección de palabras, Vic. Me pregunto qué pensarían Shira y Fia de ellos.",
  ui_story_5036_50361101_78_dialog_content = "Lo siento, ¿qué? ¿Dije algo? ¡Parece que no puedo recordar!",
  ui_story_5036_50361101_79_dialog_content = "Oh, deja de actuar, Vic. Sigamos con esto.",
  ui_story_5036_50361101_80_dialog_content = "Ejem. Hay otro método, pero es un poco problemático y no puedo garantizar que funcione.",
  ui_story_5036_50361101_81_dialog_content = "¡Cuéntanoslo ya! ¡Haré cualquier cosa, siempre y cuando me dé la oportunidad de realizar este concierto!",
  ui_story_5036_50361101_82_dialog_content = "Háblame de la visión que viste hace unos minutos, PlayerName. ¿Chaminade pareció verse afectado negativamente por el huevo de Ouroboros de alguna manera?",
  ui_story_5036_50361101_83_dialog_content = "¿Eh? Ahora que lo pienso... No, ella realmente no parecía molestarse por eso en absoluto.",
  ui_story_5036_50361101_84_dialog_content = "Ya veo. ¡Ahí está la respuesta, mis amigos!",
  ui_story_5036_50361101_85_dialog_content = "Las habilidades psíquicas de Ouroboros parecen ser un mecanismo de autodefensa que solo usa cuando siente peligro cerca.",
  ui_story_5036_50361101_86_dialog_content = "¡Si podemos eliminar la fuente de ese peligro del Coloso, debería sentirse lo suficientemente seguro como para disipar su influencia psíquica!",
  ui_story_5036_50361101_87_dialog_content = "¿Estás diciendo que tenemos que limpiar los eclipses del Coloso?",
  ui_story_5036_50361101_88_dialog_content = "Esa es una forma de decirlo, sí.",
  ui_story_5036_50361101_89_dialog_content = "¿Eso es todo? ¡Eso no es un problema para nosotros!",
  ui_story_5036_50361101_90_dialog_content = "¡N-Ahora espera un minuto!",
  ui_story_5036_50361101_91_dialog_content = "¡Este Coloso es, bueno, colosal! ¡¿Cómo se supone que vamos a eliminar cada Eclipsite con solo nosotros cuatro?! ¡Es imposible!",
  ui_story_5036_50361101_92_dialog_content = "Tienes un punto...",
  ui_story_5036_50361101_93_dialog_content = "Además, existe la posibilidad de que esto ni siquiera funcione, ¿verdad?",
  ui_story_5036_50361101_94_dialog_content = "Correcto. ¡Pero no lo sabremos a menos que lo intentemos!",
  ui_story_5036_50361101_95_dialog_content = "¿Qué tal si tratamos de eliminar los Eclipsites en las inmediaciones y luego sellamos todas las grietas en las paredes? ¡De esa manera, no tendrán forma de acercarse al huevo!",
  ui_story_5036_50361101_96_dialog_content = "Hmm, eso podría producir un resultado similar, sí.",
  ui_story_5036_50361101_97_dialog_content = "Vamos a intentarlo!",
  ui_story_5036_50361101_98_dialog_content = "¡Muy bien, salgamos!",
  ui_story_5036_50361101_99_dialog_content = "¡Para el concierto!",
  ui_story_5036_50361102_1_dialog_content = "Ven dame una mano por aquí, PlayerName.",
  ui_story_5036_50361102_2_dialog_content = "Empujemos esta roca hacia allá y bloqueemos esa grieta en la pared.",
  ui_story_5036_50361102_3_dialog_content = "¡Entendido!",
  ui_story_5036_50361102_4_dialog_content = "¡Hrrrnnnng—!",
  ui_story_5036_50361102_5_dialog_content = "¡Uf! Esa debería ser la última grieta, ¿verdad?",
  ui_story_5036_50361102_6_dialog_content = "¡Lo parece! Excelente trabajo, todos.",
  ui_story_5036_50361102_7_dialog_content = "¡Otra empresa exitosa bajo mi liderazgo impecable!",
  ui_story_5036_50361102_8_dialog_content = "Si puede llamar a sentarse y animarnos \"liderazgo\", entonces seguro...",
  ui_story_5036_50361102_9_dialog_content = "¿De verdad esperabas que un viejo como yo siguiera el ritmo de un montón de pollos primaverales como tú?",
  ui_story_5036_50361102_10_dialog_content = "La atmósfera sombría parece estar debilitándose...",
  ui_story_5036_50361102_11_dialog_content = "Estás bien. Aunque todavía puedo sentirlo débilmente, se siente mucho mejor ahora que antes.",
  ui_story_5036_50361102_12_dialog_content = "¡Entonces parece que mi hipótesis era correcta!",
  ui_story_5036_50361102_13_dialog_content = "Entonces, ¿qué hacemos ahora? ¿Deberíamos seguir limpiando los eclipses?",
  ui_story_5036_50361102_14_dialog_content = "Creo que hemos hecho más que suficiente en este momento. Lo único que queda por hacer ahora...",
  ui_story_5036_50361102_15_dialog_content = "es volver a meternos en la cama para ver si tenemos más sueños extraños.",
  ui_story_5036_50361102_16_dialog_content = "Solo quieres ir a la cama, ¿no?",
  ui_story_5036_50361102_17_dialog_content = "Lo sentimos, pero dado que hay tan poca información sobre los Ouroboros, nuestra única opción es prueba y error.",
  ui_story_5036_50361102_18_dialog_content = "Él tiene un punto.",
  ui_story_5036_50361102_19_dialog_content = "Se ha hecho muy tarde y todo el mundo parece exhausto.",
  ui_story_5036_50361102_20_dialog_content = "Regresemos y descansemos un poco, y veamos si nuestros esfuerzos valieron la pena.",
  ui_story_5036_50361102_21_dialog_content = "Y si no lo han hecho, pensaré en otra cosa.",
  ui_story_5036_50361102_22_dialog_content = "¡Creo que todo tu arduo trabajo definitivamente valdrá la pena, Goldie!",
  ui_story_5036_50361102_23_dialog_content = "¡Jejeje! ¡Gracias por decirlo!",
  ui_story_5036_50361102_24_dialog_content = "Muy bien, entonces, volvamos a tomar un sueño muy necesario. ¡Nos encontraremos de nuevo por la mañana!",
  ui_story_5036_50361102_25_dialog_content = "<color=#e8d9bb>A la mañana siguiente, un día antes del concierto.</color>",
  ui_story_5036_50361102_26_dialog_content = "Yaaaawn... ¡No he tenido una buena noche de sueño así en mucho tiempo!",
  ui_story_5036_50361102_27_dialog_content = "Estaba tan agotado después de anoche que me desmayé tan pronto como llegué a mi habitación. ¡Estaba demasiado cansada para siquiera soñar!",
  ui_story_5036_50361102_28_dialog_content = "¡Buenos días, mi rival derrotado!",
  ui_story_5036_50361102_29_dialog_content = "¡Si acabas de despertar, eso significa que gané el juego de despertar hoy! ¡Impresionante!",
  ui_story_5036_50361102_30_dialog_content = "Hola, Gronru. ¿Dormiste bien anoche?",
  ui_story_5036_50361102_31_dialog_content = "¡Anoche me dormí un poco!",
  ui_story_5036_50361102_32_dialog_content = "Nada comparado con las últimas noches, donde seguí soñando con esa chica Caelestite.",
  ui_story_5036_50361102_33_dialog_content = "¿En serio? ¡Es una noticia maravillosa!",
  ui_story_5036_50361102_34_dialog_content = "¿Crees que sí? Yo no. ¡Tener sueños extraños como ese es como desbloquear un logro oculto en un juego!",
  ui_story_5036_50361102_35_dialog_content = "Uh, sí, seguro... De todos modos, me alegro de que hayas podido descansar un poco.",
  ui_story_5036_50361102_36_dialog_content = "¡Gracias! Me voy a ver el ensayo, ¡te veo luego!",
  ui_story_5036_50361102_37_dialog_content = "¡Muy bien, nos vemos!",
  ui_story_5036_50361102_38_dialog_content = "¡Esto es genial! ¡Parece que todo nuestro arduo trabajo de anoche no fue en vano!",
  ui_story_5036_50361102_39_dialog_content = "Debería ir a decírselo a Goldie ahora mismo, para que finalmente pueda relajarse un poco.",
  ui_story_5036_50361102_40_dialog_content = "En este momento, debería estar... en la sala de entrenamiento, ¿creo?",
  ui_story_5036_50361102_41_dialog_content = "Oh hola PlayerName!",
  ui_story_5036_50361102_42_dialog_content = "¿Ya estás despierto? Anoche salimos tan tarde que pensé que hoy querrías dormir un poco más.",
  ui_story_5036_50361102_43_dialog_content = "¡De nada! ¡Me siento completamente renovado ahora!",
  ui_story_5036_50361102_44_dialog_content = "Además, parece que nuestro arduo trabajo valió la pena. ¡Acabo de hablar con Gronru y me dijo que no tuvo sueños extraños anoche!",
  ui_story_5036_50361102_45_dialog_content = "¡Está bien! También le pregunté a algunos concursantes, ¡y todos dijeron que también durmieron bien anoche!",
  ui_story_5036_50361102_46_dialog_content = "¡Esto es perfecto!",
  ui_story_5036_50361102_47_dialog_content = "Realmente es... perfecto.",
  ui_story_5036_50361102_48_option_content = "¿Goldie? ¿Estás bien?",
  ui_story_5036_50361102_49_dialog_content = "¿Por qué te ves tan fatigado?",
  ui_story_5036_50361102_50_dialog_content = "¿Eh? ¿Yo?",
  ui_story_5036_50361102_51_dialog_content = "¡No me siento agotado en absoluto! ¡Después de todo, los ídolos están llenos de toneladas de energía!",
  ui_story_5036_50361102_52_option_content = "¿Por qué te ves tan agotado?",
  ui_story_5036_50361102_53_dialog_content = "¿Eh? ¿Yo?",
  ui_story_5036_50361102_54_dialog_content = "Creo que podrías estar viendo cosas. ¡Me siento perfectamente bien ahora mismo!",
  ui_story_5036_50361102_55_dialog_content = "(Te juro que no estoy viendo cosas. Esa expresión de hace un momento... ¿Podría ser?)",
  ui_story_5036_50361102_56_dialog_content = "Te estás obligando a mantener el ánimo alto, ¿no?",
  ui_story_5036_50361102_57_dialog_content = "¡...!",
  ui_story_5036_50361102_58_dialog_content = "No es difícil de decir. Después de todo, saliste tan tarde como nosotros anoche.",
  ui_story_5036_50361102_59_dialog_content = "Es más, tuviste que organizar el entrenamiento y la audición hoy, ¿verdad? No parece que hayas descansado nada anoche.",
  ui_story_5036_50361102_60_dialog_content = "¡Está bien, lo prometo! Soy un ídolo, ¿recuerdas? e ídolos—",
  ui_story_5036_50361102_61_option_content = "—también son personas, ¿verdad?",
  ui_story_5036_50361102_62_dialog_content = "Todavía sois gente. Tú también necesitas tu descanso.",
  ui_story_5036_50361102_63_dialog_content = "Puede que no sepa la historia completa detrás de este concierto o por qué es tan importante para ti...",
  ui_story_5036_50361102_64_dialog_content = "Pero sé que deberías dejar tu trabajo a un lado por un momento y descansar un poco ahora mismo, Goldie.",
  ui_story_5036_50361102_65_dialog_content = "Suspiro.",
  ui_story_5036_50361102_66_dialog_content = "Supongo que no estaría de más decirte la verdad, PlayerName. Después de todo, ya has hecho mucho para ayudarme.",
  ui_story_5036_50361102_67_dialog_content = "¿Eh? ¿Acabas de decir \"la verdad\"?",
  ui_story_5036_50361102_X67_dialog_content = "No solo estoy cumpliendo mi promesa a mis fans con este concierto... También estoy cumpliendo mi promesa a Lady Sheol.",
  ui_story_5036_50361102_68_dialog_content = "Para ser completamente honesto contigo, hice una especie de pacto con Sheol.",
  ui_story_5036_50361102_69_dialog_content = "¿Un pacto? ¿Con el Seol?",
  ui_story_5036_50361102_70_dialog_content = "Reconoció el potencial de la industria de los ídolos, así como mis propias habilidades. Así que decidió invertir en mi carrera.",
  ui_story_5036_50361102_71_dialog_content = "Ella es mi mayor fuente de respaldo financiero, pero al mismo tiempo, tengo que hacer todo lo que esté a mi alcance para cumplir con sus demandas.",
  ui_story_5036_50361102_72_dialog_content = "Uno de los cuales era organizar un concierto aquí en Umbraton dentro de un cierto período de tiempo, y ese concierto—",
  ui_story_5036_50361102_73_dialog_content = "Tiene que iluminar a todos en Umbraton y Lumopolis sobre el concepto de un ídolo y difundir mi nombre por toda la región.",
  ui_story_5036_50361102_74_dialog_content = "¿No crees que el Seol se está aprovechando de ti? ¿Es ese objetivo posible?",
  ui_story_5036_50361102_75_dialog_content = "Admito que no será fácil para alguien con mi nivel de popularidad. Pero nada es imposible mientras planifique todo a la perfección.",
  ui_story_5036_50361102_76_dialog_content = "Pero ya sabes, todas esas cosas sucedieron, así que no pude alquilar un lugar.",
  ui_story_5036_50361102_77_dialog_content = "Pero justo cuando parecía que se había perdido toda esperanza, ¡el Coloso Errante apareció de repente en el cielo! ¡Su llegada fue tan fortuita!",
  ui_story_5036_50361102_78_dialog_content = "Según mi pacto con Sheol, mañana es el último día que puedo realizar mi concierto. Es mi última oportunidad, así que tengo que darlo todo.",
  ui_story_5036_50361102_79_dialog_content = "Si fallo, tendré que pagarle a Sheol todos sus gastos. Estaré bajo una montaña de deudas.",
  ui_story_5036_50361102_80_dialog_content = "Mi carrera como ídolo también habrá terminado.",
  ui_story_5036_50361102_81_dialog_content = "No tenía idea de que estuvieras trabajando bajo tanta presión, Goldie. ¿No es todo demasiado?",
  ui_story_5036_50361102_82_dialog_content = "No me parece. Es mi deber, después de todo.",
  ui_story_5036_50361102_83_dialog_content = "Como ídolo, toda mi razón de ser es llevar esperanza y felicidad a mis fieles seguidores a través del canto y el baile.",
  ui_story_5036_50361102_84_dialog_content = "Sin su amor y apoyo, nunca podría llamarme ídolo.",
  ui_story_5036_50361102_85_dialog_content = "Después de todo el amor que me han mostrado, ¿qué clase de persona sería si no les pagara trabajando tan duro como pudiera?",
  ui_story_5036_50361102_86_dialog_content = "¡Lo arriesgaré todo si eso significa que mi concierto ayudará a que mi voz llegue a más personas!",
  ui_story_5036_50361102_87_dialog_content = "¡Sé que puedes hacerlo, Goldie!",
  ui_story_5036_50361102_88_dialog_content = "Pero no estás solo. ¡También me tienes a mí!",
  ui_story_5036_50361102_89_dialog_content = "Si hay algo que pueda hacer para ayudar, todo lo que tienes que hacer es preguntar.",
  ui_story_5036_50361102_90_dialog_content = "Gracias, PlayerName!",
  ui_story_5036_50361102_91_dialog_content = "¡Hagamos todo lo posible para proteger a Eulogoz y hacer de este concierto el mejor que el mundo haya visto jamás!",
  ui_story_5036_50361201_1_dialog_content = "<color=#e8d9bb>Al día siguiente, quince minutos antes del inicio del concierto.</color>",
  ui_story_5036_50361201_2_dialog_content = "¡El concierto está a punto de empezar! ¿Todos listos?",
  ui_story_5036_50361201_3_dialog_content = "¡Lista!",
  ui_story_5036_50361201_4_dialog_content = "¿El espectáculo finalmente comienza? ¡Es el momento que todos hemos estado esperando!",
  ui_story_5036_50361201_5_dialog_content = "(Honestamente, haciéndome perder mi valioso tiempo asociándome con estos plebeyos).",
  ui_story_5036_50361201_6_dialog_content = "Expresión, revelación.",
  ui_story_5036_50361201_7_dialog_content = "La presencia de pensamientos groseros y degradantes es claramente visible en tu rostro.",
  ui_story_5036_50361201_8_dialog_content = "Callate.",
  ui_story_5036_50361201_9_dialog_content = "¡Impresionante! ¡El juego está a punto de comenzar!",
  ui_story_5036_50361201_10_dialog_content = "¿Listo para ayudarme a animarlos, Sio?",
  ui_story_5036_50361201_11_dialog_content = "R-Listo...",
  ui_story_5036_50361201_12_dialog_content = "¿Por qué no hemos comenzado todavía? ¡Me muero por dejar boquiabiertos a este público con mi música rock!",
  ui_story_5036_50361201_13_dialog_content = "¡Sé realista, imbécil! ¡Este es un concierto de ídolos, no un concierto de rock! ¡Lo más importante aquí es el ídolo!",
  ui_story_5036_50361201_14_dialog_content = "¡Por eso yo, Barbara the Diesel Sweety, fui hecha para esto!",
  ui_story_5036_50361201_15_dialog_content = "¿Quién querría escuchar música infantil como la tuya? ¡La multitud no quiere escuchar esa basura!",
  ui_story_5036_50361201_16_dialog_content = "¡¿Qué fue eso?!",
  ui_story_5036_50361201_17_dialog_content = "Esos dos están tan animados como siempre. Espero que no nos causen ningún problema.",
  ui_story_5036_50361201_18_dialog_content = "Acordado. ¡Después de todo, tienen que realizar el acto de apertura juntos!",
  ui_story_5036_50361201_19_dialog_content = "Sí, sé lo que tú... Espera, ¡¿QUÉ?! ¿Acto de apertura? ¡¿Juntos?!",
  ui_story_5036_50361201_20_dialog_content = "¡¿Estás seguro de que está bien?!",
  ui_story_5036_50361201_21_dialog_content = "No voy a mentir, estoy un poco preocupado por eso también. Pero si los dejo actuar por separado, se pelearán por quién será el primero.",
  ui_story_5036_50361201_22_dialog_content = "Al hacerlos subir al escenario al mismo tiempo, al menos el concierto se desarrollará sin problemas.",
  ui_story_5036_50361201_23_dialog_content = "Además, ¡ambos juraron que harían un gran acto de apertura para el concierto!",
  ui_story_5036_50361201_24_dialog_content = "Oh, será \"asesino\", está bien... Solo que no estoy seguro de cuál será la habilidad...",
  ui_story_5036_50361201_25_dialog_content = "¡Ten un poco de fe en ellos! Sé que discuten todo el tiempo, pero no se puede negar sus habilidades o su dedicación a sus actuaciones.",
  ui_story_5036_50361201_26_dialog_content = "Bien, solo espero que puedan compartir el escenario el tiempo suficiente para terminar su acto.",
  ui_story_5036_50361201_27_dialog_content = "Después de todo, Eulogoz también tiene todo en juego en este concierto.",
  ui_story_5036_50361201_28_dialog_content = "Realmente te preocupas por Eulogoz, ¿no?",
  ui_story_5036_50361201_29_dialog_content = "Eso es porque es el único Coloso completamente operativo en el mundo, además de Soroz y Lepidoz.",
  ui_story_5036_50361201_30_dialog_content = "Los Caelestites comparten un estrecho vínculo con todos y cada uno de los Colosos. Son la prueba de que mi pueblo existió alguna vez.",
  ui_story_5036_50361201_31_dialog_content = "Quiero hacer todo lo posible para preservarlos tanto como sea posible. Sé que a los otros Caelestites les hubiera gustado eso...",
  ui_story_5036_50361201_32_dialog_content = "Sin mencionar que si arreglamos Eulogoz, Soroz finalmente tendrá otro compañero. No se sentiría tan solo.",
  ui_story_5036_50361201_33_dialog_content = "No te preocupes, PlayerName. ¡Haré lo mejor que pueda por tu bien, así como por el de ellos!",
  ui_story_5036_50361201_34_dialog_content = "¡También ayudaremos!",
  ui_story_5036_50361201_35_dialog_content = "Si algo realmente sale mal, estaré allí para mantener el orden.",
  ui_story_5036_50361201_36_dialog_content = "Como siempre, ¡Carleen tiene todo bajo control!",
  ui_story_5036_50361201_37_dialog_content = "Wow, ustedes dos lucen totalmente listos para este concierto.",
  ui_story_5036_50361201_38_dialog_content = "¡Por supuesto! ¡Incluso preparamos un arma secreta para la ocasión!",
  ui_story_5036_50361201_39_dialog_content = "¿Qué canción van a hacer juntos?",
  ui_story_5036_50361201_40_dialog_content = "Originalmente íbamos a cantar una canción de nuestros días de estudiantes, pero cuando la ensayamos, algo se sintió como si faltara.",
  ui_story_5036_50361201_41_dialog_content = "No capturó completamente todo sobre nuestros viajes, dificultades o momentos de alegría.",
  ui_story_5036_50361201_42_dialog_content = "¡Así es! Y cuando le pregunté al respecto, ¡me di cuenta de que ambos sentíamos lo mismo!",
  ui_story_5036_50361201_43_dialog_content = "¡Es por eso que decidimos escribir una canción completamente nueva para el programa!",
  ui_story_5036_50361201_44_dialog_content = "¡Vaya, no puedo esperar a escucharlo!",
  ui_story_5036_50361201_45_dialog_content = "Regina, Bárbara, Carleen, Vice, Vic...",
  ui_story_5036_50361201_46_dialog_content = "Espera, ¿dónde está Vic?",
  ui_story_5036_50361201_47_dialog_content = "Vic? Ahora que lo mencionas, me di cuenta de que su habitación estaba vacía cuando pasé por aquí.",
  ui_story_5036_50361201_48_dialog_content = "¿Pensé que llegó temprano?",
  ui_story_5036_50361201_49_dialog_content = "¿Tampoco lo has visto entonces?",
  ui_story_5036_50361201_50_dialog_content = "¡Oh, por el amor de Dios, el concierto está a punto de comenzar! ¿Adónde podría haberse escapado?",
  ui_story_5036_50361201_51_dialog_content = "¿Quizás volvió para ver cómo estaba el huevo de Ouroboros?",
  ui_story_5036_50361201_52_dialog_content = "A veces, se preocupa mucho más por las bestias maravillosas que por otras personas, y también tiene la tendencia a quedarse dormido al azar.",
  ui_story_5036_50361201_53_dialog_content = "Hay una buena probabilidad de que se haya quedado dormido allí.",
  ui_story_5036_50361201_54_dialog_content = "Pero no te preocupes, lo traeré de vuelta.",
  ui_story_5036_50361201_55_dialog_content = "¿Por tí mismo? ¿Está seguro?",
  ui_story_5036_50361201_56_dialog_content = "Estaré bien. ¡Sólo déjamelo a mi!",
  ui_story_5036_50361201_57_dialog_content = "Nos informaron. Está en el área de bloqueo, ¿no?",
  ui_story_5036_50361201_58_dialog_content = "¡Ese lugar es demasiado peligroso! ¡Voy contigo!",
  ui_story_5036_50361201_59_dialog_content = "Cuenta conmigo también.",
  ui_story_5036_50361201_60_dialog_content = "Está bastante lejos del escenario. Ir allí y volver definitivamente tomaría un tiempo.",
  ui_story_5036_50361201_61_dialog_content = "Si todavía planean actuar, será mejor que se queden aquí y se preparen.",
  ui_story_5036_50361201_62_dialog_content = "Pero, ¿cómo puedes manejar esos eclipses por tu cuenta?",
  ui_story_5036_50361201_63_dialog_content = "No tienes que preocuparte por eso, Carleen. Goldie, Vic y yo ya nos deshicimos de cada Eclipsite entre aquí y allá.",
  ui_story_5036_50361201_64_dialog_content = "Debería estar bien si voy solo.",
  ui_story_5036_50361201_65_dialog_content = "Si tú lo dices, sé rápido y ¡cuidado!",
  ui_story_5036_50361201_66_dialog_content = "Lo haré, no te preocupes.",
  ui_story_5036_50361201_67_dialog_content = "¡Muy bien, amigos! ¡Es hora de comenzar nuestro concierto!",
  ui_story_5036_50361201_68_dialog_content = "Si Vic no regresa a tiempo, ustedes dos tendrán que subir al escenario un poco antes de lo programado, ¿entendido?",
  ui_story_5036_50361201_69_dialog_content = "¡Sí! ¡Entiendo!",
  ui_story_5036_50361201_70_dialog_content = "Entendido.",
  ui_story_5036_50361201_71_dialog_content = "¿Todavía no ha comenzado?",
  ui_story_5036_50361201_72_dialog_content = "¡Creo que están a punto de hacerlo! ¡Mira allá!",
  ui_story_5036_50361201_73_dialog_content = "¡Por fin ha llegado el momento, todos! ¡Lamento haberos hecho esperar a todos!",
  ui_story_5036_50361201_74_dialog_content = "¡El concierto en el cielo \"The Moment the Stars Shine Brightest\" finalmente está a punto de comenzar!",
  ui_story_5036_50361201_75_dialog_content = "Guauuuuu!!!",
  ui_story_5036_50361201_76_dialog_content = "<color=#e8d9bb>Mientras tanto</color>",
  ui_story_5036_50361201_77_dialog_content = "¿Mmm? ¿Qué podría ser eso?",
  ui_story_5036_50361201_78_dialog_content = "Algo brillante está pasando entre las nubes... ¡¿Eso es un Coloso?!",
  ui_story_5036_50361201_79_dialog_content = "Parece que sale música de él. Esa voz dijo algo sobre un Sky Concert, ¿verdad?",
  ui_story_5036_50361201_80_dialog_content = "Permítame aclarar, señorita. Como puede que sepa o no, ese es el Coloso Errante que llegó recientemente de la Noche Eterna.",
  ui_story_5036_50361201_81_dialog_content = "Parece que una ídolo llamada Goldie está organizando un concierto a bordo.",
  ui_story_5036_50361201_82_dialog_content = "Todos los periódicos de Umbraton están llenos de noticias sobre este concierto.",
  ui_story_5036_50361201_83_dialog_content = "¿Es eso así? Que divertido",
  ui_story_5036_50361201_84_dialog_content = "¡Ven, busquemos un buen ángulo de visión y veamos de qué se trata la conmoción!",
  ui_story_5036_50361201_85_dialog_content = "Como desee, milady.",
  ui_story_5036_50361201_86_dialog_content = "¡Mira hacia arriba, hermana! ¡Es un coloso!",
  ui_story_5036_50361201_87_dialog_content = "¡Guau! ¡Un verdadero coloso!",
  ui_story_5036_50361201_88_dialog_content = "Espera, encima del Coloso, ¿eso es una pantalla? Parece que está tocando algo...",
  ui_story_5036_50361201_89_dialog_content = "¡Oye! ¡¿No es esa la chica que nos protegió del dueño del teatro ese día?!",
  ui_story_5036_50361201_90_dialog_content = "¡Es ella! ¡Así que encontró un lugar para celebrar su concierto después de todo! ¡Y en un Colossus, nada menos!",
  ui_story_5036_50361201_91_dialog_content = "Aunque no tenemos boletos, podemos ver y escuchar todo tan claro como el día. Ella es increíble, ¿eh hermana?",
  ui_story_5036_50361201_92_dialog_content = "¡Está volando por ahí! ¡Vamos, vamos a alcanzarlo!",
  ui_story_5036_50361201_93_dialog_content = "¡Seguiremos el río y la animaremos todo el camino!",
  ui_story_5036_50361201_94_dialog_content = "¡Ya puedo sentir el entusiasmo de todos!",
  ui_story_5036_50361201_95_dialog_content = "Para nuestro acto de apertura, tenemos dos ídolos candentes de un lugar aún más candente: ¡el desierto de Rediesel, que les brinda una actuación apasionada y ardiente!",
  ui_story_5036_50361201_96_dialog_content = "¡Vamos a rendirnos por Regina y Barbara!",
  ui_story_5036_50361201_97_dialog_content = "♪ Incinerar, quemarlo todo hasta los cimientos—♪",
  ui_story_5036_50361201_98_dialog_content = "♪ Te ofrezco todo mi amor—♪",
  ui_story_5036_50361201_99_dialog_content = "<size=40>♪ ¡Explosión! ¡Explosión! ¡Rompelo en pedazos! ♪</size>",
  ui_story_5036_50361201_100_dialog_content = "<size=45>♪ Escucha los latidos de mi corazón, que anhela volver a verte ♪</size>",
  ui_story_5036_50361201_101_dialog_content = "(Maldita sea, ¡¿por qué su voz es tan fuerte?!)",
  ui_story_5036_50361201_102_dialog_content = "(¡No dejaré que me gane!)",
  ui_story_5036_50361201_103_dialog_content = "<size=40>♪ Este, es mi—♪</size>",
  ui_story_5036_50361201_104_dialog_content = "<size=45>♪ Mi único deseo, ser tu—♪</size>",
  ui_story_5036_50361201_105_dialog_content = "<size=50>♪ ¡¡¡Rock and Roll!!! ♪</size>",
  ui_story_5036_50361201_106_dialog_content = "<size=50>♪ Ídolo!!! ♪</size>",
  ui_story_5036_50361201_107_dialog_content = "¡¿Qué diablos es este ruido?! ¡Es tan fuerte que no entiendo nada de lo que dicen!",
  ui_story_5036_50361201_108_dialog_content = "Ugh, se siente como si mis oídos estuvieran a punto de explotar. ¡Apaguen sus micrófonos!",
  ui_story_5036_50361201_109_dialog_content = "¡¿Me estás tomando el pelo?! ¡Prometieron no pelear en el escenario!",
  ui_story_5036_50361201_110_dialog_content = "Esto no servirá... Si las cosas siguen así, la actuación será un desastre. ¡Tengo que volver a ponerlos en marcha!",
  ui_story_5036_50361201_111_dialog_content = "♪ Siente mi corazón, cómo late y arde, como el sol del desierto—♪",
  ui_story_5036_50361201_112_dialog_content = "(Espera, ¿qué está haciendo la presentadora en el escenario? ¡¿Y por qué está cantando?!)",
  ui_story_5036_50361201_113_dialog_content = "(¡Esto no era parte del ensayo!)",
  ui_story_5036_50361201_114_dialog_content = "(Espero que capten el mensaje. ¡Vamos, dama de la suerte, no me falles ahora!)",
  ui_story_5036_50361201_115_dialog_content = "♪ ¡Todo lo que quiero es que me escuches y sientas cómo me siento! Y eso es—♪",
  ui_story_5036_50361201_116_dialog_content = "♪ Eso es—♪",
  ui_story_5036_50361201_117_dialog_content = "♪ Eso es—♪",
  ui_story_5036_50361201_118_dialog_content = "<size=45>♪ Amor—!!!♪</size>",
  ui_story_5036_50361201_119_dialog_content = "♪ ¡Amor que nunca se quema! ♪",
  ui_story_5036_50361201_120_dialog_content = "♪ ¡Amor que siempre está aquí para quedarse! ♪",
  ui_story_5036_50361201_121_dialog_content = "<size=50>♪ Amor como las arenas infinitas de Rediesel—♪</size>",
  ui_story_5036_50361201_122_dialog_content = "(¡Funcionó! ¡Esos dos finalmente volvieron a estar sincronizados!)",
  ui_story_5036_50361201_123_dialog_content = "(Ahora para hacer mi salida.)",
  ui_story_5036_50361201_124_dialog_content = "♪ Con mi roca justa que no puede ser detenida— ♪",
  ui_story_5036_50361201_125_dialog_content = "♪ Extenderé una mano y tocaré tu corazón— ♪",
  ui_story_5036_50361201_126_dialog_content = "<size=50>♪ Deja que nuestra canción resuene en los cielos—♪</size>",
  ui_story_5036_50361201_127_dialog_content = "¿Eh? Oye, ¡están empezando a sonar bastante bien!",
  ui_story_5036_50361201_128_dialog_content = "¡Las poses de Goldie son increíbles! ¡Será mejor que tome tantas fotos como pueda!",
  ui_story_5036_50361201_129_dialog_content = "A pesar de lo diferentes que son sus melodías, los dos cantan en perfecta armonía. ¡Solo mira la multitud que se ha reunido!",
  ui_story_5036_50361201_130_dialog_content = "¡Asombroso! ¡No creo que Lumopolis haya organizado nunca un concierto como este!",
  ui_story_5036_50361201_131_dialog_content = "Parece que el Coloso está volando ahora, señorita.",
  ui_story_5036_50361201_132_dialog_content = "¡Rápido! ¡A mi aeronave privada!",
  ui_story_5036_50361201_133_dialog_content = "?!?",
  ui_story_5036_50361201_134_dialog_content = "¿Cómo podría perderme un concierto tan increíble? ¡Apuro!",
  ui_story_5036_50361201_135_dialog_content = "Celebrando un concierto en un Coloso para que el mundo lo vea. ¡No creo que nadie lo haya hecho antes!",
  ui_story_5036_50361201_136_dialog_content = "Cada vez se junta más gente.",
  ui_story_5036_50361201_137_dialog_content = "Incluso los comerciantes están empezando a alquilar sus barcos para que la gente vea el concierto desde el Río Dorado.",
  ui_story_5036_50361201_138_dialog_content = "Jejeje. Parece que hice bien en invertir en el sueño de esta chica, después de todo.",
  ui_story_5036_50361201_139_dialog_content = "son vic y PlayerName ¿regresado todavía?",
  ui_story_5036_50361201_140_dialog_content = "Aún no.",
  ui_story_5036_50361201_141_dialog_content = "Estoy empezando a preocuparme por esos dos...",
  ui_story_5036_50361201_142_dialog_content = "Parece que no tenemos otra opción que dejar que ustedes dos suban al escenario primero.",
  ui_story_5036_50361201_143_dialog_content = "¡En eso!",
  ui_story_5036_50361201_144_dialog_content = "¡Démosle un aplauso a Regina y Bárbara por su maravillosa actuación!",
  ui_story_5036_50361201_145_dialog_content = "El espectáculo está empezando a calentarse. ¡Mi corazón está prácticamente latiendo fuera de mi pecho!",
  ui_story_5036_50361201_146_dialog_content = "¡A continuación, tenemos dos de las estrellas más brillantes de todo Astra listas para hacer su gran debut!",
  ui_story_5036_50361201_147_dialog_content = "Un dúo poco probable: ¡uno es un caballero de Lumopolis y el otro es un oficial de la Federación Illumina!",
  ui_story_5036_50361201_148_dialog_content = "¡Pero a pesar de sus diferentes facciones, se han convertido en los mejores amigos y han emprendido innumerables aventuras junto con el legendario Caelestite!",
  ui_story_5036_50361201_149_dialog_content = "¡Hoy les gustaría compartir su canción con todos ustedes, una canción que captura la belleza y la emoción de todos sus viajes juntos!",
  ui_story_5036_50361201_150_dialog_content = "¡Junten sus manos por Carleen y Vice—!",
  ui_story_5036_50361201_151_dialog_content = "Wow, solo mira a toda esa gente. si solo PlayerName estuvo aquí...",
  ui_story_5036_50361201_152_dialog_content = "No estés nervioso. Estaremos bien.",
  ui_story_5036_50361201_153_dialog_content = "¡Estás bien! ¡Vamos, Carlena!",
  ui_story_5036_50361201_154_dialog_content = "♪ Un viaje inimaginable ♪",
  ui_story_5036_50361201_155_dialog_content = "♪ Un camino que no se encuentra en ningún mapa ♪",
  ui_story_5036_50361201_156_dialog_content = "♪ Dime, ¿qué podría estar por venir? ♪",
  ui_story_5036_50361201_157_dialog_content = "♪ Una sensación de asombro ♪",
  ui_story_5036_50361201_158_dialog_content = "♪ Hemos caminado lado a lado, desde el día que nos conocimos ♪",
  ui_story_5036_50361201_159_dialog_content = "♪ No importa la distancia, ¡siempre nos volveremos a encontrar! ♪",
  ui_story_5036_50361201_160_dialog_content = "♪ Mi querida compañera ♪",
  ui_story_5036_50361201_161_dialog_content = "♪ ¡De extraños a amigos! ♪",
  ui_story_5036_50361201_162_dialog_content = "♪ ¡Un compañero de por vida, una luz sin fin! ♪",
  ui_story_5036_50361201_163_dialog_content = "♪ Navegamos por el cielo como dos cometas entrelazados ♪",
  ui_story_5036_50361201_164_dialog_content = "Gracias a Dios, Gronru tuvo la previsión de instalar un transmisor de señales antes de que comenzara el concierto. Ahora todos podemos disfrutar de la música, incluso desde aquí.",
  ui_story_5036_50361201_165_dialog_content = "Debo decir que esta nueva forma de entretenimiento es bastante digna de consideración.",
  ui_story_5036_50361201_166_dialog_content = "Tal vez incluso podamos realizar pruebas similares en Undercities algún día. ¿Qué dices, Gran Mariscal?",
  ui_story_5036_50361201_167_dialog_content = "Muy bien. lo permitiré",
  ui_story_5036_50361201_168_dialog_content = "R-¿En serio? ¡Excelente!",
  ui_story_5036_50361201_169_dialog_content = "¿Por qué te ves tan sorprendido?",
  ui_story_5036_50361201_170_dialog_content = "Solo me preocupaba que no aprobaras este tipo de entretenimiento, eso es todo.",
  ui_story_5036_50361201_171_dialog_content = "¡Jajaja! Por supuesto, tengo mi consideración sobre este tipo de cosas... pero escucha atentamente la música.",
  ui_story_5036_50361201_172_dialog_content = "Puede que no tenga mucho talento cuando se trata de cantar, pero incluso yo puedo decir que ahora mismo, en este mismo momento, Vice está rebosante de felicidad.",
  ui_story_5036_50361201_173_dialog_content = "Es justo el tipo de sentimiento que necesitamos, ¿no?",
  ui_story_5036_50361201_174_dialog_content = "Apenas puedo escuchar a Lady Carleen y Vice cantando, incluso desde aquí...",
  ui_story_5036_50361201_175_dialog_content = "¡Suenan increíbles! ¡Esa es Lady Carleen para ti!",
  ui_story_5036_50361201_176_dialog_content = "Raphael, quédate aquí y protege este lugar con vigilancia adicional.",
  ui_story_5036_50361201_177_dialog_content = "Además, haz que alguien me prepare un dirigible y mantenlo en secreto.",
  ui_story_5036_50361201_178_dialog_content = "¿Eh? ¿Va a salir ahora, mi señor?",
  ui_story_5036_50361201_179_dialog_content = "Todavía no está claro si Colossus representa o no una amenaza. Como Señor de la Ciudad, es mi deber investigar el asunto y garantizar personalmente la seguridad de nuestra ciudad.",
  ui_story_5036_50361201_180_dialog_content = "¡E-Entendido!",
  ui_story_5036_50361201_181_dialog_content = "Suspiro...",
  ui_story_5036_50361201_182_dialog_content = "¿Cuándo admitirá Lord Schwartz que se preocupa por Lady Carleen?",
  ui_story_5036_50361201_183_dialog_content = "<color=#e8d9bb>Mientras tanto, dentro del Coloso Errante</color>",
  ui_story_5036_50361201_184_dialog_content = "¡Ese canto suena como Vice y Carleen!",
  ui_story_5036_50361201_185_dialog_content = "¿Ya es hora de su actuación? Mierda, ¡debería acelerar el ritmo!",
  ui_story_5036_50361201_186_dialog_content = "Aunque ya debería estar allí...",
  ui_story_5036_50361201_187_dialog_content = "¡Nada como una actuación de dos de los más grandes aventureros del mundo!",
  ui_story_5036_50361201_188_dialog_content = "¡Simplemente muestra que los ídolos pueden provenir de todos los ámbitos de la vida!",
  ui_story_5036_50361201_189_dialog_content = "Para algunos fanáticos, ¡los mejores ídolos son aquellos que sacan a relucir la verdadera fuerza de otras personas!",
  ui_story_5036_50361201_190_dialog_content = "¡El siguiente en subir al escenario es un coro carismático de Illumina!",
  ui_story_5036_50361201_191_dialog_content = "¡Están aquí para cantar un himno militar inspirador—!",
  ui_story_5036_50361201_192_dialog_content = "Guauuuuu!!!",
  ui_story_5036_50361201_193_dialog_content = "¡Uf! ¡Gracias de nuevo por la ayuda, señoras!",
  ui_story_5036_50361201_194_dialog_content = "¡No lo menciones! ¡Solo me alegro de que todo haya ido bien!",
  ui_story_5036_50361201_195_dialog_content = "Estoy empezando a preocuparme por PlayerName y Vic sin embargo. Se han ido por un tiempo.",
  ui_story_5036_50361201_196_dialog_content = "Por cierto. El Coloso puede ser grande, pero no debería llevar tanto tiempo encontrar a alguien.",
  ui_story_5036_50361201_197_dialog_content = "Mmm...",
  ui_story_5036_50361201_198_dialog_content = "Vamos, Carleen. Deberíamos ir a buscarlos.",
  ui_story_5036_50361201_199_dialog_content = "Estoy de acuerdo. Ahora que nuestra actuación ha terminado, nuestra principal prioridad es garantizar que esos dos estén a salvo.",
  ui_story_5036_50361201_200_dialog_content = "Claro, pero ten cuidado y recuerda regresar para poder hacer una reverencia.",
  ui_story_5036_50361201_201_dialog_content = "¡Entendido!",
  ui_story_5036_50361201_202_dialog_content = "Vamos.",
  ui_story_5036_50361201_203_dialog_content = "<color=#e8d9bb>Algún tiempo después</color>",
  ui_story_5036_50361201_204_dialog_content = "El Illumina Choir terminó su canción, y el Lumopolis Choir casi ha terminado con la suya también...",
  ui_story_5036_50361201_205_dialog_content = "¿Dónde diablos están PlayerName ¿y los otros? ¿Podría haberles pasado algo?",
  ui_story_5036_50361201_206_dialog_content = "Están empezando a preocuparme, pero no puedo irme. ¡Mi actuación final se acerca pronto!",
  ui_story_5036_50361201_207_dialog_content = "Tengo que asegurarme de que todos escuchen mi canción.",
  ui_story_5036_50361201_208_dialog_content = "De lo contrario, todo nuestro arduo trabajo habrá sido en vano.",
  ui_story_5036_50361201_209_dialog_content = "Iré a buscarlos en cuanto termine.",
  ui_story_5036_50361201_210_dialog_content = "¡Nos estamos acercando a la gran final, todos! ¿Seguimos pasando un buen rato?",
  ui_story_5036_50361201_211_dialog_content = "Sí-!",
  ui_story_5036_50361201_212_dialog_content = "¡Fantástico! ¡Gracias por mantener la energía durante todo el concierto, amigos!",
  ui_story_5036_50361201_213_dialog_content = "Ahora bien, para el acto final del espectáculo, ¡permítanme despedirlos a todos con una canción propia!",
  ui_story_5036_50361201_214_dialog_content = "¡¡¡Guau!!! ¡¡¡Por fin es el turno de Goldie de cantar!!!",
  ui_story_5036_50361201_215_dialog_content = "La siguiente canción es muy especial. Fue utilizado por los Caelestitas para comunicarse con los Colosos.",
  ui_story_5036_50361201_216_dialog_content = "¡Usando su melodía única, los Caelestites pilotarían sus majestuosos Colosos por todo el mundo!",
  ui_story_5036_50361201_217_dialog_content = "¡Hoy, en honor al tan esperado regreso de este coloso, esta melodía sonará una vez más!",
  ui_story_5036_50361201_218_dialog_content = "Woooo—!!!",
  ui_story_5036_50361201_219_dialog_content = "(Esto es todo. Este es el momento que todos hemos estado esperando.)",
  ui_story_5036_50361201_220_dialog_content = "¡Dondequiera que va Goldie, los Ricitos de Oro la siguen!",
  ui_story_5036_50361201_221_dialog_content = "(Que esta canción sea mi forma de pagar a mis fans y PlayerName por todo su apoyo infinito!)",
  ui_story_5036_50361201_222_dialog_content = "♪ Starlight, brillando en el cielo ♪",
  ui_story_5036_50361201_223_dialog_content = "♪ Un pajarito extiende sus alas para volar ♪",
  ui_story_5036_50361201_224_dialog_content = "♪ Un viaje largo y peligroso se encuentra ante sus ojos ♪",
  ui_story_5036_50361201_225_dialog_content = "♪ ¡Ilumina su camino durante toda la noche! ♪",
  ui_story_5036_50361201_226_dialog_content = "Goldie! Goldie!",
  ui_story_5036_50361201_227_dialog_content = "Ah... puedo oír el canto de la señorita Goldie...",
  ui_story_5036_50361201_228_dialog_content = "No importa lo difíciles que hayan sido las cosas. ¡Esto hace que todo valga la pena!",
  ui_story_5036_50361201_229_dialog_content = "♪ ¡Una oportunidad para verte, una oportunidad para que el amor crezca! ♪",
  ui_story_5036_50361201_230_dialog_content = "♪ ¡Llena mi corazón de coraje y dime a dónde ir! ♪",
  ui_story_5036_50361201_231_dialog_content = "(Urgh... ¿P-Por qué tengo tanto sueño...?)",
  ui_story_5036_50361201_232_dialog_content = "(Espera, ¡¿en qué estoy pensando?! ¡Estoy en medio de una canción ahora mismo!)",
  ui_story_5036_50361201_233_dialog_content = "♪ ¡Vamos, vamos, llévame! ♪",
  ui_story_5036_50361201_234_dialog_content = "♪ ¡A un lugar donde pueda verte todos los días! ♪",
  ui_story_5036_50361201_235_dialog_content = "(¿Qué está pasando...? Mi cabeza da vueltas...)",
  ui_story_5036_50361201_236_dialog_content = "Kree—!",
  ui_story_5036_50361201_237_dialog_content = "(Ese sonido... ¿De dónde vino ese sonido?)",
  ui_story_5036_50361201_238_dialog_content = "(Estoy tan cansada... ¡Pero todavía no puedo dormir! El concierto... Todavía no ha terminado...)",
  ui_story_5036_50361301_1_dialog_content = "<color=#e8d9bb>Mientras tanto, en el área de encierro</color>",
  ui_story_5036_50361301_2_dialog_content = "¿Que esta pasando? Se siente como si estuviera dando vueltas en círculos otra vez.",
  ui_story_5036_50361301_3_dialog_content = "Todavía recuerdo el camino al huevo, así que ¿por qué no he llegado todavía?",
  ui_story_5036_50361301_4_dialog_content = "¿Podría el Ouroboros haber activado sus poderes psíquicos nuevamente?",
  ui_story_5036_50361301_5_dialog_content = "¿Ya llegamos? El concierto probablemente ya casi ha terminado...",
  ui_story_5036_50361301_6_dialog_content = "¡Ay! ¡Ahí está! Después de todo este tiempo, ¡por fin lo logré!",
  ui_story_5036_50361301_7_dialog_content = "¿Mmm? Qué estás haciendo aquí, PlayerName?",
  ui_story_5036_50361301_8_dialog_content = "¿No me digas que el concierto fue tan aburrido que viniste aquí a dormir la siesta también?",
  ui_story_5036_50361301_9_dialog_content = "¡¿Por qué clase de idiota me tomas?!",
  ui_story_5036_50361301_10_dialog_content = "Más importante aún, ¿qué estás haciendo TÚ aquí? ¡Todos siguen esperando tu actuación!",
  ui_story_5036_50361301_11_dialog_content = "¿Mi rendimiento? Oh, te refieres a todo el asunto del canto, ¿verdad?",
  ui_story_5036_50361301_12_dialog_content = "Lo siento, pero no puedo hacerlo.",
  ui_story_5036_50361301_13_dialog_content = "¡¿Qué quieres decir?! ¡Tienes un don, y Goldie dedicó todo ese tiempo y esfuerzo a entrenarte! ¡¿Cómo pudiste elegir abandonar en un momento como este?!",
  ui_story_5036_50361301_14_dialog_content = "Jajajaja! Tienes toda la razón, tengo un don. Pero realmente no puedo hacerlo.",
  ui_story_5036_50361301_15_dialog_content = "¿Has visto cómo entrenan?",
  ui_story_5036_50361301_16_dialog_content = "Para actuar en el escenario, requieren semanas de entrenamiento, así como un suministro inagotable de energía y entusiasmo. Y me falta mucho en ambos departamentos, chico.",
  ui_story_5036_50361301_17_dialog_content = "Además, no me interesan los conciertos ni los ídolos. Mis viejos huesos simplemente no están hechos para ese tipo de cosas de niños.",
  ui_story_5036_50361301_18_dialog_content = "E incluso si me subiera a ese escenario, solo los estaría reteniendo, jóvenes.",
  ui_story_5036_50361301_19_dialog_content = "Entonces, en lugar de dificultar las cosas para todos, ¡decidí usar mis pocas habilidades para un buen uso! ¡Como vigilar este huevo y asegurarse de que no arruine el concierto!",
  ui_story_5036_50361301_20_dialog_content = "Para alguien que dice que no le importa el concierto, seguro que estás mostrando mucha preocupación.",
  ui_story_5036_50361301_21_dialog_content = "¡Ja ja! Simplemente no quiero estar en una posición de deberle un favor a un grupo de niños.",
  ui_story_5036_50361301_22_dialog_content = "Creo que es un poco tarde para eso...",
  ui_story_5036_50361301_23_dialog_content = "Ejem, si estás hablando de mis aprendices, todo es parte de su entrenamiento.",
  ui_story_5036_50361301_24_dialog_content = "Pero ya basta de eso, también lo sentiste de camino aquí, ¿no? El huevo de Ouroboros activó sus poderes una vez más.",
  ui_story_5036_50361301_25_dialog_content = "Sí. Me sentí como si hubiera estado caminando durante horas antes de llegar aquí.",
  ui_story_5036_50361301_26_dialog_content = "Esto solo puede significar que el Ouroboros detecta peligro nuevamente y está tratando de defenderse.",
  ui_story_5036_50361301_27_dialog_content = "Pero, ¿qué pasa con los eclipses que eliminamos o las grietas que aseguramos?",
  ui_story_5036_50361301_28_dialog_content = "¿Será porque los otros Aurorianos están demasiado lejos?",
  ui_story_5036_50361301_29_dialog_content = "Con el concierto en pleno apogeo, todos los Aurorianos están reunidos hacia el frente del Coloso, el lugar más alejado de nuestra posición actual.",
  ui_story_5036_50361301_30_dialog_content = "Si algo sucediera aquí, seríamos los únicos que quedaríamos para defenderlo. Los otros posiblemente no podrían llegar aquí a tiempo.",
  ui_story_5036_50361301_31_dialog_content = "¿Entonces crees que el Ouroboros está asustado por esto?",
  ui_story_5036_50361301_32_dialog_content = "¡Es posible!",
  ui_story_5036_50361301_33_dialog_content = "Qué criatura cobarde resultó ser este Ouroboros. Después de todos estos años a bordo de un Coloso infestado de Eclipsitas, ¡todavía tiene miedo!",
  ui_story_5036_50361301_34_dialog_content = "No creo que tenga tanto miedo de ellos como miedo de estar solo otra vez, Vic.",
  ui_story_5036_50361301_35_dialog_content = "Pasé los primeros diecisiete años de mi vida a bordo de un Colossus. Aunque estaba solo, nunca me sentí solo porque tenía a Soroz para hacerme compañía.",
  ui_story_5036_50361301_36_dialog_content = "Pero ahora que he hecho tantos amigos. Sé que nunca podría separarme de ellos.",
  ui_story_5036_50361301_37_dialog_content = "Haces un buen punto.",
  ui_story_5036_50361301_38_dialog_content = "De todos modos, ¿qué quisiste decir ahora con el huevo \"arruinando el concierto\"?",
  ui_story_5036_50361301_39_dialog_content = "Ya está en marcha. ¿Qué podría hacerle ahora el huevo de Ouroboros?",
  ui_story_5036_50361301_40_dialog_content = "Un agudo observador como siempre.",
  ui_story_5036_50361301_41_dialog_content = "Como dije antes, algún factor desconocido ha impedido que este huevo eclosione, razón por la cual creció hasta proporciones monumentales.",
  ui_story_5036_50361301_42_dialog_content = "Pero por esa misma razón, tampoco tengo idea de cuándo eclosionará.",
  ui_story_5036_50361301_43_dialog_content = "Dado el tamaño actual del huevo, si los Ouroboros eclosionaran ahora mismo... Me temo que tendría un enorme impacto en todo el Coloso.",
  ui_story_5036_50361301_44_dialog_content = "Eh...?!",
  ui_story_5036_50361301_45_dialog_content = "¿Eso no significa que este huevo es tan peligroso como una bomba de relojería, verdad?",
  ui_story_5036_50361301_46_dialog_content = "¡Precisamente!",
  ui_story_5036_50361301_47_dialog_content = "Por eso decidí vigilarlo, ¿ves? No solo por el bien del concierto, sino también por el bien de nuestras propias vidas.",
  ui_story_5036_50361301_48_dialog_content = "Y el hecho de que haya podido llegar a tal conclusión significa que tiene la aptitud para una carrera en extrozoología, PlayerName!",
  ui_story_5036_50361301_49_dialog_content = "¿Qué dices? ¿Te importaría trabajar debajo de mí como mi aprendiz más nuevo?",
  ui_story_5036_50361301_50_option_content = "¡Seguro!",
  ui_story_5036_50361301_51_dialog_content = "Debo admitir que las bestias maravillosas son bastante interesantes. Sin mencionar que muchos de ellos también están en peligro de extinción.",
  ui_story_5036_50361301_52_dialog_content = "Protegerlos sería una elección de carrera muy significativa.",
  ui_story_5036_50361301_53_dialog_content = "Un punto de vista muy válido, PlayerName. ¿O debería decir, mi pequeño aprendiz?",
  ui_story_5036_50361301_54_dialog_content = "Pero te lo digo ahora mismo, no dejaré que me mandes ni me envíes a hacer recados gratis.",
  ui_story_5036_50361301_55_dialog_content = "*Sollozo* ¿Es esa una forma de ver a tu amo?",
  ui_story_5036_50361301_56_option_content = "Creo que paso.",
  ui_story_5036_50361301_57_dialog_content = "Investigar bestias maravillosas es genial y todo eso, pero después de conocer a Fia y Shira, sé todo sobre la vida como uno de tus aprendices...",
  ui_story_5036_50361301_58_dialog_content = "Ser enviado a investigaciones sin dinero, cuidar bestias maravillosas, cuidar a su amo...",
  ui_story_5036_50361301_59_dialog_content = "¡¿Qué clase de vida es esa?!",
  ui_story_5036_50361301_60_dialog_content = "Todo lo que hacemos por las maravillosas bestias es por amor y respeto por ellas, ¡por eso no pedimos nada a cambio!",
  ui_story_5036_50361301_61_dialog_content = "Pero si te sientes tan en contra, no intentaré hacerte cambiar de opinión.",
  ui_story_5036_50361301_62_dialog_content = "He perdido tanto tiempo aquí. Me pregunto cómo va el concierto.",
  ui_story_5036_50361301_63_dialog_content = "Volveré y les haré saber que todo está bien, para que no sigan preocupándose por nosotros.",
  ui_story_5036_50361301_64_dialog_content = "¡Por supuesto! En ese caso, me quedaré aquí y...",
  ui_story_5036_50361301_65_dialog_content = "Kree—!",
  ui_story_5036_50361301_66_dialog_content = "¿Qué fue ese sonido?",
  ui_story_5036_50361301_67_dialog_content = "¿Sonido? ¿Que sonido? ¿Seguro que no estás escuchando cosas?",
  ui_story_5036_50361301_68_dialog_content = "¿Hola, Carleen? ¿Acabas de escuchar un ruido extraño?",
  ui_story_5036_50361301_69_dialog_content = "Parecía el grito de un animal.",
  ui_story_5036_50361301_70_dialog_content = "No...",
  ui_story_5036_50361301_71_dialog_content = "¡Carleen! ¡¿Estás bien?! Qué...",
  ui_story_5036_50361301_72_dialog_content = "Qué esta pasando...? Tan somnoliento...",
  ui_story_5036_50361301_73_dialog_content = "Sonaba como... el Ouroboros...",
  ui_story_5036_50361301_74_dialog_content = "(¿Eh? ¿Por qué tengo... tanto... sueño...?)",
  ui_story_5036_50361301_75_dialog_content = "PlayerName? ¿Qué pasa? ¡Animarse!",
  ui_story_5036_50361301_76_dialog_content = "Parece que no tengo más remedio que usar mi último recurso. Bica! ¡Entra en el bolsillo de PlayerName y cómete todo su Nightium!",
  ui_story_5036_50361301_77_dialog_content = "¡Hola!",
  ui_story_5036_50361301_78_dialog_content = "¡¿Q-Qué?! ¡No por favor! ¡Todo menos eso!",
  ui_story_5036_50361301_79_dialog_content = "¡¿Sabes cuánto tiempo trabajé para salvar todo esto?!",
  ui_story_5036_50361301_80_dialog_content = "Oh bueno, estás despierto.",
  ui_story_5036_50361301_81_dialog_content = "¿Te quedaste despierto hasta tarde anoche o algo así? Estabas a punto de desmayarte.",
  ui_story_5036_50361301_82_dialog_content = "¿Eh? En absoluto, en realidad me fui a la cama bastante temprano anoche.",
  ui_story_5036_50361301_83_dialog_content = "Extraño... Podría haber jurado que escuché el Ouroboros hace un momento, y luego de repente me sentí extremadamente somnoliento...",
  ui_story_5036_50361301_84_dialog_content = "¿Has oído hablar de los Ouroboros? ¿Por qué no lo escuché?",
  ui_story_5036_50361301_85_dialog_content = "¡Lo digo en serio! Si no me crees, sigue escuchando; ¡podría volver a gritar!",
  ui_story_5036_50361301_86_dialog_content = "Si tú lo dices, estaré atento.",
  ui_story_5036_50361301_87_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361301_88_dialog_content = "¡No escucho nada, mucho menos un Ouroboros! Debes haber oído mal.",
  ui_story_5036_50361301_89_dialog_content = "Pero...",
  ui_story_5036_50361301_90_dialog_content = "<color=#e8d9bb>Golpear-</color>",
  ui_story_5036_50361301_91_dialog_content = "¡Oí algo otra vez! Solo que esta vez, no sonó como el grito de los Ouroboros.",
  ui_story_5036_50361301_92_dialog_content = "Ese sonido, ¿podría ser?",
  ui_story_5036_50361301_93_dialog_content = "Así que tú también lo escuchas, ¿verdad?",
  ui_story_5036_50361301_94_dialog_content = "<color=#e8d9bb>Chunda chunda-</color>",
  ui_story_5036_50361301_95_dialog_content = "Oh, lo escucho, está bien. Lo escucho alto y claro.",
  ui_story_5036_50361301_96_dialog_content = "Es... un latido del corazón.",
  ui_story_5036_50361301_97_dialog_content = "Viene del interior del huevo.",
  ui_story_5036_50361301_98_dialog_content = "¿Eh? ¡¿Quieres decir que finalmente está saliendo del cascarón?!",
  ui_story_5036_50361301_99_dialog_content = "Este tipo tiene el peor momento, ¿no le parece?",
  ui_story_5036_50361301_100_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5036_50361301_101_dialog_content = "¡¿Ahora que?!",
  ui_story_5036_50361301_102_dialog_content = "¡Cuidado, PlayerName!",
  ui_story_5036_50361301_103_dialog_content = "¡Algo está tratando de atravesar la pared que sellamos anoche!",
  ui_story_5036_50361301_104_dialog_content = "<color=#e8d9bb>¡¡Boom—!!</color>",
  ui_story_5036_50361301_105_dialog_content = "Graaaaaah-!",
  ui_story_5036_50361301_106_dialog_content = "¡Son los eclipses, Vic!",
  ui_story_5036_50361301_107_dialog_content = "¡Sálvanos, pequeña bola de pelo!",
  ui_story_5036_50361302_1_dialog_content = "¡¿Por qué hay tantos eclipses aquí?!",
  ui_story_5036_50361302_2_dialog_content = "¡Pensé que nos deshicimos de todos ellos anoche!",
  ui_story_5036_50361302_3_dialog_content = "Parecería que estos Eclipsites vinieron de aún más lejos.",
  ui_story_5036_50361302_4_dialog_content = "A juzgar por lo agitados que se han vuelto, supongo que tiene algo que ver con la eclosión de los Ouroboros.",
  ui_story_5036_50361302_5_dialog_content = "Sea lo que sea, ¡tenemos que decírselo a Goldie y a los demás de inmediato!",
  ui_story_5036_50361302_6_dialog_content = "Si el Ouroboros realmente se trata de la escotilla, ¡permanecer a bordo del Colossus será demasiado peligroso para nosotros!",
  ui_story_5036_50361302_7_dialog_content = "¡Tenemos que darnos prisa y evacuar a todos!",
  ui_story_5036_50361302_8_dialog_content = "Cierto, quedarse aquí está completamente fuera de cuestión.",
  ui_story_5036_50361302_9_dialog_content = "Después de todo, esta habitación podría estrellarse contra nuestras cabezas una vez que el Ouroboros eclosione.",
  ui_story_5036_50361302_10_dialog_content = "¡Parece que es hora de correr!",
  ui_story_5036_50361302_11_dialog_content = "De esta manera. ¡No te separes!",
  ui_story_5036_50361302_12_dialog_content = "Espera, creo que hay dos personas en el piso de allí.",
  ui_story_5036_50361302_13_dialog_content = "¡Son Vice y Carleen!",
  ui_story_5036_50361302_14_dialog_content = "¡Vicio! ¡Carleen! ¡Despierta!",
  ui_story_5036_50361302_15_dialog_content = "¿Que esta pasando? ¡No puedo despertarlos!",
  ui_story_5036_50361302_16_dialog_content = "¿Podría ser esto también obra de los Ouroboros?",
  ui_story_5036_50361302_17_dialog_content = "Es demasiado peligroso dejarlos aquí. Solo tendremos que llevarlos.",
  ui_story_5036_50361302_18_dialog_content = "Está bien, déjamelo a mí. Los conseguiré.",
  ui_story_5036_50361302_19_dialog_content = "¡Hrrrrrrrng—uf!",
  ui_story_5036_50361302_20_dialog_content = "Podrías considerar levantar pesas si logramos salir de aquí, PlayerName.",
  ui_story_5036_50361302_21_dialog_content = "¡Definitivamente no es el momento, Vic! ¡Ayúdame a recogerlos!",
  ui_story_5036_50361302_22_dialog_content = "No creo que sea de mucha ayuda en ese sentido tampoco. Sin embargo-",
  ui_story_5036_50361302_23_dialog_content = "¡Sal, pequeña bola de pelo!",
  ui_story_5036_50361302_24_dialog_content = "¡Chirrido!",
  ui_story_5036_50361302_25_dialog_content = "¿Se puede hacer más grande?",
  ui_story_5036_50361302_26_dialog_content = "¡Obviamente! Pero eso no cambia su pelaje suave y abrazable.",
  ui_story_5036_50361302_27_dialog_content = "¡No podría pedir una cama mejor para mis siestas de la tarde! Aquí, ¿quieres sentirlo? ¡El primer toque es gratis!",
  ui_story_5036_50361302_28_dialog_content = "M-Quizás la próxima vez, Vic...",
  ui_story_5036_50361302_29_dialog_content = "Ahora bien, Little Furball, ¿o debería decir Big Furball? Necesito que lleves a esas dos chicas allá.",
  ui_story_5036_50361302_30_dialog_content = "Chirrrrp-!",
  ui_story_5036_50361302_31_dialog_content = "¡Sigamos moviéndonos! ¡Todavía tenemos que advertir a los demás!",
  ui_story_5036_50361302_32_dialog_content = "Oh no...",
  ui_story_5036_50361302_33_dialog_content = "Parece que están todos dormidos.",
  ui_story_5036_50361302_34_dialog_content = "Esa chica incluso se desmayó sola en el escenario.",
  ui_story_5036_50361302_35_dialog_content = "...",
  ui_story_5036_50361302_36_dialog_content = "Goldie! ¡Quítate de encima, Goldie!",
  ui_story_5036_50361302_37_dialog_content = "¿Por qué no puedo despertar a ninguno de ellos...?",
  ui_story_5036_50361302_38_dialog_content = "Algo es extraño en su condición. Este parece ser el trabajo de Luminatics.",
  ui_story_5036_50361302_39_dialog_content = "¿Crees que los Ouroboros también hicieron esto?",
  ui_story_5036_50361302_40_dialog_content = "Pero si es así, ¿por qué seguimos despiertos cuando todos los demás están en coma como este?",
  ui_story_5036_50361302_41_dialog_content = "Porque hay algo especial entre nosotros dos.",
  ui_story_5036_50361302_42_dialog_content = "Eres un Caelestite, posees habilidades psíquicas únicas.",
  ui_story_5036_50361302_43_dialog_content = "En cuanto a mí, mi línea de sangre comparte un origen similar con los Ouroboros. Esta podría ser la fuente de mi inmunidad.",
  ui_story_5036_50361302_44_dialog_content = "¿Hay alguna forma de despertarlos?",
  ui_story_5036_50361302_45_dialog_content = "No puedo decir con certeza, no.",
  ui_story_5036_50361302_46_dialog_content = "Pero, ¿cómo podría ser eso? Tú mismo lo dijiste: ¡compartes un origen con los Ouroboros! Debes tener algo.",
  ui_story_5036_50361302_47_dialog_content = "Lo siento, pero además de ser longevos, los Ouroboros y yo no tenemos mucho más en común.",
  ui_story_5036_50361302_48_dialog_content = "Puede que tengas una mejor oportunidad.",
  ui_story_5036_50361302_49_dialog_content = "Tu habilidad psíquica podría permitirte sentir algo que no sé.",
  ui_story_5036_50361302_50_dialog_content = "Vale, supongo que no tenemos otras ideas.",
  ui_story_5036_50361401_1_dialog_content = "¿Estoy... dormido?",
  ui_story_5036_50361401_2_dialog_content = "¡Espera, este es Eraveil! ¿Estoy soñando otra vez?",
  ui_story_5036_50361401_3_dialog_content = "Algo es diferente esta vez. La escena se ve mucho más clara que antes.",
  ui_story_5036_50361401_4_dialog_content = "Incluso puedo ver una torre blanca por allí.",
  ui_story_5036_50361401_5_dialog_content = "Espera, ¿qué es eso que vuela encima? Es eso...",
  ui_story_5036_50361401_6_dialog_content = "¿Un dragón?",
  ui_story_5036_50361401_7_dialog_content = "¡Oh, definitivamente estoy soñando!",
  ui_story_5036_50361401_8_dialog_content = "¿Pero cómo? ¿Cómo pasó esto? Vamos, Goldie. ¡Tienes que despertar! ¡El concierto aún no ha terminado!",
  ui_story_5036_50361401_9_dialog_content = "Dicen que pellizcarte el muslo en un sueño te despertará.",
  ui_story_5036_50361401_10_dialog_content = "¡Aquí va!",
  ui_story_5036_50361401_11_dialog_content = "¡Siiiiiiiii!",
  ui_story_5036_50361401_12_dialog_content = "¡¿Por qué no me desperté?! ¡Tal vez necesito pellizcarme aún más fuerte!",
  ui_story_5036_50361401_13_dialog_content = "♪ La—La la ♪",
  ui_story_5036_50361401_14_dialog_content = "Esa voz... ¡La he escuchado antes! ¡Suena como esa chica Caelestite, Chaminade!",
  ui_story_5036_50361401_15_dialog_content = "♪ Alas... empapadas ♪",
  ui_story_5036_50361401_16_dialog_content = "Creo que puedo distinguir la letra de su canción esta vez.",
  ui_story_5036_50361401_17_dialog_content = "No pude escuchar nada más que la melodía la última vez.",
  ui_story_5036_50361401_18_dialog_content = "♪... casa ♪",
  ui_story_5036_50361401_19_dialog_content = "Parece que viene de allí.",
  ui_story_5036_50361401_20_dialog_content = "♪ Todo lo que queda son esos momentos en mis recuerdos ♪",
  ui_story_5036_50361401_21_dialog_content = "♪ La torre blanca se yergue alta y orgullosa ♪",
  ui_story_5036_50361401_22_dialog_content = "♪ Pero su luz guía está más allá de mi vista ♪",
  ui_story_5036_50361401_23_dialog_content = "(La melodía suena tan hermosa, pero la expresión de su rostro está llena de tristeza...)",
  ui_story_5036_50361401_24_dialog_content = "♪ Deambula, deambula, mira la tierra y el mar ♪",
  ui_story_5036_50361401_25_dialog_content = "♪ Pero nunca olvides la casa de tus sueños ♪",
  ui_story_5036_50361401_26_dialog_content = "¿Hmm? No me di cuenta de que habría otros visitantes.",
  ui_story_5036_50361401_27_dialog_content = "(¡¿Eh?! ¡¿E-está hablando conmigo?!)",
  ui_story_5036_50361401_28_dialog_content = "(Esto nunca sucedió en mis sueños anteriores. A menos que... ¿esto no es un sueño?)",
  ui_story_5036_50361401_29_dialog_content = "¡H-Hola! Debes ser Chaminade. Mi nombre es Goldie. ¡Soy un ídolo!",
  ui_story_5036_50361401_30_dialog_content = "¿Mmm? ¿Usted sabe mi nombre?",
  ui_story_5036_50361401_31_dialog_content = "¡Por supuesto que sí! Mi amigo PlayerName ¡también es Caelestita! Usó sus poderes psíquicos para ver tus recuerdos del pasado.",
  ui_story_5036_50361401_32_dialog_content = "¿Es eso así? Jejeje, eso es un poco vergonzoso.",
  ui_story_5036_50361401_33_dialog_content = "Dime, ¿qué es exactamente un \"ídolo\"?",
  ui_story_5036_50361401_34_dialog_content = "Un ídolo es alguien que usa el poder de la música para traer felicidad y esperanza a otras personas. ¡Soy un ídolo profesional!",
  ui_story_5036_50361401_35_dialog_content = "¡Eso es increíble! ¡Yo también quiero ser un ídolo!",
  ui_story_5036_50361401_36_dialog_content = "Estaría encantado de compartir algunos consejos con usted si lo desea. Oh, pero ahora no es un buen momento. ¡Tengo que volver a mi concierto y terminar mi actuación!",
  ui_story_5036_50361401_37_dialog_content = "¿Sabes cómo puedo salir de aquí, Chaminade?",
  ui_story_5036_50361401_38_dialog_content = "Lo siento... pero no sé cómo salir de este lugar.",
  ui_story_5036_50361401_39_dialog_content = "Después de todo, yo tampoco tengo forma de salir de aquí.",
  ui_story_5036_50361401_40_dialog_content = "¿No hay manera de salir?",
  ui_story_5036_50361401_41_dialog_content = "(Eso tiene sentido ya que la verdadera ella ya es...)",
  ui_story_5036_50361401_42_dialog_content = "(Espera, si el verdadero Chaminade ya está muerto... Entonces, ¿quién o qué está frente a mí?)",
  ui_story_5036_50361401_43_dialog_content = "¡Mm, está bien!",
  ui_story_5036_50361401_44_dialog_content = "¡Mientras busquemos, encontraremos uno!",
  ui_story_5036_50361401_45_dialog_content = "<color=#e8d9bb>Choque—</color>",
  ui_story_5036_50361401_46_dialog_content = "¿Eh? ¿Que fue ese ruido?",
  ui_story_5036_50361401_47_dialog_content = "¡Son ellos!",
  ui_story_5036_50361401_48_dialog_content = "¡Ellos vienen! ¡Tenemos que salir de aquí!",
  ui_story_5036_50361401_49_dialog_content = "\"A ellos\"? ¿De qué estás hablando?",
  ui_story_5036_50361401_50_dialog_content = "¡Los eclipses!",
  ui_story_5036_50361401_51_dialog_content = "Graaaaaah-!",
  ui_story_5036_50361401_52_dialog_content = "¡Oh, ella no está bromeando! ¡¿Por qué hay tantos de ellos?!",
  ui_story_5036_50361401_53_dialog_content = "Grahhhhhh—!",
  ui_story_5036_50361401_54_dialog_content = "¡¿De dónde salieron todos?!",
  ui_story_5036_50361401_55_dialog_content = "¡Van a volver, Goldie! ¡Escondite rapido!",
  ui_story_5036_50361401_56_dialog_content = "No hay dónde esconderse, no con tantos de ellos. ¡Nuestra única opción es luchar!",
  ui_story_5036_50361401_57_dialog_content = "¡No dejaré que los Eclipsites se vuelvan locos por más tiempo!",
  ui_story_5036_50361402_1_dialog_content = "¡Uf—!",
  ui_story_5036_50361402_2_dialog_content = "¡Maldito! ¡Simplemente no hay fin para ellos! ¡No podemos vencerlos a todos!",
  ui_story_5036_50361402_3_dialog_content = "Grahh!",
  ui_story_5036_50361402_4_dialog_content = "¡Ahhh!",
  ui_story_5036_50361402_5_dialog_content = "¡Olvídate de mí y solo corre! Desaparecerán pronto, ¡así que aléjate por ahora!",
  ui_story_5036_50361402_6_dialog_content = "¿Eh? ¿Qué quieres decir?",
  ui_story_5036_50361402_7_dialog_content = "Kree—",
  ui_story_5036_50361402_8_dialog_content = "Kree—!",
  ui_story_5036_50361402_9_dialog_content = "¿¡El dragón... está brillando!?",
  ui_story_5036_50361402_10_dialog_content = "¡Es tan brillante! ¡No puedo ver nada—!",
  ui_story_5036_50361402_11_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361402_12_dialog_content = "Solo tengo que seguir moviéndome, los Eclipsites están justo detrás... ¿Eh? ¿A dónde fueron los eclipses?",
  ui_story_5036_50361402_13_dialog_content = "Se han ido ahora. Todo está bien.",
  ui_story_5036_50361402_13X1_dialog_content = "¡Los Ouroboros los hicieron desaparecer a todos!",
  ui_story_5036_50361402_13X2_dialog_content = "Ah, sí, todavía no te lo he presentado, ¿verdad? ¡Está ahí, el pequeño volando en el cielo arriba!",
  ui_story_5036_50361402_14_dialog_content = "¿Desaparecido? ¿Quieres decir que la luz de los Ouroboros se deshizo de ellos?",
  ui_story_5036_50361402_15_dialog_content = "No, no es lo suficientemente fuerte para hacer eso. Todo lo que hizo fue comenzar este sueño de nuevo.",
  ui_story_5036_50361402_16_dialog_content = "¡Así que esto realmente es un sueño!",
  ui_story_5036_50361402_17_dialog_content = "Sí, lo es. Un sueño hecho para mí por los Ouroboros.",
  ui_story_5036_50361402_18_dialog_content = "Ya que tu amigo es Caelestite, entonces ya debes haber visto lo que me pasó...",
  ui_story_5036_50361402_19_dialog_content = "Sí...",
  ui_story_5036_50361402_20_dialog_content = "Después de sentir que morí protegiéndolo, el Ouroboros se sintió abrumado por el dolor.",
  ui_story_5036_50361402_21_dialog_content = "Detectó el último deseo de mi corazón de regresar a mi hogar, por lo que creó a Eraveil en su paisaje onírico ya mí.",
  ui_story_5036_50361402_22_dialog_content = "Pero debido a su propio deseo de no abandonar este sueño, el Ouroboros se obligó a sí mismo a un sueño interminable.",
  ui_story_5036_50361402_23_dialog_content = "Entonces esos eclipses de hace un momento eran—",
  ui_story_5036_50361402_24_dialog_content = "Son mis miedos.",
  ui_story_5036_50361402_25_dialog_content = "Son manifestaciones del miedo que sentí en mis momentos finales. Por eso siguen apareciendo y atacándome constantemente.",
  ui_story_5036_50361402_26_dialog_content = "Pero está bien, porque el Ouroboros me está protegiendo. ¡Justo cuando están a punto de atraparme, restablece el sueño y los hace desaparecer!",
  ui_story_5036_50361402_27_dialog_content = "Espera, ¿tal vez puedas pedirle a los Ouroboros que te ayuden a irte?",
  ui_story_5036_50361402_28_dialog_content = "¡Buena idea! ¡Iré a preguntarlo ahora!",
  ui_story_5036_50361402_29_dialog_content = "¡De acuerdo! Pero antes de que lo hagas, ¿podrías quedarte y hablar conmigo un poco más?",
  ui_story_5036_50361402_30_dialog_content = "Me encantaría, Chaminade, de verdad. Pero mis fans todavía me están esperando por ahí.",
  ui_story_5036_50361402_31_dialog_content = "¡No tomará mucho tiempo, lo prometo! Solo tengo una pequeña pregunta, ¿te parece bien?",
  ui_story_5036_50361402_32_dialog_content = "¡Por supuesto que es! ¿Qué es?",
  ui_story_5036_50361402_33_dialog_content = "¿Cómo es Eraveil hoy en día?",
  ui_story_5036_50361402_34_dialog_content = "¡Por favor dime! Soy muy curioso.",
  ui_story_5036_50361402_35_dialog_content = "Um... ¿Erraveil?",
  ui_story_5036_50361402_36_dialog_content = "Lo siento, pero nunca he estado allí antes...",
  ui_story_5036_50361402_37_dialog_content = "Oh...",
  ui_story_5036_50361402_38_dialog_content = "¡Pero no te sientas tan deprimido! Aunque nunca he estado allí, ¡tengo un fiel amigo caelestita que vive allí!",
  ui_story_5036_50361402_39_dialog_content = "¿Te refieres a la Caelestita que mencionaste antes?",
  ui_story_5036_50361402_40_dialog_content = "¡Así es! Se llama PlayerName, ¡y es una de las personas más increíbles que he conocido!",
  ui_story_5036_50361402_41_dialog_content = "Antes de conocerlo, todo lo que sabía era que era el piloto Caelestite de un Coloso que viajaba por todo el mundo.",
  ui_story_5036_50361402_42_dialog_content = "A lo largo de sus viajes, ha hecho muchos amigos y ha vivido muchas aventuras. ¡También ha derrotado a más Eclipsites de los que puedo contar!",
  ui_story_5036_50361402_43_dialog_content = "Solía estar tan celoso de su vida. Para mí, era como si viviera una vida de máxima libertad.",
  ui_story_5036_50361402_44_dialog_content = "Pero después de conocer al verdadero él, aprendí lo difícil que ha sido su vida.",
  ui_story_5036_50361402_45_dialog_content = "Pasó los primeros años de su vida viviendo solo bajo tierra. No fue hasta que hizo su primer amigo que finalmente vio la luz del día.",
  ui_story_5036_50361402_46_dialog_content = "Es el último de los caelestitas e incluso reconstruyó Eraveil a partir de sus ruinas.",
  ui_story_5036_50361402_47_dialog_content = "¿Qué?",
  ui_story_5036_50361402_48_dialog_content = "¿Qué quieres decir? ¿Fue Eraveil... destruido? ¿Solo queda... una Caelestita?",
  ui_story_5036_50361402_49_dialog_content = "¡Ay! ¡N-No, no quise decir eso! Lo que quise decir-",
  ui_story_5036_50361402_50_dialog_content = "Mi... mi casa fue destruida...",
  ui_story_5036_50361402_51_dialog_content = "Eraveil... ¿Eraveil realmente se ha ido?",
  ui_story_5036_50361402_52_dialog_content = "¿Pero cómo? ¡¿Cómo podría ser esto?!",
  ui_story_5036_50361402_53_dialog_content = "<color=#e8d9bb>¡Choque!</color>",
  ui_story_5036_50361402_54_dialog_content = "<color=#e8d9bb>Grieta-!</color>",
  ui_story_5036_50361402_55_dialog_content = "¡El paisaje onírico está empezando a desmoronarse! ¿Es por las emociones de Chaminade?",
  ui_story_5036_50361402_56_dialog_content = "Chaminade! ¡P-Por favor, cálmate!",
  ui_story_5036_50361402_57_dialog_content = "Mi casa... Sólo quiero irme a casa... ¡Ahhhhh!",
  ui_story_5036_50361402_58_dialog_content = "Ella no se está calmando en absoluto...",
  ui_story_5036_50361402_59_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5036_50361402_60_dialog_content = "Kree! Kree—!",
  ui_story_5036_50361402_61_dialog_content = "Más y más del sueño está comenzando a desmoronarse. Pero, ¿por qué no se reinicia?",
  ui_story_5036_50361402_62_dialog_content = "¿Qué debo hacer? Tal vez debería empezar a contar y saltarme todos los sietes. ¿Pasará algo bueno?",
  ui_story_5036_50361402_63_dialog_content = "No... ¡Ahora no es el momento de quedarse parado! ¡Al menos necesito alejarme de las partes del sueño que se están desmoronando!",
  ui_story_5036_50361402_64_dialog_content = "Esa torre de allí todavía parece estar en buen estado. También es el lugar más cercano a los Ouroboros.",
  ui_story_5036_50361402_65_dialog_content = "Vamos, Chaminade—¡Ahh!",
  ui_story_5036_50361402_66_dialog_content = "*Sollozo*",
  ui_story_5036_50361402_67_dialog_content = "¡Ay! ¡No me deja acercarme a ella!",
  ui_story_5036_50361402_68_dialog_content = "Chaminade! Chaminade! ¡¡¡Necesitas calmarte!!!",
  ui_story_5036_50361402_69_dialog_content = "ella no me escucha...",
  ui_story_5036_50361402_70_dialog_content = "¡Si esto sigue así, todo el sueño se derrumbará a nuestro alrededor!",
  ui_story_5036_50361402_71_dialog_content = "¡Tengo que encontrar una manera de arreglar este sueño!",
  ui_story_5036_50361402_72_dialog_content = "¡Solo espero que Ouroboros sepa qué hacer!",
  ui_story_5036_50361402_73_dialog_content = "¡Esta torre parece interminable! ¿Cómo es que todavía no estoy en la cima?",
  ui_story_5036_50361402_74_dialog_content = "¿Que tipo de lugar es éste? Está tan oscuro y vacío.",
  ui_story_5036_50361402_75_dialog_content = "¡No! ¡No puedo dejar que mi miedo a la oscuridad me detenga ahora!",
  ui_story_5036_50361402_76_dialog_content = "Grah...",
  ui_story_5036_50361402_77_dialog_content = "Parece que ni siquiera este lugar está a salvo de los eclipses.",
  ui_story_5036_50361402_78_dialog_content = "Supongo que tiene sentido. Como centro del sueño, es el lugar más estable.",
  ui_story_5036_50361402_79_dialog_content = "Parece que incluso los eclipses saben huir del peligro.",
  ui_story_5036_50361402_80_dialog_content = "Sin embargo, no tengo tiempo que perder con ellos. ¡Tengo que llegar a la cima!",
  ui_story_5036_50361402_81_dialog_content = "Esa luz más adelante debe ser la salida.",
  ui_story_5036_50361402_82_dialog_content = "¡Finalmente!",
  ui_story_5036_50361402_83_dialog_content = "¡Kree, kree!",
  ui_story_5036_50361402_84_dialog_content = "¡Es el Ouroboros! ¡Oye!",
  ui_story_5036_50361402_85_dialog_content = "¿Puedes por favor arreglar el sueño y hacer que Chaminade se calme?",
  ui_story_5036_50361402_86_dialog_content = "Kree...",
  ui_story_5036_50361402_87_dialog_content = "(Parece preocupado. ¿También está tratando de decirme que no puede ayudar?)",
  ui_story_5036_50361402_88_dialog_content = "(¡¿Qué se supone que debo hacer ahora?!)",
  ui_story_5036_50361402_89_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_5036_50361402_90_dialog_content = "¡¡Incluso el cielo está empezando a desmoronarse!!",
  ui_story_5036_50361402_91_dialog_content = "Kree! Kree—!",
  ui_story_5036_50361402_92_dialog_content = "El Ouroboros parece que tiene mucho dolor...",
  ui_story_5036_50361402_93_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5036_50361402_94_dialog_content = "¡Ahhh! ¡E-La torre está empezando a derrumbarse!",
  ui_story_5036_50361402_95_dialog_content = "Ahhhhhhh—!!!",
  ui_story_5036_50361402_96_dialog_content = "Goldie! ¡Toma mi mano!",
  ui_story_5036_50361402_97_dialog_content = "¿¡PlayerName!?",
  ui_story_5036_50361402_98_dialog_content = "¡¿Qué estás haciendo aquí?!",
  ui_story_5036_50361402_99_dialog_content = "Nos dimos cuenta de que algo andaba mal con el huevo de Ouroboros, así que volvimos al escenario para investigar.",
  ui_story_5036_50361402_100_dialog_content = "Pero cuando volvimos al concierto, ¡todos estaban desmayados! No solo eso, había rastros de Luminatics de Ouroboros alrededor de tu cuerpo inconsciente.",
  ui_story_5036_50361402_101_dialog_content = "Entonces, ¿los Ouroboros finalmente nacieron? Pero ¿por qué ahora, de todos los tiempos?",
  ui_story_5036_50361402_102_dialog_content = "Es posible que naciera después de escuchar tu canción.",
  ui_story_5036_50361402_103_dialog_content = "Al escribir su canción con una melodía utilizada para activar los Colosos, es posible que sin querer le haya dado al Ouroboros la llamada de atención que necesitaba para salir del cascarón.",
  ui_story_5036_50361402_104_dialog_content = "¡¿Qué?!",
  ui_story_5036_50361402_105_dialog_content = "Si seguimos holgazaneando, mis manos no podrán seguir aguantando...",
  ui_story_5036_50361402_106_dialog_content = "¡Esperar! ¡¡¡No te sueltes!!!",
  ui_story_5036_50361402_107_dialog_content = "¡Jajaja! ¡Sólo estaba bromeando! ¿De verdad crees que soy tan poco fiable?",
  ui_story_5036_50361402_108_dialog_content = "Muy bien, ¡saquémosla de aquí ahora!",
  ui_story_5036_50361402_109_dialog_content = "¡Agárrate fuerte, Goldie!",
  ui_story_5036_50361402_110_dialog_content = "¡Ahhh!",
  ui_story_5036_50361402_111_dialog_content = "¡Estoy despierto!",
  ui_story_5036_50361402_112_dialog_content = "¿Estás bien?",
  ui_story_5036_50361402_113_dialog_content = "Sí, mi cabeza se siente un poco mareada...",
  ui_story_5036_50361402_114_dialog_content = "Finalmente... Después de todo este tiempo, finalmente estoy... ¿Eh? ¡¿E-Estaba soñando?!",
  ui_story_5036_50361402_115_dialog_content = "Uf... ¿Qué pasó?",
  ui_story_5036_50361402_116_dialog_content = "Mi cabeza... ¿Estábamos dormidos?",
  ui_story_5036_50361402_117_dialog_content = "Bostezo. Buenos dias...? ¿O debería decir buenas noches?",
  ui_story_5036_50361402_118_dialog_content = "¡¿De verdad me quedé dormido junto a todos estos plebeyos?! Uf, tendré que quemar este conjunto cuando llegue a casa...",
  ui_story_5036_50361402_119_dialog_content = "¡Parece que todo el mundo está empezando a entrar en razón!",
  ui_story_5036_50361402_120_dialog_content = "¿Es porque el sueño volvió a la normalidad?",
  ui_story_5036_50361402_121_dialog_content = "No, es porque...",
  ui_story_5036_50361402_122_dialog_content = "el Ouroboros está a punto de salir del cascarón.",
  ui_story_5036_50361501_1_dialog_content = "<color=#e8d9bb>Umbraton, a orillas del Río Dorado</color>",
  ui_story_5036_50361501_2_dialog_content = "Oye, ¿qué diablos está pasando ahí arriba? ¡¿Qué tipo de artista se queda dormido en medio de su actuación?!",
  ui_story_5036_50361501_3_dialog_content = "Me pregunto si ella está bien.",
  ui_story_5036_50361501_4_dialog_content = "¡No te preocupes! Estoy seguro de que ella está bien. ¡Ella es fuerte, después de todo!",
  ui_story_5036_50361501_5_dialog_content = "¿Qué diablos están haciendo esas dos personas al azar en el escenario?",
  ui_story_5036_50361501_6_dialog_content = "¡Qué estafa! No voy a perder más tiempo aquí.",
  ui_story_5036_50361501_7_dialog_content = "Un momento, señor.",
  ui_story_5036_50361501_8_dialog_content = "Todavía es demasiado pronto para partir. Después de todo, todo lo que has visto era parte del espectáculo.",
  ui_story_5036_50361501_9_dialog_content = "¿Qué?",
  ui_story_5036_50361501_10_dialog_content = "Hicimos todo lo posible para planificar todos los efectos especiales. Cantar y bailar es muy aburrido, ¿no crees?",
  ui_story_5036_50361501_11_dialog_content = "Preparamos una serie de sorpresas para complementar el espectáculo y hacerlo lo más emocionante posible, todo para su placer visual.",
  ui_story_5036_50361501_12_dialog_content = "Espero que todos se queden un rato más y disfruten del espectáculo. Te prometo que no te defraudará.",
  ui_story_5036_50361501_13_dialog_content = "Bien, haremos lo que dices por ahora.",
  ui_story_5036_50361501_14_dialog_content = "¡Gracias por su comprensión y apoyo! También hemos preparado snacks y refrescos para todos.",
  ui_story_5036_50361501_15_dialog_content = "Por favor Ayúdense ustedes mismos.",
  ui_story_5036_50361501_16_dialog_content = "(Tengo a la multitud bajo control por ahora, pero esto no durará mucho más).",
  ui_story_5036_50361501_17_dialog_content = "(¿Qué diablos está pasando allá arriba, Goldie?)",
  ui_story_5036_50361501_18_dialog_content = "(PlayerName y sus amigos también están allá arriba... Solo espero que no estén en peligro...)",
  ui_story_5036_50361501_19_dialog_content = "<color=#e8d9bb>Mientras tanto, en Eulogoz</color>",
  ui_story_5036_50361501_20_dialog_content = "¿Qué? ¡¿El Ouroboros está saliendo del cascarón?!",
  ui_story_5036_50361501_21_dialog_content = "Sé que es repentino, pero no tenemos tiempo para explicarlo.",
  ui_story_5036_50361501_22_dialog_content = "Si el Ouroboros sale del cascarón, desequilibrará a todo el Coloso y nos pondrá a todos en peligro.",
  ui_story_5036_50361501_23_dialog_content = "¡Nuestra principal prioridad en este momento es evacuar a todos a bordo!",
  ui_story_5036_50361501_24_dialog_content = "Y será mejor que lo hagamos rápido, o... Uh-oh. Parece que ya es demasiado tarde.",
  ui_story_5036_50361501_25_dialog_content = "Grahhhh—!!!",
  ui_story_5036_50361501_26_dialog_content = "¡Están saliendo eclipses desde el interior del Coloso!",
  ui_story_5036_50361501_27_dialog_content = "¡Despertad, todos! ¡Asume posiciones defensivas!",
  ui_story_5036_50361501_28_dialog_content = "¡Sí, mi sra.!",
  ui_story_5036_50361501_29_dialog_content = "Graaaaah!",
  ui_story_5036_50361501_30_dialog_content = "¡No me pasarás!",
  ui_story_5036_50361501_31_dialog_content = "¡Maldita sea! ¿No hay fin para estas criaturas sucias?",
  ui_story_5036_50361501_32_dialog_content = "Basta de quejarse. Centrarse en la defensa.",
  ui_story_5036_50361501_33_dialog_content = "¡Si si lo se!",
  ui_story_5036_50361501_34_dialog_content = "<color=#e8d9bb>Estruendo...</color>",
  ui_story_5036_50361501_35_dialog_content = "¡Todo el Coloso está temblando! ¿Está a punto de aparecer el jefe final?",
  ui_story_5036_50361501_36_dialog_content = "¡Agárrense fuerte, todos! ¡Parece que algo está saliendo del Coloso!",
  ui_story_5036_50361501_37_dialog_content = "Kree—!",
  ui_story_5036_50361501_38_dialog_content = "¡¿Un dragón?! ¡¡Es enorme!!",
  ui_story_5036_50361501_39_dialog_content = "¡Así que realmente salió del cascarón!",
  ui_story_5036_50361501_40_dialog_content = "¡Graagh!",
  ui_story_5036_50361501_41_dialog_content = "¡Los Eclipsites están comenzando a atacar a los Ouroboros!",
  ui_story_5036_50361501_42_dialog_content = "¡Kree-Kree-!",
  ui_story_5036_50361501_43_dialog_content = "¡Mira, hermana! ¡Allí, en la cima del Coloso!",
  ui_story_5036_50361501_44_dialog_content = "¿Es eso... un dragón?",
  ui_story_5036_50361501_45_dialog_content = "¡Oye! El Coloso está temblando tan fuerte. ¡Se va a caer del cielo!",
  ui_story_5036_50361501_46_dialog_content = "<color=#e8d9bb>¡¡¡BOOM!!!</color>",
  ui_story_5036_50361501_47_dialog_content = "¡Esto es malo! Los Ouroboros acaban de nacer. ¡Aún no puede volar!",
  ui_story_5036_50361501_48_dialog_content = "¡Los ataques de los Eclipsites harán que la lucha sea aún más feroz!",
  ui_story_5036_50361501_49_dialog_content = "¿Hay alguna manera de calmarlo primero?",
  ui_story_5036_50361501_50_dialog_content = "¿Qué hay de usar sus habilidades psíquicas?",
  ui_story_5036_50361501_51_dialog_content = "Lo intentaré.",
  ui_story_5036_50361501_52_option_content = "\"¡Detente, Uróboros!\"",
  ui_story_5036_50361501_53_dialog_content = "Kree—!",
  ui_story_5036_50361501_54_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5036_50361501_55_dialog_content = "¡Ah!",
  ui_story_5036_50361501_56_dialog_content = "¡No me escuchará en absoluto!",
  ui_story_5036_50361501_57_dialog_content = "Los Eclipsites han... rodeado el escenario.",
  ui_story_5036_50361501_58_dialog_content = "El concierto... lo arruinó totalmente...",
  ui_story_5036_50361501_59_dialog_content = "¡Goldie, cálmate! ¡Todavía estamos en peligro!",
  ui_story_5036_50361501_60_dialog_content = "Lo sé pero.",
  ui_story_5036_50361501_61_dialog_content = "No hay tiempo que perder. ¡Posiciones, todos! ¡Debemos poner distancia entre los Eclipsites y el dragón!",
  ui_story_5036_50361501_62_dialog_content = "¡Sí!",
  ui_story_5036_50361501_63_dialog_content = "¡Illumina tampoco retrocederá! ¡La batalla del jefe acaba de comenzar!",
  ui_story_5036_50361501_64_dialog_content = "¡¡¡Sí!!!",
  ui_story_5036_50361501_65_dialog_content = "Vicio, PlayerName! ¡Ustedes dos cubran y escolten a los civiles lejos del área de batalla!",
  ui_story_5036_50361501_66_dialog_content = "¡Póngase en contacto con las aeronaves de Soroz y Lumopolis y elabore un plan de evacuación!",
  ui_story_5036_50361501_67_dialog_content = "¡Está bien, déjamelo a mí!",
  ui_story_5036_50361501_68_dialog_content = "¡Está bien!",
  ui_story_5036_50361501_69_dialog_content = "¡Los Caballeros de Lumopolis son tan confiables en tiempos de peligro como este!",
  ui_story_5036_50361501_70_dialog_content = "¿No tienes algo que hacer? Encuentra una manera de calmar a ese dragón.",
  ui_story_5036_50361501_71_dialog_content = "Perdóname, no soy un luchador...",
  ui_story_5036_50361501_72_dialog_content = "Nunca te importa. Evacue con el resto, entonces.",
  ui_story_5036_50361501_73_dialog_content = "No hay problema. Me veré afuera ahora.",
  ui_story_5036_50361501_74_dialog_content = "¡Todos, vengan aquí!",
  ui_story_5036_50361501_75_dialog_content = "¿Cómo está Soroz? PlayerName?",
  ui_story_5036_50361501_76_dialog_content = "El Ouroboros no se está calmando. ¡Soroz no puede vincularse con él!",
  ui_story_5036_50361501_77_dialog_content = "Si tan solo hubiera una manera de calmarlo aunque sea por un segundo...",
  ui_story_5036_50361501_78_dialog_content = "Pero no parece que vaya a hacer eso, al menos no por mucho tiempo.",
  ui_story_5036_50361501_79_dialog_content = "¿Dónde están los dirigibles de Lumopolis?",
  ui_story_5036_50361501_80_dialog_content = "Obviamente ya me he puesto en contacto con ellos.",
  ui_story_5036_50361501_81_dialog_content = "El concierto ya atrajo a algunos nobles con sus aeronaves. Varios de ellos ya están ayudando con la evacuación.",
  ui_story_5036_50361501_82_dialog_content = "El Señor de la Ciudad está enviando todas las aeronaves disponibles en Lumopolis aquí, pero aún llevará algún tiempo.",
  ui_story_5036_50361501_83_dialog_content = "Sin mencionar que Lumopolis solo tiene aeronaves pequeñas la mayoría de las veces. Hará falta bastantes viajes para sacar a toda esa gente de aquí.",
  ui_story_5036_50361501_84_dialog_content = "Tenemos que ganarles más tiempo.",
  ui_story_5036_50361501_85_dialog_content = "Urgh—!",
  ui_story_5036_50361501_X85_dialog_content = "¡Mantener estable!",
  ui_story_5036_50361501_87_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5036_50361501_88_dialog_content = "¡Lady Carleen, hay demasiados eclipses! ¡No podemos mantener nuestras líneas!",
  ui_story_5036_50361501_89_dialog_content = "¡Ahh, todos los de Lumopolis, será mejor que nos vayamos de allí!",
  ui_story_5036_50361501_90_dialog_content = "El dragón está luchando con demasiada fiereza y el Coloso es demasiado viejo.",
  ui_story_5036_50361501_91_dialog_content = "Muchas de sus partes no aguantan los golpes, ¡está empezando a desmoronarse!",
  ui_story_5036_50361501_92_dialog_content = "¿Dónde están las aeronaves?",
  ui_story_5036_50361501_93_dialog_content = "¡Reporte! ¡Soroz no puede conectarse, pero las aeronaves de Lumopolis están en camino!",
  ui_story_5036_50361501_94_dialog_content = "¡Nos hemos quedado sin opciones! Póngase en contacto con todos los equipos para retroceder. ¡Deja de defender a los Ouroboros por ahora y muévete hacia la gente!",
  ui_story_5036_50361501_95_dialog_content = "¡Sí!",
  ui_story_5036_50361501_96_dialog_content = "¡Carleen!",
  ui_story_5036_50361501_97_dialog_content = "Estoy bien, ¿están todos aquí?",
  ui_story_5036_50361501_98_dialog_content = "¡Están todos aquí, Lady Carleen!",
  ui_story_5036_50361501_99_dialog_content = "El primer lote de aeronaves ha llegado. La evacuación está en marcha, pero...",
  ui_story_5036_50361501_100_dialog_content = "Necesita tiempo.",
  ui_story_5036_50361501_101_dialog_content = "Dirigibles demasiado pequeños. Demasiada gente.",
  ui_story_5036_50361501_102_dialog_content = "Haré todo lo posible para ganar tiempo.",
  ui_story_5036_50361501_103_dialog_content = "¡Apuro! ¡El Colossus puede volcarse en cualquier momento!",
  ui_story_5036_50361501_104_dialog_content = "Sollozo... yo...",
  ui_story_5036_50361501_105_dialog_content = "¿Estás bien, Goldie?",
  ui_story_5036_50361501_106_dialog_content = "Estoy bien... el concierto está todo arruinado, pero estoy bien...",
  ui_story_5036_50361501_107_dialog_content = "Aún así, tengo que proteger a mis fans. ¡No pueden lastimarse por mi culpa!",
  ui_story_5036_50361501_108_dialog_content = "Incluso si... ¡este es mi último concierto!",
  ui_story_5036_50361501_109_dialog_content = "Sí, concentrémonos primero en los problemas que nos ocupan.",
  ui_story_5036_50361501_110_dialog_content = "Por cierto Vic, ¿pueden los Ouroboros realmente no... Vic?",
  ui_story_5036_50361501_111_dialog_content = "¿Hacia dónde se ha escapado ahora?",
  ui_story_5036_50361501_112_dialog_content = "¿No evacuó con usted?",
  ui_story_5036_50361501_113_dialog_content = "¡Pensé que estaba detrás de mí, así que no le presté mucha atención!",
  ui_story_5036_50361501_114_dialog_content = "Oh, realmente no soy un luchador en absoluto.",
  ui_story_5036_50361501_115_dialog_content = "¿Creo que lo escucho?",
  ui_story_5036_50361501_116_dialog_content = "¡Ahi esta!",
  ui_story_5036_50361501_117_dialog_content = "Bueno, como me llamo extrozoólogo, será mejor que empiece a actuar como tal.",
  ui_story_5036_50361501_118_dialog_content = "¿Por qué está allí solo?",
  ui_story_5036_50361501_119_dialog_content = "¡Regresa aquí! ¡Es peligroso!",
  ui_story_5036_50361501_120_dialog_content = "Gracias por el recordatorio, pero no puedo. No todavía.",
  ui_story_5036_50361501_121_dialog_content = "¡Eh, tú! ¡Cosas asquerosas y fantasmales! ¡Aqui!",
  ui_story_5036_50361501_122_dialog_content = "¡Peeeko! Silbido-!",
  ui_story_5036_50361501_123_dialog_content = "Grrrr...",
  ui_story_5036_50361501_124_dialog_content = "¡Sí! Eso es todo...",
  ui_story_5036_50361501_125_dialog_content = "¿Por qué ir tras un Ouroboros cuando hay un Aurorian indefenso justo aquí?",
  ui_story_5036_50361501_126_dialog_content = "(Solo un poco más cerca... Tengo que alejarlos de los Ouroboros.)",
  ui_story_5036_50361501_127_dialog_content = "(El Lutumi Owl debería ser suficiente para mantener su atención y ganar algo de tiempo).",
  ui_story_5036_50361501_128_option_content = "¡Vic, vuelve aquí!",
  ui_story_5036_50361501_129_dialog_content = "¡Jajaja! ¡No te preocupes por eso, estoy totalmente bien!",
  ui_story_5036_50361501_130_dialog_content = "¡Solo el mejor extrozoólogo podría confiar su vida a sus maravillosas bestias!",
  ui_story_5036_50361501_131_dialog_content = "¡Gahhhhhh—!",
  ui_story_5036_50361501_132_dialog_content = "(¡Bien! ¡Mordieron el anzuelo!)",
  ui_story_5036_50361501_133_dialog_content = "(¡Ahora, todo lo que necesito es invocar al Búho Lutumi!)",
  ui_story_5036_50361501_134_dialog_content = "¡Búho Lutumi!",
  ui_story_5036_50361501_135_dialog_content = "¡Bul! ¡Bul! ¡Bul!",
  ui_story_5036_50361501_136_dialog_content = "¿¡Por qué huyes, Lutumi Owl!? Regresa aquí-!",
  ui_story_5036_50361501_137_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_5036_50361501_138_dialog_content = "Kree!",
  ui_story_5036_50361501_139_dialog_content = "¡¿Qué?!",
  ui_story_5036_50361501_140_dialog_content = "<color=#e8d9bb>¡Whoosh—Bang!</color>",
  ui_story_5036_50361501_141_dialog_content = "Vic?",
  ui_story_5036_50361501_142_dialog_content = "¡Ay, ay, ay!",
  ui_story_5036_50361501_143_dialog_content = "(¡La cola del Ouroboros lo envió volando! ¡Espera un minuto! ¡Eso es...!)",
  ui_story_5036_50361501_144_dialog_content = "Vic! ¡Correr!",
  ui_story_5036_50361501_145_dialog_content = "Tsk! Ese dragón realmente no sabe cómo ser amable.",
  ui_story_5036_50361501_146_dialog_content = "PlayerName, ¿qué dijiste? ¡No te escuché!",
  ui_story_5036_50361501_147_dialog_content = "¡Gahhhh!",
  ui_story_5036_50361501_148_dialog_content = "Dios... ¡Estoy rodeado!",
  ui_story_5036_50361501_149_dialog_content = "¡Oigan, Eclipsites, soy viejo y eso me hace saber mal!",
  ui_story_5036_50361501_150_dialog_content = "¡Mira la Caelestita de allí! ¡Es joven y tierno! ¡Y mucho más jugoso que yo!",
  ui_story_5036_50361501_151_dialog_content = "Graaaaaah!!!",
  ui_story_5036_50361501_152_dialog_content = "¡Sálvame, pequeña bola de pelo!",
  ui_story_5036_50361501_153_dialog_content = "¡PlayerName!",
  ui_story_5036_50361502_1_dialog_content = "¡Fabuloso! ¡Que todavía estoy vivo!",
  ui_story_5036_50361502_2_dialog_content = "A pesar de que todo mi plan para llamar la atención de los Eclipsites fracasó.",
  ui_story_5036_50361502_3_dialog_content = "¿Cómo estás de humor para reír?",
  ui_story_5036_50361502_4_dialog_content = "Si tienes un plan, ¡debes contárnoslo!",
  ui_story_5036_50361502_5_dialog_content = "¡Lo siento lo siento! Estaba tan preocupado por la seguridad de los Ouroboros que lo olvidé por completo.",
  ui_story_5036_50361502_6_dialog_content = "Pero, solo para que conste, mi plan habría tenido éxito si no me hubiera hecho volar.",
  ui_story_5036_50361502_7_dialog_content = "¡Este no es el momento de discutir sobre los que podrían tener!",
  ui_story_5036_50361502_8_dialog_content = "¿Hay alguna otra forma de calmarlo?",
  ui_story_5036_50361502_9_dialog_content = "Desafortunadamente, no puedo pensar en otra cosa que no sea derrotar a todos los Eclipsites.",
  ui_story_5036_50361502_10_dialog_content = "¿No podemos esperar a que el Ouroboros reúna la fuerza suficiente para volar solo?",
  ui_story_5036_50361502_11_dialog_content = "Eso es un poco demasiado optimista. Los Eclipsites no retroceden en absoluto.",
  ui_story_5036_50361502_12_dialog_content = "Si esto continúa, incluso si el Ouroboros puede volar de nuevo, estaría demasiado herido para hacerlo.",
  ui_story_5036_50361502_13_dialog_content = "Cómo...",
  ui_story_5036_50361502_14_dialog_content = "Lady Carleen, hemos recibido órdenes del Señor de la Ciudad.",
  ui_story_5036_50361502_15_dialog_content = "Seguir.",
  ui_story_5036_50361502_16_dialog_content = "La evacuación está casi completa. Tanto la administración de Illumina como la de Lumopolis han completado su evaluación de riesgos del Coloso.",
  ui_story_5036_50361502_17_dialog_content = "Han decidido dejar atrás a los soldados para contener a los Eclipsites, mantener al dragón bajo control y mantener el equilibrio del Coloso.",
  ui_story_5036_50361502_18_dialog_content = "Una vez que el Coloso esté fuera de Umbraton, lo derribarán.",
  ui_story_5036_50361502_19_dialog_content = "¿¡Quieres derribar al Coloso junto con los Ouroboros!? ¡De ninguna manera!",
  ui_story_5036_50361502_20_dialog_content = "¡Puede ser el último de su tipo! ¡Se extinguirán por completo si haces eso!",
  ui_story_5036_50361502_21_dialog_content = "¡Y no voy a perder a Eulogoz!",
  ui_story_5036_50361502_22_dialog_content = "Tienes una mejor idea? Si no lo haces, entonces cállate.",
  ui_story_5036_50361502_23_dialog_content = "El Coloso está justo encima de la zona más poblada de Umbraton. ¡No vamos a arriesgar la vida de millones de aurorianos!",
  ui_story_5036_50361502_24_dialog_content = "¿Qué pasa si me niego a dejar el Coloso?",
  ui_story_5036_50361502_25_dialog_content = "Vic, ¿qué estás diciendo?",
  ui_story_5036_50361502_26_dialog_content = "Soy extrozoólogo. De ninguna manera voy a dejar que le suceda daño a ese Ouroboros.",
  ui_story_5036_50361502_27_dialog_content = "Si quieres derribar el Coloso, tendrás que derribarme con él.",
  ui_story_5036_50361502_28_dialog_content = "¡Vic, eso es peligroso!",
  ui_story_5036_50361502_29_dialog_content = "¡Dejar de perder el tiempo!",
  ui_story_5036_50361502_30_dialog_content = "(¿Qué hago? ¿Cómo puedo salvar al Ouroboros y al Coloso?)",
  ui_story_5036_50361502_31_dialog_content = "(Debe haber una forma...)",
  ui_story_5036_50361502_32_dialog_content = "¡Definitivamente podrán escuchar mi voz en el suelo a través del equipo!",
  ui_story_5036_50361502_33_dialog_content = "Qué asombroso, la criatura podía comunicarse usando la melodía que usan los Caelestites para controlar a los Colosos.",
  ui_story_5036_50361502_34_dialog_content = "Al escribir su canción con una melodía utilizada para activar los Colosos, es posible que sin querer le haya dado al Ouroboros la llamada de atención que necesitaba para salir del cascarón.",
  ui_story_5036_50361502_35_dialog_content = "¡Hay otra forma que quiero probar!",
  ui_story_5036_50361502_36_dialog_content = "¿Ah?",
  ui_story_5036_50361502_37_dialog_content = "¿Qué es?",
  ui_story_5036_50361502_38_dialog_content = "Chaminade descubrió que los Ouroboros podían entender las melodías que Caelestites usaba para controlar a los Colosos.",
  ui_story_5036_50361502_39_dialog_content = "Si podemos tocar la melodía que apaga el Coloso y detener los Eclipses al mismo tiempo, tal vez podamos calmarlo.",
  ui_story_5036_50361502_40_dialog_content = "Vale la pena intentarlo.",
  ui_story_5036_50361502_41_dialog_content = "¿Funcionaría una canción si incluso las habilidades psíquicas de PlayerName no pueden alcanzar al dragón?",
  ui_story_5036_50361502_42_dialog_content = "Bueno... Mientras sea lo suficientemente fuerte, deberíamos poder llamar su atención.",
  ui_story_5036_50361502_43_dialog_content = "¡Podemos usar el sistema de altavoces del escenario!",
  ui_story_5036_50361502_44_dialog_content = "Sí. Necesitaré la ayuda de Goldie. ¡Deberíamos poder hacerlo con su Luminatic y el equipo!",
  ui_story_5036_50361502_45_dialog_content = "¿Yo?",
  ui_story_5036_50361502_46_dialog_content = "...",
  ui_story_5036_50361502_47_dialog_content = "Entiendo.",
  ui_story_5036_50361502_48_dialog_content = "Mi concierto no puede terminar antes de que haya terminado mi canción.",
  ui_story_5036_50361502_49_dialog_content = "Incluso si ya no puedo subir al escenario como un ídolo en el futuro, mientras tú y mis fans estén ahí afuera...",
  ui_story_5036_50361502_50_dialog_content = "Cantaré para todos ustedes cuando me necesiten.",
  ui_story_5036_50361502_51_dialog_content = "Sin mencionar que Umbraton está justo debajo de nosotros. Es mi hogar, y el hogar de mis fans.",
  ui_story_5036_50361502_52_dialog_content = "¿Qué tan seguro está de que esto funcionará? PlayerName?",
  ui_story_5036_50361502_53_option_content = "no puedo prometerte nada...",
  ui_story_5036_50361502_54_option_content = "¡Quiero darle una oportunidad!",
  ui_story_5036_50361502_55_dialog_content = "Está bien.",
  ui_story_5036_50361502_56_dialog_content = "Ayudaré.",
  ui_story_5036_50361502_57_dialog_content = "¡Señora Carleen! ¿En serio?",
  ui_story_5036_50361502_58_dialog_content = "Por supuesto. Y también proporcionaré soporte si falla.",
  ui_story_5036_50361502_59_dialog_content = "¡Notifique a todos los equipos que estén en espera!",
  ui_story_5036_50361502_60_dialog_content = "Comprendido. ¡Caballeros, formen!",
  ui_story_5036_50361502_61_dialog_content = "Carleen, muchas gracias!",
  ui_story_5036_50361502_62_dialog_content = "¡Yo también ayudaré!",
  ui_story_5036_50361502_63_dialog_content = "Pero la tripulación que maneja el sistema de altavoces ya se fue en una aeronave.",
  ui_story_5036_50361502_64_dialog_content = "¡No te olvides de nosotros! Tenemos esto.",
  ui_story_5036_50361502_65_dialog_content = "El equipo puede ser modificado, pero siguen siendo muy parecidos. Déjanoslos a nosotros.",
  ui_story_5036_50361502_66_dialog_content = "¿¡Gronru, Siobhan!?",
  ui_story_5036_50361502_67_dialog_content = "PlayerName, estás tratando de desafiar algunas etapas súper difíciles, ¿verdad?",
  ui_story_5036_50361502_68_dialog_content = "¿Cómo podría perderme algo tan divertido?",
  ui_story_5036_50361502_69_dialog_content = "A-¡Y yo!",
  ui_story_5036_50361502_70_dialog_content = "Estuve entrevistando a gente en los últimos días, incluidos los que manejaban el sistema de altavoces.",
  ui_story_5036_50361502_71_dialog_content = "¡También aprendí una o dos cosas de ellos!",
  ui_story_5036_50361502_72_dialog_content = "Esto parece un esfuerzo loco, ¡pero déjame acompañarte! ¡Haré todo lo posible para ayudar a Goldie y a ti!",
  ui_story_5036_50361502_73_dialog_content = "Gracias...",
  ui_story_5036_50361502_74_dialog_content = "PlayerName, seguro que tienes una manera de unir a todos.",
  ui_story_5036_50361502_75_dialog_content = "Esta habilidad por sí sola convierte a Caelestite en una bestia maravillosa.",
  ui_story_5036_50361502_76_dialog_content = "¡Espera, no soy una bestia maravillosa!",
  ui_story_5036_50361502_77_dialog_content = "jajaja No hay tiempo para debatir.",
  ui_story_5036_50361502_78_dialog_content = "Estamos cortos de tiempo. ¡Salvemos a los Ouroboros primero!",
  ui_story_5036_50361502_79_dialog_content = "Derecha. ¡Al escenario!",
  ui_story_5036_50361601_1_dialog_content = "Goldie, ¿memorizaste la melodía que te enseñé?",
  ui_story_5036_50361601_2_dialog_content = "¡Por supuesto! Cada nota de ella!",
  ui_story_5036_50361601_3_dialog_content = "Pero hay tantos eclipses en nuestro camino...",
  ui_story_5036_50361601_4_dialog_content = "No te preocupes. Nos ocuparemos de ellos y despejaremos el camino para usted.",
  ui_story_5036_50361601_5_dialog_content = "Sí. Déjanos el combate a nosotros. ¡Tú solo enfócate en cantar!",
  ui_story_5036_50361601_6_dialog_content = "Por cierto. No puedo pelear, pero Little Furball ayudará.",
  ui_story_5036_50361601_7_dialog_content = "¡Chirrido!",
  ui_story_5036_50361601_8_dialog_content = "Gracias por seguir queriendo ayudarme, Goldie.",
  ui_story_5036_50361601_9_dialog_content = "No tienes que agradecerme.",
  ui_story_5036_50361601_10_dialog_content = "Me has estado ayudando durante los últimos días. PlayerName.",
  ui_story_5036_50361601_11_dialog_content = "Si no fuera por su ayuda, este concierto nunca hubiera llegado a realizarse.",
  ui_story_5036_50361601_12_dialog_content = "Pero se arruinó...",
  ui_story_5036_50361601_13_dialog_content = "Aun así, sé cuánto esfuerzo pones.",
  ui_story_5036_50361601_14_dialog_content = "El fracaso del concierto no cambia ese hecho.",
  ui_story_5036_50361601_15_dialog_content = "Así que ahora, ¡es hora de que te pague!",
  ui_story_5036_50361601_16_dialog_content = "¡Está bien!",
  ui_story_5036_50361601_17_dialog_content = "Vamos, entonces!",
  ui_story_5036_50361601_18_dialog_content = "Graaaaaah!!!",
  ui_story_5036_50361601_19_dialog_content = "Eclipses entrantes! ¡Prepárate para la batalla!",
  ui_story_5036_50361602_1_dialog_content = "¡Hemos llegado al escenario! ¿Cómo está el equipo?",
  ui_story_5036_50361602_2_dialog_content = "¡El equipo está bien!",
  ui_story_5036_50361602_3_dialog_content = "Volumen de salida al máximo—!",
  ui_story_5036_50361602_4_dialog_content = "Grahhhhhh—!",
  ui_story_5036_50361602_5_dialog_content = "¡¿Eh?!",
  ui_story_5036_50361602_6_dialog_content = "¡Torrente rápido!",
  ui_story_5036_50361602_7_dialog_content = "¡Gracias!",
  ui_story_5036_50361602_8_dialog_content = "De nada.",
  ui_story_5036_50361602_9_dialog_content = "¡Déjanos los eclipses a nosotros! ¡Tú solo enfócate en manejar el equipo!",
  ui_story_5036_50361602_10_dialog_content = "¡Mientras estemos aquí, no dejaremos pasar ningún Eclipsite!",
  ui_story_5036_50361602_11_dialog_content = "¡Grahhhh!",
  ui_story_5036_50361602_12_dialog_content = "¡Ni se te ocurra escapar!",
  ui_story_5036_50361602_13_dialog_content = "¡Aquí está tu oportunidad! ¡Pequeño Furball, ataca su espalda!",
  ui_story_5036_50361602_14_dialog_content = "¡Chirrido!",
  ui_story_5036_50361602_15_dialog_content = "Grahhhh—",
  ui_story_5036_50361602_16_dialog_content = "Wow, esa cosa es rápida. Incluso Little Furball tiene problemas para ponerse al día.",
  ui_story_5036_50361602_17_dialog_content = "Sigue dando vueltas. ¡Qué problemático!",
  ui_story_5036_50361602_18_dialog_content = "¡Aférrate! ¡No dejes que interfiera con el canto de Goldie, por lo menos!",
  ui_story_5036_50361602_19_dialog_content = "¡Correcto!",
  ui_story_5036_50361602_20_dialog_content = "(Todos están peleando. Tengo que hacer mi trabajo.)",
  ui_story_5036_50361602_21_dialog_content = "¡Kree, Kree!",
  ui_story_5036_50361602_22_dialog_content = "<color=#e8d9bb>Retumbar-!</color>",
  ui_story_5036_50361602_23_dialog_content = "Ouroboros, tú también estás luchando, ¿no?",
  ui_story_5036_50361602_24_dialog_content = "Solo aguanta un poco más. Confía en nosotros. Te protegeremos.",
  ui_story_5036_50361602_25_dialog_content = "Uhm... ¡Voy a empezar a cantar!",
  ui_story_5036_50361602_26_dialog_content = "¡Entendido!",
  ui_story_5036_50361602_27_dialog_content = "(Cálmate, Goldie.)",
  ui_story_5036_50361602_28_dialog_content = "(Calma los nervios de los Ouroboros con esta canción y tranquilízalos).",
  ui_story_5036_50361602_29_dialog_content = "(Haz que esta canción sea digna de una última despedida del escenario y de la vida como ídolo).",
  ui_story_5036_50361602_30_dialog_content = "¡Uroboros, escucha mi canción!",
  ui_story_5036_50361602_31_dialog_content = "♪ El mundo es vasto, el universo un océano ♪",
  ui_story_5036_50361602_32_dialog_content = "♪ Nacemos como meteoritos, juguetones y brillantes ♪",
  ui_story_5036_50361602_33_dialog_content = "♪ Jugamos con alegría, pero a veces nos cansamos ♪",
  ui_story_5036_50361602_34_dialog_content = "♪ Las luces del hogar, guíanos cálidamente a nuestros nidos ♪",
  ui_story_5036_50361602_35_dialog_content = "¡Todos, sigan las instrucciones y evacuen! ¡El Señor de las Sombras garantizará tu seguridad!",
  ui_story_5036_50361602_36_dialog_content = "♪ Las luces del hogar, guíanos cálidamente a nuestros nidos ♪",
  ui_story_5036_50361602_37_dialog_content = "Hermana, ¿escuchas eso?",
  ui_story_5036_50361602_38_dialog_content = "¡Está cantando!",
  ui_story_5036_50361602_39_dialog_content = "Señorita, todas las personas evacuadas han salido de la aeronave.",
  ui_story_5036_50361602_40_dialog_content = "Bueno. ¡Prepárate para salir de nuevo y evacuar al siguiente grupo de civiles!",
  ui_story_5036_50361602_41_dialog_content = "♪ Las luces del hogar, guíanos cálidamente a nuestros nidos ♪",
  ui_story_5036_50361602_42_dialog_content = "¿Eso es... cantar?",
  ui_story_5036_50361602_43_dialog_content = "Una voz tan suave. ¿Viene del Coloso?",
  ui_story_5036_50361602_44_dialog_content = "♪ Niño agotado, vete a dormir ♪",
  ui_story_5036_50361602_45_dialog_content = "♪ Que esta canción de cuna, guarde tus sueños ♪",
  ui_story_5036_50361602_46_dialog_content = "♪ Esta es tu casa ♪",
  ui_story_5036_50361602_47_dialog_content = "Kree—!",
  ui_story_5036_50361602_48_dialog_content = "(¡El Ouroboros parece estar respondiendo!)",
  ui_story_5036_50361602_49_dialog_content = "carleen, PlayerName! ¡Parece que se está calmando!",
  ui_story_5036_50361602_50_dialog_content = "¡Excelente! ¡La canción está funcionando!",
  ui_story_5036_50361602_51_dialog_content = "El Colossus ha dejado de mecerse. ¡Esto funcionará!",
  ui_story_5036_50361602_52_dialog_content = "¡Avanza sobre los eclipses!",
  ui_story_5036_50361602_53_dialog_content = "♪ Esta es tu casa ♪",
  ui_story_5036_50361602_54_dialog_content = "¿Una canción?",
  ui_story_5036_50361602_55_dialog_content = "Es la melodía que apaga el Coloso. Es suave como una canción de cuna.",
  ui_story_5036_50361602_56_dialog_content = "¿Es esa Goldie la que canta? Pero...",
  ui_story_5036_50361602_57_dialog_content = "♪ Ahora que el hogar ya no existe ♪",
  ui_story_5036_50361602_58_dialog_content = "(¡Parece que estoy escuchando a Chaminade cantando!)",
  ui_story_5036_50361602_59_dialog_content = "(Debe estar devastada. Ni siquiera tuve la oportunidad de consolarla...)",
  ui_story_5036_50361602_60_dialog_content = "(Ella puede ser solo una figura de un sueño y en realidad no existe).",
  ui_story_5036_50361602_61_dialog_content = "(Pero su tristeza y soledad son tan reales).",
  ui_story_5036_50361602_62_dialog_content = "(Entonces te dedicaré esta canción, Chaminade.)",
  ui_story_5036_50361602_63_dialog_content = "(Y espero que te quite la tristeza.)",
  ui_story_5036_50361602_64_dialog_content = "♪ Ahora que el hogar ya no existe ♪",
  ui_story_5036_50361602_65_dialog_content = "♪ Aún así, los jóvenes emprenden viajes ♪",
  ui_story_5036_50361602_66_dialog_content = "♪ A través de lágrimas que fluyen a través de la noche ♪",
  ui_story_5036_50361602_67_dialog_content = "♪ A través de penas y alegrías, partidas y reencuentros ♪",
  ui_story_5036_50361602_68_dialog_content = "♪ ¿Todavía pueden ver la luz del amanecer de la esperanza? ♪",
  ui_story_5036_50361602_69_dialog_content = "♪ La luz que aún debe estar esperando por delante ♪",
  ui_story_5036_50361602_70_dialog_content = "¡Torrente rápido!",
  ui_story_5036_50361602_71_dialog_content = "¿Cuántos más hay...?",
  ui_story_5036_50361602_72_dialog_content = "Grah!!!",
  ui_story_5036_50361602_73_dialog_content = "¡Míralo! ¡Está regresando!",
  ui_story_5036_50361602_74_dialog_content = "¡No dejaré que te acerques!",
  ui_story_5036_50361602_75_dialog_content = "¿Es esa tu canción, Goldie?",
  ui_story_5036_50361602_76_dialog_content = "Hace tanto calor, como el sol y el viento en Eraveil.",
  ui_story_5036_50361602_77_dialog_content = "Ya lo veo. Incluso si Eraveil fue destruido, no se ha ido. Casa... se puede reconstruir.",
  ui_story_5036_50361602_78_dialog_content = "Goldie, te escucho.",
  ui_story_5036_50361602_79_dialog_content = "Entonces, debería—",
  ui_story_5036_50361602_80_dialog_content = "♪ Intenta limpiar esas lágrimas ♪",
  ui_story_5036_50361602_81_dialog_content = "♪ Límpiate esas lágrimas, ponte en marcha de nuevo— ♪",
  ui_story_5036_50361602_82_dialog_content = "♪ Difunde esta canción a lo lejos ♪",
  ui_story_5036_50361602_83_dialog_content = "Gracias, Goldie.",
  ui_story_5036_50361602_84_dialog_content = "Ídolo del futuro, te confío Ouroboros y el futuro.",
  ui_story_5036_50361602_85_dialog_content = "Chaminade... parece haberse ido por completo.",
  ui_story_5036_50361602_86_dialog_content = "Kree—",
  ui_story_5036_50361602_87_dialog_content = "¡El Ouroboros se ha calmado!",
  ui_story_5036_50361602_88_dialog_content = "¡Funcionó! PlayerName¡Tu plan funcionó!",
  ui_story_5036_50361602_89_dialog_content = "¡Eso es genial!",
  ui_story_5036_50361602_90_dialog_content = "¡Pero no podemos aguantar más aquí!",
  ui_story_5036_50361602_91_dialog_content = "¡Urgh!",
  ui_story_5036_50361602_92_dialog_content = "Grah!!!",
  ui_story_5036_50361602_93_dialog_content = "¡Torrente rápido!",
  ui_story_5036_50361602_94_dialog_content = "Grahh! Grah!",
  ui_story_5036_50361602_95_dialog_content = "¡¿Cómo es que esta cosa sigue viva?!",
  ui_story_5036_50361602_96_dialog_content = "Cualquier Eclipsite que pueda sobrevivir en este Coloso no debería ser fácil de convencer.",
  ui_story_5036_50361602_97_dialog_content = "Solo espera. ¡Los Ouroboros deberían poder volar en cualquier momento!",
  ui_story_5036_50361602_98_dialog_content = "Rugido-!",
  ui_story_5036_50361602_99_dialog_content = "¡Cuidado, Carleen!",
  ui_story_5036_50361602_100_dialog_content = "Kree!",
  ui_story_5036_50361602_101_dialog_content = "<color=#e8d9bb>Bofetada-!</color>",
  ui_story_5036_50361602_102_dialog_content = "Rugido—",
  ui_story_5036_50361602_103_dialog_content = "¡Guau! ¿Q-Qué...?",
  ui_story_5036_50361602_104_dialog_content = "¡Los Ouroboros enviaron ese Eclipsite volando con su cola!",
  ui_story_5036_50361602_105_dialog_content = "¡Kree, kree!",
  ui_story_5036_50361602_106_dialog_content = "¡Ya no parece asustado! es feliz!",
  ui_story_5036_50361602_107_dialog_content = "¡Eso fue brillante! Sin ese Eclipsite jugando, el resto debería ser fácil de manejar.",
  ui_story_5036_50361602_108_dialog_content = "¡Flor de hielo!",
  ui_story_5036_50361602_109_dialog_content = "Grrrr...",
  ui_story_5036_50361602_110_dialog_content = "Kree—!",
  ui_story_5036_50361602_111_dialog_content = "<color=#e8d9bb>Choque—</color>",
  ui_story_5036_50361602_112_dialog_content = "¿¡El Coloso está rockeando de nuevo!?",
  ui_story_5036_50361602_113_dialog_content = "Sin embargo, los Ouroboros se calmaron.",
  ui_story_5036_50361602_114_dialog_content = "¡Aférrate! ¡Parece que está tomando vuelo!",
  ui_story_5036_50361602_115_dialog_content = "Kree—!",
  ui_story_5036_50361602_116_dialog_content = "Kree!",
  ui_story_5036_50361602_117_dialog_content = "¡Mira, el dragón del Coloso acaba de despegar!",
  ui_story_5036_50361602_118_dialog_content = "¡Es verdad! ¿Está Goldie todavía en el Coloso? ¿Está segura?",
  ui_story_5036_50361602_119_dialog_content = "Ella es una ídolo increíble.",
  ui_story_5036_50361602_120_dialog_content = "No importa lo que se avecina, ella lo logrará.",
  ui_story_5036_50361602_121_dialog_content = "Así que... solo cree en ella.",
  ui_story_5036_50361602_122_dialog_content = "¡Correcto!",
  ui_story_5036_50361602_123_dialog_content = "¡Yo también creo en ella!",
  ui_story_5036_50361602_124_dialog_content = "Bien. Deberías unirte a los demás en la evacuación.",
  ui_story_5036_50361602_125_dialog_content = "Ahora que el dragón ha volado, ¿todo ha terminado?",
  ui_story_5036_50361602_126_dialog_content = "Tengo que contactarlos y confirmar la situación.",
  ui_story_5036_50361602_127_dialog_content = "¡Reporte! Todo el personal evacuado del Coloso Errante ha sido asegurado.",
  ui_story_5036_50361602_128_dialog_content = "Solo unos pocos sufrieron heridas leves. ¡Sin lesiones graves ni muertes!",
  ui_story_5036_50361602_129_dialog_content = "Afortunadamente, el Señor de la Ciudad estaba en una aeronave cerca del Coloso Errante.",
  ui_story_5036_50361602_130_dialog_content = "Lumopolis solo pudo responder tan rápido y minimizar las lesiones debido a esto.",
  ui_story_5036_50361602_131_dialog_content = "¿Cuál es la situación actual con el Coloso y el dragón?",
  ui_story_5036_50361602_132_dialog_content = "El dragón dejó el Coloso, pero Carleen y el resto todavía están a bordo.",
  ui_story_5036_50361602_133_dialog_content = "...",
  ui_story_5036_50361602_134_dialog_content = "PlayerName y Vice están allí, ¡así que Carleen debe estar a salvo!",
  ui_story_5036_50361602_135_dialog_content = "Ordenar a las aeronaves que continúen con la evacuación del personal a bordo del Colossus.",
  ui_story_5036_50361602_136_dialog_content = "¡Sí señor!",
  ui_story_5036_50361602_137_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_5036_50361602_138_dialog_content = "¡¿Eh?!",
  ui_story_5036_50361602_139_dialog_content = "¿Se está volcando el Coloso?",
  ui_story_5036_50361602_140_dialog_content = "¡¿Ah?!",
  ui_story_5036_50361602_141_dialog_content = "¡La partida de los Ouroboros cambió el equilibrio del Coloso!",
  ui_story_5036_50361602_142_dialog_content = "¡Está ganando altura!",
  ui_story_5036_50361602_143_dialog_content = "¡El plan fue todo un éxito!",
  ui_story_5036_50361602_144_dialog_content = "Démonos prisa y salgamos de aquí. Hay demasiados eclipses. ¡Nos superan en número!",
  ui_story_5036_50361602_145_dialog_content = "¡PlayerName!",
  ui_story_5036_50361602_146_dialog_content = "Los Ouroboros volaron. ¡Tuvimos éxito!",
  ui_story_5036_50361602_147_dialog_content = "¡Qué feliz conclusión para todos nosotros!",
  ui_story_5036_50361602_148_option_content = "¿Dónde está Chaminade?",
  ui_story_5036_50361602_149_dialog_content = "Me pareció oírla cantar contigo.",
  ui_story_5036_50361602_150_dialog_content = "Creo que ya se fue...",
  ui_story_5036_50361602_151_dialog_content = "No se fue con los Ouroboros, sino que se fue por completo.",
  ui_story_5036_50361602_152_dialog_content = "Entiendo...",
  ui_story_5036_50361602_153_dialog_content = "Sí. Dijo que me lo confiaría todo.",
  ui_story_5036_50361602_154_dialog_content = "Probablemente quiera que esta canción sea escuchada por todo Astra.",
  ui_story_5036_50361602_155_option_content = "¿Y Eulogoz?",
  ui_story_5036_50361602_156_dialog_content = "Está bien ahora, pero la salida de los Ouroboros se desvió de su camino.",
  ui_story_5036_50361602_157_dialog_content = "Está ganando altura.",
  ui_story_5036_50361602_158_dialog_content = "PlayerName, no hay tiempo para charlas. ¡Vamos a salir de aquí!",
  ui_story_5036_50361602_159_dialog_content = "La partida del Ouroboros cambió la ruta de Eulogoz y la carga aligerada lo hizo acelerar.",
  ui_story_5036_50361602_160_dialog_content = "Sí, al paso que va ahora, estaremos tan alto que no podremos respirar en diez minutos más o menos.",
  ui_story_5036_50361602_161_dialog_content = "¡Démonos prisa y salgamos de aquí!",
  ui_story_5036_50361602_162_dialog_content = "Pero Eulogoz...",
  ui_story_5036_50361602_163_dialog_content = "Eulogoz puede que nunca regrese...",
  ui_story_5036_50361602_164_dialog_content = "Incluso Gronru no puede arreglar el sistema de control de Eulogoz en tan poco tiempo.",
  ui_story_5036_50361602_165_dialog_content = "Entonces, ¿no fue en vano todo nuestro esfuerzo?",
  ui_story_5036_50361602_166_dialog_content = "¡Para nada!",
  ui_story_5036_50361602_167_dialog_content = "Es posible que el concierto no haya ido según lo planeado, pero pudimos compartirlo con todos en el ínterin.",
  ui_story_5036_50361602_168_dialog_content = "Y aprendimos sobre Eulogoz y Chaminade a través de nuestra aventura.",
  ui_story_5036_50361602_169_dialog_content = "Mientras no los olvidemos, siempre estarán con nosotros.",
  ui_story_5036_50361602_170_dialog_content = "...",
  ui_story_5036_50361602_171_option_content = "Vamos.",
  ui_story_5036_50361602_172_option_content = "Nunca los olvidaré.",
  ui_story_5036_50361602_173_dialog_content = "¡Sí!",
  ui_story_5036_50361602_174_dialog_content = "PlayerName, nos estamos quedando sin tiempo.",
  ui_story_5036_50361602_175_dialog_content = "Regresemos.",
  ui_story_5036_50361602_176_dialog_content = "Cierto.",
  ui_story_5036_50361602_177_dialog_content = "Lo siento, Eulogoz.",
  ui_story_5036_50361602_178_dialog_content = "Adiós.",
  ui_story_5036_50361701_1_dialog_content = "¡Actívate, Soroz!",
  ui_story_5036_50361701_2_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_5036_50361701_3_dialog_content = "Eulogoz está volando cada vez más alto, hacia el universo de arriba.",
  ui_story_5036_50361701_4_dialog_content = "Va a llevar la canción de Chaminade a las estrellas.",
  ui_story_5036_50361701_5_dialog_content = "No importa qué, finalmente estamos a salvo.",
  ui_story_5036_50361701_6_dialog_content = "Aunque el concierto fracasó y no pudimos salvar a Eulogoz.",
  ui_story_5036_50361701_7_dialog_content = "Todos están a salvo ahora. La gente de Umbraton ya no tiene que temer. Eso tiene que ser suficiente.",
  ui_story_5036_50361701_8_dialog_content = "Lo que todavía no entiendo es por qué los Ouroboros nacieron de repente.",
  ui_story_5036_50361701_9_dialog_content = "Si tan solo naciera un poco más tarde, las cosas serían tan diferentes ahora...",
  ui_story_5036_50361701_10_dialog_content = "En realidad, lo pensé un poco, y creo que es por mi culpa.",
  ui_story_5036_50361701_11_dialog_content = "En mi sueño... No, en realidad, era el sueño de Ouroboros. Conocí a Chaminade.",
  ui_story_5036_50361701_12_dialog_content = "¿Reunió? ¿No querrás decir que soñaste con ella?",
  ui_story_5036_50361701_13_dialog_content = "No. La conocí.",
  ui_story_5036_50361701_14_dialog_content = "¿Quién o qué es realmente Chaminade?",
  ui_story_5036_50361701_15_dialog_content = "¿Realmente podría haber una forma de que los muertos siguieran existiendo?",
  ui_story_5036_50361701_16_dialog_content = "Solo pensarlo me da escalofríos...",
  ui_story_5036_50361701_17_dialog_content = "Tal vez el Chaminade en el sueño era simplemente un producto de la imaginación de los Ouroboros.",
  ui_story_5036_50361701_18_dialog_content = "¿Quieres decir que ella no era la verdadera Chaminade?",
  ui_story_5036_50361701_19_dialog_content = "Sí. Recuerdo que Chaminade en mi sueño dijo—",
  ui_story_5036_50361701_20_dialog_content = "Detectó el último deseo de mi corazón de regresar a mi hogar, por lo que creó a Eraveil en su paisaje onírico ya mí.",
  ui_story_5036_50361701_21_dialog_content = "Así que supongo que el Eraveil y el Chaminade que vi en el sueño fueron creados por los Ouroboros.",
  ui_story_5036_50361701_22_dialog_content = "No todos estábamos inmersos en sueños en el Coloso simplemente por las habilidades psíquicas de los Ouroboros.",
  ui_story_5036_50361701_23_dialog_content = "Estábamos soñando porque estaba soñando.",
  ui_story_5036_50361701_24_dialog_content = "No estábamos teniendo el mismo sueño. Todos compartíamos el sueño del dragón.",
  ui_story_5036_50361701_25_dialog_content = "Pero, ¿por qué creó un sueño como ese?",
  ui_story_5036_50361701_26_dialog_content = "Por anhelo y odio, probablemente...",
  ui_story_5036_50361701_27_dialog_content = "Aunque se había convertido en un huevo, todavía podía sentir que Chaminade estaba en peligro.",
  ui_story_5036_50361701_28_dialog_content = "No podía ayudarla, pero sabía que su deseo era volver a casa.",
  ui_story_5036_50361701_29_dialog_content = "Entonces, el sueño nació de cómo la extrañaba. Creó un sueño donde su amigo finalmente regresaba a casa.",
  ui_story_5036_50361701_30_dialog_content = "Los Ouroboros continuaron durmiendo solo para mantener vivo ese sueño.",
  ui_story_5036_50361701_31_dialog_content = "Ya veo. ¡No es de extrañar que nunca eclosionara!",
  ui_story_5036_50361701_32_dialog_content = "Entonces, ¿por qué eclosionó de repente? ¿Podría tener algo que ver con el sueño también?",
  ui_story_5036_50361701_33_dialog_content = "Porque podría haber cometido un desliz...",
  ui_story_5036_50361701_34_dialog_content = "Chaminade quedó devastado al enterarse de que Eraveil fue destruido.",
  ui_story_5036_50361701_35_dialog_content = "Así que el sueño se derrumbó y nunca pudo volver a ser como era.",
  ui_story_5036_50361701_36_dialog_content = "Ni siquiera tuve la oportunidad de disculparme con ella.",
  ui_story_5036_50361701_37_dialog_content = "Pero, al final, ella quería que llevara la canción a todos.",
  ui_story_5036_50361701_38_dialog_content = "Mantendré esa promesa, incluso si ya no puedo ser un ídolo.",
  ui_story_5036_50361701_39_dialog_content = "<color=#e8d9bb>bip bip bip—</color>",
  ui_story_5036_50361701_40_dialog_content = "¡Oye! ¡Una solicitud de mensaje de Sheol!",
  ui_story_5036_50361701_41_dialog_content = "¿Q-Qué hacemos? ¿Deberíamos responderlo?",
  ui_story_5036_50361701_42_dialog_content = "De alguna manera, tengo un mal presentimiento sobre esto.",
  ui_story_5036_50361701_43_dialog_content = "Espera, ¡preguntémosle a mi horquilla!",
  ui_story_5036_50361701_44_dialog_content = "<color=#e8d9bb>Timbre-</color>",
  ui_story_5036_50361701_45_dialog_content = "Está apuntando hacia abajo. ¡Esa es una buena señal!",
  ui_story_5036_50361701_46_dialog_content = "¿Deberíamos responder?",
  ui_story_5036_50361701_47_dialog_content = "Vamos a responder, PlayerName.",
  ui_story_5036_50361701_48_dialog_content = "La única manera de avanzar es enfrentar nuestros problemas.",
  ui_story_5036_50361701_49_dialog_content = "Bien entonces. haciéndola pasar—",
  ui_story_5036_50361701_50_dialog_content = "¿PlayerName?",
  ui_story_5036_50361701_51_dialog_content = "¿Señora Seol? ¡Estoy escuchando!",
  ui_story_5036_50361701_52_dialog_content = "¿Dónde estás ahora? ¿Que esta pasando?",
  ui_story_5036_50361701_53_dialog_content = "Estamos en Soroz. Estamos todos aquí. Todos están bien.",
  ui_story_5036_50361701_54_dialog_content = "¿Nadie está herido? Eso es genial... ahora entonces...",
  ui_story_5036_50361701_55_dialog_content = "GOL—¡MUERE!",
  ui_story_5036_50361701_56_dialog_content = "*Sollozo*",
  ui_story_5036_50361701_57_dialog_content = "Será mejor que te expliques. ¿¡Cómo un concierto que se suponía que iba a ir sin problemas se convirtió en esta catástrofe!?",
  ui_story_5036_50361701_58_dialog_content = "yo, eh...",
  ui_story_5036_50361701_59_dialog_content = "Lo siento. Lo desordené...",
  ui_story_5036_50361701_60_dialog_content = "No inspeccioné el lugar con suficiente cuidado, así que no pude encontrar el huevo de Ouroboros en el Coloso y darme cuenta de la amenaza potencial que representaba.",
  ui_story_5036_50361701_61_dialog_content = "Y no preví que Ouroboros de alguna manera reaccionaría a mi canto y saldría del cascarón...",
  ui_story_5036_50361701_62_dialog_content = "Sabes, podrías culpar a Ouroboros por todo.",
  ui_story_5036_50361701_63_dialog_content = "No. Asumiré toda la responsabilidad por esto y compensaré por completo todas las pérdidas según el contrato.",
  ui_story_5036_50361701_64_dialog_content = "Suspiro... realmente me jodiste.",
  ui_story_5036_50361701_65_dialog_content = "Invertí mucho dinero en promocionar el concierto. Con la desaparición del Colossus, todo el dinero que se gastó en mantener su equipo y montar el escenario también se fue por el desagüe.",
  ui_story_5036_50361701_66_dialog_content = "Sin mencionar que hubo otros costos, como los costos de cuidar a la audiencia cuando ocurrió el incidente.",
  ui_story_5036_50361701_67_dialog_content = "Lo siento mucho.",
  ui_story_5036_50361701_68_dialog_content = "Pero tenga la seguridad de que le devolveré el dinero en su totalidad.",
  ui_story_5036_50361701_69_dialog_content = "Incluso si ya no soy un ídolo en el futuro, seguiré trabajando duro para pagar⁠—",
  ui_story_5036_50361701_70_dialog_content = "¿Eh? ¿Cuándo te pedí que cubrieras las pérdidas?",
  ui_story_5036_50361701_71_dialog_content = "¿Eh...?",
  ui_story_5036_50361701_72_dialog_content = "El concierto fue un desastre, sí, ¡pero lo hiciste inesperadamente bien!",
  ui_story_5036_50361701_73_dialog_content = "¡Las emociones en tu canción se transmitieron no solo a Ouroboros sino también a la audiencia!",
  ui_story_5036_50361701_74_dialog_content = "¡Incluso aquellos que nunca estuvieron interesados en los ídolos se enteraron de ti debido a este incidente!",
  ui_story_5036_50361701_75_dialog_content = "¡Y muchos vinieron preguntando por \"el ídolo\"!",
  ui_story_5036_50361701_76_dialog_content = "¡¿Qué?!",
  ui_story_5036_50361701_77_dialog_content = "No solo completó su contrato en su totalidad sino que lo excedió con creces.",
  ui_story_5036_50361701_78_dialog_content = "A-¿Hablas en serio?",
  ui_story_5036_50361701_79_dialog_content = "¿Soy yo? ¿Por qué no te enteras por tus fans?",
  ui_story_5036_50361701_80_dialog_content = "¡Señorita! ¿Eres tu?",
  ui_story_5036_50361701_81_dialog_content = "¡Eres tu! ¿Están usted y su hermana a salvo?",
  ui_story_5036_50361701_82_dialog_content = "¡Estamos bien! ¡Estuviste increíble!",
  ui_story_5036_50361701_83_dialog_content = "La canción era agradable, ¡e incluso domesticaste a ese dragón!",
  ui_story_5036_50361701_84_dialog_content = "¡Todos vieron lo valiente que eras! ¡Muy guay!",
  ui_story_5036_50361701_85_dialog_content = "¿En serio? Jejeje! ¡Estoy tan feliz de oírte decir eso!",
  ui_story_5036_50361701_86_dialog_content = "¡Alguien más también quiere hablar contigo!",
  ui_story_5036_50361701_87_dialog_content = "¿Ese es Goldie?",
  ui_story_5036_50361701_88_dialog_content = "S-Sí, habla Goldie. Y usted es-?",
  ui_story_5036_50361701_89_dialog_content = "¿Estás interesado en ser mi solista personal?",
  ui_story_5036_50361701_90_dialog_content = "¿¡Qué dijiste!?",
  ui_story_5036_50361701_91_dialog_content = "Tu desempeño me hace creer que eres una persona confiable de honor y valor.",
  ui_story_5036_50361701_92_dialog_content = "¡Por favor, sé mi solista! Puedo ayudarte a cantar en los escenarios más lujosos de todo Lumopolis.",
  ui_story_5036_50361701_93_dialog_content = "Gracias por tu amable oferta, pero...",
  ui_story_5036_50361701_94_dialog_content = "¿Cómo puedo convencerte? ¡Di tu precio!",
  ui_story_5036_50361701_95_dialog_content = "No es una cuestión de dinero. Prefiero seguir siendo un ídolo que convertirme en un artista privado.",
  ui_story_5036_50361701_96_dialog_content = "Un ídolo trae esperanza y felicidad a todos, independientemente de su estatus.",
  ui_story_5036_50361701_97_dialog_content = "¡Le prometí a un importante amigo y predecesor llevar nuestra canción a todos!",
  ui_story_5036_50361701_98_dialog_content = "Es eso así...? Qué pena.",
  ui_story_5036_50361701_99_dialog_content = "Bueno, te deseo suerte con tus sueños y me aseguraré de asistir a tu próximo concierto.",
  ui_story_5036_50361701_100_dialog_content = "¡Muchas gracias!",
  ui_story_5036_50361701_101_dialog_content = "¿Asi que? ¿Estás convencido ahora?",
  ui_story_5036_50361701_102_dialog_content = "¡Sí! ¡Sin duda!",
  ui_story_5036_50361701_103_dialog_content = "Entonces anímate y prepárate para el próximo desafío.",
  ui_story_5036_50361701_104_dialog_content = "Ya he llenado tu agenda. Tendrás mucho que hacer una vez que regreses a Umbraton.",
  ui_story_5036_50361701_105_dialog_content = "¡De acuerdo! ¡Regresaré ahora mismo!",
  ui_story_5036_50361701_106_dialog_content = "Por cierto, escuché que descubriste un potencial nuevo talento llamado Vic. ¿Está el aquí?",
  ui_story_5036_50361701_107_dialog_content = "¿Quién, yo?",
  ui_story_5036_50361701_108_dialog_content = "¿Estás interesado en firmar como uno de mis ídolos?",
  ui_story_5036_50361701_109_dialog_content = "¿Qué? ¿Jajaja? Tienes que estar bromeando.",
  ui_story_5036_50361701_110_dialog_content = "No estoy hecho para estar bajo los reflectores. Me gusta pasar tiempo con los animales.",
  ui_story_5036_50361701_111_dialog_content = "¿No lo reconsiderarás?",
  ui_story_5036_50361701_112_dialog_content = "Puedo pagarte generosamente e incluir el mejor champán de Umbraton como bonificación.",
  ui_story_5036_50361701_113_dialog_content = "Seguro que suena tentador. No necesitaría cuidar a Little Furball, y podría beber todos los días—",
  ui_story_5036_50361701_114_dialog_content = "¡¿Chirrido?! ",
  ui_story_5036_50361701_115_dialog_content = "¡¡¡CHIRRIDO!!!",
  ui_story_5036_50361701_116_dialog_content = "¿Eh? ¡Oye! ¡Déjate llevar, tú! ¡Déjalo ir!",
  ui_story_5036_50361701_117_dialog_content = "Parece que alguien está totalmente en desacuerdo.",
  ui_story_5036_50361701_118_dialog_content = "De acuerdo entonces. Hablaremos de esto en otro momento.",
  ui_story_5036_50361701_119_dialog_content = "Luego, los veré a todos en Umbraton.",
  ui_story_5036_50361701_120_dialog_content = "¡Excelente! Realmente es... ¡perfecto!",
  ui_story_5036_50361701_121_dialog_content = "¡Puedo seguir siendo un ídolo!",
  ui_story_5036_50361701_122_dialog_content = "¡Felicidades, Goldie!",
  ui_story_5036_50361701_123_dialog_content = "A pesar de que este concierto fracasó, ¡la próxima vez lo lograré!",
  ui_story_5036_50361701_124_dialog_content = "por favor ven, PlayerName. ¡Te guardaré los mejores lugares!",
  ui_story_5036_50361701_125_dialog_content = "Por supuesto. ¡Es un trato!",
  ui_story_5036_50361701_126_dialog_content = "Pero pasará algún tiempo antes de que eso suceda.",
  ui_story_5036_50361701_127_dialog_content = "¡Después de que regrese, voy a escribir una canción sobre esta terrible experiencia!",
  ui_story_5036_50361701_128_dialog_content = "Parece que todo está bien si termina bien.",
  ui_story_5036_50361701_129_dialog_content = "Parece que si. Wow, ahora que tengo un momento para relajarme, de repente estoy tan cansada.",
  ui_story_5036_50361701_130_dialog_content = "Ya me está dando sueño... Bostezo...",
  ui_story_5036_50361701_131_dialog_content = "¡Hmph! ¡Si no fuera por este drama, estaría tomando un buen baño caliente ahora mismo!",
  ui_story_5036_50361701_132_dialog_content = "Sin baño, sin problema.",
  ui_story_5036_50361701_133_dialog_content = "No hay diferencia, de todos modos.",
  ui_story_5036_50361701_134_dialog_content = "Sin embargo, fue muy agradable ver toda esa rara tecnología antigua en Eulogoz.",
  ui_story_5036_50361701_135_dialog_content = "La pantalla y el sistema estéreo eran fascinantes. ¡Estoy inspirado!",
  ui_story_5036_50361701_136_dialog_content = "Me pregunto si debería investigar sus principios de funcionamiento y hacer algunos para el trono...",
  ui_story_5036_50361701_137_dialog_content = "No me digas...",
  ui_story_5036_50361701_138_dialog_content = "¡Entonces puedo jugar en cualquier momento, todo el tiempo!",
  ui_story_5036_50361701_139_dialog_content = "Como yo pensaba.",
  ui_story_5036_50361701_140_dialog_content = "De todos modos. Volvamos a bajar a la superficie primero.",
  ui_story_5036_50361701_141_dialog_content = "<color=#e8d9bb>Algún tiempo después</color>",
  ui_story_5036_50361701_142_dialog_content = "Ya es de día. No me di cuenta de que había pasado tanto tiempo.",
  ui_story_5036_50361701_143_dialog_content = "¡Por fin de vuelta a tierra! Eso fue bastante, ¿no es así, Little Furball?",
  ui_story_5036_50361701_144_dialog_content = "¡Chirrido!",
  ui_story_5036_50361701_145_dialog_content = "¡Nosotros éramos los que peleábamos mientras tú solo mirabas!",
  ui_story_5036_50361701_146_dialog_content = "Oye, no es justo decir eso. ¡Hice lo mejor que pude para proteger a Ouroboros también!",
  ui_story_5036_50361701_147_dialog_content = "No importa, no discutiré contigo ya que te esforzaste un poco.",
  ui_story_5036_50361701_148_dialog_content = "Voy a estar despegando ahora. Fia y Shira todavía están esperando a que les cuente sobre Ouroboros.",
  ui_story_5036_50361701_149_dialog_content = "Hasta la próxima.",
  ui_story_5036_50361701_150_dialog_content = "¡Hasta luego Vic!",
  ui_story_5036_50361701_151_dialog_content = "¡Cuidado por ahí! ¡No te vuelvan a secuestrar!",
  ui_story_5036_50361701_152_dialog_content = "¡No te preocupes! ¡Soy un adulto totalmente confiable!",
  ui_story_5036_50361701_153_dialog_content = "También tomaremos un dirigible de regreso a Lumopolis.",
  ui_story_5036_50361701_154_dialog_content = "(Honestamente, tengo que conseguir que alguien me prepare un baño caliente la próxima vez...)",
  ui_story_5036_50361701_155_dialog_content = "Oigan, mocosos de Rediesel Wrench. La próxima vez que los vea, los enviaré a todos a prisión.",
  ui_story_5036_50361701_156_dialog_content = "¿Qué? Que arrogante ¿Quién diablos te crees que eres?",
  ui_story_5036_50361701_157_dialog_content = "Posteriormente Caelestita.",
  ui_story_5036_50361701_158_dialog_content = "¡Adiós!",
  ui_story_5036_50361701_159_dialog_content = "¿Todos se han ido? Sio, volvamos también.",
  ui_story_5036_50361701_160_dialog_content = "Bien. Se acabaron las vacaciones. Es hora de volver al trabajo.",
  ui_story_5036_50361701_161_dialog_content = "Oficial Gronru, ¿no regresará con nosotros en el Coloso?",
  ui_story_5036_50361701_162_dialog_content = "Está bien. Sio y yo tomaremos el auto para no interferir con tus planes.",
  ui_story_5036_50361701_163_dialog_content = "¡Además, necesito discutir con Sio la posibilidad de agregar una pantalla y una consola de juegos al trono!",
  ui_story_5036_50361701_164_dialog_content = "¿¡Q-Qué dijiste!?",
  ui_story_5036_50361701_165_dialog_content = "¡Vamos, mi pequeño Sio!",
  ui_story_5036_50361701_166_dialog_content = "¡Ayúdame...!",
  ui_story_5036_50361701_167_dialog_content = "Parece que todavía hay problemas irresolubles para alguien como Siobhan.",
  ui_story_5036_50361701_168_dialog_content = "Supongo que también deberíamos volver.",
  ui_story_5036_50361701_169_dialog_content = "¡Sí, sí!",
  ui_story_5036_50361701_170_dialog_content = "¡He decidido!",
  ui_story_5036_50361701_171_dialog_content = "¿eh? ¿Qué locura has decidido esta vez?",
  ui_story_5036_50361701_172_dialog_content = "¡Una vez que regresemos, voy a convencer al jefe de poner un escenario en la cabeza de Lepidoz!",
  ui_story_5036_50361701_173_dialog_content = "¡Eso realmente suena como una buena idea!",
  ui_story_5036_50361701_174_dialog_content = "¡Oye! ¡Fue mi idea! ¡Voy a pedirle al jefe que haga un escenario de ídolo!",
  ui_story_5036_50361701_175_dialog_content = "¡Vuelve aquí, tú! ¡El heavy metal es música de verdad!",
  ui_story_5036_50361701_176_dialog_content = "Oh, qué animado.",
  ui_story_5036_50361701_177_dialog_content = "Vamos a despedirnos también, PlayerName.",
  ui_story_5036_50361701_178_dialog_content = "¡Gracias por todo!",
  ui_story_5036_50361701_179_dialog_content = "Tú también. Trabajaste duro para que este concierto sucediera y peleamos una larga batalla. Es hora de tomar un buen descanso.",
  ui_story_5036_50361701_180_dialog_content = "Soy un ídolo profesional, ya sabes. ¡Solo una pequeña siesta y estaré listo para irme!",
  ui_story_5036_50361701_181_dialog_content = "¡Esperen con ansias mi próximo concierto!",
  ui_story_5036_50361701_182_dialog_content = "¡Me aseguraré de esperar tus buenas noticias!",
  ui_story_5036_50361701_183_dialog_content = "¡Adiós, entonces!",
  ui_story_5036_50361701_184_dialog_content = "Así que las tendencias violentas de Goldie eran puras habladurías. Tengo que aclarar eso en mi artículo.",
  ui_story_5036_50361701_185_dialog_content = "¿Eh, editor jefe?",
  ui_story_5036_50361701_186_dialog_content = "<size=45>¡Brandy! ¿Por qué tardaste tanto en contactarme?</size>",
  ui_story_5036_50361701_187_dialog_content = "¡Te despedirán si no tienes algo grande para mí!",
  ui_story_5036_50361701_188_dialog_content = "He investigado los rumores que afirman que Goldie es una persona violenta. ¡Todo es falso!",
  ui_story_5036_50361701_189_dialog_content = "...",
  ui_story_5036_50361701_190_dialog_content = "¿¡Eso es todo lo que descubriste todo el tiempo que el Coloso Errante volaba sobre Umbraton!?",
  ui_story_5036_50361701_191_dialog_content = "Incluso si son noticias falsas, seguirán atrayendo a los lectores, ¿no es así? Sin este tipo de chismes, tendríamos que cerrar.",
  ui_story_5036_50361701_192_dialog_content = "Estoy muy decepcionado contigo, Brandy. Estás siendo degradado⁠—",
  ui_story_5036_50361701_193_dialog_content = "¡Esperar! ¡Eso no es lo único! ¡Tengo detalles exclusivos sobre el concierto de Wandering Colossus!",
  ui_story_5036_50361701_194_dialog_content = "¿¡Qué!? ¡Vas en serio! Bueno, ¡tráelo aquí, entonces!",
  ui_story_5036_50361701_195_dialog_content = "Con una condición.",
  ui_story_5036_50361701_196_dialog_content = "¿Qué es?",
  ui_story_5036_50361701_197_dialog_content = "La exclusiva y el artículo que disipa los rumores sobre Goldie tienen que estar en la misma página.",
  ui_story_5036_50361701_198_dialog_content = "¡Quiero que todos sepan que tienen una idea equivocada sobre Goldie!",
  ui_story_5036_50361701_199_dialog_content = "E-Eso es prepost...",
  ui_story_5036_50361701_200_dialog_content = "<size=45>¡Uf, está bien, está bien!</size>",
  ui_story_5036_50361701_201_dialog_content = "Yo haré eso. Ahora traiga sus informes aquí.",
  ui_story_5036_50361701_202_dialog_content = "¡Inmediatamente!",
  ui_story_5036_50361701_203_dialog_content = "Así que secuestraste al Drakolion con galletas de animales y te escabulliste en el Coloso Errante para investigarlo... ¿¡por nada!?",
  ui_story_5036_50361701_204_dialog_content = "¡Casi me emboscan los Eclipsites mientras intentaba encontrar el Drakolion!",
  ui_story_5036_50361701_205_dialog_content = "¿¡Cómo vas a compensarme por esto, eh!? ¿Maestro?",
  ui_story_5036_50361701_206_dialog_content = "¡Bien! A pesar de que no pudimos averiguar más sobre Ouroboros, ¡lo despertamos y obtuvimos mucha información!",
  ui_story_5036_50361701_207_dialog_content = "¡El regreso de los Ouroboros definitivamente sacudirá las cosas en Astra!",
  ui_story_5036_50361701_208_dialog_content = "Confía en mí, con la información que tengo ahora. ¡Será fácil localizar a Ouroboros en el futuro!",
  ui_story_5036_50361701_209_dialog_content = "¿Por qué suena tan familiar?",
  ui_story_5036_50361701_210_dialog_content = "Eso es lo que dijo la última vez.",
  ui_story_5036_50361701_211_dialog_content = "\"¡Confía en mí, definitivamente ganaré mucho dinero la próxima vez!\"",
  ui_story_5036_50361701_212_dialog_content = "¿Cómo es que lo recuerdas tan bien?",
  ui_story_5036_50361701_213_dialog_content = "Porque eso es lo que dijo la vez anterior también.",
  ui_story_5036_50361701_214_dialog_content = "Pero, hasta ahora, no ha habido ningún cambio positivo en su estado financiero. Él sigue cada vez más pobre.",
  ui_story_5036_50361701_215_dialog_content = "Verdadero. ¡Todavía no ha pagado el maravilloso alimento para bestias del mes pasado!",
  ui_story_5036_50361701_216_dialog_content = "*Sollozo* ¿De verdad soy tan perdedor a tus ojos?",
  ui_story_5036_50361701_217_dialog_content = "¿Que esperabas?",
  ui_story_5036_50361701_218_dialog_content = "¡Estoy muy triste!",
  ui_story_5036_50361701_219_dialog_content = "Entonces, ¿todos piensan que estaría mejor siendo un ídolo?",
  ui_story_5036_50361701_220_dialog_content = "Te dieron aplausos porque se apiadaron de ti. No deberías tomártelo en serio.",
  ui_story_5036_50361701_221_dialog_content = "*Sollozo*",
  ui_story_5036_50361701_222_dialog_content = "Pero, tenías razón por una vez. Ouroboros realmente estaba en el Coloso Errante.",
  ui_story_5036_50361701_223_dialog_content = "¿Como lo descubriste?",
  ui_story_5036_50361701_224_dialog_content = "Tal vez para los Ouroboros, dirigirse al Coloso era una forma de regreso.",
  ui_story_5036_50361701_225_dialog_content = "¿A qué te refieres con eso?",
  ui_story_5036_50361701_226_dialog_content = "No importa cuánto tiempo pueda vivir un Ouroboros o cuántas veces haya salido del cascarón...",
  ui_story_5036_50361701_227_dialog_content = "Comenzó como un huevo de otro Ouroboros.",
  ui_story_5036_50361701_228_dialog_content = "Un joven confía en la protección de sus padres por instinto.",
  ui_story_5036_50361701_229_dialog_content = "Lo mismo es cierto incluso para un Ouroboros que regresa a su etapa de infancia en cada ciclo de vida.",
  ui_story_5036_50361701_230_dialog_content = "Sin embargo, los Ouroboroses son muy pocos en número. Muchos nunca encuentran a sus padres.",
  ui_story_5036_50361701_231_dialog_content = "Por eso, solo pueden buscar a los Colosos, con quienes comparten fuertes lazos.",
  ui_story_5036_50361701_232_dialog_content = "Tratar a los Colosos como a sus padres... que tristeza.",
